window.NANG_CAO = {"avg": [{"id": "cd1-b1a", "lesson": "avg", "rank": 1, "q": {"vi": "Tìm trung bình cộng của các số sau: 10; 17; 24; 37.", "en": "Find the average of these numbers: 10; 17; 24; 37."}, "parts": [{"kind": "num", "lab": {"vi": "Trung bình cộng", "en": "Average"}, "ans": 22, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tổng của 4 số: 10 + 17 + 24 + 37 = 88.", "en": "Sum of the 4 numbers: 10 + 17 + 24 + 37 = 88."}, {"vi": "Trung bình cộng: 88 : 4 = 22.", "en": "Average: 88 ÷ 4 = 22."}], "tip": {"vi": "Trung bình cộng = tổng các số : số các số.", "en": "Average = sum of the numbers ÷ how many numbers."}, "src": "250 bài, CĐ1, Bài 1a"}, {"id": "cd1-b1b", "lesson": "avg", "rank": 1, "q": {"vi": "Tìm trung bình cộng của các số sau: 1; 4; 7; 10; 13; 16; 19; 22; 25.", "en": "Find the average of these numbers: 1; 4; 7; 10; 13; 16; 19; 22; 25."}, "parts": [{"kind": "num", "lab": {"vi": "Trung bình cộng", "en": "Average"}, "ans": 13, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Dãy số cách đều 3, có 9 số.", "en": "The numbers go up by 3 each time, and there are 9 of them."}, {"vi": "Tổng: (1 + 25) × 9 : 2 = 117.", "en": "Sum: (1 + 25) × 9 ÷ 2 = 117."}, {"vi": "Trung bình cộng: 117 : 9 = 13.", "en": "Average: 117 ÷ 9 = 13."}], "tip": {"vi": "Trong dãy cách đều, trung bình cộng bằng trung bình cộng của số đầu và số cuối.", "en": "In an evenly spaced list, the average equals the average of the first and last numbers."}, "src": "250 bài, CĐ1, Bài 1b"}, {"id": "cd1-b1c", "lesson": "avg", "rank": 1, "q": {"vi": "Tìm trung bình cộng của các số sau: 2; 6; 10; 14; 18; 22; 26; 30; 34; 38.", "en": "Find the average of these numbers: 2; 6; 10; 14; 18; 22; 26; 30; 34; 38."}, "parts": [{"kind": "num", "lab": {"vi": "Trung bình cộng", "en": "Average"}, "ans": 20, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Dãy số cách đều 4, có 10 số.", "en": "The numbers go up by 4 each time, and there are 10 of them."}, {"vi": "Tổng: (2 + 38) × 10 : 2 = 200.", "en": "Sum: (2 + 38) × 10 ÷ 2 = 200."}, {"vi": "Trung bình cộng: 200 : 10 = 20.", "en": "Average: 200 ÷ 10 = 20."}], "tip": {"vi": "Trong dãy cách đều, trung bình cộng bằng trung bình cộng của số đầu và số cuối.", "en": "In an evenly spaced list, the average equals the average of the first and last numbers."}, "src": "250 bài, CĐ1, Bài 1c"}, {"id": "cd1-b2", "lesson": "avg", "rank": 1, "q": {"vi": "Trung bình cộng của 3 số bằng 25. Biết số thứ nhất là 12; số thứ hai là 40. Tìm số thứ ba.", "en": "The average of 3 numbers is 25. The first number is 12 and the second number is 40. Find the third number."}, "parts": [{"kind": "num", "lab": {"vi": "Số thứ ba", "en": "Third number"}, "ans": 23, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tổng của 3 số: 25 × 3 = 75.", "en": "Sum of the 3 numbers: 25 × 3 = 75."}, {"vi": "Tổng hai số đã biết: 12 + 40 = 52.", "en": "Sum of the two known numbers: 12 + 40 = 52."}, {"vi": "Số thứ ba: 75 − 52 = 23.", "en": "Third number: 75 − 52 = 23."}], "tip": {"vi": "Tổng các số = trung bình cộng × số các số.", "en": "Sum = average × how many numbers."}, "src": "250 bài, CĐ1, Bài 2"}, {"id": "cd1-b10", "lesson": "avg", "rank": 2, "q": {"vi": "Trung bình cộng của 3 số bằng 24. Trung bình cộng của số thứ nhất và số thứ hai bằng 21, của số thứ hai và số thứ ba bằng 26. Tìm 3 số đó.", "en": "The average of 3 numbers is 24. The average of the first and second numbers is 21, and the average of the second and third numbers is 26. Find the 3 numbers."}, "parts": [{"kind": "num", "lab": {"vi": "Số thứ nhất", "en": "First number"}, "ans": 20, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số thứ hai", "en": "Second number"}, "ans": 22, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số thứ ba", "en": "Third number"}, "ans": 30, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tổng 3 số: 24 × 3 = 72; tổng số thứ nhất và thứ hai: 21 × 2 = 42; tổng số thứ hai và thứ ba: 26 × 2 = 52.", "en": "Sum of 3 numbers: 24 × 3 = 72; first + second: 21 × 2 = 42; second + third: 26 × 2 = 52."}, {"vi": "Số thứ ba: 72 − 42 = 30.", "en": "Third number: 72 − 42 = 30."}, {"vi": "Số thứ nhất: 72 − 52 = 20.", "en": "First number: 72 − 52 = 20."}, {"vi": "Số thứ hai: 72 − 20 − 30 = 22.", "en": "Second number: 72 − 20 − 30 = 22."}], "tip": {"vi": "Lấy tổng 3 số trừ đi tổng của hai số.", "en": "Subtract the sum of two numbers from the sum of all 3."}, "src": "250 bài, CĐ1, Bài 10"}, {"id": "cd1-b12", "lesson": "avg", "rank": 2, "q": {"vi": "Tìm 3 số tự nhiên A, B, C biết trung bình cộng của A và B là 20, trung bình cộng của B và C là 25 và trung bình cộng của A và C là 15.", "en": "Find 3 whole numbers A, B, C, if the average of A and B is 20, the average of B and C is 25, and the average of A and C is 15."}, "parts": [{"kind": "num", "lab": {"vi": "Số A", "en": "Number A"}, "ans": 10, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số B", "en": "Number B"}, "ans": 30, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số C", "en": "Number C"}, "ans": 20, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "A + B = 20 × 2 = 40; B + C = 25 × 2 = 50; A + C = 15 × 2 = 30.", "en": "A + B = 20 × 2 = 40; B + C = 25 × 2 = 50; A + C = 15 × 2 = 30."}, {"vi": "Cộng ba tổng: 40 + 50 + 30 = 120, đây là 2 lần (A + B + C), nên A + B + C = 60.", "en": "Adding the three sums: 40 + 50 + 30 = 120, which is 2 times (A + B + C), so A + B + C = 60."}, {"vi": "C = 60 − 40 = 20; A = 60 − 50 = 10; B = 60 − 30 = 30.", "en": "C = 60 − 40 = 20; A = 60 − 50 = 10; B = 60 − 30 = 30."}], "tip": {"vi": "Mỗi số được cộng hai lần khi cộng ba tổng.", "en": "Each number is counted twice when you add the three sums."}, "src": "250 bài, CĐ1, Bài 12"}, {"id": "cd1-b1d", "lesson": "avg", "rank": 2, "q": {"vi": "Tìm trung bình cộng của các số sau: 1; 2; 3; 4; 5; …; 2014; 2015.", "en": "Find the average of these numbers: 1; 2; 3; 4; 5; …; 2,014; 2,015."}, "parts": [{"kind": "num", "lab": {"vi": "Trung bình cộng", "en": "Average"}, "ans": 1008, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Các số cách đều 1, nên số đầu và số cuối là một cặp có tổng 1 + 2015 = 2016.", "en": "The numbers go up by 1, so the first and last numbers make a pair with sum 1 + 2,015 = 2,016."}, {"vi": "Các cặp (2 + 2014), (3 + 2013), … đều có tổng 2016, nên trung bình cộng bằng nửa tổng của một cặp.", "en": "Every pair (2 + 2,014), (3 + 2,013), … also has sum 2,016, so the average is half of a pair's sum."}, {"vi": "Trung bình cộng: 2016 : 2 = 1008.", "en": "Average: 2,016 ÷ 2 = 1,008."}], "tip": {"vi": "Ghép số đầu với số cuối.", "en": "Pair the first number with the last number."}, "src": "250 bài, CĐ1, Bài 1d"}, {"id": "cd1-b1e", "lesson": "avg", "rank": 2, "q": {"vi": "Tìm trung bình cộng của các số sau: 5; 10; 15; 20; …; 2000; 2005.", "en": "Find the average of these numbers: 5; 10; 15; 20; …; 2,000; 2,005."}, "parts": [{"kind": "num", "lab": {"vi": "Trung bình cộng", "en": "Average"}, "ans": 1005, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Các số cách đều 5; số đầu là 5, số cuối là 2005.", "en": "The numbers go up by 5; the first is 5 and the last is 2,005."}, {"vi": "Mỗi cặp số cách đều hai đầu có tổng 5 + 2005 = 2010.", "en": "Each pair of numbers equally far from the two ends has sum 5 + 2,005 = 2,010."}, {"vi": "Trung bình cộng: 2010 : 2 = 1005.", "en": "Average: 2,010 ÷ 2 = 1,005."}], "tip": {"vi": "Ghép số đầu với số cuối.", "en": "Pair the first number with the last number."}, "src": "250 bài, CĐ1, Bài 1e"}, {"id": "cd1-b3", "lesson": "avg", "rank": 2, "q": {"vi": "Trung bình cộng của 3 số là 35. Tìm số thứ ba, biết số thứ nhất gấp đôi số thứ hai, số thứ hai gấp đôi số thứ ba.", "en": "The average of 3 numbers is 35. Find the third number, if the first number is twice the second number and the second number is twice the third number."}, "parts": [{"kind": "num", "lab": {"vi": "Số thứ ba", "en": "Third number"}, "ans": 15, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tổng của 3 số: 35 × 3 = 105.", "en": "Sum of the 3 numbers: 35 × 3 = 105."}, {"vi": "Coi số thứ ba là 1 phần; số thứ hai là 2 phần; số thứ nhất là 2 × 2 = 4 phần.", "en": "Let the third number be 1 part; the second is 2 parts; the first is 2 × 2 = 4 parts."}, {"vi": "Tổng số phần bằng nhau: 1 + 2 + 4 = 7 (phần).", "en": "Total number of equal parts: 1 + 2 + 4 = 7 (parts)."}, {"vi": "Số thứ ba: 105 : 7 = 15.", "en": "Third number: 105 ÷ 7 = 15."}], "tip": {"vi": "Vẽ sơ đồ đoạn thẳng, lấy số thứ ba làm 1 phần.", "en": "Draw a bar diagram and let the third number be 1 part."}, "src": "250 bài, CĐ1, Bài 3"}, {"id": "cd1-b4", "lesson": "avg", "rank": 2, "q": {"vi": "Tìm 5 số chẵn liên tiếp, biết trung bình cộng của chúng bằng 126. Hãy cho biết số bé nhất và số lớn nhất trong 5 số đó.", "en": "Find 5 consecutive even numbers whose average is 126. Give the smallest and the largest of the 5 numbers."}, "parts": [{"kind": "num", "lab": {"vi": "Số bé nhất", "en": "Smallest number"}, "ans": 122, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số lớn nhất", "en": "Largest number"}, "ans": 130, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Với 5 số chẵn liên tiếp (cách đều 2), trung bình cộng chính là số ở giữa, nên số ở giữa là 126.", "en": "For 5 consecutive even numbers (they go up by 2), the average is the middle number, so the middle number is 126."}, {"vi": "Hai số bên trái: 126 − 2 = 124 và 124 − 2 = 122.", "en": "The two numbers on the left: 126 − 2 = 124 and 124 − 2 = 122."}, {"vi": "Hai số bên phải: 126 + 2 = 128 và 128 + 2 = 130.", "en": "The two numbers on the right: 126 + 2 = 128 and 128 + 2 = 130."}, {"vi": "Năm số là 122; 124; 126; 128; 130.", "en": "The five numbers are 122; 124; 126; 128; 130."}], "tip": {"vi": "Trung bình cộng của dãy cách đều là số ở giữa.", "en": "In an evenly spaced list, the average is the middle number."}, "src": "250 bài, CĐ1, Bài 4"}, {"id": "cd1-b5", "lesson": "avg", "rank": 2, "q": {"vi": "Tuổi trung bình cộng của cô giáo chủ nhiệm và 30 học sinh lớp 4A là 12 tuổi. Nếu không kể cô giáo chủ nhiệm thì tuổi trung bình cộng của 30 học sinh là 11. Hỏi cô giáo chủ nhiệm bao nhiêu tuổi?", "en": "The average age of the homeroom teacher and the 30 students of class 4A is 12 years. Without the teacher, the average age of the 30 students is 11 years. How old is the homeroom teacher?"}, "parts": [{"kind": "num", "lab": {"vi": "Tuổi cô giáo", "en": "Teacher's age"}, "ans": 42, "unit": {"vi": "tuổi", "en": "years old"}}], "steps": [{"vi": "Tổng số tuổi của 30 học sinh: 11 × 30 = 330 (tuổi).", "en": "Total age of the 30 students: 11 × 30 = 330 (years)."}, {"vi": "Cô giáo và học sinh có 30 + 1 = 31 người, tổng số tuổi: 12 × 31 = 372 (tuổi).", "en": "The teacher and students are 30 + 1 = 31 people, with total age: 12 × 31 = 372 (years)."}, {"vi": "Tuổi cô giáo: 372 − 330 = 42 (tuổi).", "en": "The teacher's age: 372 − 330 = 42 (years)."}], "tip": {"vi": "Đừng quên cô giáo cũng là một người trong nhóm.", "en": "Do not forget that the teacher is one more person in the group."}, "src": "250 bài, CĐ1, Bài 5"}, {"id": "cd1-b6", "lesson": "avg", "rank": 2, "q": {"vi": "An có 18 viên bi, Bình có 16 viên bi, Hùng có số viên bi bằng trung bình cộng số bi của An và Bình cộng thêm 6 viên bi, Dũng có số bi bằng trung bình cộng của cả 4 bạn. Hỏi Dũng có bao nhiêu viên bi?", "en": "An has 18 marbles, Binh has 16 marbles, Hung has as many marbles as the average of An's and Binh's marbles plus 6 more marbles, and Dung has as many marbles as the average of all 4 children. How many marbles does Dung have?"}, "parts": [{"kind": "num", "lab": {"vi": "Số bi của Dũng", "en": "Dung's marbles"}, "ans": 19, "unit": {"vi": "viên", "en": "marbles"}}], "steps": [{"vi": "Trung bình cộng của An và Bình: (18 + 16) : 2 = 17 (viên).", "en": "Average of An and Binh: (18 + 16) ÷ 2 = 17 (marbles)."}, {"vi": "Hùng có: 17 + 6 = 23 (viên).", "en": "Hung has: 17 + 6 = 23 (marbles)."}, {"vi": "Ba bạn An, Bình, Hùng có: 18 + 16 + 23 = 57 (viên).", "en": "An, Binh and Hung have: 18 + 16 + 23 = 57 (marbles)."}, {"vi": "Tổng 4 bạn bằng 4 lần số bi của Dũng, mà cũng bằng 57 cộng số bi của Dũng; vậy 3 lần số bi của Dũng bằng 57.", "en": "The total of 4 children is 4 times Dung's marbles, and also 57 plus Dung's marbles; so 3 times Dung's marbles is 57."}, {"vi": "Số bi của Dũng: 57 : 3 = 19 (viên).", "en": "Dung's marbles: 57 ÷ 3 = 19 (marbles)."}], "tip": {"vi": "Tổng 4 bạn bằng 4 lần số bi của Dũng.", "en": "The total of 4 children equals 4 times Dung's marbles."}, "src": "250 bài, CĐ1, Bài 6"}, {"id": "cd1-b8", "lesson": "avg", "rank": 2, "q": {"vi": "Trọng lượng của năm gói hàng trong một thùng hàng lần lượt là 700 g, 800 g, 800 g, 850 g và 900 g. Hỏi phải bỏ thêm một gói hàng nặng bao nhiêu gam vào thùng đó để trọng lượng trung bình của cả sáu gói sẽ tăng thêm 40 g?", "en": "The weights of five packages in a box are 700 g, 800 g, 800 g, 850 g and 900 g. How many grams must a new package weigh so that, when it is added to the box, the average weight of all six packages goes up by 40 g?"}, "parts": [{"kind": "num", "lab": {"vi": "Gói thêm nặng", "en": "New package weighs"}, "ans": 1050, "unit": {"vi": "g", "en": "g"}}], "steps": [{"vi": "Tổng trọng lượng 5 gói: 700 + 800 + 800 + 850 + 900 = 4050 (g).", "en": "Total weight of the 5 packages: 700 + 800 + 800 + 850 + 900 = 4,050 (g)."}, {"vi": "Trung bình cộng 5 gói: 4050 : 5 = 810 (g).", "en": "Average of the 5 packages: 4,050 ÷ 5 = 810 (g)."}, {"vi": "Trung bình cộng mới: 810 + 40 = 850 (g); tổng 6 gói: 850 × 6 = 5100 (g).", "en": "New average: 810 + 40 = 850 (g); total of 6 packages: 850 × 6 = 5,100 (g)."}, {"vi": "Gói thêm nặng: 5100 − 4050 = 1050 (g).", "en": "The new package weighs: 5,100 − 4,050 = 1,050 (g)."}], "tip": {"vi": "Tính trung bình cộng mới rồi tìm tổng của 6 gói.", "en": "Find the new average, then the total of 6 packages."}, "src": "250 bài, CĐ1, Bài 8"}, {"id": "cd1-b9", "lesson": "avg", "rank": 2, "q": {"vi": "Lớp 5A và 5B trồng được một số cây. Biết trung bình cộng số cây 2 lớp trồng được là 235. Nếu lớp 5A trồng thêm 80 cây và lớp 5B trồng thêm 40 cây thì số cây 2 lớp bằng nhau. Tính số cây mỗi lớp đã trồng.", "en": "Classes 5A and 5B planted some trees. The average number of trees planted by the 2 classes is 235. If class 5A planted 80 more trees and class 5B planted 40 more trees, the 2 classes would have the same number of trees. Find the number of trees each class planted."}, "parts": [{"kind": "num", "lab": {"vi": "Số cây lớp 5A", "en": "Class 5A trees"}, "ans": 215, "unit": {"vi": "cây", "en": "trees"}}, {"kind": "num", "lab": {"vi": "Số cây lớp 5B", "en": "Class 5B trees"}, "ans": 255, "unit": {"vi": "cây", "en": "trees"}}], "steps": [{"vi": "Tổng số cây của 2 lớp: 235 × 2 = 470 (cây).", "en": "Total trees of the 2 classes: 235 × 2 = 470 (trees)."}, {"vi": "Sau khi trồng thêm, tổng là 470 + 80 + 40 = 590 (cây).", "en": "After planting more, the total is 470 + 80 + 40 = 590 (trees)."}, {"vi": "Hai lớp bằng nhau nên mỗi lớp có 590 : 2 = 295 (cây).", "en": "The two classes are equal, so each has 590 ÷ 2 = 295 (trees)."}, {"vi": "Lớp 5A đã trồng: 295 − 80 = 215 (cây); lớp 5B đã trồng: 295 − 40 = 255 (cây).", "en": "Class 5A planted: 295 − 80 = 215 (trees); class 5B planted: 295 − 40 = 255 (trees)."}], "tip": {"vi": "Tìm tổng số cây sau khi trồng thêm.", "en": "Find the total number of trees after planting more."}, "src": "250 bài, CĐ1, Bài 9"}, {"id": "cd1-b11", "lesson": "avg", "rank": 3, "q": {"vi": "Trung bình cộng của 4 số bằng 25. Trung bình cộng của 3 số đầu bằng 22, của 3 số cuối bằng 20. Tìm trung bình cộng của số thứ hai và số thứ ba.", "en": "The average of 4 numbers is 25. The average of the first 3 numbers is 22, and the average of the last 3 numbers is 20. Find the average of the second and third numbers."}, "parts": [{"kind": "num", "lab": {"vi": "Trung bình cộng", "en": "Average"}, "ans": 13, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tổng 4 số: 25 × 4 = 100; tổng 3 số đầu: 22 × 3 = 66; tổng 3 số cuối: 20 × 3 = 60.", "en": "Sum of 4 numbers: 25 × 4 = 100; first 3: 22 × 3 = 66; last 3: 20 × 3 = 60."}, {"vi": "Số thứ tư: 100 − 66 = 34; số thứ nhất: 100 − 60 = 40.", "en": "Fourth number: 100 − 66 = 34; first number: 100 − 60 = 40."}, {"vi": "Tổng số thứ hai và thứ ba: 100 − 40 − 34 = 26.", "en": "Second + third: 100 − 40 − 34 = 26."}, {"vi": "Trung bình cộng của hai số đó: 26 : 2 = 13.", "en": "Their average: 26 ÷ 2 = 13."}], "tip": {"vi": "Tìm số thứ nhất và số thứ tư trước.", "en": "Find the first and the fourth numbers first."}, "src": "250 bài, CĐ1, Bài 11"}, {"id": "cd1-b13", "lesson": "avg", "rank": 3, "q": {"vi": "Trung bình cộng của 2 số bằng 57. Nếu gấp số thứ hai lên 3 lần thì trung bình cộng của chúng bằng 105. Tìm 2 số đó.", "en": "The average of 2 numbers is 57. If the second number is tripled, their average becomes 105. Find the 2 numbers."}, "parts": [{"kind": "num", "lab": {"vi": "Số thứ nhất", "en": "First number"}, "ans": 66, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số thứ hai", "en": "Second number"}, "ans": 48, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tổng 2 số lúc đầu: 57 × 2 = 114; tổng lúc sau: 105 × 2 = 210.", "en": "Sum at first: 57 × 2 = 114; sum after: 105 × 2 = 210."}, {"vi": "Tổng tăng: 210 − 114 = 96, đó là 2 lần số thứ hai (vì từ 1 lần thành 3 lần).", "en": "The sum went up by 210 − 114 = 96, which is 2 times the second number (1 time became 3 times)."}, {"vi": "Số thứ hai: 96 : 2 = 48.", "en": "Second number: 96 ÷ 2 = 48."}, {"vi": "Số thứ nhất: 114 − 48 = 66.", "en": "First number: 114 − 48 = 66."}], "tip": {"vi": "Tổng hai số tăng lên bao nhiêu khi gấp số thứ hai lên 3 lần?", "en": "By how much does the sum grow when the second number is tripled?"}, "src": "250 bài, CĐ1, Bài 13"}, {"id": "cd1-b14", "lesson": "avg", "rank": 3, "q": {"vi": "Khối lớp 4 của một trường Tiểu học có ba lớp. Biết rằng lớp 4A có 28 học sinh, lớp 4B có 26 học sinh. Trung bình số học sinh hai lớp 4A và 4C nhiều hơn trung bình số học sinh của ba lớp là 2 học sinh. Tính số học sinh lớp 4C.", "en": "Grade 4 at an elementary school has three classes. Class 4A has 28 students and class 4B has 26 students. The average number of students of classes 4A and 4C is 2 more than the average number of students of all three classes. Find the number of students in class 4C."}, "parts": [{"kind": "num", "lab": {"vi": "Số học sinh lớp 4C", "en": "Class 4C students"}, "ans": 36, "unit": {"vi": "học sinh", "en": "students"}}], "steps": [{"vi": "Gọi số học sinh lớp 4C là một đoạn thẳng. Trung bình 2 lớp 4A và 4C là 28 : 2 = 14 cộng {1/2} đoạn thẳng đó.", "en": "Draw the number of students of 4C as one bar. The average of 4A and 4C is 28 ÷ 2 = 14 plus {1/2} of that bar."}, {"vi": "Trung bình 3 lớp là (28 + 26) : 3 = 18 cộng {1/3} đoạn thẳng đó.", "en": "The average of the 3 classes is (28 + 26) ÷ 3 = 18 plus {1/3} of that bar."}, {"vi": "Hai trung bình hơn kém nhau 2: 14 + {1/2} = 18 + {1/3} + 2, nên {1/2} − {1/3} = 18 + 2 − 14 = 6.", "en": "They differ by 2: 14 + {1/2} = 18 + {1/3} + 2, so {1/2} − {1/3} = 18 + 2 − 14 = 6."}, {"vi": "Vậy {1/6} số học sinh lớp 4C là 6, số học sinh lớp 4C là 6 × 6 = 36.", "en": "So {1/6} of the students of 4C is 6, and class 4C has 6 × 6 = 36 students."}], "tip": {"vi": "Viết hai trung bình cộng theo số học sinh lớp 4C rồi so sánh.", "en": "Write both averages using the number of students of 4C, then compare."}, "src": "250 bài, CĐ1, Bài 14"}, {"id": "cd1-b7", "lesson": "avg", "rank": 3, "q": {"vi": "Lân có 20 viên bi. Long có số bi bằng một nửa số bi của Lân. Quý có số bi nhiều hơn trung bình cộng của 3 bạn là 6 viên bi. Hỏi Quý có bao nhiêu viên bi?", "en": "Lan has 20 marbles. Long has half as many marbles as Lan. Quy has 6 more marbles than the average of the 3 children. How many marbles does Quy have?"}, "parts": [{"kind": "num", "lab": {"vi": "Số bi của Quý", "en": "Quy's marbles"}, "ans": 24, "unit": {"vi": "viên", "en": "marbles"}}], "steps": [{"vi": "Long có: 20 : 2 = 10 (viên). Lân và Long có: 20 + 10 = 30 (viên).", "en": "Long has: 20 ÷ 2 = 10 (marbles). Lan and Long have: 20 + 10 = 30 (marbles)."}, {"vi": "Quý hơn trung bình cộng 6 viên, nên tổng 3 bạn = 30 + (trung bình cộng + 6).", "en": "Quy has 6 more than the average, so the total of 3 children = 30 + (average + 6)."}, {"vi": "Tổng 3 bạn cũng bằng 3 lần trung bình cộng; vậy 2 lần trung bình cộng bằng 30 + 6 = 36.", "en": "The total of 3 children is also 3 times the average; so 2 times the average is 30 + 6 = 36."}, {"vi": "Trung bình cộng: 36 : 2 = 18 (viên).", "en": "Average: 36 ÷ 2 = 18 (marbles)."}, {"vi": "Quý có: 18 + 6 = 24 (viên).", "en": "Quy has: 18 + 6 = 24 (marbles)."}], "tip": {"vi": "Gọi trung bình cộng là một đoạn thẳng, tổng 3 bạn là 3 đoạn như thế.", "en": "Draw the average as one bar; the total of 3 children is 3 such bars."}, "src": "250 bài, CĐ1, Bài 7"}], "cond": [{"id": "cd2-b1a", "lesson": "cond", "rank": 1, "q": {"vi": "Viết số tự nhiên lẻ, nhỏ nhất và có 3 chữ số khác nhau.", "en": "Write the smallest odd whole number with 3 different digits."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 103, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số nhỏ nhất có 3 chữ số: hàng trăm bé nhất là 1, hàng chục bé nhất là 0.", "en": "For the smallest 3-digit number: the hundreds digit is the smallest, 1, and the tens digit is the smallest, 0."}, {"vi": "Hàng đơn vị phải là số lẻ khác 1 và 0, bé nhất là 3.", "en": "The ones digit must be odd and different from 1 and 0, the smallest is 3."}, {"vi": "Số cần tìm là 103.", "en": "The number is 103."}], "tip": {"vi": "Số lẻ có chữ số hàng đơn vị là 1, 3, 5, 7 hoặc 9.", "en": "An odd number ends in 1, 3, 5, 7 or 9."}, "src": "250 bài, CĐ2, Bài 1a"}, {"id": "cd2-b1b", "lesson": "cond", "rank": 1, "q": {"vi": "Viết số tự nhiên lớn nhất có 4 chữ số khác nhau.", "en": "Write the largest whole number with 4 different digits."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 9876, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số lớn nhất: chọn chữ số lớn nhất cho các hàng cao.", "en": "For the largest number, put the biggest digits in the highest places."}, {"vi": "Hàng nghìn là 9, hàng trăm là 8, hàng chục là 7, hàng đơn vị là 6.", "en": "Thousands 9, hundreds 8, tens 7, ones 6."}, {"vi": "Số cần tìm là 9876.", "en": "The number is 9,876."}], "tip": {"vi": "Số nhỏ nhất: ít chữ số nhất, chữ số nhỏ ở hàng cao. Số lớn nhất: nhiều chữ số nhất, chữ số lớn ở hàng cao.", "en": "For the smallest number: fewest digits, small digits in high places. For the largest number: most digits, big digits in high places."}, "src": "250 bài, CĐ2, Bài 1b"}, {"id": "cd2-b2a", "lesson": "cond", "rank": 1, "q": {"vi": "Viết số tự nhiên lớn nhất có 8 chữ số khác nhau.", "en": "Write the largest whole number with 8 different digits."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 98765432, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Viết các chữ số lớn nhất, giảm dần từ trái sang phải.", "en": "Write the biggest digits, going down from left to right."}, {"vi": "8 chữ số lớn nhất khác nhau là 9, 8, 7, 6, 5, 4, 3, 2, nên số cần tìm là 98 765 432.", "en": "The 8 biggest different digits are 9, 8, 7, 6, 5, 4, 3, 2, so the number is 98,765,432."}], "tip": {"vi": "Số nhỏ nhất: ít chữ số nhất, chữ số nhỏ ở hàng cao. Số lớn nhất: nhiều chữ số nhất, chữ số lớn ở hàng cao.", "en": "For the smallest number: fewest digits, small digits in high places. For the largest number: most digits, big digits in high places."}, "src": "250 bài, CĐ2, Bài 2a"}, {"id": "cd2-b1c", "lesson": "cond", "rank": 2, "q": {"vi": "Viết số tự nhiên lẻ, nhỏ nhất có 7 chữ số khác nhau.", "en": "Write the smallest odd whole number with 7 different digits."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 1023457, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số nhỏ nhất có 7 chữ số khác nhau là 1 023 456, nhưng số này chẵn.", "en": "The smallest 7-digit number with different digits is 1,023,456, but it is even."}, {"vi": "Cần chữ số hàng đơn vị lẻ. Các chữ số 1, 3, 5 đã dùng, nên chọn 7 cho hàng đơn vị.", "en": "The ones digit must be odd. The digits 1, 3, 5 are already used, so choose 7 for the ones place."}, {"vi": "Các hàng còn lại giữ nhỏ dần: 1 023 45, số cần tìm là 1 023 457.", "en": "Keep the other places as small as possible: 1,023,45_, so the number is 1,023,457."}], "tip": {"vi": "Chọn chữ số hàng đơn vị lẻ bé nhất chưa dùng.", "en": "Pick the smallest odd digit that is not already used."}, "src": "250 bài, CĐ2, Bài 1c"}, {"id": "cd2-b1d", "lesson": "cond", "rank": 2, "q": {"vi": "Viết số tự nhiên chẵn, nhỏ nhất và có 10 chữ số khác nhau.", "en": "Write the smallest even whole number with 10 different digits."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 1023456798, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số có 10 chữ số khác nhau dùng đủ 10 chữ số từ 0 đến 9.", "en": "A number with 10 different digits uses every digit from 0 to 9."}, {"vi": "Số nhỏ nhất là 1 023 456 789 nhưng số này lẻ.", "en": "The smallest such number is 1,023,456,789 but it is odd."}, {"vi": "Đổi chỗ hai chữ số cuối để hàng đơn vị là số chẵn: 1 023 456 798.", "en": "Swap the last two digits so the ones digit is even: 1,023,456,798."}], "tip": {"vi": "Chữ số 0 không được đứng đầu.", "en": "The digit 0 cannot be the first digit."}, "src": "250 bài, CĐ2, Bài 1d"}, {"id": "cd2-b2b", "lesson": "cond", "rank": 2, "q": {"vi": "Viết số lẻ lớn nhất có 6 chữ số khác nhau.", "en": "Write the largest odd number with 6 different digits."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 987653, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số lớn nhất có 6 chữ số khác nhau là 987 654 nhưng số này chẵn.", "en": "The largest 6-digit number with different digits is 987,654 but it is even."}, {"vi": "Hàng đơn vị phải lẻ: chọn số lẻ lớn nhất chưa dùng là 3 (vì 9, 7, 5 đã dùng).", "en": "The ones digit must be odd: choose the biggest unused odd digit, 3 (9, 7, 5 are used)."}, {"vi": "Các hàng còn lại là 9, 8, 7, 6, 5 nên số cần tìm là 987 653.", "en": "The other places are 9, 8, 7, 6, 5, so the number is 987,653."}], "tip": {"vi": "Chọn hàng đơn vị trước.", "en": "Choose the ones digit first."}, "src": "250 bài, CĐ2, Bài 2b"}, {"id": "cd2-b2c", "lesson": "cond", "rank": 2, "q": {"vi": "Viết số chẵn bé nhất có 5 chữ số khác nhau.", "en": "Write the smallest even number with 5 different digits."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 10234, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số bé nhất có 5 chữ số khác nhau là 10 234.", "en": "The smallest 5-digit number with different digits is 10,234."}, {"vi": "Chữ số hàng đơn vị là 4, đây là số chẵn nên không cần đổi.", "en": "The ones digit is 4, which is even, so no change is needed."}, {"vi": "Số cần tìm là 10 234.", "en": "The number is 10,234."}], "tip": {"vi": "Hãy kiểm tra xem số bé nhất có sẵn chẵn không.", "en": "Check whether the smallest number is already even."}, "src": "250 bài, CĐ2, Bài 2c"}, {"id": "cd2-b2d", "lesson": "cond", "rank": 2, "q": {"vi": "Viết số bé nhất có 7 chữ số khác nhau bắt đầu bởi chữ số 8.", "en": "Write the smallest number with 7 different digits that starts with the digit 8."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 8012345, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Chữ số đầu tiên là 8; các hàng còn lại phải nhỏ nhất có thể và khác nhau.", "en": "The first digit is 8; the other places must be as small as possible and different."}, {"vi": "Sáu chữ số nhỏ nhất còn lại là 0, 1, 2, 3, 4, 5 theo thứ tự tăng dần.", "en": "The six smallest remaining digits are 0, 1, 2, 3, 4, 5 in increasing order."}, {"vi": "Số cần tìm là 8 012 345.", "en": "The number is 8,012,345."}], "tip": {"vi": "Chữ số 0 được phép ở các hàng sau hàng đầu.", "en": "The digit 0 is allowed in the places after the first."}, "src": "250 bài, CĐ2, Bài 2d"}, {"id": "cd2-b3a", "lesson": "cond", "rank": 2, "q": {"vi": "Viết số lớn nhất sao cho kể từ trái sang phải, mỗi chữ số của nó đều lớn hơn chữ số đứng liền sau là 2 đơn vị.", "en": "Write the largest number such that, going from left to right, each of its digits is 2 more than the digit right after it."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 97531, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Để số lớn nhất, chữ số đầu là 9 và số có nhiều chữ số nhất.", "en": "For the largest number, the first digit is 9 and the number has as many digits as possible."}, {"vi": "Mỗi chữ số kém chữ số trước 2 đơn vị: 9, 7, 5, 3, 1.", "en": "Each digit is 2 less than the one before: 9, 7, 5, 3, 1."}, {"vi": "Sau 1 không còn chữ số nào nhỏ hơn 2 đơn vị, nên số cần tìm là 97 531.", "en": "After 1 there is no digit 2 less, so the number is 97,531."}], "tip": {"vi": "Bắt đầu từ chữ số 9 và giảm dần 2 đơn vị.", "en": "Start from 9 and go down by 2 each time."}, "src": "250 bài, CĐ2, Bài 3a"}, {"id": "cd2-b4b", "lesson": "cond", "rank": 2, "q": {"vi": "Viết số nhỏ nhất có tổng các chữ số bằng 30.", "en": "Write the smallest number whose digits add up to 30."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 3999, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Mỗi chữ số tối đa là 9; 3 chữ số có tổng tối đa 27 < 30, nên số nhỏ nhất có 4 chữ số.", "en": "Each digit is at most 9; 3 digits add to at most 27, less than 30, so the smallest number has 4 digits."}, {"vi": "Để số nhỏ nhất, các hàng thấp nhận 9: ba chữ số cuối là 9, 9, 9 (tổng 27).", "en": "To make it smallest, the low places get 9: the last three digits are 9, 9, 9 (sum 27)."}, {"vi": "Chữ số đầu tiên: 30 − 27 = 3. Số cần tìm là 3999.", "en": "The first digit: 30 − 27 = 3. The number is 3,999."}], "tip": {"vi": "Dùng các chữ số 9 ở những hàng thấp.", "en": "Use the 9s in the lowest places."}, "src": "250 bài, CĐ2, Bài 4b"}, {"id": "cd2-b5a", "lesson": "cond", "rank": 2, "q": {"vi": "Hãy viết số tự nhiên nhỏ nhất có tích các chữ số bằng 120.", "en": "Write the smallest whole number whose digits have a product of 120."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 358, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hai chữ số có tích tối đa 9 × 9 = 81 < 120, nên số nhỏ nhất có ít nhất 3 chữ số.", "en": "Two digits have a product of at most 9 × 9 = 81, less than 120, so the number has at least 3 digits."}, {"vi": "Phân tích 120 thành tích 3 chữ số: 120 = 3 × 5 × 8 = 4 × 5 × 6.", "en": "Write 120 as a product of 3 digits: 120 = 3 × 5 × 8 = 4 × 5 × 6."}, {"vi": "Xếp tăng dần được 358 và 456; số nhỏ hơn là 358.", "en": "In increasing order they give 358 and 456; the smaller is 358."}], "tip": {"vi": "Số nhỏ nhất cần ít chữ số nhất.", "en": "The smallest number needs the fewest digits."}, "src": "250 bài, CĐ2, Bài 5a"}, {"id": "cd2-b6a", "lesson": "cond", "rank": 2, "q": {"vi": "Viết số tự nhiên nhỏ nhất có tổng các chữ số bằng 35.", "en": "Write the smallest whole number whose digits add up to 35."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 8999, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "3 chữ số có tổng tối đa 27 < 35, nên số nhỏ nhất có 4 chữ số.", "en": "3 digits add to at most 27, less than 35, so the smallest number has 4 digits."}, {"vi": "Ba chữ số cuối là 9, 9, 9 (tổng 27); chữ số đầu là 35 − 27 = 8.", "en": "The last three digits are 9, 9, 9 (sum 27); the first digit is 35 − 27 = 8."}, {"vi": "Số cần tìm là 8999.", "en": "The number is 8,999."}], "tip": {"vi": "Dùng chữ số 9 ở các hàng thấp.", "en": "Use 9s in the lowest places."}, "src": "250 bài, CĐ2, Bài 6a"}, {"id": "cd2-b6b", "lesson": "cond", "rank": 2, "q": {"vi": "Viết số tự nhiên nhỏ nhất có tổng các chữ số bằng 52.", "en": "Write the smallest whole number whose digits add up to 52."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 799999, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "5 chữ số có tổng tối đa 45 < 52, nên số nhỏ nhất có 6 chữ số.", "en": "5 digits add to at most 45, less than 52, so the smallest number has 6 digits."}, {"vi": "Năm chữ số cuối là 9 (tổng 45); chữ số đầu là 52 − 45 = 7.", "en": "The last five digits are 9 (sum 45); the first digit is 52 − 45 = 7."}, {"vi": "Số cần tìm là 799 999.", "en": "The number is 799,999."}], "tip": {"vi": "Có bao nhiêu chữ số ít nhất để có tổng 52?", "en": "What is the fewest number of digits that can add up to 52?"}, "src": "250 bài, CĐ2, Bài 6b"}, {"id": "cd2-b6c", "lesson": "cond", "rank": 2, "q": {"vi": "Viết số tự nhiên lớn nhất có các chữ số khác 0 và tổng các chữ số bằng 7.", "en": "Write the largest whole number whose digits are all different from 0 and add up to 7."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 1111111, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số lớn nhất cần nhiều chữ số nhất; các chữ số khác 0 nên mỗi chữ số ít nhất là 1.", "en": "The largest number needs the most digits; the digits are not 0, so each digit is at least 1."}, {"vi": "Nhiều chữ số nhất là 7 chữ số, mỗi chữ số bằng 1 (tổng 7).", "en": "The most digits is 7 digits, each equal to 1 (sum 7)."}, {"vi": "Số cần tìm là 1 111 111.", "en": "The number is 1,111,111."}], "tip": {"vi": "Dùng chữ số bé nhất có thể để số có nhiều chữ số.", "en": "Use the smallest digits so that the number has many digits."}, "src": "250 bài, CĐ2, Bài 6c"}, {"id": "cd3-b5a", "lesson": "cond", "rank": 2, "q": {"vi": "Có bao nhiêu số có 4 chữ số mà tổng các chữ số là 3?", "en": "How many 4-digit numbers have digits that add up to 3?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số", "en": "Count"}, "ans": 10, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Chữ số hàng nghìn là 1, 2 hoặc 3.", "en": "The thousands digit is 1, 2 or 3."}, {"vi": "Hàng nghìn là 3: số 3 000 (1 số). Hàng nghìn là 2: ba chữ số còn lại có tổng 1: 2 001, 2 010, 2 100 (3 số).", "en": "Thousands digit 3: 3,000 (1 number). Thousands digit 2: the other digits add to 1: 2,001, 2,010, 2,100 (3 numbers)."}, {"vi": "Hàng nghìn là 1: ba chữ số còn lại có tổng 2: 1 002, 1 011, 1 020, 1 101, 1 110, 1 200 (6 số).", "en": "Thousands digit 1: the other digits add to 2: 1,002, 1,011, 1,020, 1,101, 1,110, 1,200 (6 numbers)."}, {"vi": "Có 1 + 3 + 6 = 10 số.", "en": "There are 1 + 3 + 6 = 10 numbers."}], "tip": {"vi": "Chia theo chữ số hàng nghìn.", "en": "Split by the thousands digit."}, "src": "250 bài, CĐ3, Bài 5a"}, {"id": "cd3-b5b", "lesson": "cond", "rank": 2, "q": {"vi": "Có bao nhiêu số có 2 chữ số mà hiệu của hai chữ số (số lớn trừ số bé) là 2?", "en": "How many 2-digit numbers have digits whose difference (bigger digit minus smaller digit) is 2?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số", "en": "Count"}, "ans": 15, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Chữ số hàng chục lớn hơn chữ số hàng đơn vị 2 đơn vị: 20, 31, 42, 53, 64, 75, 86, 97 (8 số).", "en": "The tens digit is 2 more than the ones digit: 20, 31, 42, 53, 64, 75, 86, 97 (8 numbers)."}, {"vi": "Chữ số hàng đơn vị lớn hơn chữ số hàng chục 2 đơn vị: 13, 24, 35, 46, 57, 68, 79 (7 số).", "en": "The ones digit is 2 more than the tens digit: 13, 24, 35, 46, 57, 68, 79 (7 numbers)."}, {"vi": "Có 8 + 7 = 15 số.", "en": "There are 8 + 7 = 15 numbers."}], "tip": {"vi": "Xét hai trường hợp: chữ số nào lớn hơn.", "en": "Look at two cases: which digit is bigger."}, "src": "250 bài, CĐ3, Bài 5b"}, {"id": "cd2-b3b", "lesson": "cond", "rank": 3, "q": {"vi": "Viết số lớn nhất sao cho kể từ trái sang phải, số đó có 2 chữ số 1 (ở đầu) và từ chữ số thứ ba trở đi thì mỗi chữ số đều bằng tổng 2 chữ số đứng liền trước nó.", "en": "Write the largest number such that, going from left to right, it starts with two digits 1 and from the third digit on, each digit equals the sum of the 2 digits right before it."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 112358, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hai chữ số đầu là 1 và 1.", "en": "The first two digits are 1 and 1."}, {"vi": "Chữ số thứ ba: 1 + 1 = 2; thứ tư: 1 + 2 = 3; thứ năm: 2 + 3 = 5; thứ sáu: 3 + 5 = 8.", "en": "Third digit: 1 + 1 = 2; fourth: 1 + 2 = 3; fifth: 2 + 3 = 5; sixth: 3 + 5 = 8."}, {"vi": "Chữ số tiếp theo là 5 + 8 = 13, không phải chữ số, nên dừng lại. Số cần tìm là 112 358.", "en": "The next would be 5 + 8 = 13, which is not a digit, so we stop. The number is 112,358."}], "tip": {"vi": "Số có nhiều chữ số hơn thì lớn hơn.", "en": "A number with more digits is larger."}, "src": "250 bài, CĐ2, Bài 3b"}, {"id": "cd2-b4a", "lesson": "cond", "rank": 3, "q": {"vi": "Viết số tự nhiên lớn nhất có các chữ số khác nhau mà tổng các chữ số của số đó bằng 12.", "en": "Write the largest whole number with different digits whose digits add up to 12."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 63210, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số lớn nhất cần nhiều chữ số nhất. Với 6 chữ số khác nhau, tổng nhỏ nhất là 0 + 1 + 2 + 3 + 4 + 5 = 15, lớn hơn 12; vậy chỉ có tối đa 5 chữ số.", "en": "The largest number needs the most digits. With 6 different digits the smallest sum is 0 + 1 + 2 + 3 + 4 + 5 = 15, more than 12; so there are at most 5 digits."}, {"vi": "Các bộ 5 chữ số khác nhau có tổng 12 là {0, 1, 2, 3, 6} và {0, 1, 2, 4, 5}.", "en": "The sets of 5 different digits with sum 12 are {0, 1, 2, 3, 6} and {0, 1, 2, 4, 5}."}, {"vi": "Xếp giảm dần được 63 210 và 54 210; số lớn hơn là 63 210.", "en": "In decreasing order they give 63,210 and 54,210; the larger is 63,210."}], "tip": {"vi": "Tìm số chữ số nhiều nhất có thể trước.", "en": "First find the greatest possible number of digits."}, "src": "250 bài, CĐ2, Bài 4a"}, {"id": "cd2-b5b", "lesson": "cond", "rank": 3, "q": {"vi": "Hãy viết số tự nhiên lớn nhất có các chữ số khác nhau và có tích các chữ số bằng 120.", "en": "Write the largest whole number with different digits whose digits have a product of 120."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 54321, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Chữ số 0 làm tích bằng 0 nên không dùng. Số lớn nhất cần nhiều chữ số nhất.", "en": "The digit 0 would make the product 0, so it is not used. The largest number needs the most digits."}, {"vi": "Có thể dùng 1 × 2 × 3 × 4 × 5 = 120 (5 chữ số). Với 6 chữ số khác nhau, tích nhỏ nhất là 1 × 2 × 3 × 4 × 5 × 6 = 720 > 120.", "en": "We can use 1 × 2 × 3 × 4 × 5 = 120 (5 digits). With 6 different digits the smallest product is 1 × 2 × 3 × 4 × 5 × 6 = 720 > 120."}, {"vi": "Xếp giảm dần các chữ số 5, 4, 3, 2, 1 được 54 321.", "en": "Arranging 5, 4, 3, 2, 1 in decreasing order gives 54,321."}], "tip": {"vi": "Thử dùng các chữ số 1, 2, 3, 4, 5.", "en": "Try the digits 1, 2, 3, 4, 5."}, "src": "250 bài, CĐ2, Bài 5b"}, {"id": "cd2-b6d", "lesson": "cond", "rank": 3, "q": {"vi": "Viết số tự nhiên lớn nhất và số tự nhiên nhỏ nhất có các chữ số khác nhau mà tổng các chữ số của số đó bằng 34.", "en": "Write the largest and the smallest whole numbers with different digits whose digits add up to 34."}, "parts": [{"kind": "num", "lab": {"vi": "Số lớn nhất", "en": "Largest number"}, "ans": 98743210, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số nhỏ nhất", "en": "Smallest number"}, "ans": 46789, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tổng 10 chữ số từ 0 đến 9 là 45. Không bỏ được 1 chữ số (45 − 34 = 11 không phải chữ số), nên lớn nhất có 8 chữ số, bỏ hai chữ số có tổng 11.", "en": "The 10 digits 0 to 9 add up to 45. We cannot leave out 1 digit (45 − 34 = 11 is not a digit), so the largest number has 8 digits, leaving out two digits with sum 11."}, {"vi": "Để số lớn nhất, bỏ hai chữ số 5 và 6 (các chữ số nhỏ nhất có thể bỏ ở hàng thấp): dùng 9, 8, 7, 4, 3, 2, 1, 0 được 98 743 210.", "en": "For the largest number, leave out 5 and 6: use 9, 8, 7, 4, 3, 2, 1, 0 to get 98,743,210."}, {"vi": "Số nhỏ nhất cần ít chữ số nhất: 4 chữ số có tổng tối đa 9 + 8 + 7 + 6 = 30 < 34; 5 chữ số cần tổng 34 = 9 + 8 + 7 + 6 + 4.", "en": "The smallest number needs the fewest digits: 4 digits add to at most 9 + 8 + 7 + 6 = 30 < 34; 5 digits work with 34 = 9 + 8 + 7 + 6 + 4."}, {"vi": "Xếp tăng dần 4, 6, 7, 8, 9 được 46 789.", "en": "Arranging 4, 6, 7, 8, 9 in increasing order gives 46,789."}], "tip": {"vi": "Tổng các chữ số từ 0 đến 9 là 45.", "en": "The digits 0 to 9 add up to 45."}, "src": "250 bài, CĐ2, Bài 6d"}, {"id": "cd2-b7a", "lesson": "cond", "rank": 3, "q": {"vi": "Viết số tự nhiên lớn nhất và số tự nhiên nhỏ nhất có các chữ số khác nhau mà tích các chữ số của số đó bằng 40.", "en": "Write the largest and the smallest whole numbers with different digits whose digits have a product of 40."}, "parts": [{"kind": "num", "lab": {"vi": "Số lớn nhất", "en": "Largest number"}, "ans": 5421, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số nhỏ nhất", "en": "Smallest number"}, "ans": 58, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số nhỏ nhất: 1 chữ số không được (tích tối đa 9); 2 chữ số có 40 = 5 × 8, nên số nhỏ nhất là 58.", "en": "Smallest number: 1 digit is not enough (product at most 9); with 2 digits 40 = 5 × 8, so the smallest number is 58."}, {"vi": "Số lớn nhất cần nhiều chữ số khác nhau nhất, không dùng 0: 40 = 1 × 2 × 4 × 5 (4 chữ số).", "en": "The largest number needs the most different digits, without 0: 40 = 1 × 2 × 4 × 5 (4 digits)."}, {"vi": "5 chữ số khác nhau khác 0 có tích ít nhất 120 > 40, nên chỉ có 4 chữ số; xếp giảm dần được 5 421.", "en": "5 different non-zero digits have a product of at least 120 > 40, so only 4 digits; in decreasing order: 5,421."}], "tip": {"vi": "Không dùng chữ số 0, vì khi đó tích bằng 0.", "en": "Do not use the digit 0, because the product would be 0."}, "src": "250 bài, CĐ2, Bài 7a"}, {"id": "cd2-b7b", "lesson": "cond", "rank": 3, "q": {"vi": "Viết số tự nhiên chẵn lớn nhất và số tự nhiên chẵn bé nhất có các chữ số khác nhau mà tích các chữ số của số đó bằng 60.", "en": "Write the largest even whole number and the smallest even whole number with different digits whose digits have a product of 60."}, "parts": [{"kind": "num", "lab": {"vi": "Số chẵn lớn nhất", "en": "Largest even number"}, "ans": 6512, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số chẵn bé nhất", "en": "Smallest even number"}, "ans": 256, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "60 = 1 × 2 × 5 × 6 = 1 × 3 × 4 × 5 (4 chữ số) và 60 = 2 × 5 × 6 = 3 × 4 × 5 (3 chữ số); 5 chữ số khác nhau khác 0 có tích ít nhất 120.", "en": "60 = 1 × 2 × 5 × 6 = 1 × 3 × 4 × 5 (4 digits) and 60 = 2 × 5 × 6 = 3 × 4 × 5 (3 digits); 5 different non-zero digits have a product of at least 120."}, {"vi": "Lớn nhất: dùng 4 chữ số. Bộ 6, 5, 2, 1 xếp 6 521 là số lẻ, nên đổi thành 6 512 (chẵn); bộ 5, 4, 3, 1 cho số chẵn nhỏ hơn 5 413. Số lớn nhất là 6 512.", "en": "Largest: use 4 digits. The set 6, 5, 2, 1 gives 6,521 which is odd, so use 6,512 (even); the set 5, 4, 3, 1 gives smaller even numbers like 5,413. The largest is 6,512."}, {"vi": "Bé nhất: dùng 3 chữ số (2 chữ số không đủ vì 9 × 9 = 81 nhưng không có tích 60). Bộ 2, 5, 6 cho số chẵn bé nhất 256; bộ 3, 4, 5 cho 354. Số bé nhất là 256.", "en": "Smallest: use 3 digits (no 2 digits multiply to 60). The set 2, 5, 6 gives the smallest even number 256; the set 3, 4, 5 gives 354. The smallest is 256."}], "tip": {"vi": "Chữ số hàng đơn vị phải là 0, 2, 4, 6 hoặc 8.", "en": "The ones digit must be 0, 2, 4, 6 or 8."}, "src": "250 bài, CĐ2, Bài 7b"}, {"id": "cd2-b7c", "lesson": "cond", "rank": 3, "q": {"vi": "Viết số tự nhiên nhỏ nhất có các chữ số khác nhau mà tích các chữ số của số đó bằng 720.", "en": "Write the smallest whole number with different digits whose digits have a product of 720."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 2589, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "3 chữ số có tích tối đa 9 × 8 × 7 = 504 < 720, nên số nhỏ nhất có ít nhất 4 chữ số.", "en": "3 digits have a product of at most 9 × 8 × 7 = 504, less than 720, so the number has at least 4 digits."}, {"vi": "Phân tích 720 thành 4 chữ số khác nhau: 720 = 2 × 5 × 8 × 9 = 3 × 5 × 6 × 8.", "en": "Write 720 as 4 different digits: 720 = 2 × 5 × 8 × 9 = 3 × 5 × 6 × 8."}, {"vi": "Xếp tăng dần được 2 589 và 3 568; số nhỏ hơn là 2 589.", "en": "In increasing order they give 2,589 and 3,568; the smaller is 2,589."}], "tip": {"vi": "Chữ số đầu càng nhỏ thì số càng bé.", "en": "The smaller the first digit, the smaller the number."}, "src": "250 bài, CĐ2, Bài 7c"}, {"id": "cd3-b15a", "lesson": "cond", "rank": 3, "q": {"vi": "Tìm số lượng các số tự nhiên có 4 chữ số mà số tạo bởi 2 chữ số đầu (theo thứ tự ấy) lớn hơn số tạo bởi 2 chữ số cuối (theo thứ tự ấy).", "en": "Find how many 4-digit natural numbers have the number formed by the first 2 digits (in that order) greater than the number formed by the last 2 digits (in that order)."}, "parts": [{"kind": "num", "lab": {"vi": "Số các số", "en": "Count"}, "ans": 4905, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Gọi số có dạng abcd; ab là số có 2 chữ số từ 10 đến 99, cd là số từ 00 đến 99, cần ab > cd.", "en": "Write the number as abcd; ab is from 10 to 99, cd is from 00 to 99, and we need ab > cd."}, {"vi": "Với ab = m thì cd có thể là 0, 1, …, m − 1 nên có m cách.", "en": "If ab = m, then cd can be 0, 1, …, m − 1, which is m choices."}, {"vi": "Tổng số cách là 10 + 11 + … + 99 = (10 + 99) × 90 : 2 = 4 905.", "en": "The total is 10 + 11 + … + 99 = (10 + 99) × 90 ÷ 2 = 4,905."}], "tip": {"vi": "Cố định hai chữ số đầu rồi đếm hai chữ số cuối.", "en": "Fix the first two digits, then count the last two."}, "src": "250 bài, CĐ3, Bài 15a"}], "count": [{"id": "cd3-b1a", "lesson": "count", "rank": 1, "q": {"vi": "Cho 4 chữ số 0, 3, 8 và 9. Viết được tất cả bao nhiêu số có 4 chữ số khác nhau từ 4 chữ số đã cho?", "en": "Given the 4 digits 0, 3, 8 and 9. How many 4-digit numbers with all different digits can be written using these 4 digits?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số", "en": "Count"}, "ans": 18, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Chữ số hàng nghìn không được là 0 nên có 3 cách chọn (3, 8 hoặc 9).", "en": "The thousands digit cannot be 0, so there are 3 choices (3, 8 or 9)."}, {"vi": "Hàng trăm: còn 3 chữ số nên có 3 cách; hàng chục: 2 cách; hàng đơn vị: 1 cách.", "en": "Hundreds: 3 digits left, so 3 choices; tens: 2 choices; ones: 1 choice."}, {"vi": "Số các số là 3 × 3 × 2 × 1 = 18.", "en": "The count is 3 × 3 × 2 × 1 = 18."}], "tip": {"vi": "Chữ số 0 không được đứng đầu số.", "en": "The digit 0 cannot be the first digit."}, "src": "250 bài, CĐ3, Bài 1a"}, {"id": "cd3-b1b1", "lesson": "count", "rank": 1, "q": {"vi": "Cho 4 chữ số 0, 3, 8 và 9. Số lớn nhất có 4 chữ số khác nhau viết từ 4 chữ số đó là số nào?", "en": "Given the 4 digits 0, 3, 8 and 9. What is the largest 4-digit number with all different digits made from these digits?"}, "parts": [{"kind": "num", "lab": {"vi": "Số lớn nhất", "en": "Largest number"}, "ans": 9830, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Muốn số lớn nhất, ta xếp các chữ số từ lớn đến bé.", "en": "For the largest number, put the digits in order from biggest to smallest."}, {"vi": "Thứ tự là 9, 8, 3, 0 nên số lớn nhất là 9 830.", "en": "The order is 9, 8, 3, 0, so the largest number is 9,830."}], "tip": {"vi": "Chữ số lớn nhất đứng ở hàng cao nhất.", "en": "Put the biggest digit in the highest place."}, "src": "250 bài, CĐ3, Bài 1b"}, {"id": "cd3-b1b2", "lesson": "count", "rank": 1, "q": {"vi": "Cho 4 chữ số 0, 3, 8 và 9. Số nhỏ nhất có 4 chữ số khác nhau viết từ 4 chữ số đó là số nào?", "en": "Given the 4 digits 0, 3, 8 and 9. What is the smallest 4-digit number with all different digits made from these digits?"}, "parts": [{"kind": "num", "lab": {"vi": "Số nhỏ nhất", "en": "Smallest number"}, "ans": 3089, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Chữ số hàng nghìn phải khác 0 và nhỏ nhất có thể, nên chọn 3.", "en": "The thousands digit must not be 0 and as small as possible, so choose 3."}, {"vi": "Các hàng còn lại xếp tăng dần: 0, 8, 9. Số nhỏ nhất là 3 089.", "en": "Put the other digits in increasing order: 0, 8, 9. The smallest number is 3,089."}], "tip": {"vi": "Số 0 không thể đứng đầu.", "en": "0 cannot come first."}, "src": "250 bài, CĐ3, Bài 1b"}, {"id": "cd3-b21", "lesson": "count", "rank": 1, "q": {"vi": "Trong hội nghị cháu ngoan Bác Hồ có 30 bạn tham dự. Vui mừng, phấn khởi nên cứ 2 bạn bắt tay nhau làm quen 1 lần. Hỏi có tất cả bao nhiêu cái bắt tay?", "en": "At a good-students conference, 30 students attend. Happily, every 2 students shake hands once to get to know each other. How many handshakes are there in all?"}, "parts": [{"kind": "num", "lab": {"vi": "Số cái bắt tay", "en": "Handshakes"}, "ans": 435, "unit": {"vi": "cái", "en": "handshakes"}}], "steps": [{"vi": "Mỗi bạn bắt tay với 29 bạn còn lại, tính được 30 × 29 = 870 lượt.", "en": "Each student shakes hands with the other 29, giving 30 × 29 = 870 counts."}, {"vi": "Mỗi cái bắt tay được tính 2 lần (một lần cho mỗi bạn).", "en": "Each handshake was counted twice (once for each student)."}, {"vi": "Số cái bắt tay là 870 : 2 = 435.", "en": "The number of handshakes is 870 ÷ 2 = 435."}], "tip": {"vi": "Mỗi cái bắt tay có hai người tham gia.", "en": "Every handshake involves two people."}, "src": "250 bài, CĐ3, Bài 21"}, {"id": "cd3-b2a", "lesson": "count", "rank": 1, "q": {"vi": "Cho 5 chữ số 1; 4; 6; 8; 9. Có thể viết được bao nhiêu số có 4 chữ số từ 5 chữ số đã cho (các chữ số có thể lặp lại)?", "en": "Given the 5 digits 1, 4, 6, 8, 9. How many 4-digit numbers can be written using these digits (digits may repeat)?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số", "en": "Count"}, "ans": 625, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Mỗi hàng (nghìn, trăm, chục, đơn vị) đều chọn được 1 trong 5 chữ số.", "en": "Each place (thousands, hundreds, tens, ones) can be any of the 5 digits."}, {"vi": "Số các số là 5 × 5 × 5 × 5 = 625.", "en": "The count is 5 × 5 × 5 × 5 = 625."}], "tip": {"vi": "Mỗi hàng có 5 cách chọn.", "en": "Each place has 5 choices."}, "src": "250 bài, CĐ3, Bài 2a"}, {"id": "cd3-b1c1", "lesson": "count", "rank": 2, "q": {"vi": "Cho 4 chữ số 0, 3, 8 và 9. Số lẻ lớn nhất có 4 chữ số khác nhau viết từ 4 chữ số đó là số nào?", "en": "Given the 4 digits 0, 3, 8 and 9. What is the largest odd 4-digit number with all different digits made from these digits?"}, "parts": [{"kind": "num", "lab": {"vi": "Số lẻ lớn nhất", "en": "Largest odd number"}, "ans": 9803, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số lẻ phải tận cùng bằng 3 hoặc 9. Để số lớn nhất, ta thử tận cùng bằng 3 trước (chữ số 9 giữ ở hàng nghìn).", "en": "An odd number must end in 3 or 9. To keep the number big, put 9 in the thousands place, so the last digit is 3."}, {"vi": "Xếp các chữ số còn lại (8, 0) giảm dần ở hàng trăm và chục: 9 8 0 3.", "en": "Put the remaining digits (8, 0) in decreasing order in the hundreds and tens: 9 8 0 3."}, {"vi": "Số lẻ lớn nhất là 9 803.", "en": "The largest odd number is 9,803."}], "tip": {"vi": "Chữ số hàng đơn vị của số lẻ là 3 hoặc 9.", "en": "An odd number ends in 3 or 9."}, "src": "250 bài, CĐ3, Bài 1c"}, {"id": "cd3-b1c2", "lesson": "count", "rank": 2, "q": {"vi": "Cho 4 chữ số 0, 3, 8 và 9. Số chẵn nhỏ nhất có 4 chữ số khác nhau viết từ 4 chữ số đó là số nào?", "en": "Given the 4 digits 0, 3, 8 and 9. What is the smallest even 4-digit number with all different digits made from these digits?"}, "parts": [{"kind": "num", "lab": {"vi": "Số chẵn nhỏ nhất", "en": "Smallest even number"}, "ans": 3098, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số chẵn phải tận cùng bằng 0 hoặc 8.", "en": "An even number must end in 0 or 8."}, {"vi": "Chữ số hàng nghìn nhỏ nhất có thể là 3. Hàng trăm nhỏ nhất còn lại là 0, rồi 9 và 8 ở hàng chục, đơn vị.", "en": "The thousands digit should be 3 (smallest nonzero). Then 0 in the hundreds, and the last digit must be even, so 8."}, {"vi": "Ta được số 3 098 (tận cùng 8, chẵn).", "en": "We get 3,098 (it ends in 8, so it is even)."}], "tip": {"vi": "Hàng đơn vị của số chẵn là 0 hoặc 8.", "en": "An even number ends in 0 or 8."}, "src": "250 bài, CĐ3, Bài 1c"}, {"id": "cd3-b22", "lesson": "count", "rank": 2, "q": {"vi": "Trong một buổi lễ có 13 cặp vợ chồng tham gia. Mỗi người đàn ông bắt tay tất cả các người khác. Các phụ nữ không ai bắt tay nhau. Hỏi có tất cả bao nhiêu cái bắt tay?", "en": "At a party there are 13 married couples. Each man shakes hands with every other person. No two women shake hands. How many handshakes are there in all?"}, "parts": [{"kind": "num", "lab": {"vi": "Số cái bắt tay", "en": "Handshakes"}, "ans": 247, "unit": {"vi": "cái", "en": "handshakes"}}], "steps": [{"vi": "Bắt tay giữa hai người đàn ông: 13 × 12 : 2 = 78 cái.", "en": "Handshakes between two men: 13 × 12 ÷ 2 = 78."}, {"vi": "Mỗi người đàn ông bắt tay với cả 13 phụ nữ: 13 × 13 = 169 cái (tính cả vợ của mình).", "en": "Each man shakes hands with all 13 women: 13 × 13 = 169 (including his own wife)."}, {"vi": "Tổng số cái bắt tay là 78 + 169 = 247.", "en": "The total number of handshakes is 78 + 169 = 247."}], "tip": {"vi": "Tách thành bắt tay nam với nam và nam với nữ.", "en": "Split into man-man and man-woman handshakes."}, "src": "250 bài, CĐ3, Bài 22"}, {"id": "cd3-b2b", "lesson": "count", "rank": 2, "q": {"vi": "Cho 5 chữ số 1; 4; 6; 8; 9. Có thể viết được bao nhiêu số lẻ có 5 chữ số mà chữ số hàng trăm là 4 (các chữ số có thể lặp lại)?", "en": "Given the 5 digits 1, 4, 6, 8, 9. How many odd 5-digit numbers can be written with 4 in the hundreds place (digits may repeat)?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số", "en": "Count"}, "ans": 250, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Số lẻ phải tận cùng bằng 1 hoặc 9 nên hàng đơn vị có 2 cách chọn.", "en": "An odd number ends in 1 or 9, so the ones place has 2 choices."}, {"vi": "Hàng trăm cố định là 4 (1 cách). Ba hàng còn lại (chục nghìn, nghìn, chục) mỗi hàng có 5 cách.", "en": "The hundreds place is fixed at 4 (1 choice). The other three places (ten-thousands, thousands, tens) have 5 choices each."}, {"vi": "Số các số là 5 × 5 × 1 × 5 × 2 = 250.", "en": "The count is 5 × 5 × 1 × 5 × 2 = 250."}], "tip": {"vi": "Chọn hàng đơn vị trước.", "en": "Start with the ones place."}, "src": "250 bài, CĐ3, Bài 2b"}, {"id": "cd3-b2c", "lesson": "count", "rank": 2, "q": {"vi": "Cho 5 chữ số 1; 4; 6; 8; 9. Có thể viết được bao nhiêu số chẵn có 5 chữ số khác nhau từ 5 chữ số đã cho?", "en": "Given the 5 digits 1, 4, 6, 8, 9. How many even 5-digit numbers with all different digits can be written from these digits?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số", "en": "Count"}, "ans": 72, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Số chẵn tận cùng bằng 4, 6 hoặc 8 nên hàng đơn vị có 3 cách chọn.", "en": "An even number ends in 4, 6 or 8, so the ones place has 3 choices."}, {"vi": "Bốn chữ số còn lại xếp vào 4 hàng còn lại: 4 × 3 × 2 × 1 = 24 cách.", "en": "The other 4 digits fill the other 4 places in 4 × 3 × 2 × 1 = 24 ways."}, {"vi": "Số các số là 3 × 24 = 72.", "en": "The count is 3 × 24 = 72."}], "tip": {"vi": "Dùng cả 5 chữ số, mỗi chữ số một lần.", "en": "Each of the 5 digits is used exactly once."}, "src": "250 bài, CĐ3, Bài 2c"}, {"id": "cd3-b3", "lesson": "count", "rank": 2, "q": {"vi": "Cho 4 chữ số 3, 5, 6, 8. Hãy lập tất cả các số có 4 chữ số mà ở mỗi số có đủ 4 chữ số đã cho. Tính tổng các số đó.", "en": "Given the 4 digits 3, 5, 6, 8. Make all the 4-digit numbers that use all 4 of these digits in each number. Find the sum of these numbers."}, "parts": [{"kind": "num", "lab": {"vi": "Tổng các số", "en": "Sum"}, "ans": 146652, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Có 4 × 3 × 2 × 1 = 24 số. Ở mỗi hàng, mỗi chữ số xuất hiện 24 : 4 = 6 lần.", "en": "There are 4 × 3 × 2 × 1 = 24 numbers. In each place, each digit appears 24 ÷ 4 = 6 times."}, {"vi": "Tổng các chữ số ở mỗi hàng là (3 + 5 + 6 + 8) × 6 = 132.", "en": "The digits in each place add up to (3 + 5 + 6 + 8) × 6 = 132."}, {"vi": "Tổng các số là 132 × 1 000 + 132 × 100 + 132 × 10 + 132 = 132 × 1 111 = 146 652.", "en": "The total is 132 × 1,000 + 132 × 100 + 132 × 10 + 132 = 132 × 1,111 = 146,652."}], "tip": {"vi": "Mỗi chữ số xuất hiện bằng nhau ở mỗi hàng.", "en": "Each digit appears equally often in every place."}, "src": "250 bài, CĐ3, Bài 3"}, {"id": "cd3-b6", "lesson": "count", "rank": 2, "q": {"vi": "Có bao nhiêu số tự nhiên có 5 chữ số mà mỗi số không có chữ số 1?", "en": "How many 5-digit natural numbers do not contain the digit 1?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số", "en": "Count"}, "ans": 52488, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Hàng chục nghìn: không được là 0 và không được là 1, nên có 10 − 2 = 8 cách.", "en": "Ten-thousands place: cannot be 0 or 1, so 10 − 2 = 8 choices."}, {"vi": "Bốn hàng còn lại: không được là 1, mỗi hàng có 9 cách.", "en": "The other four places cannot be 1, so each has 9 choices."}, {"vi": "Số các số là 8 × 9 × 9 × 9 × 9 = 52 488.", "en": "The count is 8 × 9 × 9 × 9 × 9 = 52,488."}], "tip": {"vi": "Hàng cao nhất khác hàng còn lại vì không được là 0.", "en": "The first place is different because it cannot be 0."}, "src": "250 bài, CĐ3, Bài 6"}, {"id": "cd3-b20a", "lesson": "count", "rank": 3, "q": {"vi": "Tính tổng các số tự nhiên có 4 chữ số được lập bởi các chữ số 2; 3; 0; 7, trong đó các chữ số có thể giống nhau.", "en": "Find the sum of all 4-digit natural numbers made from the digits 2, 3, 0, 7, where the digits may repeat."}, "parts": [{"kind": "num", "lab": {"vi": "Tổng", "en": "Sum"}, "ans": 831936, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hàng nghìn có 3 cách (2, 3, 7), ba hàng còn lại mỗi hàng 4 cách: 3 × 4 × 4 × 4 = 192 số.", "en": "The thousands place has 3 choices (2, 3, 7) and each other place has 4: 3 × 4 × 4 × 4 = 192 numbers."}, {"vi": "Hàng nghìn: mỗi chữ số 2, 3, 7 xuất hiện 4 × 4 × 4 = 64 lần, tổng (2 + 3 + 7) × 64 = 768 (nghìn) = 768 000.", "en": "Thousands: each of 2, 3, 7 appears 4 × 4 × 4 = 64 times, giving (2 + 3 + 7) × 64 = 768 thousand = 768,000."}, {"vi": "Mỗi hàng còn lại: mỗi chữ số xuất hiện 3 × 4 × 4 = 48 lần, tổng (2 + 3 + 0 + 7) × 48 = 576.", "en": "Each other place: each digit appears 3 × 4 × 4 = 48 times, giving (2 + 3 + 0 + 7) × 48 = 576."}, {"vi": "Tổng là 768 000 + 576 × 100 + 576 × 10 + 576 = 831 936.", "en": "The sum is 768,000 + 576 × 100 + 576 × 10 + 576 = 831,936."}], "tip": {"vi": "Đếm số lần mỗi chữ số xuất hiện ở từng hàng.", "en": "Count how often each digit appears in each place."}, "src": "250 bài, CĐ3, Bài 20a"}, {"id": "cd3-b20b", "lesson": "count", "rank": 3, "q": {"vi": "Tính tổng các số tự nhiên có 4 chữ số khác nhau được lập bởi các chữ số 2; 3; 0; 7.", "en": "Find the sum of all 4-digit natural numbers with all different digits made from the digits 2, 3, 0, 7."}, "parts": [{"kind": "num", "lab": {"vi": "Tổng", "en": "Sum"}, "ans": 77328, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Có 3 × 3 × 2 × 1 = 18 số.", "en": "There are 3 × 3 × 2 × 1 = 18 numbers."}, {"vi": "Hàng nghìn: 2, 3, 7 mỗi chữ số xuất hiện 6 lần: (2 + 3 + 7) × 6 = 72 (nghìn) = 72 000.", "en": "Thousands: each of 2, 3, 7 appears 6 times: (2 + 3 + 7) × 6 = 72 thousand = 72,000."}, {"vi": "Mỗi hàng còn lại: 2, 3, 7 mỗi chữ số xuất hiện 4 lần (số 0 không đóng góp): (2 + 3 + 7) × 4 = 48.", "en": "Each other place: 2, 3, 7 each appear 4 times (0 adds nothing): (2 + 3 + 7) × 4 = 48."}, {"vi": "Tổng là 72 000 + 48 × 100 + 48 × 10 + 48 = 77 328.", "en": "The sum is 72,000 + 48 × 100 + 48 × 10 + 48 = 77,328."}], "tip": {"vi": "Làm giống bài trước nhưng các chữ số phải khác nhau.", "en": "Same idea as before, but all digits must be different."}, "src": "250 bài, CĐ3, Bài 20b"}, {"id": "cd3-b24", "lesson": "count", "rank": 3, "q": {"vi": "Một chú kiến đang ở vị trí A. Hỏi có bao nhiêu cách để kiến đến được vị trí B, biết kiến chỉ đi theo 3 hướng: sang phải (→), lên (↑) và chéo lên (↗) dọc theo các đoạn thẳng của hình?\nHình gồm 2 hình vuông cạnh nhau (hình chữ nhật 2 × 1). A là đỉnh dưới trái, B là đỉnh trên phải. Mỗi hình vuông có một đường chéo nối đỉnh dưới trái với đỉnh trên phải của nó.", "en": "An ant is at point A. How many ways can the ant get to point B if it only moves in 3 directions: right (→), up (↑) and diagonally up-right (↗), along the line segments of the figure?\nThe figure is 2 squares side by side (a 2 × 1 rectangle). A is the bottom-left corner and B is the top-right corner. Each square has a diagonal joining its bottom-left corner to its top-right corner."}, "parts": [{"kind": "num", "lab": {"vi": "Số cách", "en": "Ways"}, "ans": 5, "unit": {"vi": "cách", "en": "ways"}}], "steps": [{"vi": "Đặt A = (0, 0), B = (2, 1). Đếm số cách đến từng đỉnh: đỉnh dưới giữa (1, 0) và dưới phải (2, 0) đều có 1 cách; đỉnh trên trái (0, 1) có 1 cách.", "en": "Put A = (0, 0) and B = (2, 1). Count ways to each corner: bottom-middle (1, 0) and bottom-right (2, 0) each have 1 way; top-left (0, 1) has 1 way."}, {"vi": "Đỉnh trên giữa (1, 1) đến được từ (0, 1), (1, 0) và A (đường chéo): 1 + 1 + 1 = 3 cách.", "en": "Top-middle (1, 1) can be reached from (0, 1), (1, 0) and A (diagonal): 1 + 1 + 1 = 3 ways."}, {"vi": "B đến được từ (1, 1), (2, 0) và (1, 0) (đường chéo): 3 + 1 + 1 = 5 cách.", "en": "B can be reached from (1, 1), (2, 0) and (1, 0) (diagonal): 3 + 1 + 1 = 5 ways."}], "tip": {"vi": "Đếm số cách đến từng đỉnh, bắt đầu từ A.", "en": "Count the ways to each corner, starting from A."}, "src": "250 bài, CĐ3, Bài 24"}, {"id": "cd3-b4", "lesson": "count", "rank": 3, "q": {"vi": "Cho 4 chữ số 0, 2, 5, 7. Hãy lập tất cả các số có 4 chữ số mà ở mỗi số có đủ 4 chữ số đã cho. Tính tổng các số đó.", "en": "Given the 4 digits 0, 2, 5, 7. Make all the 4-digit numbers that use all 4 of these digits in each number. Find the sum of these numbers."}, "parts": [{"kind": "num", "lab": {"vi": "Tổng các số", "en": "Sum"}, "ans": 90216, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hàng nghìn không được là 0: có 3 × 3 × 2 × 1 = 18 số.", "en": "The thousands digit cannot be 0: there are 3 × 3 × 2 × 1 = 18 numbers."}, {"vi": "Hàng nghìn: 2, 5, 7 mỗi chữ số xuất hiện 6 lần, tổng (2 + 5 + 7) × 6 = 84 (nghìn).", "en": "Thousands place: 2, 5, 7 each appear 6 times, so (2 + 5 + 7) × 6 = 84 thousand."}, {"vi": "Ở mỗi hàng còn lại: 2, 5, 7 mỗi chữ số xuất hiện 4 lần (số 0 xuất hiện 6 lần), tổng (2 + 5 + 7) × 4 = 56.", "en": "In each other place: 2, 5, 7 each appear 4 times (0 appears 6 times), so (2 + 5 + 7) × 4 = 56."}, {"vi": "Tổng là 84 000 + 56 × 100 + 56 × 10 + 56 = 84 000 + 6 216 = 90 216.", "en": "The total is 84,000 + 56 × 100 + 56 × 10 + 56 = 84,000 + 6,216 = 90,216."}], "tip": {"vi": "Đếm riêng hàng nghìn và các hàng còn lại.", "en": "Count the thousands place separately from the other places."}, "src": "250 bài, CĐ3, Bài 4"}, {"id": "cd3-b7", "lesson": "count", "rank": 3, "q": {"vi": "Có bao nhiêu số tự nhiên chẵn có 4 chữ số khác nhau mà mỗi số không có chữ số 6?", "en": "How many even natural numbers with 4 different digits do not contain the digit 6?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số", "en": "Count"}, "ans": 1218, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Trường hợp tận cùng bằng 0: ba hàng còn lại chọn từ 8 chữ số (1, 2, 3, 4, 5, 7, 8, 9): 8 × 7 × 6 = 336 số.", "en": "Case ending in 0: the other three places use the 8 digits 1, 2, 3, 4, 5, 7, 8, 9: 8 × 7 × 6 = 336 numbers."}, {"vi": "Trường hợp tận cùng bằng 2, 4 hoặc 8 (3 cách): hàng nghìn không phải 0, 6 và chữ số cuối nên có 7 cách.", "en": "Case ending in 2, 4 or 8 (3 choices): the thousands digit is not 0, 6 or the last digit, so 7 choices."}, {"vi": "Hàng trăm: 7 cách (đã bỏ 6, chữ số cuối, chữ số nghìn); hàng chục: 6 cách. Được 3 × 7 × 7 × 6 = 882 số.", "en": "Hundreds: 7 choices (no 6, last digit, thousands digit); tens: 6 choices. That gives 3 × 7 × 7 × 6 = 882 numbers."}, {"vi": "Tổng cộng 336 + 882 = 1 218 số.", "en": "The total is 336 + 882 = 1,218 numbers."}], "tip": {"vi": "Chia hai trường hợp: tận cùng bằng 0 và tận cùng khác 0.", "en": "Split into two cases: ends in 0 and ends in another even digit."}, "src": "250 bài, CĐ3, Bài 7"}, {"id": "cd3-b8", "lesson": "count", "rank": 3, "q": {"vi": "Có bao nhiêu số có 5 chữ số mà trong đó có ít nhất 1 chữ số 9?", "en": "How many 5-digit numbers have at least one digit 9?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số", "en": "Count"}, "ans": 37512, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Có tất cả 99 999 − 10 000 + 1 = 90 000 số có 5 chữ số.", "en": "There are 99,999 − 10,000 + 1 = 90,000 five-digit numbers in all."}, {"vi": "Đếm các số không có chữ số 9: hàng cao nhất có 8 cách (khác 0 và 9), mỗi hàng còn lại có 9 cách: 8 × 9 × 9 × 9 × 9 = 52 488 số.", "en": "Count numbers with no digit 9: the first place has 8 choices (not 0 or 9), each other place has 9: 8 × 9 × 9 × 9 × 9 = 52,488."}, {"vi": "Số các số có ít nhất một chữ số 9 là 90 000 − 52 488 = 37 512.", "en": "Numbers with at least one 9: 90,000 − 52,488 = 37,512."}], "tip": {"vi": "Đếm phần còn lại (không có chữ số 9) rồi trừ đi.", "en": "Count the opposite case (no digit 9) and subtract."}, "src": "250 bài, CĐ3, Bài 8"}, {"id": "cd3-b9", "lesson": "count", "rank": 3, "q": {"vi": "Cho các chữ số x; 2; 5; 8. Từ 4 chữ số đã cho ta lập được tất cả 12 số có 4 chữ số mà mỗi số có đủ cả 4 chữ số ấy. Biết tổng các số lập được bằng 66 660. Tìm x.", "en": "Given the digits x, 2, 5, 8. From these 4 digits we can make exactly 12 four-digit numbers, each using all 4 digits. The sum of these numbers is 66,660. Find x."}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 5, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Với 4 chữ số khác nhau (không có 0) sẽ lập được 24 số; có 0 thì được 18 số. Chỉ có 12 số nên x trùng với một chữ số khác (x là 2, 5 hoặc 8).", "en": "Four different digits give 24 numbers (18 if one is 0). Only 12 numbers means x equals one of the other digits (x is 2, 5 or 8)."}, {"vi": "Ở mỗi hàng, tổng các chữ số của 12 số là 12 : 4 × (x + 2 + 5 + 8) = 3 × (x + 15).", "en": "In each place, the digits of the 12 numbers add up to 12 ÷ 4 × (x + 2 + 5 + 8) = 3 × (x + 15)."}, {"vi": "Tổng các số là 3 × (x + 15) × 1 111 = 66 660, nên x + 15 = 66 660 : 3 333 = 20.", "en": "The sum is 3 × (x + 15) × 1,111 = 66,660, so x + 15 = 66,660 ÷ 3,333 = 20."}, {"vi": "Vậy x = 20 − 15 = 5.", "en": "So x = 20 − 15 = 5."}], "tip": {"vi": "Tìm xem mỗi chữ số xuất hiện bao nhiêu lần ở mỗi hàng.", "en": "Find how many times each digit appears in each place."}, "src": "250 bài, CĐ3, Bài 9"}, {"id": "cd3-b15b", "lesson": "count", "rank": 3, "q": {"vi": "Tìm số lượng các số tự nhiên có 4 chữ số mà số tạo bởi 2 chữ số đầu (theo thứ tự ấy) cộng với số tạo bởi 2 chữ số cuối (theo thứ tự ấy) nhỏ hơn 100.", "en": "Find how many 4-digit natural numbers have the number formed by the first 2 digits (in that order) plus the number formed by the last 2 digits (in that order) less than 100."}, "parts": [{"kind": "num", "lab": {"vi": "Số các số", "en": "Count"}, "ans": 4095, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Gọi số có dạng abcd; ab từ 10 đến 99, cd từ 00 đến 99, cần ab + cd < 100.", "en": "Write the number as abcd; ab is from 10 to 99, cd is from 00 to 99, and we need ab + cd < 100."}, {"vi": "Với ab = m thì cd có thể là 0, 1, …, 99 − m nên có 100 − m cách.", "en": "If ab = m, then cd can be 0, 1, …, 99 − m, which is 100 − m choices."}, {"vi": "Tổng là 90 + 89 + … + 1 = (90 + 1) × 90 : 2 = 4 095.", "en": "The total is 90 + 89 + … + 1 = (90 + 1) × 90 ÷ 2 = 4,095."}], "tip": {"vi": "Với mỗi ab, đếm các cd thỏa mãn.", "en": "For each ab, count the valid cd."}, "src": "250 bài, CĐ3, Bài 15b"}], "divis": [{"id": "cd9-b11", "lesson": "divis", "rank": 1, "q": {"vi": "Tìm số lớn nhất có 4 chữ số mà tổng các chữ số bằng 9, biết số đó chia 2 dư 1, chia 5 dư 2.", "en": "Find the largest four-digit number whose digits add up to 9, given that it leaves remainder 1 when divided by 2 and remainder 2 when divided by 5."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 2007, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Chia 5 dư 2 nên tận cùng là 2 hoặc 7; chia 2 dư 1 nên số lẻ, vậy tận cùng là 7.", "en": "Remainder 2 mod 5 means it ends in 2 or 7; remainder 1 mod 2 means it is odd, so it ends in 7."}, {"vi": "Ba chữ số đầu có tổng 9 − 7 = 2.", "en": "The first three digits add up to 9 − 7 = 2."}, {"vi": "Để số lớn nhất, chữ số hàng nghìn lớn nhất là 2, hai chữ số còn lại là 0; số đó là 2007.", "en": "To make it largest, take the biggest thousands digit 2 and make the other two digits 0. The number is 2,007."}], "tip": {"vi": "Chữ số tận cùng được xác định trước.", "en": "The last digit can be found first."}, "src": "250 bài, CĐ9, Bài 11"}, {"id": "cd9-b15a", "lesson": "divis", "rank": 1, "q": {"vi": "Không làm phép chia, hãy xét xem số 111…111 (có 2010 chữ số 1) chia hết cho những số nào trong các số 2, 3, 5, 9.", "en": "Without dividing, decide which of 2, 3, 5 and 9 the number 111…111 (with 2,010 digits of 1) is divisible by."}, "parts": [{"kind": "choice", "lab": {"vi": "Chia hết cho 2?", "en": "Divisible by 2?"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 1}, {"kind": "choice", "lab": {"vi": "Chia hết cho 3?", "en": "Divisible by 3?"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 0}, {"kind": "choice", "lab": {"vi": "Chia hết cho 5?", "en": "Divisible by 5?"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 1}, {"kind": "choice", "lab": {"vi": "Chia hết cho 9?", "en": "Divisible by 9?"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 1}], "steps": [{"vi": "Số tận cùng là 1 nên không chia hết cho 2 và 5.", "en": "It ends in 1, so it is not divisible by 2 or 5."}, {"vi": "Tổng các chữ số là 2010 × 1 = 2010 và 2 + 0 + 1 + 0 = 3.", "en": "The digit sum is 2,010 × 1 = 2,010, and 2 + 0 + 1 + 0 = 3."}, {"vi": "3 chia hết cho 3 nên số đó chia hết cho 3; 3 không chia hết cho 9 nên số đó không chia hết cho 9.", "en": "3 is divisible by 3, so the number is divisible by 3; 3 is not divisible by 9, so the number is not divisible by 9."}], "tip": {"vi": "Tính tổng các chữ số rồi xét dấu hiệu chia hết.", "en": "Find the digit sum and use the divisibility rules."}, "src": "250 bài, CĐ9, Bài 15a"}, {"id": "cd9-b15b", "lesson": "divis", "rank": 1, "q": {"vi": "Không làm phép chia, hãy xét xem số 333…333 (có 2007 chữ số 3) chia hết cho những số nào trong các số 2, 3, 5, 9.", "en": "Without dividing, decide which of 2, 3, 5 and 9 the number 333…333 (with 2,007 digits of 3) is divisible by."}, "parts": [{"kind": "choice", "lab": {"vi": "Chia hết cho 2?", "en": "Divisible by 2?"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 1}, {"kind": "choice", "lab": {"vi": "Chia hết cho 3?", "en": "Divisible by 3?"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 0}, {"kind": "choice", "lab": {"vi": "Chia hết cho 5?", "en": "Divisible by 5?"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 1}, {"kind": "choice", "lab": {"vi": "Chia hết cho 9?", "en": "Divisible by 9?"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 0}], "steps": [{"vi": "Số tận cùng là 3 nên không chia hết cho 2 và 5.", "en": "It ends in 3, so it is not divisible by 2 or 5."}, {"vi": "Tổng các chữ số là 2007 × 3 = 6021 và 6 + 0 + 2 + 1 = 9.", "en": "The digit sum is 2,007 × 3 = 6,021, and 6 + 0 + 2 + 1 = 9."}, {"vi": "Tổng chia hết cho 9 nên số đó chia hết cho 9 và cũng chia hết cho 3.", "en": "The digit sum is divisible by 9, so the number is divisible by 9 and also by 3."}], "tip": {"vi": "Tính tổng các chữ số rồi xét dấu hiệu chia hết.", "en": "Find the digit sum and use the divisibility rules."}, "src": "250 bài, CĐ9, Bài 15b"}, {"id": "cd9-b15c", "lesson": "divis", "rank": 1, "q": {"vi": "Không làm phép chia, hãy xét xem số 444…444 (có 2001 chữ số 4) chia hết cho những số nào trong các số 2, 3, 5, 9.", "en": "Without dividing, decide which of 2, 3, 5 and 9 the number 444…444 (with 2,001 digits of 4) is divisible by."}, "parts": [{"kind": "choice", "lab": {"vi": "Chia hết cho 2?", "en": "Divisible by 2?"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 0}, {"kind": "choice", "lab": {"vi": "Chia hết cho 3?", "en": "Divisible by 3?"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 0}, {"kind": "choice", "lab": {"vi": "Chia hết cho 5?", "en": "Divisible by 5?"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 1}, {"kind": "choice", "lab": {"vi": "Chia hết cho 9?", "en": "Divisible by 9?"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 1}], "steps": [{"vi": "Số tận cùng là 4 (chữ số chẵn, khác 0 và 5) nên chia hết cho 2, không chia hết cho 5.", "en": "It ends in 4 (even, not 0 or 5), so it is divisible by 2 but not by 5."}, {"vi": "Tổng các chữ số là 2001 × 4 = 8004 và 8 + 0 + 0 + 4 = 12.", "en": "The digit sum is 2,001 × 4 = 8,004, and 8 + 0 + 0 + 4 = 12."}, {"vi": "12 chia hết cho 3 nhưng không chia hết cho 9, nên số đó chia hết cho 3, không chia hết cho 9.", "en": "12 is divisible by 3 but not by 9, so the number is divisible by 3 but not by 9."}], "tip": {"vi": "Tính tổng các chữ số rồi xét dấu hiệu chia hết.", "en": "Find the digit sum and use the divisibility rules."}, "src": "250 bài, CĐ9, Bài 15c"}, {"id": "cd9-b2", "lesson": "divis", "rank": 1, "q": {"vi": "Viết thêm vào bên phải và bên trái số 1996 mỗi bên 1 chữ số để được số chia hết cho 2, 5 và 9. Tìm chữ số viết thêm bên trái và bên phải.", "en": "Write one digit on the left and one digit on the right of 1,996 so that the new number is divisible by 2, 5 and 9. Find the digit on the left and the digit on the right."}, "parts": [{"kind": "num", "lab": {"vi": "Chữ số bên trái", "en": "Left digit"}, "ans": 2, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Chữ số bên phải", "en": "Right digit"}, "ans": 0, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Chia hết cho cả 2 và 5 thì tận cùng là 0, nên chữ số bên phải là 0.", "en": "Divisible by both 2 and 5 means the last digit is 0, so the right digit is 0."}, {"vi": "Tổng các chữ số của 1996 là 1 + 9 + 9 + 6 = 25, cộng thêm chữ số bên trái a phải chia hết cho 9.", "en": "The digits of 1,996 add up to 1 + 9 + 9 + 6 = 25, and adding the left digit a must give a multiple of 9."}, {"vi": "25 + a chia hết cho 9 thì 25 + a = 27, nên a = 2.", "en": "25 + a divisible by 9 gives 25 + a = 27, so a = 2."}, {"vi": "Số mới là 219960 (219 960 : 9 = 24 440).", "en": "The new number is 219,960 (219,960 ÷ 9 = 24,440)."}], "tip": {"vi": "Số chia hết cho 2 và 5 tận cùng bằng chữ số nào?", "en": "Which digit does a number divisible by both 2 and 5 end in?"}, "src": "250 bài, CĐ9, Bài 2"}, {"id": "cd9-b4a", "lesson": "divis", "rank": 1, "q": {"vi": "Xác định các chữ số a, b để thay vào số 6a49b được số chia hết cho 2, 5 và 9.", "en": "Find the digits a and b so that the number 6a49b is divisible by 2, 5 and 9."}, "parts": [{"kind": "num", "lab": {"vi": "Chữ số a", "en": "Digit a"}, "ans": 8, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Chữ số b", "en": "Digit b"}, "ans": 0, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Chia hết cho 2 và 5 nên b = 0.", "en": "Divisible by 2 and 5 means b = 0."}, {"vi": "Tổng các chữ số 6 + a + 4 + 9 + 0 = 19 + a phải chia hết cho 9.", "en": "The digit sum 6 + a + 4 + 9 + 0 = 19 + a must be a multiple of 9."}, {"vi": "19 + a = 27 nên a = 8; số đó là 68490.", "en": "19 + a = 27 so a = 8; the number is 68,490."}], "tip": {"vi": "Chữ số tận cùng quyết định chia hết cho 2 và 5.", "en": "The last digit decides divisibility by 2 and 5."}, "src": "250 bài, CĐ9, Bài 4a"}, {"id": "cd3-b12", "lesson": "divis", "rank": 2, "q": {"vi": "Từ 5 chữ số 0; 2; 3; 7; 5 lập được bao nhiêu số có 4 chữ số khác nhau và đều chia hết cho 5?", "en": "Using the 5 digits 0, 2, 3, 7, 5, how many 4-digit numbers with all different digits that are divisible by 5 can be made?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số", "en": "Count"}, "ans": 42, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Số chia hết cho 5 tận cùng bằng 0 hoặc 5.", "en": "A number divisible by 5 ends in 0 or 5."}, {"vi": "Tận cùng bằng 0: ba hàng còn lại chọn từ 4 chữ số: 4 × 3 × 2 = 24 số.", "en": "Ends in 0: the other three places use the 4 other digits: 4 × 3 × 2 = 24 numbers."}, {"vi": "Tận cùng bằng 5: hàng nghìn khác 0 nên có 3 cách, hàng trăm 3 cách, hàng chục 2 cách: 3 × 3 × 2 = 18 số.", "en": "Ends in 5: thousands is not 0 so 3 choices, hundreds 3 choices, tens 2 choices: 3 × 3 × 2 = 18 numbers."}, {"vi": "Tổng cộng 24 + 18 = 42 số.", "en": "The total is 24 + 18 = 42 numbers."}], "tip": {"vi": "Chia hai trường hợp theo chữ số hàng đơn vị.", "en": "Split into two cases by the last digit."}, "src": "250 bài, CĐ3, Bài 12"}, {"id": "cd3-b14", "lesson": "divis", "rank": 2, "q": {"vi": "Có bao nhiêu số tự nhiên có 4 chữ số, chia hết cho 3 và tận cùng bằng 5?", "en": "How many 4-digit natural numbers are divisible by 3 and end in 5?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số", "en": "Count"}, "ans": 300, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Số chia hết cho 3 và tận cùng bằng 5 thì chia hết cho 15 và là số lẻ.", "en": "A number divisible by 3 that ends in 5 is divisible by 15 and is odd."}, {"vi": "Các số đó có dạng 15 × k với k lẻ. Số nhỏ nhất có 4 chữ số là 15 × 67 = 1 005, số lớn nhất là 15 × 665 = 9 975.", "en": "These numbers are 15 × k with k odd. The smallest 4-digit one is 15 × 67 = 1,005, the largest is 15 × 665 = 9,975."}, {"vi": "Các số lẻ k từ 67 đến 665 có (665 − 67) : 2 + 1 = 300 số.", "en": "The odd values of k from 67 to 665 number (665 − 67) ÷ 2 + 1 = 300."}], "tip": {"vi": "Các số này cách đều nhau 30 đơn vị.", "en": "These numbers are 30 apart."}, "src": "250 bài, CĐ3, Bài 14"}, {"id": "cd5-b15", "lesson": "divis", "rank": 2, "q": {"vi": "Trong các số từ 1 đến 2014 có bao nhiêu số chia hết cho 2 nhưng không chia hết cho 3?", "en": "How many numbers from 1 to 2,014 are divisible by 2 but not divisible by 3?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số", "en": "Count"}, "ans": 672, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Số chia hết cho 2 từ 1 đến 2014: 2014 : 2 = 1007 số.", "en": "Numbers divisible by 2 from 1 to 2,014: 2,014 ÷ 2 = 1,007."}, {"vi": "Số chia hết cho cả 2 và 3 tức là chia hết cho 6: 2014 : 6 = 335 dư 4 nên có 335 số.", "en": "Numbers divisible by both 2 and 3 are divisible by 6: 2,014 ÷ 6 = 335 remainder 4, so there are 335."}, {"vi": "Số cần tìm: 1007 − 335 = 672.", "en": "The answer: 1,007 − 335 = 672."}], "tip": {"vi": "Lấy số chia hết cho 2 trừ đi số chia hết cho 6.", "en": "Subtract the multiples of 6 from the multiples of 2."}, "src": "250 bài, CĐ5, Bài 15"}, {"id": "cd9-b10", "lesson": "divis", "rank": 2, "q": {"vi": "Viết thêm 2 chữ số vào bên phải số 537 để được một số lẻ có 5 chữ số, biết số đó chia cho 5 và 9 đều dư 4. Tìm hai chữ số viết thêm.", "en": "Write 2 more digits to the right of 537 to make an odd five-digit number that leaves remainder 4 when divided by 5 and also when divided by 9. Find the two added digits."}, "parts": [{"kind": "num", "lab": {"vi": "Chữ số thứ nhất", "en": "First added digit"}, "ans": 7, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Chữ số thứ hai", "en": "Second added digit"}, "ans": 9, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số 537ab chia 5 dư 4 thì b = 4 hoặc 9; số lẻ nên b = 9.", "en": "537ab leaves remainder 4 when divided by 5, so b = 4 or 9; it is odd so b = 9."}, {"vi": "Chia 9 dư 4 thì tổng chữ số 5 + 3 + 7 + a + 9 = 24 + a chia 9 dư 4.", "en": "Remainder 4 when divided by 9 means the digit sum 5 + 3 + 7 + a + 9 = 24 + a leaves remainder 4 when divided by 9."}, {"vi": "24 + a = 31 (31 = 27 + 4) nên a = 7; số đó là 53779.", "en": "24 + a = 31 (31 = 27 + 4), so a = 7. The number is 53,779."}], "tip": {"vi": "Số dư khi chia cho 9 bằng số dư của tổng các chữ số khi chia cho 9.", "en": "A number leaves the same remainder mod 9 as the sum of its digits."}, "src": "250 bài, CĐ9, Bài 10"}, {"id": "cd9-b12", "lesson": "divis", "rank": 2, "q": {"vi": "Tìm số tự nhiên bé nhất lớn hơn 3 sao cho khi chia số đó cho 4; 5; 7 đều dư 3.", "en": "Find the smallest natural number greater than 3 that leaves remainder 3 when divided by 4, by 5 and by 7."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 143, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Bớt số đó đi 3 thì được số chia hết cho cả 4, 5 và 7.", "en": "If we subtract 3 from the number, we get a number divisible by 4, 5 and 7."}, {"vi": "4, 5, 7 không có ước chung nào khác 1 nên số bé nhất khác 0 chia hết cho cả ba là 4 × 5 × 7 = 140.", "en": "4, 5 and 7 share no common factor other than 1, so the smallest nonzero number divisible by all three is 4 × 5 × 7 = 140."}, {"vi": "Vậy số cần tìm là 140 + 3 = 143.", "en": "So the number is 140 + 3 = 143."}], "tip": {"vi": "Bớt đi 3 rồi tìm số chia hết cho 4, 5, 7.", "en": "Subtract 3 first, then look for a number divisible by 4, 5 and 7."}, "src": "250 bài, CĐ9, Bài 12"}, {"id": "cd9-b14", "lesson": "divis", "rank": 2, "q": {"vi": "Trong một cuộc họp người ta xếp ghế băng thành 2 dãy. Cứ mỗi ghế băng bố trí 3 người ngồi. Số đại biểu ở 2 dãy bằng nhau. Nếu mỗi ghế băng bố trí 5 người thì có 1 người ngồi riêng một mình. Hãy tính số người dự họp, biết rằng số người dự họp là số có 2 chữ số không quá 50.", "en": "At a meeting, benches are arranged in 2 rows. Each bench seats 3 people. The two rows have the same number of delegates. If each bench seats 5 people instead, then 1 person sits alone. Find the number of people at the meeting, given that it is a two-digit number not greater than 50."}, "parts": [{"kind": "num", "lab": {"vi": "Số người dự họp", "en": "People at the meeting"}, "ans": 36, "unit": {"vi": "người", "en": "people"}}], "steps": [{"vi": "Hai dãy bằng nhau, mỗi ghế 3 người nên số người là bội của 3 × 2 = 6: 12, 18, 24, 30, 36, 42, 48.", "en": "The two rows are equal and each bench seats 3, so the number of people is a multiple of 3 × 2 = 6: 12, 18, 24, 30, 36, 42, 48."}, {"vi": "Xếp 5 người một ghế còn thừa 1 người, tức là số người chia 5 dư 1, nên tận cùng là 1 hoặc 6.", "en": "Seating 5 per bench leaves 1 person, so the number leaves remainder 1 when divided by 5, and ends in 1 or 6."}, {"vi": "Trong các số trên chỉ có 36 tận cùng bằng 6. Vậy có 36 người dự họp.", "en": "Among the numbers above only 36 ends in 6. So 36 people are at the meeting."}], "tip": {"vi": "Liệt kê các bội của 6 có hai chữ số không quá 50.", "en": "List the two-digit multiples of 6 that are at most 50."}, "src": "250 bài, CĐ9, Bài 14"}, {"id": "cd9-b15d", "lesson": "divis", "rank": 2, "q": {"vi": "Không làm phép chia, hãy xét xem số bbb…bbb (có 999 chữ số b, b là chữ số chẵn khác 0) chia hết cho những số nào trong các số 2, 3, 5, 9.", "en": "Without dividing, decide which of 2, 3, 5 and 9 the number bbb…bbb (with 999 digits b, where b is an even nonzero digit) is divisible by."}, "parts": [{"kind": "choice", "lab": {"vi": "Chia hết cho 2?", "en": "Divisible by 2?"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 0}, {"kind": "choice", "lab": {"vi": "Chia hết cho 3?", "en": "Divisible by 3?"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 0}, {"kind": "choice", "lab": {"vi": "Chia hết cho 5?", "en": "Divisible by 5?"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 1}, {"kind": "choice", "lab": {"vi": "Chia hết cho 9?", "en": "Divisible by 9?"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 0}], "steps": [{"vi": "b là chữ số chẵn khác 0 nên số tận cùng chẵn: chia hết cho 2, và không chia hết cho 5 (tận cùng không phải 0 hay 5).", "en": "b is an even nonzero digit, so the number ends in an even digit: it is divisible by 2, and not by 5 (it does not end in 0 or 5)."}, {"vi": "Tổng các chữ số là 999 × b, mà 999 = 9 × 111 chia hết cho 9.", "en": "The digit sum is 999 × b, and 999 = 9 × 111 is divisible by 9."}, {"vi": "Vậy tổng chia hết cho 9, nên số đó chia hết cho 9 và cho 3.", "en": "So the digit sum is divisible by 9, and the number is divisible by 9 and by 3."}], "tip": {"vi": "Tổng các chữ số là 999 × b.", "en": "The digit sum is 999 × b."}, "src": "250 bài, CĐ9, Bài 15d"}, {"id": "cd9-b16", "lesson": "divis", "rank": 2, "q": {"vi": "An có 3 mảnh giấy. Em xé mỗi mảnh làm 5, rồi lại lấy 1 mảnh xé làm 5, cứ như vậy mãi. Hỏi cuối cùng An có thể thu được 49 mảnh hay không?", "en": "An has 3 pieces of paper. She tears each piece into 5, then takes 1 piece and tears it into 5, and keeps doing this. Can An end up with exactly 49 pieces?"}, "parts": [{"kind": "choice", "lab": {"vi": "Có thể có 49 mảnh?", "en": "Can she get 49?"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 1}], "steps": [{"vi": "Lần đầu xé 3 mảnh mỗi mảnh làm 5 được 15 mảnh; mỗi lần xé thêm 1 mảnh làm 5 thì số mảnh tăng thêm 5 − 1 = 4.", "en": "The first time she tears all 3 pieces into 5, giving 15 pieces. Each later tearing of one piece into 5 increases the count by 5 − 1 = 4."}, {"vi": "Vậy số mảnh luôn là 15 + 4 × k (k là số lần xé thêm), chia 4 luôn dư 3.", "en": "So the number of pieces is always 15 + 4 × k, which always leaves remainder 3 when divided by 4."}, {"vi": "49 chia 4 dư 1, không dư 3, nên không thể có đúng 49 mảnh.", "en": "49 leaves remainder 1 when divided by 4, not 3, so she can never have exactly 49 pieces."}], "tip": {"vi": "Mỗi lần xé thêm, số mảnh tăng thêm bao nhiêu?", "en": "By how much does the number of pieces increase with each extra tear?"}, "src": "250 bài, CĐ9, Bài 16"}, {"id": "cd9-b17", "lesson": "divis", "rank": 2, "q": {"vi": "Có thể thay các chữ trong phép tính sau bằng các chữ số thích hợp được không (các chữ khác nhau thay bằng chữ số khác nhau, các chữ giống nhau thay bằng chữ số giống nhau)? CHAMHOC − HOCCHAM = 102386.", "en": "Can the letters in the following calculation be replaced by suitable digits (different letters stand for different digits, the same letters for the same digit)? CHAMHOC − HOCCHAM = 102,386."}, "parts": [{"kind": "choice", "lab": {"vi": "Có thể thay được?", "en": "Is it possible?"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 1}], "steps": [{"vi": "Hai số CHAMHOC và HOCCHAM đều gồm các chữ C, H, A, M, H, O, C (cùng các chữ số, chỉ khác vị trí).", "en": "CHAMHOC and HOCCHAM both use the same letters C, H, A, M, H, O, C, only in different positions."}, {"vi": "Hai số có cùng tổng các chữ số nên cùng số dư khi chia cho 9, do đó hiệu của chúng chia hết cho 9.", "en": "They have the same digit sum, so they leave the same remainder when divided by 9, and their difference is divisible by 9."}, {"vi": "Nhưng 102386 có tổng các chữ số 1 + 0 + 2 + 3 + 8 + 6 = 20, không chia hết cho 9. Vậy không thể thay được.", "en": "But 102,386 has digit sum 1 + 0 + 2 + 3 + 8 + 6 = 20, which is not divisible by 9. So it is impossible."}], "tip": {"vi": "Hai số có cùng các chữ số thì cùng số dư khi chia cho 9.", "en": "Two numbers with the same digits leave the same remainder when divided by 9."}, "src": "250 bài, CĐ9, Bài 17"}, {"id": "cd9-b18", "lesson": "divis", "rank": 2, "q": {"vi": "Tổng kết học kì I học sinh lớp 4A đều được xếp học lực Khá và Giỏi. Trong đó, 21 bạn xếp loại Giỏi và 18 bạn xếp loại Khá. Cô giáo mua 200 quyển vở để làm phần thưởng và được phân đều cho mỗi bạn (mỗi bạn nhận số vở như nhau). Hỏi 200 quyển vở có vừa đủ để thưởng cho các bạn học sinh trong lớp không?", "en": "At the end of the first semester, every student in Class 4A is rated Good or Excellent. There are 21 Excellent students and 18 Good students. The teacher buys 200 notebooks as rewards, to be shared equally so that every student gets the same number. Are 200 notebooks exactly enough for the class?"}, "parts": [{"kind": "choice", "lab": {"vi": "Vừa đủ?", "en": "Exactly enough?"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 1}], "steps": [{"vi": "Lớp có 21 + 18 = 39 học sinh.", "en": "The class has 21 + 18 = 39 students."}, {"vi": "Chia đều 200 quyển cho 39 bạn: 200 : 39 = 5 dư 5 (vì 39 × 5 = 195).", "en": "Sharing 200 notebooks equally among 39 students: 200 ÷ 39 = 5 remainder 5 (since 39 × 5 = 195)."}, {"vi": "200 không chia hết cho 39 nên không vừa đủ.", "en": "200 is not divisible by 39, so it is not exactly enough."}], "tip": {"vi": "Đếm số học sinh cả lớp rồi thử chia.", "en": "Count all the students, then try dividing."}, "src": "250 bài, CĐ9, Bài 18"}, {"id": "cd9-b19a", "lesson": "divis", "rank": 2, "q": {"vi": "Có 32 đoạn que, mỗi đoạn dài 1 cm, 48 đoạn que, mỗi đoạn dài 2 cm và 45 đoạn que, mỗi đoạn dài 3 cm. Hỏi có thể xếp nối các đoạn que đó (dùng hết tất cả) thành một hình chữ nhật không?", "en": "There are 32 sticks of length 1 cm, 48 sticks of length 2 cm and 45 sticks of length 3 cm. Can all of these sticks be joined end to end to form a rectangle?"}, "parts": [{"kind": "choice", "lab": {"vi": "Xếp được hình chữ nhật?", "en": "Can form a rectangle?"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 1}], "steps": [{"vi": "Tổng độ dài các que là 32 × 1 + 48 × 2 + 45 × 3 = 32 + 96 + 135 = 263 (cm).", "en": "The total length is 32 × 1 + 48 × 2 + 45 × 3 = 32 + 96 + 135 = 263 (cm)."}, {"vi": "Chu vi hình chữ nhật bằng 2 lần tổng chiều dài và chiều rộng nên là số chẵn.", "en": "The perimeter of a rectangle is 2 times (length + width), so it is an even number."}, {"vi": "263 là số lẻ nên không thể xếp thành hình chữ nhật.", "en": "263 is odd, so the sticks cannot form a rectangle."}], "tip": {"vi": "Chu vi hình chữ nhật là số chẵn hay lẻ?", "en": "Is the perimeter of a rectangle even or odd?"}, "src": "250 bài, CĐ9, Bài 19a"}, {"id": "cd9-b21a", "lesson": "divis", "rank": 2, "q": {"vi": "Cho số tự nhiên M = 555…555 (2015 chữ số 5). Hỏi phải thêm vào M ít nhất bao nhiêu đơn vị để được một số chia hết cho 15?", "en": "Let M = 555…555 (2,015 digits of 5). What is the least number that must be added to M to get a number divisible by 15?"}, "parts": [{"kind": "num", "lab": {"vi": "Số đơn vị phải thêm", "en": "Number to add"}, "ans": 5, "unit": {"vi": "đơn vị", "en": "units"}}], "steps": [{"vi": "Tổng các chữ số của M là 5 × 2015 = 10075, có 1 + 0 + 0 + 7 + 5 = 13, chia 3 dư 1. Vậy M chia 3 dư 1; M tận cùng bằng 5 nên chia hết cho 5.", "en": "The digit sum of M is 5 × 2,015 = 10,075 (1 + 0 + 0 + 7 + 5 = 13), which leaves remainder 1 when divided by 3. So M leaves remainder 1 when divided by 3; M ends in 5, so it is divisible by 5."}, {"vi": "15 = 3 × 5. Số thêm vào phải chia hết cho 5 (để giữ chia hết cho 5), nên chỉ có thể là 5, 10, 15, …", "en": "15 = 3 × 5. The number added must be divisible by 5 (to stay divisible by 5), so it can only be 5, 10, 15, …"}, {"vi": "Thêm 5 thì M + 5 chia 3 dư 1 + 2 = 3, tức là chia hết cho 3. Vậy ít nhất phải thêm 5 đơn vị.", "en": "Adding 5 gives remainder 1 + 2 = 3 when divided by 3, so M + 5 is divisible by 3. So at least 5 must be added."}], "tip": {"vi": "15 = 3 × 5: xét dấu hiệu chia hết cho 3 và cho 5.", "en": "15 = 3 × 5: use the divisibility tests for 3 and for 5."}, "src": "250 bài, CĐ9, Bài 21a"}, {"id": "cd9-b3", "lesson": "divis", "rank": 2, "q": {"vi": "Tìm x, y trong số 4x5y để được một số chia hết cho 9 và 4. Hỏi có bao nhiêu số như vậy và số lớn nhất là số nào?", "en": "Find x and y in the number 4x5y so that it is divisible by both 9 and 4. How many such numbers are there, and which is the largest?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số tìm được", "en": "How many numbers"}, "ans": 2, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số lớn nhất", "en": "Largest number"}, "ans": 4752, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Chia hết cho 4 thì hai chữ số cuối 5y chia hết cho 4, nên y = 2 hoặc y = 6.", "en": "Divisible by 4 means the last two digits 5y are divisible by 4, so y = 2 or y = 6."}, {"vi": "Chia hết cho 9 thì 4 + x + 5 + y = 9 + x + y chia hết cho 9, tức là x + y bằng 0, 9 hoặc 18.", "en": "Divisible by 9 means 4 + x + 5 + y = 9 + x + y is a multiple of 9, so x + y is 0, 9 or 18."}, {"vi": "Với y = 2 thì x = 7 (số 4752); với y = 6 thì x = 3 (số 4356).", "en": "If y = 2 then x = 7 (the number 4,752); if y = 6 then x = 3 (the number 4,356)."}, {"vi": "Có 2 số, số lớn nhất là 4752.", "en": "There are 2 numbers, and the largest is 4,752."}], "tip": {"vi": "Xét hai chữ số cuối trước, rồi đến tổng các chữ số.", "en": "Look at the last two digits first, then at the sum of the digits."}, "src": "250 bài, CĐ9, Bài 3"}, {"id": "cd9-b5a", "lesson": "divis", "rank": 2, "q": {"vi": "Cho số 2x387y. Hãy thay x, y bởi các chữ số thích hợp để được số chia hết cho 12. Hỏi có bao nhiêu số như vậy, số nhỏ nhất và số lớn nhất là bao nhiêu?", "en": "Take the number 2x387y. Replace x and y with suitable digits so that it is divisible by 12. How many such numbers are there, and what are the smallest and the largest?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số tìm được", "en": "How many numbers"}, "ans": 6, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số nhỏ nhất", "en": "Smallest number"}, "ans": 213876, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số lớn nhất", "en": "Largest number"}, "ans": 283872, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "12 = 3 × 4, nên số phải chia hết cho 3 và cho 4.", "en": "12 = 3 × 4, so the number must be divisible by 3 and by 4."}, {"vi": "Chia hết cho 4: hai chữ số cuối 7y chia hết cho 4, nên y = 2 hoặc y = 6.", "en": "Divisible by 4: the last two digits 7y are divisible by 4, so y = 2 or y = 6."}, {"vi": "Chia hết cho 3: 2 + x + 3 + 8 + 7 + y = 20 + x + y chia hết cho 3. Với y = 2 thì 22 + x nên x = 2, 5, 8; với y = 6 thì 26 + x nên x = 1, 4, 7.", "en": "Divisible by 3: 2 + x + 3 + 8 + 7 + y = 20 + x + y is a multiple of 3. For y = 2, 22 + x gives x = 2, 5, 8; for y = 6, 26 + x gives x = 1, 4, 7."}, {"vi": "Có 6 số: 213876, 223872, 243876, 253872, 273876, 283872; nhỏ nhất 213876, lớn nhất 283872.", "en": "There are 6 numbers: 213,876; 223,872; 243,876; 253,872; 273,876; 283,872. The smallest is 213,876 and the largest is 283,872."}], "tip": {"vi": "12 = 3 × 4: xét dấu hiệu chia hết cho 4 rồi cho 3.", "en": "12 = 3 × 4: use the rule for 4, then the rule for 3."}, "src": "250 bài, CĐ9, Bài 5a"}, {"id": "cd9-b5b", "lesson": "divis", "rank": 2, "q": {"vi": "Cho số 2x387y. Hãy thay x, y bởi các chữ số thích hợp để được số chia hết cho 225.", "en": "Take the number 2x387y. Replace x and y with suitable digits so that it is divisible by 225."}, "parts": [{"kind": "num", "lab": {"vi": "Chữ số x", "en": "Digit x"}, "ans": 2, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Chữ số y", "en": "Digit y"}, "ans": 5, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "225 = 9 × 25, nên số phải chia hết cho 9 và cho 25.", "en": "225 = 9 × 25, so the number must be divisible by 9 and by 25."}, {"vi": "Chia hết cho 25 thì hai chữ số cuối 7y là 75, nên y = 5.", "en": "Divisible by 25 means the last two digits 7y are 75, so y = 5."}, {"vi": "Chia hết cho 9: 2 + x + 3 + 8 + 7 + 5 = 25 + x, nên 25 + x = 27 và x = 2.", "en": "Divisible by 9: 2 + x + 3 + 8 + 7 + 5 = 25 + x, so 25 + x = 27 and x = 2."}, {"vi": "Số đó là 223875; kiểm tra 223 875 : 225 = 995.", "en": "The number is 223,875. Check: 223,875 ÷ 225 = 995."}], "tip": {"vi": "Số chia hết cho 25 có hai chữ số cuối là 00, 25, 50 hoặc 75.", "en": "A number divisible by 25 ends in 00, 25, 50 or 75."}, "src": "250 bài, CĐ9, Bài 5b"}, {"id": "cd9-b7a", "lesson": "divis", "rank": 2, "q": {"vi": "Biết tích 18 × 19 × 20 × 21 × a có kết quả đúng là số có dạng 3*91000. Hãy tìm giá trị của chữ số * mà không nhân trực tiếp kết quả.", "en": "The product 18 × 19 × 20 × 21 × a is exactly a number of the form 3*91000. Find the digit * without multiplying everything out."}, "parts": [{"kind": "num", "lab": {"vi": "Chữ số *", "en": "Digit *"}, "ans": 5, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tích có thừa số 18 nên chia hết cho 9.", "en": "The product has a factor 18, so it is divisible by 9."}, {"vi": "Vậy tổng các chữ số 3 + * + 9 + 1 + 0 + 0 + 0 = 13 + * phải chia hết cho 9.", "en": "So the digit sum 3 + * + 9 + 1 + 0 + 0 + 0 = 13 + * must be a multiple of 9."}, {"vi": "13 + * = 18 nên * = 5 (số đó là 3591000).", "en": "13 + * = 18 so * = 5 (the number is 3,591,000)."}], "tip": {"vi": "Trong tích có thừa số nào chia hết cho 9?", "en": "Which factor in the product is divisible by 9?"}, "src": "250 bài, CĐ9, Bài 7a"}, {"id": "cd9-b7b", "lesson": "divis", "rank": 2, "q": {"vi": "Biết tích 21 × 22 × 23 × 24 × 25 có kết quả là số có dạng 63*56**. Không nhân trực tiếp kết quả, hãy tìm ba chữ số * theo thứ tự từ trái sang phải.", "en": "The product 21 × 22 × 23 × 24 × 25 is a number of the form 63*56**. Without multiplying it out, find the three digits *, from left to right."}, "parts": [{"kind": "num", "lab": {"vi": "Dấu * thứ nhất", "en": "First *"}, "ans": 7, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Dấu * thứ hai", "en": "Second *"}, "ans": 0, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Dấu * thứ ba", "en": "Third *"}, "ans": 0, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tích có 24 × 25 = 600 nên tận cùng có hai chữ số 0: hai dấu * cuối đều là 0.", "en": "The product contains 24 × 25 = 600, so it ends in two zeros: the last two * are both 0."}, {"vi": "Tích có thừa số 21 và 24 đều chia hết cho 3 nên chia hết cho 9.", "en": "The factors 21 and 24 are both divisible by 3, so the product is divisible by 9."}, {"vi": "6 + 3 + * + 5 + 6 + 0 + 0 = 20 + * chia hết cho 9 nên * = 7. Tích là 6375600.", "en": "6 + 3 + * + 5 + 6 + 0 + 0 = 20 + * must be a multiple of 9, so * = 7. The product is 6,375,600."}], "tip": {"vi": "Tích có thừa số 25 và thừa số chẵn nên tận cùng thế nào?", "en": "The product has a factor 25 and an even factor; how does it end?"}, "src": "250 bài, CĐ9, Bài 7b"}, {"id": "cd9-b9", "lesson": "divis", "rank": 2, "q": {"vi": "Cho số A = 5x1y. Thay x, y bởi những chữ số thích hợp để A chia hết cho 6 và chia 5 dư 4. Tìm y, hỏi có bao nhiêu số A như vậy và số A lớn nhất.", "en": "Let A = 5x1y. Replace x and y with suitable digits so that A is divisible by 6 and leaves remainder 4 when divided by 5. Find y, how many such numbers A there are, and the largest A."}, "parts": [{"kind": "num", "lab": {"vi": "Chữ số y", "en": "Digit y"}, "ans": 4, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số các số A", "en": "How many numbers A"}, "ans": 3, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số A lớn nhất", "en": "Largest A"}, "ans": 5814, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "A chia 5 dư 4 nên y = 4 hoặc y = 9; A chia hết cho 6 nên A chẵn, vậy y = 4.", "en": "A leaves remainder 4 when divided by 5, so y = 4 or 9; A is divisible by 6 so it is even, and y = 4."}, {"vi": "A chia hết cho 3: 5 + x + 1 + 4 = 10 + x chia hết cho 3, nên x = 2, 5 hoặc 8.", "en": "A is divisible by 3: 5 + x + 1 + 4 = 10 + x is a multiple of 3, so x = 2, 5 or 8."}, {"vi": "Có 3 số: 5214, 5514, 5814; lớn nhất là 5814.", "en": "There are 3 numbers: 5,214; 5,514; 5,814. The largest is 5,814."}], "tip": {"vi": "Chia hết cho 6 = chia hết cho 2 và cho 3.", "en": "Divisible by 6 = divisible by 2 and by 3."}, "src": "250 bài, CĐ9, Bài 9"}, {"id": "cd3-b11", "lesson": "divis", "rank": 3, "q": {"vi": "Cho 5 chữ số 0; 2; 4; 6; 9. Hỏi lập được tất cả bao nhiêu số có 4 chữ số khác nhau và đều chia hết cho 3?", "en": "Given the 5 digits 0, 2, 4, 6, 9. How many 4-digit numbers with all different digits that are divisible by 3 can be made?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số", "en": "Count"}, "ans": 60, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Tổng 5 chữ số là 21. Bỏ đi 1 chữ số để 4 chữ số còn lại có tổng chia hết cho 3: bỏ 0, 6 hoặc 9.", "en": "The 5 digits add up to 21. Drop one digit so the other four have a sum divisible by 3: drop 0, 6 or 9."}, {"vi": "Bỏ 0: bộ 2, 4, 6, 9 xếp được 4 × 3 × 2 × 1 = 24 số.", "en": "Drop 0: the digits 2, 4, 6, 9 make 4 × 3 × 2 × 1 = 24 numbers."}, {"vi": "Bỏ 6 hoặc bỏ 9: bộ có chữ số 0 nên xếp được 3 × 3 × 2 × 1 = 18 số mỗi bộ, tức 36 số.", "en": "Drop 6 or drop 9: each set contains 0, so it makes 3 × 3 × 2 × 1 = 18 numbers, which is 36 numbers."}, {"vi": "Tổng cộng 24 + 36 = 60 số.", "en": "The total is 24 + 36 = 60 numbers."}], "tip": {"vi": "Một số chia hết cho 3 khi tổng các chữ số chia hết cho 3.", "en": "A number is divisible by 3 when its digit sum is divisible by 3."}, "src": "250 bài, CĐ3, Bài 11"}, {"id": "cd3-b13", "lesson": "divis", "rank": 3, "q": {"vi": "Từ 6 chữ số 0; 1; 2; 4; 7; 9 lập được bao nhiêu số chẵn có 5 chữ số khác nhau và mỗi số đều chia hết cho 3?", "en": "Using the 6 digits 0, 1, 2, 4, 7, 9, how many even 5-digit numbers with all different digits that are divisible by 3 can be made?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số", "en": "Count"}, "ans": 42, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Tổng 6 chữ số là 23. Bỏ 1 chữ số để tổng 5 chữ số còn lại chia hết cho 3: 23 − 2 = 21, nên bỏ chữ số 2. Bộ số là 0, 1, 4, 7, 9.", "en": "The 6 digits add up to 23. Drop one digit so the other 5 add to a multiple of 3: 23 − 2 = 21, so drop 2. The set is 0, 1, 4, 7, 9."}, {"vi": "Số chẵn tận cùng bằng 0 hoặc 4.", "en": "An even number ends in 0 or 4."}, {"vi": "Tận cùng 0: 4 chữ số còn lại xếp tùy ý: 4 × 3 × 2 × 1 = 24 số.", "en": "Ends in 0: the other 4 digits go anywhere: 4 × 3 × 2 × 1 = 24 numbers."}, {"vi": "Tận cùng 4: hàng chục nghìn khác 0 nên có 3 cách; 3 hàng còn lại có 3 × 2 × 1 cách: 3 × 3 × 2 × 1 = 18 số. Tổng 24 + 18 = 42.", "en": "Ends in 4: ten-thousands is not 0 so 3 choices; the other 3 places give 3 × 2 × 1 ways: 3 × 3 × 2 × 1 = 18 numbers. Total: 24 + 18 = 42."}], "tip": {"vi": "Tìm xem phải bỏ chữ số nào để tổng chia hết cho 3.", "en": "Find which digit to drop so the sum is divisible by 3."}, "src": "250 bài, CĐ3, Bài 13"}, {"id": "cd3-b16", "lesson": "divis", "rank": 3, "q": {"vi": "Có bao nhiêu số tự nhiên có 4 chữ số, chia hết cho 5, có đúng 1 chữ số 5?", "en": "How many 4-digit natural numbers are divisible by 5 and contain exactly one digit 5?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số", "en": "Count"}, "ans": 873, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Số chia hết cho 5 tận cùng bằng 0 hoặc 5.", "en": "A number divisible by 5 ends in 0 or 5."}, {"vi": "Tận cùng bằng 5: ba hàng còn lại không có chữ số 5: 8 × 9 × 9 = 648 số.", "en": "Ends in 5: the other three places have no 5: 8 × 9 × 9 = 648 numbers."}, {"vi": "Tận cùng bằng 0: chữ số 5 đứng ở hàng nghìn (1 × 9 × 9 = 81 số), hàng trăm (8 × 1 × 9 = 72 số) hoặc hàng chục (8 × 9 × 1 = 72 số): 225 số.", "en": "Ends in 0: the 5 is in the thousands place (1 × 9 × 9 = 81 numbers), hundreds (8 × 1 × 9 = 72) or tens (8 × 9 × 1 = 72): 225 numbers."}, {"vi": "Tổng cộng 648 + 225 = 873 số.", "en": "The total is 648 + 225 = 873 numbers."}], "tip": {"vi": "Chia hai trường hợp theo chữ số tận cùng.", "en": "Split into two cases by the last digit."}, "src": "250 bài, CĐ3, Bài 16"}, {"id": "cd3-b17", "lesson": "divis", "rank": 3, "q": {"vi": "Có bao nhiêu số tự nhiên có 3 chữ số, biết cộng nó với số viết theo thứ tự ngược lại ta được một số chia hết cho 5?", "en": "How many 3-digit natural numbers are there such that adding the number to the number written in reverse order gives a number divisible by 5?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số", "en": "Count"}, "ans": 180, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Gọi số là abc. Số ngược lại là cba. Tổng abc + cba = 101 × (a + c) + 20 × b.", "en": "Let the number be abc. Its reverse is cba. The sum abc + cba = 101 × (a + c) + 20 × b."}, {"vi": "20 × b chia hết cho 5 nên tổng chia hết cho 5 khi a + c chia hết cho 5, tức a + c bằng 5, 10 hoặc 15.", "en": "20 × b is divisible by 5, so the sum is divisible by 5 when a + c is divisible by 5, so a + c is 5, 10 or 15."}, {"vi": "Có 5 cặp (a, c) với a + c = 5, có 9 cặp với a + c = 10 và có 4 cặp với a + c = 15: 18 cặp.", "en": "There are 5 pairs (a, c) with a + c = 5, 9 pairs with a + c = 10 and 4 pairs with a + c = 15: 18 pairs."}, {"vi": "Chữ số b có 10 cách chọn nên có 18 × 10 = 180 số.", "en": "The digit b has 10 choices, so there are 18 × 10 = 180 numbers."}], "tip": {"vi": "Chữ số hàng chục không ảnh hưởng đến việc chia hết cho 5.", "en": "The tens digit does not affect divisibility by 5."}, "src": "250 bài, CĐ3, Bài 17"}, {"id": "cd3-b18", "lesson": "divis", "rank": 3, "q": {"vi": "Từ 5 chữ số 0; 3; 5; 7; 8 lập được tất cả bao nhiêu số có 4 chữ số khác nhau chia hết cho 15?", "en": "Using the 5 digits 0, 3, 5, 7, 8, how many 4-digit numbers with all different digits that are divisible by 15 can be made?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số", "en": "Count"}, "ans": 16, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Số chia hết cho 15 là số chia hết cho cả 3 và 5: tận cùng bằng 0 hoặc 5 và tổng các chữ số chia hết cho 3.", "en": "A number divisible by 15 is divisible by both 3 and 5: it ends in 0 or 5 and its digit sum is divisible by 3."}, {"vi": "Tổng 5 chữ số là 23; bỏ chữ số 5 hoặc 8 thì tổng còn lại là 18 hoặc 15 (chia hết cho 3).", "en": "The 5 digits add up to 23; dropping 5 or 8 leaves a sum of 18 or 15 (divisible by 3)."}, {"vi": "Bỏ 5: bộ 0, 3, 7, 8 tận cùng bằng 0: 3 × 2 × 1 = 6 số.", "en": "Drop 5: with 0, 3, 7, 8 the number must end in 0: 3 × 2 × 1 = 6 numbers."}, {"vi": "Bỏ 8: bộ 0, 3, 5, 7: tận cùng 0 có 6 số; tận cùng 5 có 2 × 2 × 1 = 4 số. Tổng 6 + 6 + 4 = 16 số.", "en": "Drop 8: with 0, 3, 5, 7: ending in 0 gives 6 numbers; ending in 5 gives 2 × 2 × 1 = 4 numbers. Total 6 + 6 + 4 = 16."}], "tip": {"vi": "Tìm chữ số cần bỏ để tổng chia hết cho 3.", "en": "Find which digit to drop so the sum is divisible by 3."}, "src": "250 bài, CĐ3, Bài 18"}, {"id": "cd3-b19", "lesson": "divis", "rank": 3, "q": {"vi": "Có bao nhiêu số có 5 chữ số chia hết cho 3 và có ít nhất 1 chữ số 6?", "en": "How many 5-digit numbers are divisible by 3 and contain at least one digit 6?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số", "en": "Count"}, "ans": 12504, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Các số có 5 chữ số chia hết cho 3 có 90 000 : 3 = 30 000 số.", "en": "The number of 5-digit numbers divisible by 3 is 90,000 ÷ 3 = 30,000."}, {"vi": "Đếm số chia hết cho 3 không có chữ số 6: 4 hàng đầu có 8 × 9 × 9 × 9 = 5 832 cách chọn.", "en": "Count those with no digit 6: the first 4 places have 8 × 9 × 9 × 9 = 5,832 ways."}, {"vi": "Với mỗi cách đó, hàng đơn vị chọn trong 9 chữ số (không có 6), mỗi lớp dư 0, 1, 2 có đúng 3 chữ số nên có đúng 3 cách để tổng chia hết cho 3: 5 832 × 3 = 17 496 số.", "en": "For each, the last digit comes from 9 digits (no 6); each remainder 0, 1, 2 has exactly 3 digits, so exactly 3 choices make the sum divisible by 3: 5,832 × 3 = 17,496."}, {"vi": "Số các số cần tìm là 30 000 − 17 496 = 12 504.", "en": "The answer is 30,000 − 17,496 = 12,504."}], "tip": {"vi": "Đếm phần ngược lại (không có chữ số 6).", "en": "Count the opposite case (no digit 6)."}, "src": "250 bài, CĐ3, Bài 19"}, {"id": "cd5-b16", "lesson": "divis", "rank": 3, "q": {"vi": "Trong các số tự nhiên từ 1 đến 252, xóa các số chia hết cho 2 nhưng không chia hết cho 5, rồi xóa các số chia hết cho 5 nhưng không chia hết cho 2. Hỏi còn lại bao nhiêu số?", "en": "From the whole numbers 1 to 252, erase the numbers divisible by 2 but not by 5, then erase the numbers divisible by 5 but not by 2. How many numbers are left?"}, "parts": [{"kind": "num", "lab": {"vi": "Số còn lại", "en": "Numbers left"}, "ans": 126, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Số chia hết cho 2: 252 : 2 = 126 số; chia hết cho 5: 252 : 5 = 50 dư 2 nên có 50 số; chia hết cho 10: 25 số (252 : 10 = 25 dư 2).", "en": "Multiples of 2: 252 ÷ 2 = 126; multiples of 5: 252 ÷ 5 = 50 remainder 2, so 50; multiples of 10: 25 (252 ÷ 10 = 25 remainder 2)."}, {"vi": "Số bị xóa lần 1 (chia hết cho 2, không chia hết cho 5): 126 − 25 = 101 số.", "en": "Erased first (divisible by 2 but not 5): 126 − 25 = 101."}, {"vi": "Số bị xóa lần 2 (chia hết cho 5, không chia hết cho 2): 50 − 25 = 25 số.", "en": "Erased second (divisible by 5 but not 2): 50 − 25 = 25."}, {"vi": "Còn lại: 252 − 101 − 25 = 126 số.", "en": "Left: 252 − 101 − 25 = 126."}], "tip": {"vi": "Đếm riêng số chia hết cho 10 (chia hết cho cả 2 và 5).", "en": "Count the multiples of 10 (divisible by both 2 and 5) separately."}, "src": "250 bài, CĐ5, Bài 16"}, {"id": "cd9-b19b", "lesson": "divis", "rank": 3, "q": {"vi": "Có 12 đoạn que, mỗi đoạn que dài 25 cm và 20 đoạn que, mỗi đoạn que dài 21 cm. Hỏi có thể xếp nối các đoạn que (dùng hết tất cả) thành hình vuông được không? Nếu xếp được, mỗi cạnh hình vuông dùng bao nhiêu đoạn que dài 25 cm?", "en": "There are 12 sticks of length 25 cm and 20 sticks of length 21 cm. Can all of these sticks be joined end to end to form a square? If yes, how many 25 cm sticks are used on each side of the square?"}, "parts": [{"kind": "choice", "lab": {"vi": "Xếp được hình vuông?", "en": "Can form a square?"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 0}, {"kind": "num", "lab": {"vi": "Số que 25 cm mỗi cạnh", "en": "25 cm sticks per side"}, "ans": 3, "unit": {"vi": "que", "en": "sticks"}}], "steps": [{"vi": "Tổng độ dài các que là 12 × 25 + 20 × 21 = 300 + 420 = 720 (cm).", "en": "The total length is 12 × 25 + 20 × 21 = 300 + 420 = 720 (cm)."}, {"vi": "Hình vuông có 4 cạnh bằng nhau nên mỗi cạnh dài 720 : 4 = 180 (cm).", "en": "A square has 4 equal sides, so each side is 720 ÷ 4 = 180 (cm)."}, {"vi": "Mỗi cạnh dùng a que 25 cm và b que 21 cm với 25 × a + 21 × b = 180. Thử a = 0, 1, …, 7 thì chỉ có a = 3 cho 180 − 75 = 105 chia hết cho 21 (b = 5).", "en": "Each side uses a sticks of 25 cm and b sticks of 21 cm with 25 × a + 21 × b = 180. Trying a = 0, 1, …, 7, only a = 3 works: 180 − 75 = 105 is divisible by 21 (b = 5)."}, {"vi": "Bốn cạnh dùng 4 × 3 = 12 que 25 cm và 4 × 5 = 20 que 21 cm, đúng bằng số que đã cho. Vậy xếp được, mỗi cạnh có 3 que 25 cm.", "en": "Four sides use 4 × 3 = 12 sticks of 25 cm and 4 × 5 = 20 sticks of 21 cm, exactly the sticks given. So it can be done, with 3 sticks of 25 cm on each side."}], "tip": {"vi": "Tính độ dài mỗi cạnh, rồi tìm cách ghép 25 và 21 để được độ dài đó.", "en": "Find the side length, then find a mix of 25 and 21 that gives it."}, "src": "250 bài, CĐ9, Bài 19b"}, {"id": "cd9-b21b", "lesson": "divis", "rank": 3, "q": {"vi": "Cho số tự nhiên M = 555…555 (2015 chữ số 5). Hỏi phải bớt M đi ít nhất bao nhiêu đơn vị để được một số chia hết cho 45?", "en": "Let M = 555…555 (2,015 digits of 5). What is the least number that must be subtracted from M to get a number divisible by 45?"}, "parts": [{"kind": "num", "lab": {"vi": "Số đơn vị phải bớt", "en": "Number to subtract"}, "ans": 40, "unit": {"vi": "đơn vị", "en": "units"}}], "steps": [{"vi": "Tổng các chữ số của M là 10075, tổng 1 + 0 + 0 + 7 + 5 = 13, 1 + 3 = 4. Vậy M chia 9 dư 4; M tận cùng bằng 5 nên chia hết cho 5.", "en": "The digit sum of M is 10,075 → 1 + 0 + 0 + 7 + 5 = 13 → 1 + 3 = 4. So M leaves remainder 4 when divided by 9; M ends in 5, so it is divisible by 5."}, {"vi": "45 = 9 × 5. Số bớt đi phải chia hết cho 5 và chia 9 dư 4.", "en": "45 = 9 × 5. The number subtracted must be divisible by 5 and leave remainder 4 when divided by 9."}, {"vi": "Thử các số chia hết cho 5: 5, 10, 15, 20, 25, 30, 35, 40: chia 9 lần lượt dư 5, 1, 6, 2, 7, 3, 8, 4. Số đầu tiên dư 4 là 40.", "en": "Try multiples of 5: 5, 10, 15, 20, 25, 30, 35, 40: remainders when divided by 9 are 5, 1, 6, 2, 7, 3, 8, 4. The first one with remainder 4 is 40."}, {"vi": "Vậy ít nhất phải bớt 40 đơn vị.", "en": "So at least 40 must be subtracted."}], "tip": {"vi": "45 = 9 × 5: xét số dư khi chia cho 9 và cho 5.", "en": "45 = 9 × 5: look at the remainders when dividing by 9 and by 5."}, "src": "250 bài, CĐ9, Bài 21b"}, {"id": "cd9-b4b", "lesson": "divis", "rank": 3, "q": {"vi": "Xác định các chữ số a, b để thay vào số 6a49b được số chia hết cho 72.", "en": "Find the digits a and b so that the number 6a49b is divisible by 72."}, "parts": [{"kind": "num", "lab": {"vi": "Chữ số a", "en": "Digit a"}, "ans": 2, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Chữ số b", "en": "Digit b"}, "ans": 6, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "72 = 8 × 9, mà 8 và 9 không có ước chung nào khác 1, nên số phải chia hết cho cả 8 và 9.", "en": "72 = 8 × 9 and 8 and 9 share no factor except 1, so the number must be divisible by both 8 and 9."}, {"vi": "Chia hết cho 8 thì ba chữ số cuối 49b chia hết cho 8: 488 và 496 là các bội của 8 gần 490; chỉ có 496 dạng 49b, nên b = 6.", "en": "Divisible by 8 means the last three digits 49b are divisible by 8. The multiples of 8 near 490 are 488 and 496, and only 496 has the form 49b, so b = 6."}, {"vi": "Chia hết cho 9: 6 + a + 4 + 9 + 6 = 25 + a chia hết cho 9, nên 25 + a = 27, a = 2.", "en": "Divisible by 9: 6 + a + 4 + 9 + 6 = 25 + a is a multiple of 9, so 25 + a = 27 and a = 2."}, {"vi": "Số đó là 62496; kiểm tra 62 496 : 72 = 868.", "en": "The number is 62,496. Check: 62,496 ÷ 72 = 868."}], "tip": {"vi": "Phân tích 72 thành tích hai số không có ước chung (trừ 1).", "en": "Write 72 as a product of two numbers with no common factor other than 1."}, "src": "250 bài, CĐ9, Bài 4b"}, {"id": "cd9-b6", "lesson": "divis", "rank": 3, "q": {"vi": "Cho 4 chữ số 0, 4, 5, 8. Hỏi có bao nhiêu số có 3 chữ số khác nhau được viết từ 4 chữ số đã cho thỏa mãn mỗi số: a) chia hết cho 6; b) chia hết cho 15; c) chia hết cho 18; d) chia hết cho 45?", "en": "Take the four digits 0, 4, 5, 8. How many three-digit numbers with different digits can be written from these four digits so that each number is: a) divisible by 6; b) divisible by 15; c) divisible by 18; d) divisible by 45?"}, "parts": [{"kind": "num", "lab": {"vi": "a) chia hết cho 6", "en": "a) divisible by 6"}, "ans": 7, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "b) chia hết cho 15", "en": "b) divisible by 15"}, "ans": 5, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "c) chia hết cho 18", "en": "c) divisible by 18"}, "ans": 3, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "d) chia hết cho 45", "en": "d) divisible by 45"}, "ans": 3, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Các số có 3 chữ số khác nhau (hàng trăm khác 0): 405, 408, 450, 458, 480, 485, 504, 508, 540, 548, 580, 584, 804, 805, 840, 845, 850, 854 (18 số).", "en": "The three-digit numbers with different digits (hundreds digit not 0) are 405, 408, 450, 458, 480, 485, 504, 508, 540, 548, 580, 584, 804, 805, 840, 845, 850, 854 (18 numbers)."}, {"vi": "a) Chia hết cho 6 = chẵn và tổng chữ số chia hết cho 3: 408, 450, 480, 504, 540, 804, 840, có 7 số.", "en": "a) Divisible by 6 = even and digit sum divisible by 3: 408, 450, 480, 504, 540, 804, 840, so 7 numbers."}, {"vi": "b) Chia hết cho 15 = tận cùng 0 hoặc 5 và tổng chữ số chia hết cho 3: 405, 450, 480, 540, 840, có 5 số.", "en": "b) Divisible by 15 = ends in 0 or 5 and digit sum divisible by 3: 405, 450, 480, 540, 840, so 5 numbers."}, {"vi": "c) Chia hết cho 18 = chẵn và tổng chữ số chia hết cho 9: 450, 504, 540, có 3 số.", "en": "c) Divisible by 18 = even and digit sum divisible by 9: 450, 504, 540, so 3 numbers."}, {"vi": "d) Chia hết cho 45 = chia hết cho 5 và 9: 405, 450, 540, có 3 số.", "en": "d) Divisible by 45 = divisible by 5 and 9: 405, 450, 540, so 3 numbers."}], "tip": {"vi": "Liệt kê các số trước, rồi lọc theo dấu hiệu.", "en": "List the numbers first, then filter them by the divisibility rules."}, "src": "250 bài, CĐ9, Bài 6"}, {"id": "cd9-b8", "lesson": "divis", "rank": 3, "q": {"vi": "Cho số tự nhiên N = 3x57y. Thay x, y bởi những chữ số thích hợp để số đó chia 2 dư 1, chia 5 dư 3 và chia hết cho 9. Tìm y, hỏi có bao nhiêu số N như vậy và số N lớn nhất.", "en": "Let N = 3x57y be a natural number. Replace x and y with suitable digits so that N leaves remainder 1 when divided by 2, remainder 3 when divided by 5, and is divisible by 9. Find y, how many such numbers N there are, and the largest N."}, "parts": [{"kind": "num", "lab": {"vi": "Chữ số y", "en": "Digit y"}, "ans": 3, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số các số N", "en": "How many numbers N"}, "ans": 2, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số N lớn nhất", "en": "Largest N"}, "ans": 39573, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "N chia 5 dư 3 nên y = 3 hoặc y = 8; N chia 2 dư 1 nên N lẻ, vậy y = 3.", "en": "N leaves remainder 3 when divided by 5, so y = 3 or 8; N leaves remainder 1 when divided by 2, so N is odd and y = 3."}, {"vi": "N chia hết cho 9: 3 + x + 5 + 7 + 3 = 18 + x chia hết cho 9, nên x = 0 hoặc x = 9.", "en": "N divisible by 9: 3 + x + 5 + 7 + 3 = 18 + x is a multiple of 9, so x = 0 or x = 9."}, {"vi": "Có 2 số N là 30573 và 39573; số lớn nhất là 39573.", "en": "There are 2 numbers, 30,573 and 39,573; the largest is 39,573."}], "tip": {"vi": "Chữ số tận cùng cho biết số dư khi chia cho 2 và cho 5.", "en": "The last digit tells the remainder when dividing by 2 and by 5."}, "src": "250 bài, CĐ9, Bài 8"}, {"id": "cd9-b20", "lesson": "divis", "rank": 3, "q": {"vi": "Một cửa hàng có 7 rổ đựng trứng gà hoặc vịt (mỗi rổ chỉ đựng một loại). Số trứng thứ tự các rổ là: 45; 56; 60; 66; 75; 85 và 92. Sau khi bán 6 rổ, còn lại một rổ trứng gà, người ta thấy trong số trứng đã bán, số trứng vịt gấp 3 lần số trứng gà. Hỏi rổ trứng gà còn lại có bao nhiêu quả? Lúc đầu có bao nhiêu quả trứng gà, bao nhiêu quả trứng vịt?", "en": "A shop has 7 baskets of chicken eggs or duck eggs (each basket holds only one kind). The baskets hold 45, 56, 60, 66, 75, 85 and 92 eggs. After 6 baskets are sold, one basket of chicken eggs is left. Among the eggs sold, the number of duck eggs is 3 times the number of chicken eggs. How many eggs are in the basket of chicken eggs that is left? At the start, how many chicken eggs and how many duck eggs were there?"}, "parts": [{"kind": "num", "lab": {"vi": "Rổ gà còn lại", "en": "Chicken basket left"}, "ans": 75, "unit": {"vi": "quả", "en": "eggs"}}, {"kind": "num", "lab": {"vi": "Trứng gà lúc đầu", "en": "Chicken eggs at start"}, "ans": 176, "unit": {"vi": "quả", "en": "eggs"}}, {"kind": "num", "lab": {"vi": "Trứng vịt lúc đầu", "en": "Duck eggs at start"}, "ans": 303, "unit": {"vi": "quả", "en": "eggs"}}], "steps": [{"vi": "Tổng số trứng là 45 + 56 + 60 + 66 + 75 + 85 + 92 = 479.", "en": "The total number of eggs is 45 + 56 + 60 + 66 + 75 + 85 + 92 = 479."}, {"vi": "Trứng đã bán: trứng vịt gấp 3 lần trứng gà nên số trứng bán bằng 4 lần số trứng gà đã bán, tức là chia hết cho 4. Vậy 479 trừ đi số trứng của rổ còn lại phải chia hết cho 4.", "en": "Eggs sold: duck eggs are 3 times chicken eggs, so the eggs sold are 4 times the chicken eggs sold, which is divisible by 4. So 479 minus the left-over basket must be divisible by 4."}, {"vi": "479 chia 4 dư 3, trong các số đã cho chỉ có 75 chia 4 dư 3. Rổ còn lại có 75 quả, đã bán 479 − 75 = 404 quả.", "en": "479 ÷ 4 leaves 3, and among the given numbers only 75 leaves 3 when divided by 4. The left-over basket has 75 eggs, and 404 eggs were sold."}, {"vi": "Trứng gà đã bán là 404 : 4 = 101 = 45 + 56. Vậy trứng gà lúc đầu là 101 + 75 = 176 (quả), trứng vịt là 404 − 101 = 303 (quả).", "en": "Chicken eggs sold: 404 ÷ 4 = 101 = 45 + 56. So at the start there were 101 + 75 = 176 chicken eggs and 404 − 101 = 303 duck eggs."}], "tip": {"vi": "Số trứng đã bán chia hết cho 4.", "en": "The number of eggs sold is divisible by 4."}, "src": "250 bài, CĐ9, Bài 20"}], "quick": [{"id": "cd4-b1a", "lesson": "quick", "rank": 1, "q": {"vi": "Tính nhanh: 687 + 969 + 123", "en": "Calculate quickly: 687 + 969 + 123"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 1779, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Nhóm 687 + 123 = 810 vì 7 + 3 = 10.", "en": "Group 687 + 123 = 810 because 7 + 3 = 10."}, {"vi": "Cộng 810 + 969 = 1 779.", "en": "Then 810 + 969 = 1,779."}], "tip": {"vi": "Đổi chỗ các số hạng để cộng thành số tròn chục, trăm.", "en": "Swap the addends to make round numbers."}, "src": "250 bài, CĐ4, Bài 1a"}, {"id": "cd4-b1b", "lesson": "quick", "rank": 1, "q": {"vi": "Tính nhanh: 186 − 65 − 35", "en": "Calculate quickly: 186 − 65 − 35"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 86, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Trừ một số lần lượt bằng trừ tổng các số: 186 − (65 + 35).", "en": "Subtracting one by one equals subtracting the sum: 186 − (65 + 35)."}, {"vi": "65 + 35 = 100 nên 186 − 100 = 86.", "en": "65 + 35 = 100, so 186 − 100 = 86."}], "tip": {"vi": "Cộng hai số bị trừ trước.", "en": "Add the two numbers being subtracted first."}, "src": "250 bài, CĐ4, Bài 1b"}, {"id": "cd4-b1c", "lesson": "quick", "rank": 1, "q": {"vi": "Tính nhanh: 1024 − (1024 − 15)", "en": "Calculate quickly: 1,024 − (1,024 − 15)"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 15, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Bỏ ngoặc có dấu trừ đứng trước thì đổi dấu: 1 024 − 1 024 + 15.", "en": "Removing brackets after a minus sign flips the sign: 1,024 − 1,024 + 15."}, {"vi": "1 024 − 1 024 = 0 nên kết quả là 15.", "en": "1,024 − 1,024 = 0, so the result is 15."}], "tip": {"vi": "Số bị trừ 1 024 và số trừ chứa 1 024.", "en": "The number 1,024 appears in both parts."}, "src": "250 bài, CĐ4, Bài 1c"}, {"id": "cd4-b4a", "lesson": "quick", "rank": 1, "q": {"vi": "Tính nhanh: 4 × 125 × 25 × 8", "en": "Calculate quickly: 4 × 125 × 25 × 8"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 100000, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Ghép (4 × 25) × (125 × 8) = 100 × 1 000.", "en": "Pair (4 × 25) × (125 × 8) = 100 × 1,000."}, {"vi": "= 100 000.", "en": "= 100,000."}], "tip": {"vi": "4 × 25 = 100 và 125 × 8 = 1 000.", "en": "4 × 25 = 100 and 125 × 8 = 1,000."}, "src": "250 bài, CĐ4, Bài 4a"}, {"id": "cd4-b1d", "lesson": "quick", "rank": 2, "q": {"vi": "Tính nhanh: (368 + 764) − (363 + 759)", "en": "Calculate quickly: (368 + 764) − (363 + 759)"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 10, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tính hiệu từng cặp: 368 − 363 = 5 và 764 − 759 = 5.", "en": "Subtract in pairs: 368 − 363 = 5 and 764 − 759 = 5."}, {"vi": "Kết quả là 5 + 5 = 10.", "en": "The result is 5 + 5 = 10."}], "tip": {"vi": "Ghép từng cặp số gần nhau.", "en": "Pair up numbers that are close."}, "src": "250 bài, CĐ4, Bài 1d"}, {"id": "cd4-b1e", "lesson": "quick", "rank": 2, "q": {"vi": "Tính nhanh: 3145 − 246 + 2347 − 145 + 4246 − 347", "en": "Calculate quickly: 3,145 − 246 + 2,347 − 145 + 4,246 − 347"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 9000, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Nhóm các số: (3 145 − 145) + (2 347 − 347) + (4 246 − 246).", "en": "Group the numbers: (3,145 − 145) + (2,347 − 347) + (4,246 − 246)."}, {"vi": "= 3 000 + 2 000 + 4 000 = 9 000.", "en": "= 3,000 + 2,000 + 4,000 = 9,000."}], "tip": {"vi": "Tìm các cặp số có phần hàng trăm, chục, đơn vị giống nhau.", "en": "Look for pairs that differ only in thousands."}, "src": "250 bài, CĐ4, Bài 1e"}, {"id": "cd4-b2a", "lesson": "quick", "rank": 3, "q": {"vi": "Tính giá trị biểu thức (tính hợp lí nếu có thể): 92 × 164 − 64 × (82 + 2170 : 217)", "en": "Find the value (calculate smartly if possible): 92 × 164 − 64 × (82 + 2,170 ÷ 217)"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 9200, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tính trong ngoặc: 2 170 : 217 = 10 rồi 82 + 10 = 92.", "en": "Inside the brackets: 2,170 ÷ 217 = 10, then 82 + 10 = 92."}, {"vi": "Biểu thức thành 92 × 164 − 64 × 92 = 92 × (164 − 64).", "en": "The expression becomes 92 × 164 − 64 × 92 = 92 × (164 − 64)."}, {"vi": "= 92 × 100 = 9 200.", "en": "= 92 × 100 = 9,200."}], "tip": {"vi": "Tính phần trong ngoặc trước, rồi tìm thừa số chung.", "en": "Do the brackets first, then find the common factor."}, "src": "250 bài, CĐ4, Bài 2a"}, {"id": "cd4-b2b", "lesson": "quick", "rank": 2, "q": {"vi": "Tính giá trị biểu thức (tính hợp lí nếu có thể): (100 + 42) × 42 + (200 − 58) × 58", "en": "Find the value (calculate smartly if possible): (100 + 42) × 42 + (200 − 58) × 58"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 14200, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tính trong ngoặc: 100 + 42 = 142 và 200 − 58 = 142.", "en": "Inside the brackets: 100 + 42 = 142 and 200 − 58 = 142."}, {"vi": "Biểu thức = 142 × 42 + 142 × 58 = 142 × (42 + 58).", "en": "The expression = 142 × 42 + 142 × 58 = 142 × (42 + 58)."}, {"vi": "= 142 × 100 = 14 200.", "en": "= 142 × 100 = 14,200."}], "tip": {"vi": "Hai ngoặc có giá trị bằng nhau.", "en": "The two brackets have the same value."}, "src": "250 bài, CĐ4, Bài 2b"}, {"id": "cd4-b2d", "lesson": "quick", "rank": 2, "q": {"vi": "Tính giá trị biểu thức (tính hợp lí nếu có thể): (56 × 27 + 56 × 35) : 62", "en": "Find the value (calculate smartly if possible): (56 × 27 + 56 × 35) ÷ 62"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 56, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Đặt thừa số chung: 56 × (27 + 35) = 56 × 62.", "en": "Factor out 56: 56 × (27 + 35) = 56 × 62."}, {"vi": "(56 × 62) : 62 = 56.", "en": "(56 × 62) ÷ 62 = 56."}], "tip": {"vi": "Đặt thừa số chung 56 ra ngoài.", "en": "Take out the common factor 56."}, "src": "250 bài, CĐ4, Bài 2d"}, {"id": "cd4-b2g", "lesson": "quick", "rank": 2, "q": {"vi": "Tính giá trị biểu thức (tính hợp lí nếu có thể): (158 × 129 − 158 × 39) : 180", "en": "Find the value (calculate smartly if possible): (158 × 129 − 158 × 39) ÷ 180"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 79, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Đặt thừa số chung: 158 × (129 − 39) = 158 × 90.", "en": "Factor out 158: 158 × (129 − 39) = 158 × 90."}, {"vi": "(158 × 90) : 180 = 158 : 2 = 79.", "en": "(158 × 90) ÷ 180 = 158 ÷ 2 = 79."}], "tip": {"vi": "Đặt thừa số chung 158 ra ngoài.", "en": "Take out the common factor 158."}, "src": "250 bài, CĐ4, Bài 2g"}, {"id": "cd4-b3a", "lesson": "quick", "rank": 2, "q": {"vi": "Tính nhanh: 8 × 427 × 3 + 6 × 573 × 4", "en": "Calculate quickly: 8 × 427 × 3 + 6 × 573 × 4"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 24000, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "8 × 3 = 24 và 6 × 4 = 24, nên biểu thức = 24 × 427 + 24 × 573.", "en": "8 × 3 = 24 and 6 × 4 = 24, so the expression = 24 × 427 + 24 × 573."}, {"vi": "= 24 × (427 + 573) = 24 × 1 000 = 24 000.", "en": "= 24 × (427 + 573) = 24 × 1,000 = 24,000."}], "tip": {"vi": "Nhóm các thừa số nhỏ để có tích bằng nhau.", "en": "Group the small factors to get equal products."}, "src": "250 bài, CĐ4, Bài 3a"}, {"id": "cd4-b3b", "lesson": "quick", "rank": 2, "q": {"vi": "Tính nhanh: 86 × 27 − 43 × 54", "en": "Calculate quickly: 86 × 27 − 43 × 54"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 0, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Viết 86 = 43 × 2 nên 86 × 27 = 43 × 2 × 27 = 43 × 54.", "en": "Write 86 = 43 × 2, so 86 × 27 = 43 × 2 × 27 = 43 × 54."}, {"vi": "Hai tích bằng nhau nên hiệu bằng 0.", "en": "The two products are equal, so the difference is 0."}], "tip": {"vi": "Hãy so sánh 86 với 43 và 54 với 27.", "en": "Compare 86 with 43 and 54 with 27."}, "src": "250 bài, CĐ4, Bài 3b"}, {"id": "cd4-b3c", "lesson": "quick", "rank": 2, "q": {"vi": "Tính nhanh: (145 × 99 + 145) − (143 × 102 − 143)", "en": "Calculate quickly: (145 × 99 + 145) − (143 × 102 − 143)"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 57, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "145 × 99 + 145 = 145 × (99 + 1) = 14 500.", "en": "145 × 99 + 145 = 145 × (99 + 1) = 14,500."}, {"vi": "143 × 102 − 143 = 143 × (102 − 1) = 143 × 101 = 14 443.", "en": "143 × 102 − 143 = 143 × (102 − 1) = 143 × 101 = 14,443."}, {"vi": "Hiệu là 14 500 − 14 443 = 57.", "en": "The difference is 14,500 − 14,443 = 57."}], "tip": {"vi": "Viết 145 = 145 × 1 để đặt thừa số chung.", "en": "Write 145 as 145 × 1 to factor."}, "src": "250 bài, CĐ4, Bài 3c"}, {"id": "cd4-b3d", "lesson": "quick", "rank": 2, "q": {"vi": "Tính nhanh: 10 000 − 47 × 72 − 47 × 28", "en": "Calculate quickly: 10,000 − 47 × 72 − 47 × 28"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 5300, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Trừ lần lượt bằng trừ tổng: 10 000 − 47 × (72 + 28).", "en": "Subtracting one by one equals subtracting the sum: 10,000 − 47 × (72 + 28)."}, {"vi": "47 × 100 = 4 700 nên kết quả là 10 000 − 4 700 = 5 300.", "en": "47 × 100 = 4,700, so the result is 10,000 − 4,700 = 5,300."}], "tip": {"vi": "Đặt 47 làm thừa số chung.", "en": "Take out 47 as a common factor."}, "src": "250 bài, CĐ4, Bài 3d"}, {"id": "cd4-b3e", "lesson": "quick", "rank": 2, "q": {"vi": "Tính nhanh: 3457 − 27 × 48 − 48 × 73 + 6543", "en": "Calculate quickly: 3,457 − 27 × 48 − 48 × 73 + 6,543"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 5200, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Nhóm: (3 457 + 6 543) − 48 × (27 + 73).", "en": "Group: (3,457 + 6,543) − 48 × (27 + 73)."}, {"vi": "= 10 000 − 48 × 100 = 10 000 − 4 800 = 5 200.", "en": "= 10,000 − 48 × 100 = 10,000 − 4,800 = 5,200."}], "tip": {"vi": "Ghép 3 457 với 6 543.", "en": "Pair 3,457 with 6,543."}, "src": "250 bài, CĐ4, Bài 3e"}, {"id": "cd4-b4b", "lesson": "quick", "rank": 2, "q": {"vi": "Tính nhanh: 2 × 8 × 50 × 25 × 125", "en": "Calculate quickly: 2 × 8 × 50 × 25 × 125"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 2500000, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Ghép (2 × 50) × (8 × 125) × 25 = 100 × 1 000 × 25.", "en": "Pair (2 × 50) × (8 × 125) × 25 = 100 × 1,000 × 25."}, {"vi": "= 100 000 × 25 = 2 500 000.", "en": "= 100,000 × 25 = 2,500,000."}], "tip": {"vi": "Ghép các cặp cho tích là 100 và 1 000.", "en": "Make pairs with products 100 and 1,000."}, "src": "250 bài, CĐ4, Bài 4b"}, {"id": "cd4-b4c", "lesson": "quick", "rank": 2, "q": {"vi": "Tính nhanh: 2 × 3 × 4 × 5 × 50 × 25", "en": "Calculate quickly: 2 × 3 × 4 × 5 × 50 × 25"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 150000, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Ghép các thừa số thành (4 × 25) × (2 × 50) × (3 × 5).", "en": "Pair the factors as (4 × 25) × (2 × 50) × (3 × 5)."}, {"vi": "= 100 × 100 × 15 = 150 000.", "en": "= 100 × 100 × 15 = 150,000."}], "tip": {"vi": "4 × 25 = 100 và 2 × 50 = 100.", "en": "4 × 25 = 100 and 2 × 50 = 100."}, "src": "250 bài, CĐ4, Bài 4c"}, {"id": "l26-b3a", "lesson": "quick", "rank": 2, "q": {"vi": "Tính nhanh: 174 × 70 − 87 × 100 + 174 × 89 − 174 × 9", "en": "Calculate in a smart way: 174 × 70 − 87 × 100 + 174 × 89 − 174 × 9"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 17400, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Vì 87 × 100 = 87 × 2 × 50 = 174 × 50, nên ta viết lại biểu thức với thừa số chung 174.", "en": "Since 87 × 100 = 87 × 2 × 50 = 174 × 50, rewrite everything with the common factor 174."}, {"vi": "= 174 × 70 − 174 × 50 + 174 × 89 − 174 × 9.", "en": "= 174 × 70 − 174 × 50 + 174 × 89 − 174 × 9."}, {"vi": "= 174 × (70 − 50 + 89 − 9) = 174 × 100.", "en": "= 174 × (70 − 50 + 89 − 9) = 174 × 100."}, {"vi": "= 17 400.", "en": "= 17,400."}], "tip": {"vi": "Hãy viết 87 × 100 thành tích có thừa số 174.", "en": "Write 87 × 100 as a product with the factor 174."}, "src": "LẦN 26, Bài 3"}, {"id": "l26-b3b", "lesson": "quick", "rank": 2, "q": {"vi": "Tính nhanh: 145 × 15 − 2 × 145 − 435", "en": "Calculate in a smart way: 145 × 15 − 2 × 145 − 435"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 1450, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Vì 435 = 145 × 3 nên ta có thừa số chung 145.", "en": "Since 435 = 145 × 3, there is a common factor 145."}, {"vi": "= 145 × 15 − 145 × 2 − 145 × 3 = 145 × (15 − 2 − 3).", "en": "= 145 × 15 − 145 × 2 − 145 × 3 = 145 × (15 − 2 − 3)."}, {"vi": "= 145 × 10 = 1450.", "en": "= 145 × 10 = 1,450."}], "tip": {"vi": "435 là mấy lần 145?", "en": "435 is how many times 145?"}, "src": "LẦN 26, Bài 3"}, {"id": "l26-b3e", "lesson": "quick", "rank": 2, "q": {"vi": "Tính nhanh: 40 × 113 × 25 − 20 × 112 × 25 × 2", "en": "Calculate in a smart way: 40 × 113 × 25 − 20 × 112 × 25 × 2"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 1000, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "20 × 2 = 40 nên số bị trừ là 40 × 112 × 25.", "en": "20 × 2 = 40, so the subtrahend is 40 × 112 × 25."}, {"vi": "Biểu thức = 40 × 25 × 113 − 40 × 25 × 112 = 1000 × 113 − 1000 × 112.", "en": "The expression = 40 × 25 × 113 − 40 × 25 × 112 = 1,000 × 113 − 1,000 × 112."}, {"vi": "= 1000 × (113 − 112) = 1000.", "en": "= 1,000 × (113 − 112) = 1,000."}], "tip": {"vi": "Ghép 20 × 2, rồi 40 × 25.", "en": "Pair 20 × 2 first, then 40 × 25."}, "src": "LẦN 26, Bài 3"}, {"id": "l26-b3f", "lesson": "quick", "rank": 2, "q": {"vi": "Tính nhanh: 5 × 25 × 125 × 192", "en": "Calculate in a smart way: 5 × 25 × 125 × 192"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 3000000, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tách 192 = 8 × 24 để ghép 125 × 8 = 1000.", "en": "Split 192 = 8 × 24 so that 125 × 8 = 1,000."}, {"vi": "5 × 25 × 24 × (125 × 8) = 5 × 25 × 24 × 1000.", "en": "5 × 25 × 24 × (125 × 8) = 5 × 25 × 24 × 1,000."}, {"vi": "5 × 25 = 125 và 125 × 24 = 3000, nên kết quả là 3000 × 1000 = 3 000 000.", "en": "5 × 25 = 125 and 125 × 24 = 3,000, so the result is 3,000 × 1,000 = 3,000,000."}], "tip": {"vi": "125 × 8 = 1000.", "en": "125 × 8 = 1,000."}, "src": "LẦN 26, Bài 3"}, {"id": "cd4-b3h", "lesson": "quick", "rank": 3, "q": {"vi": "Tính nhanh: 326 × 728 + 327 × 272", "en": "Calculate quickly: 326 × 728 + 327 × 272"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 326272, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Viết 327 = 326 + 1 nên 327 × 272 = 326 × 272 + 272.", "en": "Write 327 = 326 + 1, so 327 × 272 = 326 × 272 + 272."}, {"vi": "Biểu thức = 326 × (728 + 272) + 272 = 326 × 1 000 + 272.", "en": "The expression = 326 × (728 + 272) + 272 = 326 × 1,000 + 272."}, {"vi": "= 326 000 + 272 = 326 272.", "en": "= 326,000 + 272 = 326,272."}], "tip": {"vi": "Tách 327 thành 326 + 1.", "en": "Split 327 into 326 + 1."}, "src": "250 bài, CĐ4, Bài 3h"}, {"id": "cd4-b3i", "lesson": "quick", "rank": 3, "q": {"vi": "Tính nhanh: 2008 × 867 + 2009 × 133", "en": "Calculate quickly: 2,008 × 867 + 2,009 × 133"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 2008133, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Viết 2 009 = 2 008 + 1 nên 2 009 × 133 = 2 008 × 133 + 133.", "en": "Write 2,009 = 2,008 + 1, so 2,009 × 133 = 2,008 × 133 + 133."}, {"vi": "Biểu thức = 2 008 × (867 + 133) + 133 = 2 008 × 1 000 + 133.", "en": "The expression = 2,008 × (867 + 133) + 133 = 2,008 × 1,000 + 133."}, {"vi": "= 2 008 000 + 133 = 2 008 133.", "en": "= 2,008,000 + 133 = 2,008,133."}], "tip": {"vi": "Tách 2 009 thành 2 008 + 1.", "en": "Split 2,009 into 2,008 + 1."}, "src": "250 bài, CĐ4, Bài 3i"}, {"id": "cd4-b4d", "lesson": "quick", "rank": 3, "q": {"vi": "Tính nhanh: 25 × 20 × 125 × 8 − 8 × 20 × 5 × 125", "en": "Calculate quickly: 25 × 20 × 125 × 8 − 8 × 20 × 5 × 125"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 400000, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Phép nhân trước: 25 × 20 × 125 × 8 = (25 × 20) × (125 × 8) = 500 × 1 000 = 500 000.", "en": "First product: 25 × 20 × 125 × 8 = (25 × 20) × (125 × 8) = 500 × 1,000 = 500,000."}, {"vi": "Tích thứ hai: 8 × 20 × 5 × 125 = (20 × 5) × (8 × 125) = 100 × 1 000 = 100 000.", "en": "Second product: 8 × 20 × 5 × 125 = (20 × 5) × (8 × 125) = 100 × 1,000 = 100,000."}, {"vi": "Hiệu là 500 000 − 100 000 = 400 000.", "en": "The difference is 500,000 − 100,000 = 400,000."}], "tip": {"vi": "Tính riêng từng tích bằng cách ghép cặp.", "en": "Work out each product separately by pairing."}, "src": "250 bài, CĐ4, Bài 4d"}, {"id": "l26-b3c", "lesson": "quick", "rank": 3, "q": {"vi": "Tính nhanh: A = 66 × 69 + 34 × 82 + 66 × 41 + 17 × 56", "en": "Calculate in a smart way: A = 66 × 69 + 34 × 82 + 66 × 41 + 17 × 56"}, "parts": [{"kind": "num", "lab": {"vi": "A", "en": "A"}, "ans": 11000, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Nhóm hai tích có thừa số 66: 66 × 69 + 66 × 41 = 66 × (69 + 41) = 66 × 110 = 7260.", "en": "Group the two products with the factor 66: 66 × 69 + 66 × 41 = 66 × (69 + 41) = 66 × 110 = 7,260."}, {"vi": "Vì 34 × 82 = 17 × 164 nên 34 × 82 + 17 × 56 = 17 × (164 + 56) = 17 × 220 = 3740.", "en": "Since 34 × 82 = 17 × 164, 34 × 82 + 17 × 56 = 17 × (164 + 56) = 17 × 220 = 3,740."}, {"vi": "A = 7260 + 3740 = 11 000.", "en": "A = 7,260 + 3,740 = 11,000."}], "tip": {"vi": "34 = 17 × 2, hãy đưa về thừa số chung 17.", "en": "34 = 17 × 2, so use the common factor 17."}, "src": "LẦN 26, Bài 3"}, {"id": "l26-b3d", "lesson": "quick", "rank": 3, "q": {"vi": "Tính nhanh: A = 54 × 69 + 46 × 82 + 54 × 41 + 23 × 56", "en": "Calculate in a smart way: A = 54 × 69 + 46 × 82 + 54 × 41 + 23 × 56"}, "parts": [{"kind": "num", "lab": {"vi": "A", "en": "A"}, "ans": 11000, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Nhóm hai tích có thừa số 54: 54 × 69 + 54 × 41 = 54 × 110 = 5940.", "en": "Group the two products with the factor 54: 54 × 69 + 54 × 41 = 54 × 110 = 5,940."}, {"vi": "Vì 46 × 82 = 23 × 164 nên 46 × 82 + 23 × 56 = 23 × (164 + 56) = 23 × 220 = 5060.", "en": "Since 46 × 82 = 23 × 164, 46 × 82 + 23 × 56 = 23 × (164 + 56) = 23 × 220 = 5,060."}, {"vi": "A = 5940 + 5060 = 11 000.", "en": "A = 5,940 + 5,060 = 11,000."}], "tip": {"vi": "46 = 23 × 2, hãy đưa về thừa số chung 23.", "en": "46 = 23 × 2, so use the common factor 23."}, "src": "LẦN 26, Bài 3"}, {"id": "cd10-b23e", "lesson": "quick", "rank": 3, "q": {"vi": "Tính giá trị biểu thức: (1248 : 5 × 625 × 4 × 2) / (2 × 312 × 125 : 25 × 10)", "en": "Find the value: (1248 ÷ 5 × 625 × 4 × 2) / (2 × 312 × 125 ÷ 25 × 10)"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 40, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tử số: 1248 : 5 × 625 = 1248 × (625 : 5) = 1248 × 125 = 156 000; rồi × 4 × 2 = 1 248 000.", "en": "Top: 1248 ÷ 5 × 625 = 1248 × (625 ÷ 5) = 1248 × 125 = 156,000; then × 4 × 2 = 1,248,000."}, {"vi": "Mẫu số: 2 × 312 = 624; 624 × 125 = 78 000; 78 000 : 25 = 3 120; 3 120 × 10 = 31 200.", "en": "Bottom: 2 × 312 = 624; 624 × 125 = 78,000; 78,000 ÷ 25 = 3,120; 3,120 × 10 = 31,200."}, {"vi": "1 248 000 : 31 200 = 40.", "en": "1,248,000 ÷ 31,200 = 40."}], "tip": {"vi": "Tính tử số và mẫu số riêng, rồi chia.", "en": "Work out the top and bottom separately, then divide."}, "src": "250 bài, CĐ10, Bài 23e"}], "findx": [{"id": "cd4-b5a", "lesson": "findx", "rank": 1, "q": {"vi": "Tìm x biết: x − 140 : 35 = 270", "en": "Find x: x − 140 ÷ 35 = 270"}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 274, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tính 140 : 35 = 4 nên x − 4 = 270.", "en": "140 ÷ 35 = 4, so x − 4 = 270."}, {"vi": "x = 270 + 4 = 274.", "en": "x = 270 + 4 = 274."}], "tip": {"vi": "Tính phép chia trước.", "en": "Do the division first."}, "src": "250 bài, CĐ4, Bài 5a"}, {"id": "cd6-b1", "lesson": "findx", "rank": 1, "q": {"vi": "Hai số có tổng là 5729. Nếu bớt số thứ nhất 1908 đơn vị và thêm vào số thứ hai 626 đơn vị thì được tổng mới bằng bao nhiêu?", "en": "Two numbers have a sum of 5,729. If you take 1,908 away from the first number and add 626 to the second number, what is the new sum?"}, "parts": [{"kind": "num", "lab": {"vi": "Tổng mới", "en": "New sum"}, "ans": 4447, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Bớt số thứ nhất 1908 thì tổng giảm 1908: 5729 − 1908 = 3821.", "en": "Taking 1,908 away from the first number lowers the sum by 1,908: 5,729 − 1,908 = 3,821."}, {"vi": "Thêm vào số thứ hai 626 thì tổng tăng 626: 3821 + 626 = 4447.", "en": "Adding 626 to the second number raises the sum by 626: 3,821 + 626 = 4,447."}], "tip": {"vi": "Tổng giảm đi bao nhiêu và tăng thêm bao nhiêu?", "en": "By how much does the sum go down, and by how much does it go up?"}, "src": "250 bài, CĐ6, Bài 1"}, {"id": "cd6-b2", "lesson": "findx", "rank": 1, "q": {"vi": "Sau khi cùng thêm vào số bị trừ và số trừ 285 đơn vị thì hiệu hai số bằng 20 187. Hỏi hiệu ban đầu của hai số là bao nhiêu?", "en": "After 285 is added to both the minuend and the subtrahend, the difference of the two numbers is 20,187. What was the original difference?"}, "parts": [{"kind": "num", "lab": {"vi": "Hiệu ban đầu", "en": "Original difference"}, "ans": 20187, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Cùng thêm một số vào số bị trừ và số trừ thì hiệu không thay đổi.", "en": "Adding the same number to both the minuend and the subtrahend does not change the difference."}, {"vi": "Vậy hiệu ban đầu bằng hiệu mới, là 20 187.", "en": "So the original difference equals the new difference, which is 20,187."}], "tip": {"vi": "Cả hai số cùng tăng thêm 285, khoảng cách giữa chúng có đổi không?", "en": "Both numbers go up by 285. Does the gap between them change?"}, "src": "250 bài, CĐ6, Bài 2"}, {"id": "cd6-b3", "lesson": "findx", "rank": 1, "q": {"vi": "Tìm hiệu của hai số, biết rằng sau khi bớt ở số bị trừ 95 đơn vị và thêm vào số trừ 56 đơn vị thì được hai số có hiệu là 7082.", "en": "Find the difference of two numbers, knowing that after 95 is taken away from the minuend and 56 is added to the subtrahend, the new difference is 7,082."}, "parts": [{"kind": "num", "lab": {"vi": "Hiệu ban đầu", "en": "Original difference"}, "ans": 7233, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Bớt số bị trừ 95 thì hiệu giảm 95; thêm vào số trừ 56 thì hiệu giảm thêm 56.", "en": "Taking 95 from the minuend lowers the difference by 95; adding 56 to the subtrahend lowers it by another 56."}, {"vi": "Hiệu đã giảm tất cả: 95 + 56 = 151.", "en": "The difference went down by 95 + 56 = 151 in all."}, {"vi": "Hiệu ban đầu: 7082 + 151 = 7233.", "en": "The original difference: 7,082 + 151 = 7,233."}], "tip": {"vi": "Cả hai thay đổi đều làm hiệu nhỏ đi.", "en": "Both changes make the difference smaller."}, "src": "250 bài, CĐ6, Bài 3"}, {"id": "cd6-b6", "lesson": "findx", "rank": 1, "q": {"vi": "Khi cộng một số tự nhiên với 107, một bạn học sinh đã chép nhầm 107 thành 1007 nên được kết quả là 1996. Tìm tổng đúng của phép cộng.", "en": "When adding a whole number and 107, a student copied 107 as 1,007 by mistake and got 1,996. Find the correct sum."}, "parts": [{"kind": "num", "lab": {"vi": "Tổng đúng", "en": "Correct sum"}, "ans": 1096, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số hạng bị chép lớn hơn số đúng: 1007 − 107 = 900.", "en": "The copied number was too big by 1,007 − 107 = 900."}, {"vi": "Một số hạng tăng 900 thì tổng tăng 900, nên tổng đúng nhỏ hơn 900.", "en": "If one addend is 900 too big, the sum is 900 too big."}, {"vi": "Tổng đúng: 1996 − 900 = 1096.", "en": "Correct sum: 1,996 − 900 = 1,096."}], "tip": {"vi": "Chép 1007 thay cho 107 làm tổng tăng hay giảm?", "en": "Does copying 1,007 instead of 107 make the sum bigger or smaller?"}, "src": "250 bài, CĐ6, Bài 6"}, {"id": "cd4-b10a", "lesson": "findx", "rank": 2, "q": {"vi": "Tìm chữ số x biết (xx là số có các chữ số đều bằng x): xx + x + 5 = 101", "en": "Find the digit x (xx is the number whose digits are all x): xx + x + 5 = 101"}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 8, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "xx = x × 11 nên x × 11 + x + 5 = 101.", "en": "xx = x × 11, so x × 11 + x + 5 = 101."}, {"vi": "x × 12 = 101 − 5 = 96 nên x = 8.", "en": "x × 12 = 101 − 5 = 96, so x = 8."}], "tip": {"vi": "xx là số có 2 chữ số đều bằng x.", "en": "xx is the 2-digit number whose digits are both x."}, "src": "250 bài, CĐ4, Bài 10a"}, {"id": "cd4-b5b", "lesson": "findx", "rank": 2, "q": {"vi": "Tìm x biết: 357 : (87 : x) = 119", "en": "Find x: 357 ÷ (87 ÷ x) = 119"}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 29, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số chia là 87 : x. Ta có 357 : (87 : x) = 119 nên 87 : x = 357 : 119 = 3.", "en": "The divisor is 87 ÷ x. Since 357 ÷ (87 ÷ x) = 119, we get 87 ÷ x = 357 ÷ 119 = 3."}, {"vi": "x = 87 : 3 = 29.", "en": "x = 87 ÷ 3 = 29."}], "tip": {"vi": "Tìm số chia trước, rồi tìm x.", "en": "Find the divisor first, then x."}, "src": "250 bài, CĐ4, Bài 5b"}, {"id": "cd4-b6c", "lesson": "findx", "rank": 2, "q": {"vi": "Tìm chữ số x biết (xxx, xx là các số có các chữ số đều bằng x): xxx + xx + x + x = 992", "en": "Find the digit x (xxx and xx are numbers whose digits are all x): xxx + xx + x + x = 992"}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 8, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "xxx là số có 3 chữ số đều bằng x: xxx = x × 111, xx = x × 11.", "en": "xxx is the 3-digit number whose digits are all x: xxx = x × 111, and xx = x × 11."}, {"vi": "Biểu thức = x × 111 + x × 11 + x + x = x × (111 + 11 + 1 + 1) = x × 124.", "en": "The expression = x × 111 + x × 11 + x + x = x × (111 + 11 + 1 + 1) = x × 124."}, {"vi": "x × 124 = 992 nên x = 992 : 124 = 8.", "en": "x × 124 = 992, so x = 992 ÷ 124 = 8."}], "tip": {"vi": "xxx = x × 111.", "en": "xxx = x × 111."}, "src": "250 bài, CĐ4, Bài 6c"}, {"id": "cd4-b9a", "lesson": "findx", "rank": 2, "q": {"vi": "Tìm x biết: 1200 : 24 − (17 − x) = 38", "en": "Find x: 1,200 ÷ 24 − (17 − x) = 38"}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 5, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "1 200 : 24 = 50 nên 50 − (17 − x) = 38.", "en": "1,200 ÷ 24 = 50, so 50 − (17 − x) = 38."}, {"vi": "17 − x = 50 − 38 = 12.", "en": "17 − x = 50 − 38 = 12."}, {"vi": "x = 17 − 12 = 5.", "en": "x = 17 − 12 = 5."}], "tip": {"vi": "Tìm 17 − x trước.", "en": "Find 17 − x first."}, "src": "250 bài, CĐ4, Bài 9a"}, {"id": "cd4-b9b", "lesson": "findx", "rank": 2, "q": {"vi": "Tìm x biết: 274 + 162 : x = 328", "en": "Find x: 274 + 162 ÷ x = 328"}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 3, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "162 : x = 328 − 274 = 54.", "en": "162 ÷ x = 328 − 274 = 54."}, {"vi": "x = 162 : 54 = 3.", "en": "x = 162 ÷ 54 = 3."}], "tip": {"vi": "Tìm số hạng 162 : x trước.", "en": "Find the term 162 ÷ x first."}, "src": "250 bài, CĐ4, Bài 9b"}, {"id": "cd4-b9c", "lesson": "findx", "rank": 2, "q": {"vi": "Tìm x biết: (x + 1) + (x + 3) + (x + 5) = 30", "en": "Find x: (x + 1) + (x + 3) + (x + 5) = 30"}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 7, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Có 3 số x và các số 1 + 3 + 5 = 9, nên x × 3 + 9 = 30.", "en": "There are three x's and 1 + 3 + 5 = 9, so x × 3 + 9 = 30."}, {"vi": "x × 3 = 21 nên x = 7.", "en": "x × 3 = 21, so x = 7."}], "tip": {"vi": "Gộp các số x lại với nhau.", "en": "Group the x's together."}, "src": "250 bài, CĐ4, Bài 9c"}, {"id": "cd4-b9d", "lesson": "findx", "rank": 2, "q": {"vi": "Tìm x biết: x × 75 + 57 × x = 32 604", "en": "Find x: x × 75 + 57 × x = 32,604"}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 247, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "x × 75 + 57 × x = x × (75 + 57) = x × 132.", "en": "x × 75 + 57 × x = x × (75 + 57) = x × 132."}, {"vi": "x = 32 604 : 132 = 247.", "en": "x = 32,604 ÷ 132 = 247."}], "tip": {"vi": "Đặt x làm thừa số chung.", "en": "Take out x as a common factor."}, "src": "250 bài, CĐ4, Bài 9d"}, {"id": "cd6-b14a", "lesson": "findx", "rank": 2, "q": {"vi": "Tìm số bị chia và số chia bé nhất để có thương bằng 125 và số dư bằng 47.", "en": "Find the dividend and the smallest divisor that give a quotient of 125 and a remainder of 47."}, "parts": [{"kind": "num", "lab": {"vi": "Số chia bé nhất", "en": "Smallest divisor"}, "ans": 48, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số bị chia", "en": "Dividend"}, "ans": 6047, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số dư phải bé hơn số chia, mà số dư là 47 nên số chia ít nhất là 47 + 1 = 48.", "en": "The remainder must be less than the divisor, and the remainder is 47, so the smallest divisor is 47 + 1 = 48."}, {"vi": "Số bị chia = thương × số chia + số dư.", "en": "Dividend = quotient × divisor + remainder."}, {"vi": "Số bị chia: 125 × 48 + 47 = 6000 + 47 = 6047.", "en": "Dividend: 125 × 48 + 47 = 6,000 + 47 = 6,047."}], "tip": {"vi": "Số dư luôn bé hơn số chia.", "en": "The remainder is always less than the divisor."}, "src": "250 bài, CĐ6, Bài 14a"}, {"id": "cd6-b4", "lesson": "findx", "rank": 2, "q": {"vi": "Khi thực hiện phép trừ hai số, một bạn đã sơ ý viết sai như sau: ở số trừ có hai chữ số cuối cùng là 49 đã viết thành 94 nên phép trừ sai có kết quả là 1935. Tìm hiệu ban đầu của phép trừ.", "en": "While subtracting two numbers, a student made a mistake: the last two digits of the subtrahend are 49, but were written as 94. The wrong subtraction gave 1,935. Find the original difference."}, "parts": [{"kind": "num", "lab": {"vi": "Hiệu ban đầu", "en": "Original difference"}, "ans": 1980, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số trừ bị viết tăng lên: 94 − 49 = 45 đơn vị.", "en": "The subtrahend was written 94 − 49 = 45 too big."}, {"vi": "Số trừ tăng 45 thì hiệu giảm 45, nên hiệu sai nhỏ hơn hiệu đúng 45 đơn vị.", "en": "When the subtrahend goes up by 45, the difference goes down by 45, so the wrong result is 45 less than the right one."}, {"vi": "Hiệu đúng: 1935 + 45 = 1980.", "en": "The correct difference: 1,935 + 45 = 1,980."}], "tip": {"vi": "Số trừ viết sai lớn hơn hay nhỏ hơn số trừ đúng?", "en": "Is the wrong subtrahend bigger or smaller than the right one?"}, "src": "250 bài, CĐ6, Bài 4"}, {"id": "cd6-b5", "lesson": "findx", "rank": 2, "q": {"vi": "Trong một phép trừ, biết tổng của số bị trừ, số trừ và hiệu bằng 2000. Tìm số bị trừ và số trừ, biết số trừ lớn hơn hiệu 200 đơn vị.", "en": "In a subtraction, the sum of the minuend, the subtrahend and the difference is 2,000. Find the minuend and the subtrahend, knowing that the subtrahend is 200 more than the difference."}, "parts": [{"kind": "num", "lab": {"vi": "Số bị trừ", "en": "Minuend"}, "ans": 1000, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số trừ", "en": "Subtrahend"}, "ans": 600, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số bị trừ = số trừ + hiệu, nên tổng ba số bằng 2 lần số bị trừ.", "en": "The minuend = subtrahend + difference, so the sum of the three numbers is 2 times the minuend."}, {"vi": "Số bị trừ: 2000 : 2 = 1000. Số trừ + hiệu = 1000.", "en": "Minuend: 2,000 ÷ 2 = 1,000. Subtrahend + difference = 1,000."}, {"vi": "Số trừ hơn hiệu 200 nên hiệu: (1000 − 200) : 2 = 400.", "en": "The subtrahend is 200 more than the difference, so the difference is (1,000 − 200) ÷ 2 = 400."}, {"vi": "Số trừ: 400 + 200 = 600.", "en": "Subtrahend: 400 + 200 = 600."}], "tip": {"vi": "Số bị trừ bằng số trừ cộng hiệu.", "en": "The minuend equals the subtrahend plus the difference."}, "src": "250 bài, CĐ6, Bài 5"}, {"id": "cd6-b7", "lesson": "findx", "rank": 2, "q": {"vi": "Hai số có tổng bằng 1148. Gấp số hạng thứ hai lên 4 lần và giữ nguyên số hạng thứ nhất thì tổng mới bằng 2015. Tìm hai số đó.", "en": "Two numbers have a sum of 1,148. If the second number is multiplied by 4 and the first number stays the same, the new sum is 2,015. Find the two numbers."}, "parts": [{"kind": "num", "lab": {"vi": "Số thứ nhất", "en": "First number"}, "ans": 859, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số thứ hai", "en": "Second number"}, "ans": 289, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Gấp số thứ hai lên 4 lần thì tổng tăng thêm 3 lần số thứ hai.", "en": "Multiplying the second number by 4 raises the sum by 3 times the second number."}, {"vi": "Tổng tăng: 2015 − 1148 = 867.", "en": "The sum rises by 2,015 − 1,148 = 867."}, {"vi": "Số thứ hai: 867 : 3 = 289.", "en": "Second number: 867 ÷ 3 = 289."}, {"vi": "Số thứ nhất: 1148 − 289 = 859.", "en": "First number: 1,148 − 289 = 859."}], "tip": {"vi": "Tổng tăng thêm bằng mấy lần số thứ hai?", "en": "The sum goes up by how many times the second number?"}, "src": "250 bài, CĐ6, Bài 7"}, {"id": "cd4-b10b", "lesson": "findx", "rank": 3, "q": {"vi": "Tìm chữ số x biết (xxx, xx là các số có các chữ số đều bằng x): xxx − xx − x − 25 = 272", "en": "Find the digit x (xxx and xx are numbers whose digits are all x): xxx − xx − x − 25 = 272"}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 3, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "xxx = x × 111, xx = x × 11 nên x × 111 − x × 11 − x − 25 = 272.", "en": "xxx = x × 111 and xx = x × 11, so x × 111 − x × 11 − x − 25 = 272."}, {"vi": "x × (111 − 11 − 1) = 272 + 25 = 297, tức x × 99 = 297.", "en": "x × (111 − 11 − 1) = 272 + 25 = 297, so x × 99 = 297."}, {"vi": "x = 297 : 99 = 3.", "en": "x = 297 ÷ 99 = 3."}], "tip": {"vi": "Cộng 25 vào hai vế trước.", "en": "Add 25 to both sides first."}, "src": "250 bài, CĐ4, Bài 10b"}, {"id": "cd4-b10c", "lesson": "findx", "rank": 3, "q": {"vi": "Tìm chữ số x biết (xxx, xx là các số có các chữ số đều bằng x): xxx + xx + x + x + x + 1 = 1001", "en": "Find the digit x (xxx and xx are numbers whose digits are all x): xxx + xx + x + x + x + 1 = 1,001"}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 8, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "xxx = x × 111, xx = x × 11 nên biểu thức = x × (111 + 11 + 1 + 1 + 1) + 1 = x × 125 + 1.", "en": "xxx = x × 111 and xx = x × 11, so the expression = x × (111 + 11 + 1 + 1 + 1) + 1 = x × 125 + 1."}, {"vi": "x × 125 = 1 001 − 1 = 1 000.", "en": "x × 125 = 1,001 − 1 = 1,000."}, {"vi": "x = 1 000 : 125 = 8.", "en": "x = 1,000 ÷ 125 = 8."}], "tip": {"vi": "Có ba chữ số x lẻ tẻ.", "en": "There are three single x's."}, "src": "250 bài, CĐ4, Bài 10c"}, {"id": "cd4-b10d", "lesson": "findx", "rank": 3, "q": {"vi": "Tìm chữ số x biết (xxx, xx là các số có các chữ số đều bằng x): 35 655 − xxx − xx − x = 34 548", "en": "Find the digit x (xxx and xx are numbers whose digits are all x): 35,655 − xxx − xx − x = 34,548"}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 9, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số trừ là xxx + xx + x = x × 111 + x × 11 + x = x × 123.", "en": "The amount subtracted is xxx + xx + x = x × 111 + x × 11 + x = x × 123."}, {"vi": "x × 123 = 35 655 − 34 548 = 1 107.", "en": "x × 123 = 35,655 − 34,548 = 1,107."}, {"vi": "x = 1 107 : 123 = 9.", "en": "x = 1,107 ÷ 123 = 9."}], "tip": {"vi": "Trừ liên tiếp bằng trừ tổng.", "en": "Subtracting one by one equals subtracting the sum."}, "src": "250 bài, CĐ4, Bài 10d"}, {"id": "cd4-b5c", "lesson": "findx", "rank": 3, "q": {"vi": "Tìm x biết: x × 101 − x + 72 × 99 + 72 = 21 500", "en": "Find x: x × 101 − x + 72 × 99 + 72 = 21,500"}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 143, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "x × 101 − x = x × (101 − 1) = x × 100.", "en": "x × 101 − x = x × (101 − 1) = x × 100."}, {"vi": "72 × 99 + 72 = 72 × (99 + 1) = 7 200.", "en": "72 × 99 + 72 = 72 × (99 + 1) = 7,200."}, {"vi": "x × 100 = 21 500 − 7 200 = 14 300, nên x = 143.", "en": "x × 100 = 21,500 − 7,200 = 14,300, so x = 143."}], "tip": {"vi": "Gộp các phần chứa x và các phần là số.", "en": "Combine the parts with x and the plain-number parts."}, "src": "250 bài, CĐ4, Bài 5c"}, {"id": "cd4-b5d", "lesson": "findx", "rank": 3, "q": {"vi": "Tìm x biết: 2010 : x − 1307 : x = 37", "en": "Find x: 2,010 ÷ x − 1,307 ÷ x = 37"}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 19, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hai phép chia có cùng số chia x nên 2 010 : x − 1 307 : x = (2 010 − 1 307) : x.", "en": "Both divisions use the same divisor x, so 2,010 ÷ x − 1,307 ÷ x = (2,010 − 1,307) ÷ x."}, {"vi": "Ta có 703 : x = 37 nên x = 703 : 37 = 19.", "en": "So 703 ÷ x = 37 and x = 703 ÷ 37 = 19."}], "tip": {"vi": "Dùng tính chất a : x − b : x = (a − b) : x.", "en": "Use a ÷ x − b ÷ x = (a − b) ÷ x."}, "src": "250 bài, CĐ4, Bài 5d"}, {"id": "cd4-b6b", "lesson": "findx", "rank": 3, "q": {"vi": "Tìm x biết: x × 32 : 8 + x × 18 : 3 − x × 10 : 5 = 120", "en": "Find x: x × 32 ÷ 8 + x × 18 ÷ 3 − x × 10 ÷ 5 = 120"}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 15, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "x : 8 × 32 = x × (32 : 8) = x × 4; x : 3 × 18 = x × 6; x : 5 × 10 = x × 2.", "en": "x ÷ 8 × 32 = x × (32 ÷ 8) = x × 4; x ÷ 3 × 18 = x × 6; x ÷ 5 × 10 = x × 2."}, {"vi": "Biểu thức thành x × 4 + x × 6 − x × 2 = x × (4 + 6 − 2) = x × 8.", "en": "The expression becomes x × 4 + x × 6 − x × 2 = x × (4 + 6 − 2) = x × 8."}, {"vi": "x × 8 = 120 nên x = 120 : 8 = 15.", "en": "x × 8 = 120, so x = 120 ÷ 8 = 15."}], "tip": {"vi": "Đưa mọi phần về dạng x nhân một số.", "en": "Turn every part into x times a number."}, "src": "250 bài, CĐ4, Bài 6b"}, {"id": "cd4-b9e", "lesson": "findx", "rank": 3, "q": {"vi": "Tìm x biết: 216 : x + 34 : x = 10", "en": "Find x: 216 ÷ x + 34 ÷ x = 10"}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 25, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hai phép chia cùng chia cho x: (216 + 34) : x = 10.", "en": "Both are divided by x: (216 + 34) ÷ x = 10."}, {"vi": "250 : x = 10 nên x = 250 : 10 = 25.", "en": "250 ÷ x = 10, so x = 250 ÷ 10 = 25."}], "tip": {"vi": "Dùng tính chất a : x + b : x = (a + b) : x.", "en": "Use a ÷ x + b ÷ x = (a + b) ÷ x."}, "src": "250 bài, CĐ4, Bài 9e"}, {"id": "cd4-b9g", "lesson": "findx", "rank": 3, "q": {"vi": "Tìm x biết: 125 + (x − 25) × 5 + x = 150", "en": "Find x: 125 + (x − 25) × 5 + x = 150"}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 25, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Từ 125 + (x − 25) × 5 + x = 150 suy ra (x − 25) × 5 + x = 150 − 125 = 25.", "en": "From 125 + (x − 25) × 5 + x = 150 we get (x − 25) × 5 + x = 150 − 125 = 25."}, {"vi": "Nếu x lớn hơn 25 thì (x − 25) × 5 + x đã lớn hơn 25; nếu x nhỏ hơn 25 thì x − 25 không trừ được. Vậy x − 25 = 0 và x = 25.", "en": "If x were more than 25, then (x − 25) × 5 + x would be more than 25; if x were less than 25, x − 25 could not be subtracted. So x − 25 = 0 and x = 25."}, {"vi": "Thử lại: 125 + 0 × 5 + 25 = 150.", "en": "Check: 125 + 0 × 5 + 25 = 150."}], "tip": {"vi": "Nếu x > 25 thì x đã lớn hơn 25 rồi.", "en": "If x > 25, then x alone is already more than 25."}, "src": "250 bài, CĐ4, Bài 9g"}, {"id": "cd6-b10", "lesson": "findx", "rank": 3, "q": {"vi": "Tìm hai số có hiệu bằng 1850, biết nếu viết thêm một chữ số 5 vào bên phải số trừ và giữ nguyên số bị trừ thì được hiệu mới bằng 360.", "en": "Find two numbers whose difference is 1,850, knowing that if a digit 5 is written at the right end of the subtrahend and the minuend stays the same, the new difference is 360."}, "parts": [{"kind": "num", "lab": {"vi": "Số bị trừ", "en": "Minuend"}, "ans": 2015, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số trừ", "en": "Subtrahend"}, "ans": 165, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Viết thêm chữ số 5 vào bên phải thì số trừ mới = số trừ cũ × 10 + 5, tức tăng 9 lần số trừ cũ rồi thêm 5.", "en": "Writing 5 on the right makes the new subtrahend = old × 10 + 5, which is 9 times the old one plus 5 more."}, {"vi": "Hiệu giảm: 1850 − 360 = 1490, gồm 9 lần số trừ cộng 5.", "en": "The difference drops by 1,850 − 360 = 1,490, which is 9 times the subtrahend plus 5."}, {"vi": "9 lần số trừ: 1490 − 5 = 1485; số trừ: 1485 : 9 = 165.", "en": "9 times the subtrahend: 1,490 − 5 = 1,485; subtrahend: 1,485 ÷ 9 = 165."}, {"vi": "Số bị trừ: 165 + 1850 = 2015.", "en": "Minuend: 165 + 1,850 = 2,015."}], "tip": {"vi": "Số trừ mới bằng 10 lần số cũ cộng thêm 5.", "en": "The new subtrahend is 10 times the old one plus 5."}, "src": "250 bài, CĐ6, Bài 10"}, {"id": "cd6-b12a", "lesson": "findx", "rank": 3, "q": {"vi": "Tìm hai số biết thương của chúng bằng {1/4} số lớn và gấp 8 lần số bé.", "en": "Find two numbers whose quotient is {1/4} of the larger number and 8 times the smaller number."}, "parts": [{"kind": "num", "lab": {"vi": "Số lớn", "en": "Larger number"}, "ans": 128, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số bé", "en": "Smaller number"}, "ans": 4, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Thương = số lớn : số bé. Thương bằng {1/4} số lớn nên số lớn : số bé = số lớn : 4, suy ra số bé = 4.", "en": "Quotient = larger ÷ smaller. The quotient is {1/4} of the larger number, so larger ÷ smaller = larger ÷ 4, which means the smaller number is 4."}, {"vi": "Thương gấp 8 lần số bé: 8 × 4 = 32.", "en": "The quotient is 8 times the smaller number: 8 × 4 = 32."}, {"vi": "Số lớn = thương × số bé: 32 × 4 = 128.", "en": "Larger number = quotient × smaller number: 32 × 4 = 128."}], "tip": {"vi": "Chia cho 4 cho cùng thương như chia cho số bé, vậy số bé là mấy?", "en": "Dividing by 4 gives the same quotient as dividing by the smaller number. So what is the smaller number?"}, "src": "250 bài, CĐ6, Bài 12a"}, {"id": "cd6-b12b", "lesson": "findx", "rank": 3, "q": {"vi": "Tìm hai số biết số bé bằng {1/3} thương (thương của số lớn chia cho số bé) và thương bằng {1/9} số lớn.", "en": "Find two numbers if the smaller number is {1/3} of their quotient (the larger number divided by the smaller) and the quotient is {1/9} of the larger number."}, "parts": [{"kind": "num", "lab": {"vi": "Số lớn", "en": "Larger number"}, "ans": 243, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số bé", "en": "Smaller number"}, "ans": 9, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số lớn gấp thương 9 lần, số bé bằng {1/3} thương, nên số lớn gấp số bé: 9 × 3 = 27 lần.", "en": "The larger number is 9 times the quotient and the smaller is {1/3} of the quotient, so the larger is 9 × 3 = 27 times the smaller."}, {"vi": "Vậy thương = số lớn : số bé = 27.", "en": "So the quotient = larger ÷ smaller = 27."}, {"vi": "Số bé: 27 : 3 = 9.", "en": "Smaller number: 27 ÷ 3 = 9."}, {"vi": "Số lớn: 27 × 9 = 243.", "en": "Larger number: 27 × 9 = 243."}], "tip": {"vi": "Số lớn gấp số bé bao nhiêu lần?", "en": "How many times as big as the smaller number is the larger number?"}, "src": "250 bài, CĐ6, Bài 12b"}, {"id": "cd6-b14b", "lesson": "findx", "rank": 3, "q": {"vi": "Tìm số bị chia của một phép chia biết thương gấp 24 lần số chia và có số dư lớn nhất là 78.", "en": "Find the dividend of a division, knowing that the quotient is 24 times the divisor and the remainder is the largest possible, 78."}, "parts": [{"kind": "num", "lab": {"vi": "Số chia", "en": "Divisor"}, "ans": 79, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Thương", "en": "Quotient"}, "ans": 1896, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số bị chia", "en": "Dividend"}, "ans": 149862, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số dư lớn nhất là 78 nên số chia lớn hơn 78 một đơn vị: 78 + 1 = 79.", "en": "The largest remainder is 78, so the divisor is 1 more: 78 + 1 = 79."}, {"vi": "Thương: 79 × 24 = 1896.", "en": "Quotient: 79 × 24 = 1,896."}, {"vi": "Số bị chia: 1896 × 79 + 78 = 149 784 + 78 = 149 862.", "en": "Dividend: 1,896 × 79 + 78 = 149,784 + 78 = 149,862."}], "tip": {"vi": "Số dư lớn nhất bằng số chia trừ 1.", "en": "The largest remainder is the divisor minus 1."}, "src": "250 bài, CĐ6, Bài 14b"}, {"id": "cd6-b14c", "lesson": "findx", "rank": 3, "q": {"vi": "Tìm một số, biết rằng nếu đem số đó chia cho 97 thì được thương kém số dư 2 đơn vị, đồng thời số dư là số lẻ lớn nhất trong các số dư có thể có.", "en": "Find a number, knowing that when it is divided by 97 the quotient is 2 less than the remainder, and the remainder is the largest odd number among all possible remainders."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 9116, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số dư lớn nhất có thể là 96, nhưng 96 là số chẵn; số lẻ lớn nhất là 95.", "en": "The largest possible remainder is 96, but it is even; the largest odd one is 95."}, {"vi": "Thương kém số dư 2 đơn vị: 95 − 2 = 93.", "en": "The quotient is 2 less than the remainder: 95 − 2 = 93."}, {"vi": "Số cần tìm: 93 × 97 + 95 = 9021 + 95 = 9116.", "en": "The number: 93 × 97 + 95 = 9,021 + 95 = 9,116."}], "tip": {"vi": "Số dư khi chia cho 97 nhiều nhất là 96.", "en": "The remainder when dividing by 97 is at most 96."}, "src": "250 bài, CĐ6, Bài 14c"}, {"id": "cd6-b15a", "lesson": "findx", "rank": 3, "q": {"vi": "Một phép chia có số chia bằng 65, số dư bằng 31. Hỏi phải bớt đi ở số bị chia ít nhất bao nhiêu đơn vị để được phép chia hết và thương giảm đi 5 đơn vị?", "en": "A division has a divisor of 65 and a remainder of 31. What is the least amount that must be taken away from the dividend to make the division exact and the quotient 5 less?"}, "parts": [{"kind": "num", "lab": {"vi": "Phải bớt", "en": "Amount to take away"}, "ans": 356, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Bớt 31 đơn vị (bằng số dư) thì được phép chia hết, thương chưa đổi.", "en": "Taking away 31 (the remainder) makes the division exact, but the quotient stays the same."}, {"vi": "Muốn thương giảm 5 thì bớt thêm 5 lần số chia: 65 × 5 = 325.", "en": "To make the quotient 5 less, take away 5 more times the divisor: 65 × 5 = 325."}, {"vi": "Tổng cộng phải bớt: 31 + 325 = 356.", "en": "The total to take away: 31 + 325 = 356."}], "tip": {"vi": "Bớt đúng số dư trước, rồi mới giảm thương.", "en": "Remove the remainder first, then lower the quotient."}, "src": "250 bài, CĐ6, Bài 15a"}, {"id": "cd6-b8", "lesson": "findx", "rank": 3, "q": {"vi": "Hiệu của hai số là 2162. Nếu viết thêm chữ số 0 vào tận cùng bên phải số trừ và vẫn giữ nguyên số bị trừ thì được hiệu mới là 56. Tìm số bị trừ và số trừ.", "en": "The difference of two numbers is 2,162. If a digit 0 is written at the right end of the subtrahend and the minuend stays the same, the new difference is 56. Find the minuend and the subtrahend."}, "parts": [{"kind": "num", "lab": {"vi": "Số bị trừ", "en": "Minuend"}, "ans": 2396, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số trừ", "en": "Subtrahend"}, "ans": 234, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Viết thêm chữ số 0 vào bên phải số trừ thì số trừ gấp lên 10 lần, tức tăng thêm 9 lần số trừ cũ.", "en": "Writing a 0 on the right makes the subtrahend 10 times as big, so it goes up by 9 times the old subtrahend."}, {"vi": "Hiệu giảm đúng bằng phần tăng đó: 2162 − 56 = 2106.", "en": "The difference drops by exactly that amount: 2,162 − 56 = 2,106."}, {"vi": "Số trừ: 2106 : 9 = 234.", "en": "Subtrahend: 2,106 ÷ 9 = 234."}, {"vi": "Số bị trừ: 234 + 2162 = 2396.", "en": "Minuend: 234 + 2,162 = 2,396."}], "tip": {"vi": "Số trừ tăng thêm bao nhiêu lần số trừ cũ?", "en": "The subtrahend goes up by how many times its old value?"}, "src": "250 bài, CĐ6, Bài 8"}, {"id": "cd6-b9", "lesson": "findx", "rank": 3, "q": {"vi": "Khi trừ một số có 3 chữ số cho một số có 1 chữ số, do đãng trí, một bạn học sinh đã đặt số trừ thẳng với chữ số hàng trăm nên đã được kết quả là 486, mà lẽ ra kết quả đúng phải là 783. Tìm số bị trừ và số trừ.", "en": "When subtracting a one-digit number from a 3-digit number, an absent-minded student lined up the subtrahend with the hundreds digit and got 486, but the correct result should be 783. Find the minuend and the subtrahend."}, "parts": [{"kind": "num", "lab": {"vi": "Số bị trừ", "en": "Minuend"}, "ans": 786, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số trừ", "en": "Subtrahend"}, "ans": 3, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Đặt thẳng hàng trăm nghĩa là trừ đi số trừ × 100, tức gấp số trừ lên 100 lần.", "en": "Lining up with the hundreds means subtracting 100 times the subtrahend."}, {"vi": "Kết quả giảm: 783 − 486 = 297, đó là 99 lần số trừ (100 − 1).", "en": "The result dropped by 783 − 486 = 297, which is 99 times the subtrahend (100 − 1)."}, {"vi": "Số trừ: 297 : 99 = 3.", "en": "Subtrahend: 297 ÷ 99 = 3."}, {"vi": "Số bị trừ: 783 + 3 = 786.", "en": "Minuend: 783 + 3 = 786."}], "tip": {"vi": "Số trừ sai gấp số trừ đúng bao nhiêu lần?", "en": "How many times as big is the wrong subtrahend as the right one?"}, "src": "250 bài, CĐ6, Bài 9"}, {"id": "l26-b4c", "lesson": "findx", "rank": 3, "q": {"vi": "Tìm y: {24/y} : {8/3} = {3/5}", "en": "Find y: {24/y} ÷ {8/3} = {3/5}"}, "parts": [{"kind": "num", "lab": {"vi": "y", "en": "y"}, "ans": 15, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "{24/y} là số bị chia, nên {24/y} = {3/5} × {8/3} (thương nhân số chia).", "en": "{24/y} is the dividend, so {24/y} = {3/5} × {8/3} (quotient times divisor)."}, {"vi": "{3/5} × {8/3} = {24/15} = {8/5}.", "en": "{3/5} × {8/3} = {24/15} = {8/5}."}, {"vi": "{24/y} = {8/5} = {24/15}, vậy y = 15.", "en": "{24/y} = {8/5} = {24/15}, so y = 15."}], "tip": {"vi": "Số bị chia = thương × số chia.", "en": "Dividend = quotient × divisor."}, "src": "LẦN 26, Bài 4"}, {"id": "l26-b4e", "lesson": "findx", "rank": 3, "q": {"vi": "Tìm X: 22 × (X − 8) = 13 × X + 22", "en": "Find X: 22 × (X − 8) = 13 × X + 22"}, "parts": [{"kind": "num", "lab": {"vi": "X", "en": "X"}, "ans": 22, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Vế trái: 22 × (X − 8) = 22 × X − 22 × 8 = 22 × X − 176.", "en": "Left side: 22 × (X − 8) = 22 × X − 22 × 8 = 22 × X − 176."}, {"vi": "Vậy 22 × X − 176 = 13 × X + 22, nên (22 − 13) × X = 176 + 22.", "en": "So 22 × X − 176 = 13 × X + 22, which gives (22 − 13) × X = 176 + 22."}, {"vi": "9 × X = 198.", "en": "9 × X = 198."}, {"vi": "X = 198 : 9 = 22.", "en": "X = 198 ÷ 9 = 22."}], "tip": {"vi": "Nhân 22 với từng số trong ngoặc, rồi gom các số X về một bên.", "en": "Multiply 22 by each term in the parentheses, then gather the X terms on one side."}, "src": "LẦN 26, Bài 4"}, {"id": "l26-b4g", "lesson": "findx", "rank": 3, "q": {"vi": "Tìm X: 15 × (X − 6) = 5 × X + 10", "en": "Find X: 15 × (X − 6) = 5 × X + 10"}, "parts": [{"kind": "num", "lab": {"vi": "X", "en": "X"}, "ans": 10, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Vế trái: 15 × (X − 6) = 15 × X − 90.", "en": "Left side: 15 × (X − 6) = 15 × X − 90."}, {"vi": "15 × X − 90 = 5 × X + 10 nên (15 − 5) × X = 90 + 10.", "en": "15 × X − 90 = 5 × X + 10, so (15 − 5) × X = 90 + 10."}, {"vi": "10 × X = 100.", "en": "10 × X = 100."}, {"vi": "X = 100 : 10 = 10.", "en": "X = 100 ÷ 10 = 10."}], "tip": {"vi": "Nhân 15 với từng số trong ngoặc, rồi gom các số X về một bên.", "en": "Multiply 15 by each term in the parentheses, then gather the X terms on one side."}, "src": "LẦN 26, Bài 4"}], "struct": [{"id": "cd8-b2", "lesson": "struct", "rank": 1, "q": {"vi": "Tìm một số tự nhiên có ba chữ số biết nếu viết thêm vào đằng trước số đó một chữ số 2 ta được số mới bằng 9 lần số phải tìm.", "en": "Find a three-digit natural number such that writing the digit 2 in front of it gives a new number equal to 9 times the original number."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 250, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Viết thêm 2 vào đằng trước số có ba chữ số thì số mới hơn số cũ 2000 đơn vị.", "en": "Writing 2 in front of a 3-digit number adds 2,000."}, {"vi": "Số mới gấp 9 lần số cũ nên hiệu là 8 lần số cũ: 8 lần số cũ = 2000.", "en": "The new number is 9 times the old one, so the difference is 8 times the old number: 8 times = 2,000."}, {"vi": "Số cần tìm: 2000 : 8 = 250.", "en": "The number is 2,000 ÷ 8 = 250."}], "tip": {"vi": "Vẽ sơ đồ: số mới 9 phần, số cũ 1 phần.", "en": "Draw a diagram: new number 9 parts, old number 1 part."}, "src": "250 bài, CĐ8, Bài 2"}, {"id": "cd8-b20", "lesson": "struct", "rank": 1, "q": {"vi": "Tìm các chữ số a, b, c, d biết: abcd + abc + ab + a = 1111 (abcd, abc, ab là các số có các chữ số a, b, c, d).", "en": "Find the digits a, b, c, d if abcd + abc + ab + a = 1,111 (abcd, abc and ab are numbers made of the digits a, b, c, d)."}, "parts": [{"kind": "num", "lab": {"vi": "Chữ số a", "en": "Digit a"}, "ans": 1, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Chữ số b", "en": "Digit b"}, "ans": 0, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Chữ số c", "en": "Digit c"}, "ans": 0, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Chữ số d", "en": "Digit d"}, "ans": 0, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tổng bằng 1111 × a + 111 × b + 11 × c + d = 1111.", "en": "The sum equals 1111 × a + 111 × b + 11 × c + d = 1,111."}, {"vi": "a là chữ số đầu nên a ≥ 1; nếu a ≥ 2 thì tổng đã ≥ 2222 (quá lớn), nên a = 1.", "en": "a is a leading digit so a ≥ 1; if a ≥ 2 the sum would be at least 2,222, too big, so a = 1."}, {"vi": "Khi đó 1111 × 1 = 1111 đã đủ, nên 111 × b + 11 × c + d = 0, vậy b = c = d = 0.", "en": "Then 1111 × 1 = 1,111 is already enough, so 111 × b + 11 × c + d = 0 and b = c = d = 0."}, {"vi": "Số abcd là 1000; kiểm tra: 1000 + 100 + 10 + 1 = 1111.", "en": "So abcd = 1,000. Check: 1,000 + 100 + 10 + 1 = 1,111."}], "tip": {"vi": "Chữ số a có thể bằng 2 không? Thử xem tổng lúc đó là bao nhiêu.", "en": "Can a be 2? Try it and see how big the sum gets."}, "src": "250 bài, CĐ8, Bài 20"}, {"id": "cd8-b7", "lesson": "struct", "rank": 1, "q": {"vi": "Tìm một số tự nhiên có ba chữ số thì nếu viết thêm chữ số 1 vào đằng trước số đó ta được số mới bằng 9 lần số phải tìm.", "en": "Find a three-digit natural number such that writing the digit 1 in front of it gives a new number equal to 9 times the original."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 125, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Viết thêm 1 vào trước số có ba chữ số thì số mới hơn số cũ 1000 đơn vị.", "en": "Writing 1 in front adds 1,000."}, {"vi": "Hiệu là 9 − 1 = 8 lần số cũ, nên 8 lần số cũ = 1000.", "en": "The difference is 9 − 1 = 8 times the old number, so 8 times = 1,000."}, {"vi": "Số cần tìm: 1000 : 8 = 125.", "en": "The number is 1,000 ÷ 8 = 125."}], "tip": {"vi": "Vẽ sơ đồ số cũ 1 phần, số mới 9 phần.", "en": "Draw a diagram: old number 1 part, new number 9 parts."}, "src": "250 bài, CĐ8, Bài 7"}, {"id": "cd8-b8", "lesson": "struct", "rank": 1, "q": {"vi": "Tìm một số tự nhiên có ba chữ số biết nếu viết thêm chữ số 3 vào đằng trước số đó thì ta được số mới bằng 13 lần số phải tìm.", "en": "Find a three-digit natural number such that writing the digit 3 in front of it gives a new number equal to 13 times the original."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 250, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Viết thêm 3 vào trước số có ba chữ số thì số mới hơn số cũ 3000 đơn vị.", "en": "Writing 3 in front adds 3,000."}, {"vi": "Hiệu là 13 − 1 = 12 lần số cũ, nên 12 lần số cũ = 3000.", "en": "The difference is 13 − 1 = 12 times the old number, so 12 times = 3,000."}, {"vi": "Số cần tìm: 3000 : 12 = 250.", "en": "The number is 3,000 ÷ 12 = 250."}], "tip": {"vi": "Số mới = số cũ + 3000.", "en": "New number = old number + 3,000."}, "src": "250 bài, CĐ8, Bài 8"}, {"id": "cd4-b11a", "lesson": "struct", "rank": 2, "q": {"vi": "So sánh C và D, biết a và b là các chữ số khác 0:\nC = aa × b và D = bb × a", "en": "Compare C and D, where a and b are nonzero digits:\nC = aa × b and D = bb × a"}, "parts": [{"kind": "choice", "lab": {"vi": "C so với D", "en": "C compared to D"}, "opts": {"vi": ["C < D", "C = D", "C > D"], "en": ["C < D", "C = D", "C > D"]}, "ans": 1}], "steps": [{"vi": "aa là số có 2 chữ số a, nên bằng a × 11.", "en": "aa is the 2-digit number made of the digit a, so it equals a × 11."}, {"vi": "C = a × 11 × b và D = b × 11 × a.", "en": "C = a × 11 × b and D = b × 11 × a."}, {"vi": "Hai tích có cùng các thừa số (a, b và số đó) nên C = D.", "en": "Both products have the same factors, so C = D."}], "tip": {"vi": "Viết mỗi số dạng a × 11 (hay 111) rồi so sánh các thừa số.", "en": "Write each number as a × 11 (or 111) and compare the factors."}, "src": "250 bài, CĐ4, Bài 11a"}, {"id": "cd4-b11b", "lesson": "struct", "rank": 2, "q": {"vi": "So sánh C và D, biết a và b là các chữ số khác 0:\nC = aaa × b và D = bbb × a", "en": "Compare C and D, where a and b are nonzero digits:\nC = aaa × b and D = bbb × a"}, "parts": [{"kind": "choice", "lab": {"vi": "C so với D", "en": "C compared to D"}, "opts": {"vi": ["C < D", "C = D", "C > D"], "en": ["C < D", "C = D", "C > D"]}, "ans": 1}], "steps": [{"vi": "aaa là số có 3 chữ số a, nên bằng a × 111.", "en": "aaa is the 3-digit number made of the digit a, so it equals a × 111."}, {"vi": "C = a × 111 × b và D = b × 111 × a.", "en": "C = a × 111 × b and D = b × 111 × a."}, {"vi": "Hai tích có cùng các thừa số (a, b và số đó) nên C = D.", "en": "Both products have the same factors, so C = D."}], "tip": {"vi": "Viết mỗi số dạng a × 11 (hay 111) rồi so sánh các thừa số.", "en": "Write each number as a × 11 (or 111) and compare the factors."}, "src": "250 bài, CĐ4, Bài 11b"}, {"id": "cd4-b7", "lesson": "struct", "rank": 2, "q": {"vi": "Cho một số có 3 chữ số mà hàng trăm, hàng chục, hàng đơn vị của nó là 3 số tự nhiên liên tiếp tăng dần (ví dụ 345). Nếu viết số đó theo thứ tự ngược lại thì số đó tăng thêm bao nhiêu đơn vị?", "en": "Take a 3-digit number whose hundreds, tens and ones digits are 3 consecutive natural numbers in increasing order (for example 345). If we write the number in reverse order, by how much does the number increase?"}, "parts": [{"kind": "num", "lab": {"vi": "Tăng thêm", "en": "Increases by"}, "ans": 198, "unit": {"vi": "đơn vị", "en": ""}}], "steps": [{"vi": "Gọi số đó là abc với b = a + 1 và c = a + 2; số viết ngược lại là cba.", "en": "Let the number be abc with b = a + 1 and c = a + 2; the reversed number is cba."}, {"vi": "cba − abc = (c × 100 + a) − (a × 100 + c) = 99 × c − 99 × a = 99 × (c − a); chữ số hàng chục giống nhau nên bị triệt tiêu.", "en": "cba − abc = (c × 100 + a) − (a × 100 + c) = 99 × c − 99 × a = 99 × (c − a); the tens digit is the same so it cancels."}, {"vi": "Vì c − a = 2 nên số tăng thêm 99 × 2 = 198 đơn vị.", "en": "Since c − a = 2, the number increases by 99 × 2 = 198."}], "tip": {"vi": "Chỉ hàng trăm và hàng đơn vị đổi chỗ có tác dụng.", "en": "Only swapping the hundreds and ones digits matters."}, "src": "250 bài, CĐ4, Bài 7"}, {"id": "cd8-b1", "lesson": "struct", "rank": 2, "q": {"vi": "Tìm một số tự nhiên biết nếu xoá chữ số 3 ở hàng đơn vị của nó đi thì nó giảm đi 1794 đơn vị.", "en": "Find a natural number such that if you erase the digit 3 in its ones place, the number decreases by 1,794."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 1993, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Gọi số mới là A thì số cũ là A × 10 + 3, hơn số mới: A × 9 + 3.", "en": "Call the new number A. The old number is A × 10 + 3, which is A × 9 + 3 more than A."}, {"vi": "A × 9 + 3 = 1794 nên A × 9 = 1791.", "en": "So A × 9 + 3 = 1,794 and A × 9 = 1,791."}, {"vi": "A = 1791 : 9 = 199, vậy số cũ là 199 × 10 + 3 = 1993.", "en": "A = 1,791 ÷ 9 = 199, so the old number is 199 × 10 + 3 = 1,993."}], "tip": {"vi": "Số cũ gấp 10 lần số mới rồi thêm 3.", "en": "The old number is 10 times the new one plus 3."}, "src": "250 bài, CĐ8, Bài 1"}, {"id": "cd8-b10", "lesson": "struct", "rank": 2, "q": {"vi": "Tìm một số tự nhiên có ba chữ số biết nếu viết thêm chữ số 5 vào đằng trước, đằng sau số đó ta đều được hai số có bốn chữ số nhưng số viết đằng trước hơn số viết đằng sau 1107 đơn vị.", "en": "Find a three-digit natural number such that writing the digit 5 in front of it and behind it gives two four-digit numbers, and the number with 5 in front is 1,107 more than the number with 5 behind."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 432, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số viết 5 đằng trước là 5000 + n, số viết 5 đằng sau là n × 10 + 5.", "en": "With 5 in front: 5,000 + n. With 5 behind: n × 10 + 5."}, {"vi": "Hiệu: 5000 + n − (n × 10 + 5) = 4995 − n × 9 = 1107.", "en": "Difference: 5,000 + n − (n × 10 + 5) = 4,995 − n × 9 = 1,107."}, {"vi": "n × 9 = 4995 − 1107 = 3888, nên n = 3888 : 9 = 432.", "en": "n × 9 = 4,995 − 1,107 = 3,888, so n = 3,888 ÷ 9 = 432."}], "tip": {"vi": "Viết hai số mới theo n rồi lập hiệu.", "en": "Write both new numbers using n and take their difference."}, "src": "250 bài, CĐ8, Bài 10"}, {"id": "cd8-b11", "lesson": "struct", "rank": 2, "q": {"vi": "Tìm một số tự nhiên có hai chữ số biết nếu viết thêm chữ số 0 vào giữa hai chữ số của số đó ta được số mới bằng 7 lần số phải tìm.", "en": "Find a two-digit natural number such that writing the digit 0 between its two digits gives a new number equal to 7 times the original."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 15, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số cần tìm là ab, số mới là a0b: a × 100 + b = (a × 10 + b) × 7.", "en": "Let the number be ab. The new number is a0b: a × 100 + b = (a × 10 + b) × 7."}, {"vi": "Bớt b ở hai vế: a × 100 + b = a × 70 + b × 7 nên a × 30 = b × 6.", "en": "Expand: a × 100 + b = a × 70 + b × 7, so a × 30 = b × 6."}, {"vi": "Suy ra b = a × 5. Chữ số b ≤ 9 nên a = 1, b = 5.", "en": "So b = a × 5. Since b ≤ 9, a = 1 and b = 5."}, {"vi": "Số cần tìm là 15; kiểm tra: 105 = 15 × 7.", "en": "The number is 15; check: 105 = 15 × 7."}], "tip": {"vi": "So sánh a × 100 + b với a × 70 + b × 7.", "en": "Compare a × 100 + b with a × 70 + b × 7."}, "src": "250 bài, CĐ8, Bài 11"}, {"id": "cd8-b12", "lesson": "struct", "rank": 2, "q": {"vi": "Tìm một số tự nhiên khác 0 bằng 9 lần chữ số hàng đơn vị của nó.", "en": "Find a natural number other than 0 that equals 9 times its ones digit."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 45, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Gọi chữ số hàng đơn vị là b thì số đó không quá 9 × 9 = 81 nên chỉ có tối đa hai chữ số.", "en": "The number equals 9 × b, which is at most 9 × 9 = 81, so it has at most 2 digits."}, {"vi": "Số có hai chữ số ab: a × 10 + b = b × 9 nên a × 10 = b × 8, tức a × 5 = b × 4.", "en": "For two digits ab: a × 10 + b = b × 9, so a × 10 = b × 8, which means a × 5 = b × 4."}, {"vi": "a = 4, b = 5 (vì b ≤ 9). Số đó là 45 = 9 × 5.", "en": "So a = 4 and b = 5. The number is 45 = 9 × 5."}], "tip": {"vi": "Số hai chữ số ab bằng a × 10 + b.", "en": "A two-digit number ab equals a × 10 + b."}, "src": "250 bài, CĐ8, Bài 12"}, {"id": "cd8-b13", "lesson": "struct", "rank": 2, "q": {"vi": "Tìm một số tự nhiên có hai chữ số biết số đó chia cho tổng các chữ số của nó được thương là 9 và dư 1.", "en": "Find a two-digit natural number that, when divided by the sum of its digits, gives quotient 9 and remainder 1."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 91, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số đó = tổng các chữ số × 9 + 1, tức a × 10 + b = (a + b) × 9 + 1.", "en": "The number = digit sum × 9 + 1, so a × 10 + b = (a + b) × 9 + 1."}, {"vi": "Rút gọn: a = b × 8 + 1.", "en": "Simplify: a = b × 8 + 1."}, {"vi": "b = 0 thì a = 1: số 10 có thương 10 chia 1 = 10 (loại). b = 1 thì a = 9: số 91.", "en": "If b = 0, a = 1: the number 10 gives 10 ÷ 1 = 10, which fails. If b = 1, a = 9: the number 91."}, {"vi": "Kiểm tra: 91 : 10 = 9 dư 1.", "en": "Check: 91 ÷ 10 = 9 remainder 1."}], "tip": {"vi": "Viết số dưới dạng a × 10 + b.", "en": "Write the number as a × 10 + b."}, "src": "250 bài, CĐ8, Bài 13"}, {"id": "cd8-b16", "lesson": "struct", "rank": 2, "q": {"vi": "Cho một số có hai chữ số. Nếu viết thêm hai chữ số nữa vào bên phải số đó thì được số mới lớn hơn số đã cho 1986 đơn vị. Tìm số đã cho và số mới.", "en": "Take a two-digit number. If you write two more digits to the right of it, the new number is 1,986 more than the original number. Find the original number and the new number."}, "parts": [{"kind": "num", "lab": {"vi": "Số đã cho", "en": "Original number"}, "ans": 20, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số mới", "en": "New number"}, "ans": 2006, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Viết thêm hai chữ số vào bên phải thì số đó gấp lên 100 lần, rồi cộng thêm số vừa viết (nhỏ hơn 100).", "en": "Writing two digits on the right multiplies the number by 100 and then adds the new two-digit part (less than 100)."}, {"vi": "Số mới hơn số cũ: 100 lần − 1 lần = 99 lần số cũ, cộng với số viết thêm; tổng là 1986.", "en": "The new number minus the old one equals 99 times the old number plus the added part, which is 1,986."}, {"vi": "Ta có 1986 : 99 = 20 dư 6, mà số viết thêm nhỏ hơn 99 nên số cũ là 20 và hai chữ số viết thêm là 06.", "en": "1,986 ÷ 99 = 20 remainder 6. The added part is less than 100, so the old number is 20 and the added digits are 06."}, {"vi": "Số mới là 2006; kiểm tra: 2006 − 20 = 1986.", "en": "The new number is 2,006. Check: 2,006 − 20 = 1,986."}], "tip": {"vi": "Viết thêm hai chữ số vào bên phải là nhân số cũ với 100 rồi cộng thêm.", "en": "Adding two digits on the right means multiplying by 100 and then adding."}, "src": "250 bài, CĐ8, Bài 16"}, {"id": "cd8-b17", "lesson": "struct", "rank": 2, "q": {"vi": "Tìm số có ba chữ số, biết nếu gạch chữ số hàng trăm ta được số có hai chữ số mà nhân số này với 7 được số ban đầu.", "en": "Find a three-digit number such that when you cross out its hundreds digit you get a two-digit number, and 7 times that two-digit number equals the original number."}, "parts": [{"kind": "num", "lab": {"vi": "Số có ba chữ số", "en": "Three-digit number"}, "ans": 350, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Gọi số hai chữ số còn lại là bc, chữ số hàng trăm là a; số ban đầu = a00 + bc.", "en": "Let bc be the two-digit number that remains and a the hundreds digit; the original number is a00 + bc."}, {"vi": "Số ban đầu bằng 7 lần bc nên a00 bằng 6 lần bc, tức là a00 chia hết cho 6.", "en": "The original number is 7 times bc, so a00 is 6 times bc; so a00 is divisible by 6."}, {"vi": "a00 chia hết cho 6 thì a chia hết cho 3: a = 3 cho 300 : 6 = 50; a = 6 cho 600 : 6 = 100 (có ba chữ số, loại); a = 9 cho 150 (loại).", "en": "a00 divisible by 6 means a is a multiple of 3: a = 3 gives 300 ÷ 6 = 50; a = 6 gives 100 and a = 9 gives 150, which are not two-digit numbers, so they are rejected."}, {"vi": "Vậy bc = 50 và số cần tìm là 350; kiểm tra 7 × 50 = 350.", "en": "So bc = 50 and the number is 350. Check: 7 × 50 = 350."}], "tip": {"vi": "Số ban đầu = a00 + bc, và bằng 7 × bc.", "en": "The original number = a00 + bc, and it equals 7 × bc."}, "src": "250 bài, CĐ8, Bài 17"}, {"id": "cd8-b19", "lesson": "struct", "rank": 2, "q": {"vi": "Thay chữ bằng số thích hợp: abcd + abc + ab + a = 11106 (abcd, abc, ab là các số có các chữ số a, b, c, d).", "en": "Replace the letters with suitable digits: abcd + abc + ab + a = 11,106 (abcd, abc and ab are numbers made of the digits a, b, c, d)."}, "parts": [{"kind": "num", "lab": {"vi": "Chữ số a", "en": "Digit a"}, "ans": 9, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Chữ số b", "en": "Digit b"}, "ans": 9, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Chữ số c", "en": "Digit c"}, "ans": 9, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Chữ số d", "en": "Digit d"}, "ans": 9, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Phân tích theo hàng: tổng bằng 1111 × a + 111 × b + 11 × c + d.", "en": "By place value the sum equals 1111 × a + 111 × b + 11 × c + d."}, {"vi": "Phần 111 × b + 11 × c + d nhiều nhất là 999 + 99 + 9 = 1107, nên 1111 × a ít nhất là 11106 − 1107 = 9999, do đó a = 9.", "en": "The part 111 × b + 11 × c + d is at most 999 + 99 + 9 = 1,107, so 1111 × a is at least 11,106 − 1,107 = 9,999. Hence a = 9."}, {"vi": "Còn lại 11106 − 9999 = 1107 = 111 × b + 11 × c + d; chỉ có b = 9, c = 9, d = 9 mới đủ 1107.", "en": "What is left is 11,106 − 9,999 = 1,107 = 111 × b + 11 × c + d; only b = 9, c = 9, d = 9 gives 1,107."}, {"vi": "Kiểm tra: 9999 + 999 + 99 + 9 = 11106.", "en": "Check: 9,999 + 999 + 99 + 9 = 11,106."}], "tip": {"vi": "Viết tổng theo hàng: mỗi chữ a, b, c, d xuất hiện ở mấy hàng?", "en": "Write the sum by place value: how many times does each letter appear and in which places?"}, "src": "250 bài, CĐ8, Bài 19"}, {"id": "cd8-b21", "lesson": "struct", "rank": 2, "q": {"vi": "Tìm các chữ số a, b, c khác nhau biết: aa × bc = 1001 (aa là số có hai chữ số a, bc là số có hai chữ số b, c).", "en": "Find the different digits a, b, c such that aa × bc = 1,001 (aa is the two-digit number made of a and a; bc is the two-digit number made of b and c)."}, "parts": [{"kind": "num", "lab": {"vi": "Chữ số a", "en": "Digit a"}, "ans": 7, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Chữ số b", "en": "Digit b"}, "ans": 1, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Chữ số c", "en": "Digit c"}, "ans": 3, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "aa = 11 × a, nên 11 × a × bc = 1001; chia hai vế cho 11 được a × bc = 91.", "en": "aa = 11 × a, so 11 × a × bc = 1,001. Dividing by 11 gives a × bc = 91."}, {"vi": "Mà 91 = 7 × 13 = 1 × 91; a là chữ số nên a = 7 (bc = 13) hoặc a = 1 (bc = 91).", "en": "Since 91 = 7 × 13 = 1 × 91 and a is a digit, either a = 7 (bc = 13) or a = 1 (bc = 91)."}, {"vi": "Với a = 1, bc = 91 thì c = 1 trùng với a, loại.", "en": "If a = 1 and bc = 91, then c = 1 is the same as a, so it is rejected."}, {"vi": "Vậy a = 7, b = 1, c = 3; kiểm tra: 77 × 13 = 1001.", "en": "So a = 7, b = 1, c = 3. Check: 77 × 13 = 1,001."}], "tip": {"vi": "aa = a × 11 và 1001 = 7 × 11 × 13.", "en": "aa = a × 11 and 1,001 = 7 × 11 × 13."}, "src": "250 bài, CĐ8, Bài 21"}, {"id": "cd8-b22", "lesson": "struct", "rank": 2, "q": {"vi": "Tìm các chữ số a, b khác 0 thỏa mãn: a × b × ab = bbb (ab là số có hai chữ số a, b; bbb là số có ba chữ số b).", "en": "Find the nonzero digits a and b such that a × b × ab = bbb (ab is the two-digit number made of a and b; bbb is the three-digit number made of three b's)."}, "parts": [{"kind": "num", "lab": {"vi": "Chữ số a", "en": "Digit a"}, "ans": 3, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Chữ số b", "en": "Digit b"}, "ans": 7, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "bbb = b × 111, nên a × b × ab = b × 111.", "en": "bbb = b × 111, so a × b × ab = b × 111."}, {"vi": "Chia hai vế cho b (b khác 0): a × ab = 111 = 3 × 37.", "en": "Divide both sides by b (b is not 0): a × ab = 111 = 3 × 37."}, {"vi": "a phải là ước của 111 nên a = 1 hoặc a = 3; a = 1 thì ab = 111 (quá ba chữ số), loại; a = 3 thì ab = 37.", "en": "a must divide 111, so a = 1 or a = 3; a = 1 gives ab = 111, which is not two-digit, so a = 3 and ab = 37."}, {"vi": "Vậy a = 3, b = 7; kiểm tra: 3 × 7 × 37 = 777.", "en": "So a = 3, b = 7. Check: 3 × 7 × 37 = 777."}], "tip": {"vi": "Chia cả hai vế cho b.", "en": "Divide both sides by b."}, "src": "250 bài, CĐ8, Bài 22"}, {"id": "cd8-b3", "lesson": "struct", "rank": 2, "q": {"vi": "Tìm một số có ba chữ số biết nếu viết thêm chữ số 4 vào đằng trước, đằng sau số đó ta đều được hai số có bốn chữ số, biết số viết đằng trước hơn số viết đằng sau 2889 đơn vị.", "en": "Find a three-digit number such that writing the digit 4 in front of it and behind it gives two four-digit numbers, and the number with 4 in front is 2,889 more than the number with 4 behind."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 123, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số viết 4 đằng trước là 4000 + n, số viết 4 đằng sau là n × 10 + 4.", "en": "With 4 in front: 4,000 + n. With 4 behind: n × 10 + 4."}, {"vi": "Hiệu: 4000 + n − (n × 10 + 4) = 3996 − n × 9 = 2889.", "en": "Difference: 4,000 + n − (n × 10 + 4) = 3,996 − n × 9 = 2,889."}, {"vi": "n × 9 = 3996 − 2889 = 1107, nên n = 1107 : 9 = 123.", "en": "n × 9 = 3,996 − 2,889 = 1,107, so n = 1,107 ÷ 9 = 123."}], "tip": {"vi": "Viết hai số mới theo n rồi lập hiệu.", "en": "Write both new numbers using n and take their difference."}, "src": "250 bài, CĐ8, Bài 3"}, {"id": "cd8-b4", "lesson": "struct", "rank": 2, "q": {"vi": "Tìm một số tự nhiên có hai chữ số biết nếu lấy số đó chia cho tổng các chữ số của nó thì được thương là 8 và dư 3.", "en": "Find a two-digit natural number such that when it is divided by the sum of its digits, the quotient is 8 and the remainder is 3."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 51, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số đó bằng 8 lần tổng các chữ số cộng 3, và dư 3 nên tổng chữ số lớn hơn 3.", "en": "The number is 8 times the digit sum plus 3, and the digit sum is greater than 3."}, {"vi": "Viết ab = a × 10 + b = (a + b) × 8 + 3, suy ra a × 2 = b × 7 + 3.", "en": "Writing ab = a × 10 + b = (a + b) × 8 + 3 gives a × 2 = b × 7 + 3."}, {"vi": "b = 1 thì a × 2 = 10, a = 5. Các giá trị b khác không cho a là chữ số.", "en": "If b = 1 then a × 2 = 10 and a = 5. Other values of b do not give a digit."}, {"vi": "Số đó là 51: 51 : 6 = 8 dư 3.", "en": "The number is 51: 51 ÷ 6 = 8 remainder 3."}], "tip": {"vi": "Viết số dưới dạng a × 10 + b.", "en": "Write the number as a × 10 + b."}, "src": "250 bài, CĐ8, Bài 4"}, {"id": "cd8-b5", "lesson": "struct", "rank": 2, "q": {"vi": "Tìm một số tự nhiên biết nếu xoá chữ số 8 ở hàng đơn vị của nó đi thì nó giảm đi 1808 đơn vị.", "en": "Find a natural number such that if you erase the digit 8 in its ones place, the number decreases by 1,808."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 2008, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Gọi số mới là A thì số cũ là A × 10 + 8, hơn số mới A × 9 + 8.", "en": "Call the new number A. The old number is A × 10 + 8, which is A × 9 + 8 more."}, {"vi": "A × 9 = 1808 − 8 = 1800, nên A = 200.", "en": "A × 9 = 1,808 − 8 = 1,800, so A = 200."}, {"vi": "Số cần tìm: 200 × 10 + 8 = 2008.", "en": "The number is 200 × 10 + 8 = 2,008."}], "tip": {"vi": "Số cũ gấp 10 lần số mới rồi thêm 8.", "en": "The old number is 10 times the new one plus 8."}, "src": "250 bài, CĐ8, Bài 5"}, {"id": "cd8-b6", "lesson": "struct", "rank": 2, "q": {"vi": "Tìm một số tự nhiên biết nếu viết thêm chữ số 7 vào tận cùng bên phải thì được số mới hơn số phải tìm 1807 đơn vị.", "en": "Find a natural number such that writing the digit 7 at the far right gives a new number that is 1,807 more than the original."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 200, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số mới là n × 10 + 7, hơn số cũ n × 9 + 7.", "en": "The new number is n × 10 + 7, which is n × 9 + 7 more."}, {"vi": "n × 9 = 1807 − 7 = 1800.", "en": "n × 9 = 1,807 − 7 = 1,800."}, {"vi": "n = 1800 : 9 = 200.", "en": "n = 1,800 ÷ 9 = 200."}], "tip": {"vi": "Viết thêm một chữ số ở cuối là nhân 10 rồi cộng chữ số đó.", "en": "Adding a digit at the end means times 10 plus that digit."}, "src": "250 bài, CĐ8, Bài 6"}, {"id": "cd8-b9", "lesson": "struct", "rank": 2, "q": {"vi": "Tìm một số tự nhiên có ba chữ số biết nếu viết thêm chữ số 1 vào đằng trước, đằng sau số đó ta đều được hai số có bốn chữ số nhưng số viết đằng sau hơn số viết đằng trước 1107 đơn vị.", "en": "Find a three-digit natural number such that writing the digit 1 in front of it and behind it gives two four-digit numbers, and the number with 1 behind is 1,107 more than the number with 1 in front."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 234, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số viết 1 đằng trước là 1000 + n, số viết 1 đằng sau là n × 10 + 1.", "en": "With 1 in front: 1,000 + n. With 1 behind: n × 10 + 1."}, {"vi": "Hiệu: n × 10 + 1 − (1000 + n) = n × 9 − 999 = 1107.", "en": "Difference: n × 10 + 1 − (1,000 + n) = n × 9 − 999 = 1,107."}, {"vi": "n × 9 = 1107 + 999 = 2106, nên n = 2106 : 9 = 234.", "en": "n × 9 = 1,107 + 999 = 2,106, so n = 2,106 ÷ 9 = 234."}], "tip": {"vi": "Viết hai số mới theo n rồi lập hiệu.", "en": "Write both new numbers using n and take their difference."}, "src": "250 bài, CĐ8, Bài 9"}, {"id": "cd4-b12", "lesson": "struct", "rank": 3, "q": {"vi": "Cho một số có 4 chữ số, biết hàng nghìn, hàng trăm, hàng chục, hàng đơn vị của nó là 4 số tự nhiên liên tiếp tăng dần (ví dụ 3 456). Nếu viết số đó theo thứ tự ngược lại thì số đó tăng thêm bao nhiêu đơn vị?", "en": "Take a 4-digit number whose thousands, hundreds, tens and ones digits are 4 consecutive natural numbers in increasing order (for example 3,456). If we write the number in reverse order, by how much does the number increase?"}, "parts": [{"kind": "num", "lab": {"vi": "Tăng thêm", "en": "Increases by"}, "ans": 3087, "unit": {"vi": "đơn vị", "en": ""}}], "steps": [{"vi": "Gọi số là abcd với b = a + 1, c = a + 2, d = a + 3; số viết ngược lại là dcba.", "en": "Let the number be abcd with b = a + 1, c = a + 2, d = a + 3; the reversed number is dcba."}, {"vi": "Hàng nghìn và hàng đơn vị đổi chỗ: tăng 999 × (d − a) = 999 × 3 = 2 997.", "en": "The thousands and ones digits swap: the change is 999 × (d − a) = 999 × 3 = 2,997."}, {"vi": "Hàng trăm và hàng chục đổi chỗ: tăng 90 × (c − b) = 90 × 1 = 90.", "en": "The hundreds and tens digits swap: the change is 90 × (c − b) = 90 × 1 = 90."}, {"vi": "Số tăng thêm 2 997 + 90 = 3 087 đơn vị.", "en": "The number increases by 2,997 + 90 = 3,087."}], "tip": {"vi": "Xét từng cặp chữ số đổi chỗ cho nhau.", "en": "Look at each pair of digits that swap places."}, "src": "250 bài, CĐ4, Bài 12"}, {"id": "cd8-b14", "lesson": "struct", "rank": 3, "q": {"vi": "Tìm một số tự nhiên có hai chữ số biết số đó chia cho tổng các chữ số của nó được 7 dư 9.", "en": "Find a two-digit natural number that, when divided by the sum of its digits, gives 7 with remainder 9."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 93, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Dư 9 nên tổng các chữ số lớn hơn 9, tức ít nhất là 10.", "en": "The remainder is 9, so the digit sum is more than 9, at least 10."}, {"vi": "a × 10 + b = (a + b) × 7 + 9 nên a × 3 = b × 6 + 9, tức a = b × 2 + 3.", "en": "a × 10 + b = (a + b) × 7 + 9 gives a × 3 = b × 6 + 9, so a = b × 2 + 3."}, {"vi": "b = 0: a = 3 (tổng 3, loại); b = 1: a = 5 (tổng 6, loại); b = 2: a = 7 (tổng 9, loại); b = 3: a = 9 (tổng 12, hợp lí).", "en": "b = 0: a = 3 (sum 3, no); b = 1: a = 5 (sum 6, no); b = 2: a = 7 (sum 9, no); b = 3: a = 9 (sum 12, yes)."}, {"vi": "Số cần tìm là 93: 93 : 12 = 7 dư 9.", "en": "The number is 93: 93 ÷ 12 = 7 remainder 9."}], "tip": {"vi": "Số dư phải bé hơn số chia.", "en": "The remainder must be less than the divisor."}, "src": "250 bài, CĐ8, Bài 14"}, {"id": "cd8-b15", "lesson": "struct", "rank": 3, "q": {"vi": "Tìm một số tự nhiên có ba chữ số biết số đó chia cho tổng các chữ số của nó thì bằng 11.", "en": "Find a three-digit natural number that equals 11 times the sum of its digits (that is, dividing it by its digit sum gives 11)."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 198, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "abc = 11 × (a + b + c) nên a × 100 + b × 10 + c = a × 11 + b × 11 + c × 11.", "en": "abc = 11 × (a + b + c), so a × 100 + b × 10 + c = a × 11 + b × 11 + c × 11."}, {"vi": "Rút gọn: a × 89 = b + c × 10.", "en": "Simplify: a × 89 = b + c × 10."}, {"vi": "b + c × 10 ≤ 99 nên a = 1, b + c × 10 = 89, vậy c = 8, b = 9.", "en": "Since b + c × 10 ≤ 99, a = 1, and b + c × 10 = 89 gives c = 8 and b = 9."}, {"vi": "Số đó là 198: 198 : 18 = 11.", "en": "The number is 198: 198 ÷ 18 = 11."}], "tip": {"vi": "Viết số dưới dạng a × 100 + b × 10 + c.", "en": "Write the number as a × 100 + b × 10 + c."}, "src": "250 bài, CĐ8, Bài 15"}, {"id": "cd8-b18", "lesson": "struct", "rank": 3, "q": {"vi": "Tìm số tự nhiên có ba chữ số, biết rằng số đó gấp 5 lần tích các chữ số của nó.", "en": "Find the three-digit natural number that is 5 times the product of its digits."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 175, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số đó gấp 5 lần một tích nên chia hết cho 5, tận cùng là 0 hoặc 5; tận cùng 0 thì tích bằng 0 (vô lí), nên c = 5.", "en": "The number is 5 times something so it ends in 0 or 5; ending in 0 makes the product 0 (impossible), so c = 5."}, {"vi": "Khi đó số = 5 × a × b × 5 = 25 × a × b, nên số chia hết cho 25; hai chữ số cuối b5 phải là 25 hoặc 75.", "en": "Then the number = 5 × a × b × 5 = 25 × a × b, so it is divisible by 25 and its last two digits b5 are 25 or 75."}, {"vi": "Nếu b = 2: 100 × a + 25 = 50 × a (vô lí vì vế trái lớn hơn).", "en": "If b = 2: 100 × a + 25 = 50 × a, impossible because the left side is bigger."}, {"vi": "Nếu b = 7: 100 × a + 75 = 175 × a, suy ra 75 = 75 × a, a = 1. Số cần tìm là 175.", "en": "If b = 7: 100 × a + 75 = 175 × a, so 75 = 75 × a and a = 1. The number is 175."}], "tip": {"vi": "Số chia hết cho 5 thì chữ số tận cùng là gì?", "en": "If a number is divisible by 5, what can its last digit be?"}, "src": "250 bài, CĐ8, Bài 18"}, {"id": "cd8-b23", "lesson": "struct", "rank": 3, "q": {"vi": "Tìm các số tự nhiên ab, cd sao cho: ab × cd = bbb (ab, cd là số có hai chữ số; bbb là số có ba chữ số b). Hỏi có bao nhiêu cặp (ab, cd) như vậy và giá trị lớn nhất của bbb là bao nhiêu?", "en": "Find the natural numbers ab and cd such that ab × cd = bbb (ab and cd are two-digit numbers; bbb is the three-digit number made of three b's). How many pairs (ab, cd) are there, and what is the largest value of bbb?"}, "parts": [{"kind": "num", "lab": {"vi": "Số cặp (ab, cd)", "en": "Number of pairs"}, "ans": 2, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Giá trị lớn nhất của bbb", "en": "Largest bbb"}, "ans": 777, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "bbb = b × 111 = b × 3 × 37, mà 37 là số nguyên tố và b nhỏ hơn 10, nên một trong hai số ab, cd chia hết cho 37, tức là 37 hoặc 74.", "en": "bbb = b × 111 = b × 3 × 37. Since 37 is prime and b is less than 10, one of ab, cd is divisible by 37, so it is 37 or 74."}, {"vi": "Nếu ab = 37 thì b = 7, cd = 3 × 7 = 21: 37 × 21 = 777 (được).", "en": "If ab = 37, then b = 7 and cd = 3 × 7 = 21: 37 × 21 = 777 (works)."}, {"vi": "Nếu cd = 37 thì ab = 3 × b có tận cùng b, nên b = 5, ab = 15: 15 × 37 = 555 (được).", "en": "If cd = 37, then ab = 3 × b must end in b, so b = 5 and ab = 15: 15 × 37 = 555 (works)."}, {"vi": "Với 74 (ab = 74 hoặc cd = 74) thì số còn lại không phù hợp. Vậy có 2 cặp, bbb lớn nhất là 777.", "en": "With 74 (as ab or cd) the other number does not fit. So there are 2 pairs and the largest bbb is 777."}], "tip": {"vi": "Phân tích 111 thành tích các thừa số nguyên tố.", "en": "Break 111 into prime factors."}, "src": "250 bài, CĐ8, Bài 23"}], "seq": [{"id": "cd5-b17a", "lesson": "seq", "rank": 1, "q": {"vi": "Cho dãy số: 12; 16; 20; 24; 28; … Tìm số hạng thứ 90 của dãy.", "en": "Given the sequence: 12, 16, 20, 24, 28, … Find the 90th term."}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng thứ 90", "en": "90th term"}, "ans": 368, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu hai số liên tiếp là 4.", "en": "The difference is 4."}, {"vi": "Từ số hạng thứ nhất đến thứ 90 có 89 khoảng cách.", "en": "From term 1 to term 90 there are 89 gaps."}, {"vi": "Số hạng thứ 90: 12 + 89 × 4 = 368.", "en": "The 90th term: 12 + 89 × 4 = 368."}], "tip": {"vi": "Số đầu cộng 89 lần hiệu.", "en": "First term plus 89 times the difference."}, "src": "250 bài, CĐ5, Bài 17a"}, {"id": "cd5-b1c", "lesson": "seq", "rank": 1, "q": {"vi": "Tìm quy luật và viết thêm 3 số hạng vào dãy số sau:\n0; 3; 7; 12; …", "en": "Find the rule and write the next 3 terms of this sequence:\n0, 3, 7, 12, …"}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 1", "en": "Next term 1"}, "ans": 18, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 2", "en": "Next term 2"}, "ans": 25, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 3", "en": "Next term 3"}, "ans": 33, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu hai số liên tiếp: 3 − 0 = 3; 7 − 3 = 4; 12 − 7 = 5. Các hiệu tăng dần 1 đơn vị.", "en": "Differences between neighbors: 3 − 0 = 3; 7 − 3 = 4; 12 − 7 = 5. The differences grow by 1."}, {"vi": "Hiệu tiếp theo là 6: 12 + 6 = 18.", "en": "The next difference is 6: 12 + 6 = 18."}, {"vi": "Hiệu 7: 18 + 7 = 25; hiệu 8: 25 + 8 = 33.", "en": "Difference 7: 18 + 7 = 25; difference 8: 25 + 8 = 33."}], "tip": {"vi": "Tính hiệu hai số liền nhau.", "en": "Find the differences between neighboring terms."}, "src": "250 bài, CĐ5, Bài 1c"}, {"id": "cd5-b1e", "lesson": "seq", "rank": 1, "q": {"vi": "Tìm quy luật và viết thêm 3 số hạng vào dãy số sau:\n100; 93; 85; 76; …", "en": "Find the rule and write the next 3 terms of this sequence:\n100, 93, 85, 76, …"}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 1", "en": "Next term 1"}, "ans": 66, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 2", "en": "Next term 2"}, "ans": 55, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 3", "en": "Next term 3"}, "ans": 43, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu hai số liên tiếp: 100 − 93 = 7; 93 − 85 = 8; 85 − 76 = 9. Số bị bớt đi tăng dần 1.", "en": "Differences: 100 − 93 = 7; 93 − 85 = 8; 85 − 76 = 9. The amount subtracted grows by 1."}, {"vi": "Số bớt tiếp theo là 10: 76 − 10 = 66.", "en": "The next amount subtracted is 10: 76 − 10 = 66."}, {"vi": "Bớt 11: 66 − 11 = 55; bớt 12: 55 − 12 = 43.", "en": "Subtract 11: 66 − 11 = 55; subtract 12: 55 − 12 = 43."}], "tip": {"vi": "Dãy giảm dần, hãy tìm số bị bớt đi mỗi lần.", "en": "The sequence goes down. Find how much is taken away each time."}, "src": "250 bài, CĐ5, Bài 1e"}, {"id": "cd5-b23a", "lesson": "seq", "rank": 1, "q": {"vi": "Một người viết liền nhau nhóm chữ cái VUIHOCTOAN VUIHOCTOAN… Chữ cái thứ 2112 là chữ cái nào?", "en": "A person writes the group of letters VUIHOCTOAN VUIHOCTOAN… over and over. Which letter is the 2,112th letter?"}, "parts": [{"kind": "choice", "lab": {"vi": "Chữ cái thứ 2112", "en": "The 2,112th letter"}, "opts": {"vi": ["V", "U", "I", "H", "O", "C", "T", "A", "N"], "en": ["V", "U", "I", "H", "O", "C", "T", "A", "N"]}, "ans": 1}], "steps": [{"vi": "Nhóm VUIHOCTOAN có 10 chữ cái.", "en": "The group VUIHOCTOAN has 10 letters."}, {"vi": "2112 : 10 = 211 dư 2.", "en": "2,112 ÷ 10 = 211 remainder 2."}, {"vi": "Dư 2 nghĩa là chữ cái thứ 2 của nhóm, đó là chữ U.", "en": "Remainder 2 means the 2nd letter of the group, which is U."}], "tip": {"vi": "Chia vị trí cho số chữ cái trong một nhóm rồi xét số dư.", "en": "Divide the position by the number of letters in a group and look at the remainder."}, "src": "250 bài, CĐ5, Bài 23a"}, {"id": "cd5-b24a", "lesson": "seq", "rank": 1, "q": {"vi": "Một người viết liền chữ QUYET TAM HOC GIOI QUYET TAM HOC GIOI… Hỏi chữ cái thứ 2000 là chữ cái nào?", "en": "A person writes the letters QUYET TAM HOC GIOI QUYET TAM HOC GIOI… over and over. Which letter is the 2,000th letter?"}, "parts": [{"kind": "choice", "lab": {"vi": "Chữ cái thứ 2000", "en": "The 2,000th letter"}, "opts": {"vi": ["Q", "U", "Y", "E", "T", "A", "M", "H", "O", "C", "G", "I"], "en": ["Q", "U", "Y", "E", "T", "A", "M", "H", "O", "C", "G", "I"]}, "ans": 4}], "steps": [{"vi": "Một nhóm QUYETTAMHOCGIOI có 5 + 3 + 3 + 4 = 15 chữ cái.", "en": "One group QUYETTAMHOCGIOI has 5 + 3 + 3 + 4 = 15 letters."}, {"vi": "2000 : 15 = 133 dư 5.", "en": "2,000 ÷ 15 = 133 remainder 5."}, {"vi": "Dư 5 nghĩa là chữ cái thứ 5 của nhóm: Q-U-Y-E-T, đó là chữ T.", "en": "Remainder 5 means the 5th letter of the group: Q-U-Y-E-T, which is T."}], "tip": {"vi": "Đếm số chữ cái trong một nhóm trước.", "en": "First count the letters in one group."}, "src": "250 bài, CĐ5, Bài 24a"}, {"id": "cd5-b2a", "lesson": "seq", "rank": 1, "q": {"vi": "Tìm số hạng đầu tiên của dãy số sau, biết rằng dãy số có 10 số hạng:\n…; 32; 36; 40", "en": "Find the first term of the sequence below, given that it has 10 terms:\n…, 32, 36, 40"}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng đầu tiên", "en": "First term"}, "ans": 4, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu hai số liên tiếp là 4 (36 − 32 = 4), dãy có 10 số hạng nên có 9 khoảng cách.", "en": "The difference between neighbors is 4 (36 − 32 = 4). With 10 terms there are 9 gaps."}, {"vi": "Từ số đầu đến số cuối tăng 9 × 4 = 36.", "en": "From the first term to the last, the increase is 9 × 4 = 36."}, {"vi": "Số hạng đầu tiên: 40 − 36 = 4.", "en": "First term: 40 − 36 = 4."}], "tip": {"vi": "10 số hạng thì có bao nhiêu khoảng cách?", "en": "How many gaps are there between 10 terms?"}, "src": "250 bài, CĐ5, Bài 2a"}, {"id": "cd5-b2b", "lesson": "seq", "rank": 1, "q": {"vi": "Tìm số hạng đầu tiên của dãy số sau, biết rằng dãy số có 10 số hạng:\n…; 44; 49; 54", "en": "Find the first term of the sequence below, given that it has 10 terms:\n…, 44, 49, 54"}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng đầu tiên", "en": "First term"}, "ans": 9, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu hai số liên tiếp là 5, dãy có 10 số hạng nên có 9 khoảng cách.", "en": "The difference is 5, and 10 terms have 9 gaps."}, {"vi": "Từ số đầu đến số cuối tăng 9 × 5 = 45.", "en": "From the first term to the last, the increase is 9 × 5 = 45."}, {"vi": "Số hạng đầu tiên: 54 − 45 = 9.", "en": "First term: 54 − 45 = 9."}], "tip": {"vi": "10 số hạng thì có bao nhiêu khoảng cách?", "en": "How many gaps are there between 10 terms?"}, "src": "250 bài, CĐ5, Bài 2b"}, {"id": "cd5-b4b", "lesson": "seq", "rank": 1, "q": {"vi": "Một dãy số có 100 số hạng: …; 589; 595; 601 (số 601 là số hạng cuối cùng). Tìm số hạng thứ 60 của dãy.", "en": "A sequence has 100 terms: …, 589, 595, 601 (601 is the last term). Find the 60th term of the sequence."}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng thứ 60", "en": "60th term"}, "ans": 361, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu hai số liên tiếp là 6 (595 − 589 = 6).", "en": "The difference between neighbors is 6 (595 − 589 = 6)."}, {"vi": "Từ số hạng thứ 60 đến số hạng thứ 100 có 100 − 60 = 40 khoảng cách.", "en": "From the 60th term to the 100th term there are 100 − 60 = 40 gaps."}, {"vi": "Số hạng thứ 60: 601 − 40 × 6 = 361.", "en": "The 60th term: 601 − 40 × 6 = 361."}], "tip": {"vi": "Đếm lùi từ số hạng cuối.", "en": "Count backward from the last term."}, "src": "250 bài, CĐ5, Bài 4b"}, {"id": "cd5-b5a", "lesson": "seq", "rank": 1, "q": {"vi": "Cho dãy số: 1; 6; 11; 16; 21; 26; … Tìm số hạng thứ 32 của dãy.", "en": "Given the sequence: 1, 6, 11, 16, 21, 26, … Find the 32nd term."}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng thứ 32", "en": "32nd term"}, "ans": 156, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu hai số liên tiếp là 5.", "en": "The difference between neighbors is 5."}, {"vi": "Từ số hạng thứ nhất đến thứ 32 có 31 khoảng cách.", "en": "From term 1 to term 32 there are 31 gaps."}, {"vi": "Số hạng thứ 32: 1 + 31 × 5 = 156.", "en": "The 32nd term: 1 + 31 × 5 = 156."}], "tip": {"vi": "Số hạng thứ n bằng số đầu cộng (n − 1) lần hiệu.", "en": "The nth term is the first term plus (n − 1) times the difference."}, "src": "250 bài, CĐ5, Bài 5a"}, {"id": "cd5-b7a", "lesson": "seq", "rank": 1, "q": {"vi": "Cho dãy số: 4; 9; 14; 19; 24; … Viết thêm 3 số hạng tiếp theo của dãy.", "en": "Given the sequence: 4, 9, 14, 19, 24, … Write the next 3 terms."}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 1", "en": "Next term 1"}, "ans": 29, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 2", "en": "Next term 2"}, "ans": 34, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 3", "en": "Next term 3"}, "ans": 39, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu hai số liên tiếp là 5 (9 − 4 = 5).", "en": "The difference is 5 (9 − 4 = 5)."}, {"vi": "Ba số hạng tiếp theo: 24 + 5 = 29; 29 + 5 = 34; 34 + 5 = 39.", "en": "The next three terms: 24 + 5 = 29; 29 + 5 = 34; 34 + 5 = 39."}], "tip": {"vi": "Mỗi số lớn hơn số đứng trước cùng một số đơn vị.", "en": "Each term is the same amount more than the one before."}, "src": "250 bài, CĐ5, Bài 7a"}, {"id": "cd5-b7b", "lesson": "seq", "rank": 1, "q": {"vi": "Cho dãy số: 4; 9; 14; 19; 24; … Tìm số hạng thứ 150 của dãy.", "en": "Given the sequence: 4, 9, 14, 19, 24, … Find the 150th term."}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng thứ 150", "en": "150th term"}, "ans": 749, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu hai số liên tiếp là 5.", "en": "The difference is 5."}, {"vi": "Từ số hạng thứ nhất đến thứ 150 có 149 khoảng cách.", "en": "From term 1 to term 150 there are 149 gaps."}, {"vi": "Số hạng thứ 150: 4 + 149 × 5 = 749.", "en": "The 150th term: 4 + 149 × 5 = 749."}], "tip": {"vi": "Số đầu cộng (150 − 1) lần hiệu.", "en": "First term plus (150 − 1) times the difference."}, "src": "250 bài, CĐ5, Bài 7b"}, {"id": "cd5-b7c", "lesson": "seq", "rank": 1, "q": {"vi": "Cho dãy số: 4; 9; 14; 19; 24; … Số 2003 có thuộc dãy số trên không?", "en": "Given the sequence: 4, 9, 14, 19, 24, … Is 2,003 in this sequence?"}, "parts": [{"kind": "choice", "lab": {"vi": "Số 2003", "en": "2,003"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 1}], "steps": [{"vi": "Mỗi số hạng của dãy chia cho 5 đều dư 4 (4; 9; 14; 19; 24 …).", "en": "Every term leaves a remainder of 4 when divided by 5 (4, 9, 14, 19, 24, …)."}, {"vi": "2003 chia cho 5 dư 3, khác 4.", "en": "2,003 divided by 5 leaves remainder 3, not 4."}, {"vi": "Vậy 2003 không thuộc dãy số.", "en": "So 2,003 is not in the sequence."}], "tip": {"vi": "Xét số dư khi chia các số hạng cho 5.", "en": "Look at the remainders when terms are divided by 5."}, "src": "250 bài, CĐ5, Bài 7c"}, {"id": "cd5-b8a", "lesson": "seq", "rank": 1, "q": {"vi": "Cho dãy số: 2; 5; 8; 11; 14; … Tìm số hạng thứ 100 của dãy.", "en": "Given the sequence: 2, 5, 8, 11, 14, … Find the 100th term."}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng thứ 100", "en": "100th term"}, "ans": 299, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu hai số liên tiếp là 3.", "en": "The difference is 3."}, {"vi": "Từ số hạng thứ nhất đến thứ 100 có 99 khoảng cách.", "en": "From term 1 to term 100 there are 99 gaps."}, {"vi": "Số hạng thứ 100: 2 + 99 × 3 = 299.", "en": "The 100th term: 2 + 99 × 3 = 299."}], "tip": {"vi": "Số đầu cộng 99 lần hiệu.", "en": "First term plus 99 times the difference."}, "src": "250 bài, CĐ5, Bài 8a"}, {"id": "l26-b5c", "lesson": "seq", "rank": 1, "q": {"vi": "Cho dãy số: 2; 4; 6; 8; …; 2022. Số hạng thứ 50 của dãy là số nào?", "en": "Given the sequence: 2, 4, 6, 8, …, 2,022. What is the 50th term?"}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng thứ 50", "en": "50th term"}, "ans": 100, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu hai số liên tiếp là 2.", "en": "The difference is 2."}, {"vi": "Số hạng thứ 50: 2 + 49 × 2 = 100.", "en": "The 50th term: 2 + 49 × 2 = 100."}], "tip": {"vi": "Số hạng thứ n của dãy này bằng n × 2.", "en": "The nth term here equals n × 2."}, "src": "Lần 26, Bài 5c"}, {"id": "l26-b5d", "lesson": "seq", "rank": 1, "q": {"vi": "Cho dãy số: 2; 4; 6; 8; …; 2022. Số 1999 có thuộc dãy số không?", "en": "Given the sequence: 2, 4, 6, 8, …, 2,022. Is 1,999 in the sequence?"}, "parts": [{"kind": "choice", "lab": {"vi": "Số 1999", "en": "1,999"}, "opts": {"vi": ["Có", "Không"], "en": ["Yes", "No"]}, "ans": 1}], "steps": [{"vi": "Mọi số hạng của dãy đều là số chẵn.", "en": "Every term of the sequence is an even number."}, {"vi": "1999 là số lẻ (chữ số tận cùng là 9).", "en": "1,999 is odd (its last digit is 9)."}, {"vi": "Vậy 1999 không thuộc dãy.", "en": "So 1,999 is not in the sequence."}], "tip": {"vi": "Nhìn chữ số tận cùng.", "en": "Look at the last digit."}, "src": "Lần 26, Bài 5d"}, {"id": "l26-b6c", "lesson": "seq", "rank": 1, "q": {"vi": "Cho dãy số: 1; 3; 5; 7; 9; …; 1999. Số hạng thứ 100 của dãy là số nào?", "en": "Given the sequence: 1, 3, 5, 7, 9, …, 1,999. What is the 100th term?"}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng thứ 100", "en": "100th term"}, "ans": 199, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu hai số liên tiếp là 2.", "en": "The difference is 2."}, {"vi": "Số hạng thứ 100: 1 + 99 × 2 = 199.", "en": "The 100th term: 1 + 99 × 2 = 199."}], "tip": {"vi": "Số đầu cộng 99 lần hiệu.", "en": "First term plus 99 times the difference."}, "src": "Lần 26, Bài 6c"}, {"id": "l26-b7c", "lesson": "seq", "rank": 1, "q": {"vi": "Cho dãy số: 3; 6; 9; 12; …; 3000. Số hạng thứ 50 của dãy là số nào?", "en": "Given the sequence: 3, 6, 9, 12, …, 3,000. What is the 50th term?"}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng thứ 50", "en": "50th term"}, "ans": 150, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu hai số liên tiếp là 3.", "en": "The difference is 3."}, {"vi": "Số hạng thứ 50: 3 + 49 × 3 = 150.", "en": "The 50th term: 3 + 49 × 3 = 150."}], "tip": {"vi": "Số hạng thứ n của dãy này bằng n × 3.", "en": "The nth term here equals n × 3."}, "src": "Lần 26, Bài 7c"}, {"id": "l26-b8c", "lesson": "seq", "rank": 1, "q": {"vi": "Cho dãy số: 4; 8; 12; 16; …; 4000. Số hạng thứ 35 của dãy là số nào?", "en": "Given the sequence: 4, 8, 12, 16, …, 4,000. What is the 35th term?"}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng thứ 35", "en": "35th term"}, "ans": 140, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu hai số liên tiếp là 4.", "en": "The difference is 4."}, {"vi": "Số hạng thứ 35: 4 + 34 × 4 = 140.", "en": "The 35th term: 4 + 34 × 4 = 140."}], "tip": {"vi": "Số hạng thứ n của dãy này bằng n × 4.", "en": "The nth term here equals n × 4."}, "src": "Lần 26, Bài 8c"}, {"id": "l26-b9a", "lesson": "seq", "rank": 1, "q": {"vi": "Cho dãy số: 4; 9; 14; 19; 24; 29; 34; 39. Tính tổng của dãy.", "en": "Given the sequence: 4, 9, 14, 19, 24, 29, 34, 39. Find the sum of the sequence."}, "parts": [{"kind": "num", "lab": {"vi": "Tổng dãy số", "en": "Sum"}, "ans": 172, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Dãy có 8 số hạng, hiệu hai số liên tiếp là 5.", "en": "The sequence has 8 terms, and the difference is 5."}, {"vi": "Ghép cặp: 4 + 39 = 43; có 8 : 2 = 4 cặp.", "en": "Pair up: 4 + 39 = 43; there are 8 ÷ 2 = 4 pairs."}, {"vi": "Tổng: 43 × 4 = 172.", "en": "Sum: 43 × 4 = 172."}], "tip": {"vi": "Ghép số đầu với số cuối.", "en": "Pair the first with the last."}, "src": "Lần 26, Bài 9a"}, {"id": "l26-b9b", "lesson": "seq", "rank": 1, "q": {"vi": "Cho dãy số: 4; 9; 14; 19; 24; 29; 34; 39; … (cứ thêm 5 đơn vị). Tìm số hạng thứ 100 của dãy.", "en": "Given the sequence: 4, 9, 14, 19, 24, 29, 34, 39, … (adding 5 each time). Find the 100th term."}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng thứ 100", "en": "100th term"}, "ans": 499, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu hai số liên tiếp là 5.", "en": "The difference is 5."}, {"vi": "Số hạng thứ 100: 4 + 99 × 5 = 499.", "en": "The 100th term: 4 + 99 × 5 = 499."}], "tip": {"vi": "Số đầu cộng 99 lần hiệu.", "en": "First term plus 99 times the difference."}, "src": "Lần 26, Bài 9b"}, {"id": "cd5-b13b", "lesson": "seq", "rank": 2, "q": {"vi": "Cho dãy số: 11; 14; 17; 20; … Tính tổng của 130 số hạng đầu tiên của dãy.", "en": "Given the sequence: 11, 14, 17, 20, … Find the sum of the first 130 terms."}, "parts": [{"kind": "num", "lab": {"vi": "Tổng 130 số hạng", "en": "Sum of 130 terms"}, "ans": 26585, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số hạng thứ 130: 11 + 129 × 3 = 398.", "en": "The 130th term: 11 + 129 × 3 = 398."}, {"vi": "Ghép cặp: 11 + 398 = 409; có 130 : 2 = 65 cặp.", "en": "Pair up: 11 + 398 = 409; there are 130 ÷ 2 = 65 pairs."}, {"vi": "Tổng: 409 × 65 = 26 585.", "en": "Sum: 409 × 65 = 26,585."}], "tip": {"vi": "Tổng = (số đầu + số cuối) × số số hạng : 2.", "en": "Sum = (first + last) × number of terms ÷ 2."}, "src": "250 bài, CĐ5, Bài 13b"}, {"id": "cd5-b17b", "lesson": "seq", "rank": 2, "q": {"vi": "Cho dãy số: 12; 16; 20; 24; 28; … Trong các số 2012; 2013; 2014; 2015 có bao nhiêu số thuộc dãy? Số đó (nếu có) là số hạng thứ bao nhiêu?", "en": "Given the sequence: 12, 16, 20, 24, 28, … Among 2,012; 2,013; 2,014; 2,015, how many are in the sequence? What position is that number in?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số thuộc dãy", "en": "How many are in it"}, "ans": 1, "unit": {"vi": "số", "en": "numbers"}}, {"kind": "num", "lab": {"vi": "Vị trí của số đó", "en": "Its position"}, "ans": 501, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Mỗi số hạng của dãy chia hết cho 4 (12; 16; 20; …).", "en": "Every term is divisible by 4 (12, 16, 20, …)."}, {"vi": "2012 : 4 = 503 nên chia hết cho 4; 2013, 2014, 2015 không chia hết cho 4. Chỉ có 2012 thuộc dãy.", "en": "2,012 ÷ 4 = 503, so it is divisible by 4; 2,013, 2,014 and 2,015 are not. Only 2,012 is in the sequence."}, {"vi": "Vị trí của 2012: (2012 − 12) : 4 + 1 = 501.", "en": "Position of 2,012: (2,012 − 12) ÷ 4 + 1 = 501."}], "tip": {"vi": "Các số hạng đều chia hết cho 4.", "en": "All terms are divisible by 4."}, "src": "250 bài, CĐ5, Bài 17b"}, {"id": "cd5-b17c", "lesson": "seq", "rank": 2, "q": {"vi": "Cho dãy số: 12; 16; 20; 24; 28; … Tính tổng 50 số hạng đầu tiên của dãy.", "en": "Given the sequence: 12, 16, 20, 24, 28, … Find the sum of the first 50 terms."}, "parts": [{"kind": "num", "lab": {"vi": "Tổng 50 số hạng", "en": "Sum of 50 terms"}, "ans": 5500, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số hạng thứ 50: 12 + 49 × 4 = 208.", "en": "The 50th term: 12 + 49 × 4 = 208."}, {"vi": "Ghép cặp: 12 + 208 = 220; có 50 : 2 = 25 cặp.", "en": "Pair up: 12 + 208 = 220; there are 50 ÷ 2 = 25 pairs."}, {"vi": "Tổng: 220 × 25 = 5500.", "en": "Sum: 220 × 25 = 5,500."}], "tip": {"vi": "Tổng = (số đầu + số cuối) × số số hạng : 2.", "en": "Sum = (first + last) × number of terms ÷ 2."}, "src": "250 bài, CĐ5, Bài 17c"}, {"id": "cd5-b1a", "lesson": "seq", "rank": 2, "q": {"vi": "Tìm quy luật và viết thêm 3 số hạng vào dãy số sau:\n1; 3; 4; 7; 11; 18; …", "en": "Find the rule and write the next 3 terms of this sequence:\n1, 3, 4, 7, 11, 18, …"}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 1", "en": "Next term 1"}, "ans": 29, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 2", "en": "Next term 2"}, "ans": 47, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 3", "en": "Next term 3"}, "ans": 76, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Mỗi số hạng (từ số thứ ba) bằng tổng hai số hạng đứng ngay trước nó: 1 + 3 = 4; 3 + 4 = 7; 4 + 7 = 11; 7 + 11 = 18.", "en": "Each term (from the third) equals the sum of the two terms before it: 1 + 3 = 4; 3 + 4 = 7; 4 + 7 = 11; 7 + 11 = 18."}, {"vi": "Số hạng tiếp theo: 11 + 18 = 29.", "en": "Next term: 11 + 18 = 29."}, {"vi": "Tiếp: 18 + 29 = 47; rồi 29 + 47 = 76.", "en": "Then: 18 + 29 = 47; then 29 + 47 = 76."}], "tip": {"vi": "Thử cộng hai số liền nhau xem có ra số đứng sau không.", "en": "Try adding two neighboring terms and compare with the next term."}, "src": "250 bài, CĐ5, Bài 1a"}, {"id": "cd5-b1d", "lesson": "seq", "rank": 2, "q": {"vi": "Tìm quy luật và viết thêm 3 số hạng vào dãy số sau:\n1; 2; 6; 24; …", "en": "Find the rule and write the next 3 terms of this sequence:\n1, 2, 6, 24, …"}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 1", "en": "Next term 1"}, "ans": 120, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 2", "en": "Next term 2"}, "ans": 720, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 3", "en": "Next term 3"}, "ans": 5040, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số sau gấp số trước: 2 : 1 = 2 lần; 6 : 2 = 3 lần; 24 : 6 = 4 lần. Số lần tăng dần 1.", "en": "Each term is a multiple of the one before: 2 ÷ 1 = 2 times; 6 ÷ 2 = 3 times; 24 ÷ 6 = 4 times. The multiplier grows by 1."}, {"vi": "Số hạng tiếp theo: 24 × 5 = 120.", "en": "Next term: 24 × 5 = 120."}, {"vi": "Tiếp: 120 × 6 = 720; 720 × 7 = 5040.", "en": "Then: 120 × 6 = 720; 720 × 7 = 5,040."}], "tip": {"vi": "Xem số sau gấp mấy lần số trước.", "en": "See how many times larger each term is than the one before."}, "src": "250 bài, CĐ5, Bài 1d"}, {"id": "cd5-b23b", "lesson": "seq", "rank": 2, "q": {"vi": "Một người viết liền nhau nhóm chữ cái VUIHOCTOAN VUIHOCTOAN… rồi tô màu lần lượt từng chữ cái bằng 6 màu Đỏ, Cam, Vàng, Lục, Lam, Tím (hết Tím lại quay về Đỏ, và cứ thế tiếp tục). Hỏi chữ V thứ 150 được tô màu gì? Chữ O thứ 135 được tô màu gì?", "en": "A person writes the group of letters VUIHOCTOAN VUIHOCTOAN… over and over, then colors the letters one by one with 6 colors in turn: Red, Orange, Yellow, Green, Blue, Purple (after Purple it goes back to Red, and so on). What color is the 150th letter V? What color is the 135th letter O?"}, "parts": [{"kind": "choice", "lab": {"vi": "Chữ V thứ 150", "en": "The 150th V"}, "opts": {"vi": ["Đỏ", "Cam", "Vàng", "Lục", "Lam", "Tím"], "en": ["Red", "Orange", "Yellow", "Green", "Blue", "Purple"]}, "ans": 2}, {"kind": "choice", "lab": {"vi": "Chữ O thứ 135", "en": "The 135th O"}, "opts": {"vi": ["Đỏ", "Cam", "Vàng", "Lục", "Lam", "Tím"], "en": ["Red", "Orange", "Yellow", "Green", "Blue", "Purple"]}, "ans": 2}], "steps": [{"vi": "Chữ V thứ 150 đứng ở vị trí 10 × 149 + 1 = 1491 (mỗi nhóm 10 chữ có 1 chữ V).", "en": "The 150th V is at position 10 × 149 + 1 = 1,491 (each group of 10 has one V)."}, {"vi": "1491 : 6 = 248 dư 3 nên chữ V đó được tô màu thứ 3: Vàng.", "en": "1,491 ÷ 6 = 248 remainder 3, so that V gets the 3rd color: Yellow."}, {"vi": "Mỗi nhóm có 2 chữ O (ở vị trí 5 và 8), nên chữ O thứ 135 là chữ O đầu của nhóm thứ 68, ở vị trí 10 × 67 + 5 = 675.", "en": "Each group has 2 Os (at positions 5 and 8), so the 135th O is the first O of the 68th group, at position 10 × 67 + 5 = 675."}, {"vi": "675 : 6 = 112 dư 3 nên chữ O đó cũng được tô màu thứ 3: Vàng.", "en": "675 ÷ 6 = 112 remainder 3, so that O also gets the 3rd color: Yellow."}], "tip": {"vi": "Tìm vị trí của chữ cái trong cả dãy, rồi chia cho 6.", "en": "Find the letter's position in the whole row, then divide by 6."}, "src": "250 bài, CĐ5, Bài 23b"}, {"id": "cd5-b24b", "lesson": "seq", "rank": 2, "q": {"vi": "Một người viết liền chữ QUYET TAM HOC GIOI QUYET TAM HOC GIOI… (viết trọn từng cụm, dừng ở cuối một cụm) Người ta đếm được trong dãy có 100 chữ T. Hỏi có bao nhiêu chữ I, bao nhiêu chữ A?", "en": "A person writes the letters QUYET TAM HOC GIOI QUYET TAM HOC GIOI… (always finishing a whole group) over and over. There are 100 letters T in the row. How many letters I and how many letters A are there?"}, "parts": [{"kind": "num", "lab": {"vi": "Số chữ I", "en": "Number of I's"}, "ans": 100, "unit": {"vi": "chữ", "en": "letters"}}, {"kind": "num", "lab": {"vi": "Số chữ A", "en": "Number of A's"}, "ans": 50, "unit": {"vi": "chữ", "en": "letters"}}], "steps": [{"vi": "Mỗi nhóm QUYET TAM HOC GIOI có 2 chữ T (QUYET và TAM).", "en": "Each group has 2 letters T (in QUYET and TAM)."}, {"vi": "100 chữ T nên có 100 : 2 = 50 nhóm.", "en": "100 T's means 100 ÷ 2 = 50 groups."}, {"vi": "Mỗi nhóm có 2 chữ I (trong GIOI) nên có 50 × 2 = 100 chữ I.", "en": "Each group has 2 letters I (in GIOI), so 50 × 2 = 100 I's."}, {"vi": "Mỗi nhóm có 1 chữ A (trong TAM) nên có 50 × 1 = 50 chữ A.", "en": "Each group has 1 letter A (in TAM), so 50 × 1 = 50 A's."}], "tip": {"vi": "Tìm số nhóm trước.", "en": "Find the number of groups first."}, "src": "250 bài, CĐ5, Bài 24b"}, {"id": "cd5-b25", "lesson": "seq", "rank": 2, "q": {"vi": "Người ta xếp các số tự nhiên liên tiếp kể từ 1 thành 4 cột A, B, C, D như sau: hàng 1: 1, 2, 3, 4 (từ cột A sang D); hàng 2: 8, 7, 6, 5 (từ cột A sang D); hàng 3: 9, 10, 11, 12; hàng 4: 16, 15, 14, 13; … (cứ tiếp tục như vậy). Hỏi số 2015 nằm ở cột nào?", "en": "The consecutive whole numbers starting from 1 are arranged in 4 columns A, B, C, D as follows: row 1: 1, 2, 3, 4 (from column A to D); row 2: 8, 7, 6, 5 (from column A to D); row 3: 9, 10, 11, 12; row 4: 16, 15, 14, 13; … (and so on). In which column is the number 2,015?"}, "parts": [{"kind": "choice", "lab": {"vi": "Cột của số 2015", "en": "Column of 2,015"}, "opts": {"vi": ["A", "B", "C", "D"], "en": ["A", "B", "C", "D"]}, "ans": 1}], "steps": [{"vi": "Mỗi hàng có 4 số. 2015 : 4 = 503 dư 3, nên số 2015 nằm ở hàng thứ 504, là số thứ 3 của hàng đó (tính theo thứ tự tăng dần).", "en": "Each row has 4 numbers. 2,015 ÷ 4 = 503 remainder 3, so 2,015 is in row 504, as the 3rd number of that row (in increasing order)."}, {"vi": "Hàng chẵn (2, 4, …) viết ngược từ phải sang trái: hàng 504 là chẵn.", "en": "Even rows (2, 4, …) are written backwards, from right to left: row 504 is even."}, {"vi": "Hàng 504 gồm 2013, 2014, 2015, 2016; viết ngược nên cột A là 2016, cột B là 2015.", "en": "Row 504 holds 2,013, 2,014, 2,015, 2,016; written backwards, column A is 2,016 and column B is 2,015."}, {"vi": "Vậy số 2015 nằm ở cột B.", "en": "So 2,015 is in column B."}], "tip": {"vi": "Hàng chẵn đảo ngược thứ tự các cột.", "en": "Even rows reverse the order of the columns."}, "src": "250 bài, CĐ5, Bài 25"}, {"id": "cd5-b3", "lesson": "seq", "rank": 2, "q": {"vi": "Điền các số thích hợp vào 10 ô trống liên tiếp, sao cho tổng các số ở 3 ô liên tiếp đều bằng 2014. Biết ô thứ 2 là 996 và ô thứ 6 là 496. Tìm số ở ô thứ nhất, ô thứ ba, ô thứ năm và ô thứ mười.", "en": "Fill in 10 boxes in a row so that the sum of any 3 consecutive boxes is 2,014. Box 2 is 996 and box 6 is 496. Find the numbers in box 1, box 3, box 5 and box 10."}, "parts": [{"kind": "num", "lab": {"vi": "Ô thứ nhất", "en": "Box 1"}, "ans": 522, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Ô thứ ba", "en": "Box 3"}, "ans": 496, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Ô thứ năm", "en": "Box 5"}, "ans": 996, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Ô thứ mười", "en": "Box 10"}, "ans": 522, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Ba ô liên tiếp luôn có tổng 2014, nên ô thứ 1 = ô thứ 4 = ô thứ 7 = ô thứ 10; ô 2 = ô 5 = ô 8; ô 3 = ô 6 = ô 9.", "en": "Any 3 consecutive boxes sum to 2,014, so box 1 = box 4 = box 7 = box 10; box 2 = box 5 = box 8; box 3 = box 6 = box 9."}, {"vi": "Ô thứ 6 là 496 nên ô thứ 3 cũng là 496; ô thứ 5 bằng ô thứ 2 là 996.", "en": "Box 6 is 496, so box 3 is 496 too; box 5 equals box 2, which is 996."}, {"vi": "Ô thứ nhất: 2014 − 996 − 496 = 522, nên ô thứ 10 cũng là 522.", "en": "Box 1: 2,014 − 996 − 496 = 522, so box 10 is also 522."}], "tip": {"vi": "Hai bộ ba ô liền nhau chỉ khác nhau ở hai ô đầu và cuối.", "en": "Two overlapping groups of 3 differ only in their first and last boxes."}, "src": "250 bài, CĐ5, Bài 3"}, {"id": "cd5-b4a", "lesson": "seq", "rank": 2, "q": {"vi": "Tìm số hạng thứ 60 của dãy:\n2; 6; 12; 20; 30; …", "en": "Find the 60th term of the sequence:\n2, 6, 12, 20, 30, …"}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng thứ 60", "en": "60th term"}, "ans": 3660, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Ta có: 2 = 1 × 2; 6 = 2 × 3; 12 = 3 × 4; 20 = 4 × 5; 30 = 5 × 6.", "en": "We have: 2 = 1 × 2; 6 = 2 × 3; 12 = 3 × 4; 20 = 4 × 5; 30 = 5 × 6."}, {"vi": "Số hạng thứ n bằng n nhân với (n + 1).", "en": "The nth term is n times (n + 1)."}, {"vi": "Số hạng thứ 60: 60 × 61 = 3660.", "en": "The 60th term: 60 × 61 = 3,660."}], "tip": {"vi": "Viết mỗi số thành tích của hai số tự nhiên liên tiếp.", "en": "Write each term as a product of two consecutive whole numbers."}, "src": "250 bài, CĐ5, Bài 4a"}, {"id": "cd5-b5b", "lesson": "seq", "rank": 2, "q": {"vi": "Cho dãy số: 1; 2; 4; 7; 11; 16; … Tìm số hạng thứ 50 của dãy.", "en": "Given the sequence: 1, 2, 4, 7, 11, 16, … Find the 50th term."}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng thứ 50", "en": "50th term"}, "ans": 1226, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu hai số liên tiếp: 1; 2; 3; 4; 5; … tăng dần 1 đơn vị.", "en": "Differences: 1, 2, 3, 4, 5, … growing by 1."}, {"vi": "Từ số hạng thứ nhất đến thứ 50, ta cộng các hiệu 1 + 2 + … + 49 = (1 + 49) × 49 : 2 = 1225.", "en": "From term 1 to term 50 we add the differences 1 + 2 + … + 49 = (1 + 49) × 49 ÷ 2 = 1,225."}, {"vi": "Số hạng thứ 50: 1 + 1225 = 1226.", "en": "The 50th term: 1 + 1,225 = 1,226."}], "tip": {"vi": "Cộng tất cả các hiệu lại với nhau.", "en": "Add up all the differences."}, "src": "250 bài, CĐ5, Bài 5b"}, {"id": "cd5-b5d", "lesson": "seq", "rank": 2, "q": {"vi": "Cho dãy số: 1; 4; 9; 16; 25; … Tìm số hạng thứ 60 của dãy.", "en": "Given the sequence: 1, 4, 9, 16, 25, … Find the 60th term."}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng thứ 60", "en": "60th term"}, "ans": 3600, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Ta có: 1 = 1 × 1; 4 = 2 × 2; 9 = 3 × 3; 16 = 4 × 4; 25 = 5 × 5.", "en": "We have: 1 = 1 × 1; 4 = 2 × 2; 9 = 3 × 3; 16 = 4 × 4; 25 = 5 × 5."}, {"vi": "Số hạng thứ n bằng n × n.", "en": "The nth term is n × n."}, {"vi": "Số hạng thứ 60: 60 × 60 = 3600.", "en": "The 60th term: 60 × 60 = 3,600."}], "tip": {"vi": "Mỗi số là tích của hai số bằng nhau.", "en": "Each term is a product of two equal numbers."}, "src": "250 bài, CĐ5, Bài 5c (lần 2)"}, {"id": "cd5-b6a", "lesson": "seq", "rank": 2, "q": {"vi": "Có bao nhiêu số có 3 chữ số chia hết cho 5?", "en": "How many 3-digit numbers are divisible by 5?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số", "en": "Count"}, "ans": 180, "unit": {"vi": "số", "en": "numbers"}}], "steps": [{"vi": "Số nhỏ nhất có 3 chữ số chia hết cho 5 là 100; số lớn nhất là 995.", "en": "The smallest 3-digit multiple of 5 is 100; the largest is 995."}, {"vi": "Các số này cách đều nhau 5 đơn vị.", "en": "These numbers are evenly spaced, 5 apart."}, {"vi": "Số các số: (995 − 100) : 5 + 1 = 180.", "en": "Count: (995 − 100) ÷ 5 + 1 = 180."}], "tip": {"vi": "Số các số = (số cuối − số đầu) : khoảng cách + 1.", "en": "Count = (last − first) ÷ gap + 1."}, "src": "250 bài, CĐ5, Bài 6a"}, {"id": "cd5-b6b", "lesson": "seq", "rank": 2, "q": {"vi": "Tính tổng tất cả các số có 3 chữ số chia cho 3 dư 2.", "en": "Find the sum of all 3-digit numbers that leave a remainder of 2 when divided by 3."}, "parts": [{"kind": "num", "lab": {"vi": "Tổng các số", "en": "Sum"}, "ans": 164850, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số nhỏ nhất có 3 chữ số chia 3 dư 2 là 101; số lớn nhất là 998; các số cách đều nhau 3 đơn vị.", "en": "The smallest such number is 101, the largest is 998, and they are 3 apart."}, {"vi": "Số các số: (998 − 101) : 3 + 1 = 300.", "en": "Count: (998 − 101) ÷ 3 + 1 = 300."}, {"vi": "Tổng: (101 + 998) × 300 : 2 = 1099 × 150 = 164 850.", "en": "Sum: (101 + 998) × 300 ÷ 2 = 1,099 × 150 = 164,850."}], "tip": {"vi": "Ghép cặp số đầu với số cuối.", "en": "Pair the first number with the last."}, "src": "250 bài, CĐ5, Bài 6b"}, {"id": "cd5-b8b", "lesson": "seq", "rank": 2, "q": {"vi": "Cho dãy số: 2; 5; 8; 11; 14; … Trong các số 2009; 2010; 2011; 2012 có bao nhiêu số thuộc dãy? Nếu số 2009 thuộc dãy thì nó là số hạng thứ mấy? Số 2012 là số hạng thứ mấy?", "en": "Given the sequence: 2, 5, 8, 11, 14, … Among the numbers 2,009; 2,010; 2,011; 2,012, how many are in the sequence? What position is 2,009 in? What position is 2,012 in?"}, "parts": [{"kind": "num", "lab": {"vi": "Số các số thuộc dãy", "en": "How many are in it"}, "ans": 2, "unit": {"vi": "số", "en": "numbers"}}, {"kind": "num", "lab": {"vi": "Vị trí của 2009", "en": "Position of 2,009"}, "ans": 670, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Vị trí của 2012", "en": "Position of 2,012"}, "ans": 671, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Mỗi số hạng của dãy chia cho 3 đều dư 2.", "en": "Every term leaves a remainder of 2 when divided by 3."}, {"vi": "2009 : 3 dư 2 và 2012 : 3 dư 2 nên hai số này thuộc dãy; 2010 chia hết cho 3 và 2011 chia 3 dư 1 nên không thuộc dãy.", "en": "2,009 ÷ 3 and 2,012 ÷ 3 both leave remainder 2, so both are in the sequence; 2,010 is divisible by 3 and 2,011 leaves remainder 1, so they are not."}, {"vi": "Vị trí của 2009: (2009 − 2) : 3 + 1 = 670.", "en": "Position of 2,009: (2,009 − 2) ÷ 3 + 1 = 670."}, {"vi": "Vị trí của 2012: (2012 − 2) : 3 + 1 = 671.", "en": "Position of 2,012: (2,012 − 2) ÷ 3 + 1 = 671."}], "tip": {"vi": "Kiểm tra số dư khi chia cho 3.", "en": "Check the remainder when dividing by 3."}, "src": "250 bài, CĐ5, Bài 8b"}, {"id": "cd5-b8c", "lesson": "seq", "rank": 2, "q": {"vi": "Cho dãy số: 2; 5; 8; 11; 14; … Tính tổng 60 số hạng đầu tiên của dãy.", "en": "Given the sequence: 2, 5, 8, 11, 14, … Find the sum of the first 60 terms."}, "parts": [{"kind": "num", "lab": {"vi": "Tổng 60 số hạng", "en": "Sum of 60 terms"}, "ans": 5430, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số hạng thứ 60: 2 + 59 × 3 = 179.", "en": "The 60th term: 2 + 59 × 3 = 179."}, {"vi": "Ghép cặp: (2 + 179) = 181, mỗi cặp là một tổng; có 60 : 2 = 30 cặp.", "en": "Pair up: 2 + 179 = 181 for each pair; there are 60 ÷ 2 = 30 pairs."}, {"vi": "Tổng: 181 × 30 = 5430.", "en": "Sum: 181 × 30 = 5,430."}], "tip": {"vi": "Tổng = (số đầu + số cuối) × số số hạng : 2.", "en": "Sum = (first + last) × number of terms ÷ 2."}, "src": "250 bài, CĐ5, Bài 8c"}, {"id": "l26-b5a", "lesson": "seq", "rank": 2, "q": {"vi": "Cho dãy số: 2; 4; 6; 8; …; 2022. Tính tổng của dãy số.", "en": "Given the sequence: 2, 4, 6, 8, …, 2,022. Find the sum of the sequence."}, "parts": [{"kind": "num", "lab": {"vi": "Tổng dãy số", "en": "Sum"}, "ans": 1023132, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu hai số liên tiếp là 2. Số số hạng: (2022 − 2) : 2 + 1 = 1011.", "en": "The difference is 2. Number of terms: (2,022 − 2) ÷ 2 + 1 = 1,011."}, {"vi": "Ghép cặp: 2 + 2022 = 2024 là tổng một cặp (số đầu và số cuối).", "en": "Pair up: 2 + 2,022 = 2,024 is the sum of one pair (first and last)."}, {"vi": "Tổng: 2024 × 1011 : 2 = 1 023 132.", "en": "Sum: 2,024 × 1,011 ÷ 2 = 1,023,132."}], "tip": {"vi": "Tổng = (số đầu + số cuối) × số số hạng : 2.", "en": "Sum = (first + last) × number of terms ÷ 2."}, "src": "Lần 26, Bài 5a"}, {"id": "l26-b6a", "lesson": "seq", "rank": 2, "q": {"vi": "Cho dãy số: 1; 3; 5; 7; 9; …; 1999. Tính tổng của dãy số.", "en": "Given the sequence: 1, 3, 5, 7, 9, …, 1,999. Find the sum of the sequence."}, "parts": [{"kind": "num", "lab": {"vi": "Tổng dãy số", "en": "Sum"}, "ans": 1000000, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu hai số liên tiếp là 2. Số số hạng: (1999 − 1) : 2 + 1 = 1000.", "en": "The difference is 2. Number of terms: (1,999 − 1) ÷ 2 + 1 = 1,000."}, {"vi": "Tổng: (1 + 1999) × 1000 : 2 = 1 000 000.", "en": "Sum: (1 + 1,999) × 1,000 ÷ 2 = 1,000,000."}], "tip": {"vi": "Tổng = (số đầu + số cuối) × số số hạng : 2.", "en": "Sum = (first + last) × number of terms ÷ 2."}, "src": "Lần 26, Bài 6a"}, {"id": "l26-b7a", "lesson": "seq", "rank": 2, "q": {"vi": "Cho dãy số: 3; 6; 9; 12; …; 3000. Tính tổng của dãy số.", "en": "Given the sequence: 3, 6, 9, 12, …, 3,000. Find the sum of the sequence."}, "parts": [{"kind": "num", "lab": {"vi": "Tổng dãy số", "en": "Sum"}, "ans": 1501500, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu hai số liên tiếp là 3. Số số hạng: (3000 − 3) : 3 + 1 = 1000.", "en": "The difference is 3. Number of terms: (3,000 − 3) ÷ 3 + 1 = 1,000."}, {"vi": "Tổng: (3 + 3000) × 1000 : 2 = 1 501 500.", "en": "Sum: (3 + 3,000) × 1,000 ÷ 2 = 1,501,500."}], "tip": {"vi": "Tổng = (số đầu + số cuối) × số số hạng : 2.", "en": "Sum = (first + last) × number of terms ÷ 2."}, "src": "Lần 26, Bài 7a"}, {"id": "l26-b8a", "lesson": "seq", "rank": 2, "q": {"vi": "Cho dãy số: 4; 8; 12; 16; …; 4000. Tính tổng của dãy số.", "en": "Given the sequence: 4, 8, 12, 16, …, 4,000. Find the sum of the sequence."}, "parts": [{"kind": "num", "lab": {"vi": "Tổng dãy số", "en": "Sum"}, "ans": 2002000, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu hai số liên tiếp là 4. Số số hạng: (4000 − 4) : 4 + 1 = 1000.", "en": "The difference is 4. Number of terms: (4,000 − 4) ÷ 4 + 1 = 1,000."}, {"vi": "Tổng: (4 + 4000) × 1000 : 2 = 2 002 000.", "en": "Sum: (4 + 4,000) × 1,000 ÷ 2 = 2,002,000."}], "tip": {"vi": "Tổng = (số đầu + số cuối) × số số hạng : 2.", "en": "Sum = (first + last) × number of terms ÷ 2."}, "src": "Lần 26, Bài 8a"}, {"id": "l26-b9c", "lesson": "seq", "rank": 2, "q": {"vi": "Cho dãy số: 4; 9; 14; 19; 24; 29; 34; 39; … (cứ thêm 5 đơn vị). Số 2019 là số hạng thứ mấy của dãy?", "en": "Given the sequence: 4, 9, 14, 19, 24, 29, 34, 39, … (adding 5 each time). Which term of the sequence is 2,019?"}, "parts": [{"kind": "num", "lab": {"vi": "Vị trí của 2019", "en": "Position of 2,019"}, "ans": 404, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Mỗi số hạng chia cho 5 dư 4; 2019 chia cho 5 dư 4 nên 2019 thuộc dãy.", "en": "Every term leaves remainder 4 when divided by 5; 2,019 also leaves remainder 4, so it is in the sequence."}, {"vi": "Từ 4 đến 2019 có (2019 − 4) : 5 = 403 khoảng cách.", "en": "From 4 to 2,019 there are (2,019 − 4) ÷ 5 = 403 gaps."}, {"vi": "Số 2019 là số hạng thứ 403 + 1 = 404.", "en": "So 2,019 is term number 403 + 1 = 404."}], "tip": {"vi": "Số số hạng = (số cuối − số đầu) : hiệu + 1.", "en": "Number of terms = (last − first) ÷ difference + 1."}, "src": "Lần 26, Bài 9c"}, {"id": "cd5-b19", "lesson": "seq", "rank": 3, "q": {"vi": "Cho dãy số 10; 11; 12; 13; …; x. Tìm x để tổng của dãy số trên bằng 5106.", "en": "Given the sequence 10, 11, 12, 13, …, x. Find x so that the sum of the sequence is 5,106."}, "parts": [{"kind": "num", "lab": {"vi": "Giá trị của x", "en": "Value of x"}, "ans": 101, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tổng của dãy bằng (số đầu + số cuối) × số số hạng : 2, nên (10 + x) × (x − 9) = 5106 × 2 = 10 212.", "en": "The sum is (first + last) × number of terms ÷ 2, so (10 + x) × (x − 9) = 5,106 × 2 = 10,212."}, {"vi": "Hai thừa số hơn kém nhau 19 và có tích 10 212. Vì 100 × 100 = 10 000 nên hai số gần 100; thử 111 × 92 = 10 212.", "en": "The two factors differ by 19 and multiply to 10,212. Since 100 × 100 = 10,000, they are near 100; try 111 × 92 = 10,212."}, {"vi": "Suy ra 10 + x = 111, vậy x = 101.", "en": "So 10 + x = 111, and x = 101."}], "tip": {"vi": "Hai thừa số hơn kém nhau 19.", "en": "The two factors differ by 19."}, "src": "250 bài, CĐ5, Bài 19"}, {"id": "cd5-b1b", "lesson": "seq", "rank": 3, "q": {"vi": "Tìm quy luật và viết thêm 3 số hạng vào dãy số sau:\n0; 2; 4; 6; 12; 22; …", "en": "Find the rule and write the next 3 terms of this sequence:\n0, 2, 4, 6, 12, 22, …"}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 1", "en": "Next term 1"}, "ans": 40, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 2", "en": "Next term 2"}, "ans": 74, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 3", "en": "Next term 3"}, "ans": 136, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Từ số hạng thứ tư, mỗi số bằng tổng ba số hạng đứng ngay trước nó: 0 + 2 + 4 = 6; 2 + 4 + 6 = 12; 4 + 6 + 12 = 22.", "en": "From the fourth term on, each term equals the sum of the three terms before it: 0 + 2 + 4 = 6; 2 + 4 + 6 = 12; 4 + 6 + 12 = 22."}, {"vi": "Số hạng tiếp theo: 6 + 12 + 22 = 40.", "en": "Next term: 6 + 12 + 22 = 40."}, {"vi": "Tiếp: 12 + 22 + 40 = 74; rồi 22 + 40 + 74 = 136.", "en": "Then: 12 + 22 + 40 = 74; then 22 + 40 + 74 = 136."}], "tip": {"vi": "Thử cộng ba số liền nhau.", "en": "Try adding three neighboring terms."}, "src": "250 bài, CĐ5, Bài 1b"}, {"id": "cd5-b1g", "lesson": "seq", "rank": 3, "q": {"vi": "Tìm quy luật và viết thêm 3 số hạng vào dãy số sau:\n0; 1; 2; 4; 7; 12; …", "en": "Find the rule and write the next 3 terms of this sequence:\n0, 1, 2, 4, 7, 12, …"}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 1", "en": "Next term 1"}, "ans": 20, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 2", "en": "Next term 2"}, "ans": 33, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 3", "en": "Next term 3"}, "ans": 54, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Thử: 1 + 2 + 1 = 4; 2 + 4 + 1 = 7; 4 + 7 + 1 = 12. Mỗi số bằng tổng hai số đứng trước cộng thêm 1.", "en": "Check: 1 + 2 + 1 = 4; 2 + 4 + 1 = 7; 4 + 7 + 1 = 12. Each term equals the sum of the two terms before it plus 1."}, {"vi": "Số hạng tiếp theo: 7 + 12 + 1 = 20.", "en": "Next term: 7 + 12 + 1 = 20."}, {"vi": "Tiếp: 12 + 20 + 1 = 33; rồi 20 + 33 + 1 = 54.", "en": "Then: 12 + 20 + 1 = 33; then 20 + 33 + 1 = 54."}], "tip": {"vi": "Cộng hai số liền nhau, xem còn thiếu hay thừa bao nhiêu.", "en": "Add two neighboring terms and see how much is missing or extra."}, "src": "250 bài, CĐ5, Bài 1g"}, {"id": "cd5-b1k", "lesson": "seq", "rank": 3, "q": {"vi": "Tìm quy luật và viết thêm 2 số hạng vào dãy số sau:\n1; 3; 3; 9; 27; …", "en": "Find the rule and write the next 2 terms of this sequence:\n1, 3, 3, 9, 27, …"}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 1", "en": "Next term 1"}, "ans": 243, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số hạng tiếp theo thứ 2", "en": "Next term 2"}, "ans": 6561, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Thử nhân hai số liền nhau: 1 × 3 = 3; 3 × 3 = 9; 3 × 9 = 27. Mỗi số bằng tích hai số đứng ngay trước nó.", "en": "Try multiplying two neighbors: 1 × 3 = 3; 3 × 3 = 9; 3 × 9 = 27. Each term is the product of the two terms before it."}, {"vi": "Số hạng tiếp theo: 9 × 27 = 243.", "en": "Next term: 9 × 27 = 243."}, {"vi": "Tiếp: 27 × 243 = 6561; rồi 243 × 6561 = 1 594 323.", "en": "Then: 27 × 243 = 6,561; then 243 × 6,561 = 1,594,323."}], "tip": {"vi": "Thử nhân hai số liền nhau.", "en": "Try multiplying two neighboring terms."}, "src": "250 bài, CĐ5, Bài 1k"}, {"id": "cd5-b24c", "lesson": "seq", "rank": 3, "q": {"vi": "Một người viết liền chữ QUYET TAM HOC GIOI QUYET TAM HOC GIOI… (mỗi nhóm có 4 tiếng) rồi tô màu lần lượt từng tiếng bằng các màu Xanh, Đỏ, Tím, Vàng, Nâu (hết Nâu lại quay về Xanh, và cứ thế tiếp tục). Hỏi tiếng thứ 2015 được tô màu gì? Chữ Y thứ 500 được tô màu gì?", "en": "A person writes the words QUYET TAM HOC GIOI QUYET TAM HOC GIOI… over and over (each group has 4 words), then colors the words one by one with the colors Blue, Red, Purple, Yellow, Brown in turn (after Brown it goes back to Blue, and so on). What color is the 2,015th word? What color is the word that contains the 500th letter Y?"}, "parts": [{"kind": "choice", "lab": {"vi": "Tiếng thứ 2015", "en": "The 2,015th word"}, "opts": {"vi": ["Xanh", "Đỏ", "Tím", "Vàng", "Nâu"], "en": ["Blue", "Red", "Purple", "Yellow", "Brown"]}, "ans": 4}, {"kind": "choice", "lab": {"vi": "Tiếng chứa chữ Y thứ 500", "en": "Word with the 500th Y"}, "opts": {"vi": ["Xanh", "Đỏ", "Tím", "Vàng", "Nâu"], "en": ["Blue", "Red", "Purple", "Yellow", "Brown"]}, "ans": 1}], "steps": [{"vi": "2015 : 5 = 403, không dư nên tiếng thứ 2015 được tô màu cuối của dãy 5 màu: Nâu.", "en": "2,015 ÷ 5 = 403 with no remainder, so the 2,015th word gets the last of the 5 colors: Brown."}, {"vi": "Chữ Y chỉ nằm trong tiếng QUYET, mỗi nhóm có 1 chữ Y, nên chữ Y thứ 500 nằm ở nhóm thứ 500, trong tiếng đầu của nhóm.", "en": "The letter Y appears only in QUYET, once per group, so the 500th Y is in the 500th group, in its first word."}, {"vi": "Tiếng đó là tiếng thứ 4 × 499 + 1 = 1997.", "en": "That word is word number 4 × 499 + 1 = 1,997."}, {"vi": "1997 : 5 = 399 dư 2 nên tiếng đó được tô màu thứ 2: Đỏ.", "en": "1,997 ÷ 5 = 399 remainder 2, so that word gets the 2nd color: Red."}], "tip": {"vi": "Mỗi nhóm có 4 tiếng; tìm số thứ tự của tiếng đó trong cả dãy.", "en": "Each group has 4 words; find the word's number in the whole row."}, "src": "250 bài, CĐ5, Bài 24 (ý b thứ hai)"}, {"id": "cd5-b2c", "lesson": "seq", "rank": 3, "q": {"vi": "Tìm số hạng đầu tiên của dãy số sau, biết rằng dãy số có 10 số hạng:\n…; 63; 80; 99", "en": "Find the first term of the sequence below, given that it has 10 terms:\n…, 63, 80, 99"}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng đầu tiên", "en": "First term"}, "ans": 0, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu hai số liên tiếp: 80 − 63 = 17; 99 − 80 = 19. Các hiệu tăng thêm 2 mỗi lần.", "en": "Differences: 80 − 63 = 17; 99 − 80 = 19. The differences grow by 2 each time."}, {"vi": "Đi lùi từ 99, các hiệu là 19; 17; 15; 13; 11; 9; 7; 5; 3 (đủ 9 hiệu cho 10 số hạng).", "en": "Going backward from 99, the differences are 19; 17; 15; 13; 11; 9; 7; 5; 3 (9 differences for 10 terms)."}, {"vi": "Các số: 99; 80; 63; 48; 35; 24; 15; 8; 3; 0. Số hạng đầu tiên là 0.", "en": "The terms: 99; 80; 63; 48; 35; 24; 15; 8; 3; 0. The first term is 0."}], "tip": {"vi": "Tìm quy luật của các hiệu rồi đi lùi từ số cuối.", "en": "Find the rule of the differences, then go backward from the last term."}, "src": "250 bài, CĐ5, Bài 2c"}, {"id": "cd5-b5c", "lesson": "seq", "rank": 3, "q": {"vi": "Cho dãy số: 3; 4; 7; 12; 19; … Tìm số hạng thứ 30 của dãy.", "en": "Given the sequence: 3, 4, 7, 12, 19, … Find the 30th term."}, "parts": [{"kind": "num", "lab": {"vi": "Số hạng thứ 30", "en": "30th term"}, "ans": 844, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Bớt mỗi số đi 3 ta được: 0; 1; 4; 9; 16; … đó là các số chính phương 0 × 0; 1 × 1; 2 × 2; 3 × 3; 4 × 4.", "en": "Subtract 3 from each term: 0, 1, 4, 9, 16, … These are 0 × 0, 1 × 1, 2 × 2, 3 × 3, 4 × 4."}, {"vi": "Số hạng thứ n bằng (n − 1) × (n − 1) + 3.", "en": "The nth term is (n − 1) × (n − 1) + 3."}, {"vi": "Số hạng thứ 30: 29 × 29 + 3 = 841 + 3 = 844.", "en": "The 30th term: 29 × 29 + 3 = 841 + 3 = 844."}], "tip": {"vi": "Thử bớt mỗi số đi 3.", "en": "Try subtracting 3 from each term."}, "src": "250 bài, CĐ5, Bài 5c"}], "digits": [{"id": "cd2-b11a", "lesson": "digits", "rank": 1, "q": {"vi": "Viết liền các số tự nhiên từ 2000 đến 2015 theo thứ tự từ bé đến lớn để được số 200020012002…20142015. Hỏi số đó có bao nhiêu chữ số?", "en": "Write the whole numbers from 2,000 to 2,015 one after another to get the number 200020012002…20142015. How many digits does the number have?"}, "parts": [{"kind": "num", "lab": {"vi": "Số chữ số", "en": "Number of digits"}, "ans": 64, "unit": {"vi": "chữ số", "en": "digits"}}], "steps": [{"vi": "Từ 2000 đến 2015 có 2015 − 2000 + 1 = 16 số.", "en": "From 2,000 to 2,015 there are 2,015 − 2,000 + 1 = 16 numbers."}, {"vi": "Mỗi số có 4 chữ số.", "en": "Each number has 4 digits."}, {"vi": "Số chữ số là 16 × 4 = 64.", "en": "The total is 16 × 4 = 64 digits."}], "tip": {"vi": "Đếm xem có bao nhiêu số, mỗi số có mấy chữ số.", "en": "Count how many numbers there are and how many digits each has."}, "src": "250 bài, CĐ2, Bài 11a"}, {"id": "cd5-b10", "lesson": "digits", "rank": 1, "q": {"vi": "Để đánh số trang của một quyển sách dày 238 trang cần dùng bao nhiêu chữ số?", "en": "How many digits are needed to number the pages of a book with 238 pages?"}, "parts": [{"kind": "num", "lab": {"vi": "Số chữ số", "en": "Digits"}, "ans": 606, "unit": {"vi": "chữ số", "en": "digits"}}], "steps": [{"vi": "Trang 1 đến 9: 9 trang, dùng 9 chữ số.", "en": "Pages 1 to 9: 9 pages, 9 digits."}, {"vi": "Trang 10 đến 99: 90 trang, dùng 90 × 2 = 180 chữ số.", "en": "Pages 10 to 99: 90 pages, 90 × 2 = 180 digits."}, {"vi": "Trang 100 đến 238: 238 − 99 = 139 trang, dùng 139 × 3 = 417 chữ số.", "en": "Pages 100 to 238: 238 − 99 = 139 pages, 139 × 3 = 417 digits."}, {"vi": "Tổng: 9 + 180 + 417 = 606.", "en": "Total: 9 + 180 + 417 = 606."}], "tip": {"vi": "Chia các trang theo số chữ số của số trang.", "en": "Group the pages by how many digits their numbers have."}, "src": "250 bài, CĐ5, Bài 10"}, {"id": "l26-b10", "lesson": "digits", "rank": 1, "q": {"vi": "Một quyển sách dày 139 trang. Hỏi cần phải dùng bao nhiêu chữ số để viết hết số trang của quyển sách đó?", "en": "A book has 139 pages. How many digits are needed to write all the page numbers?"}, "parts": [{"kind": "num", "lab": {"vi": "Số chữ số", "en": "Digits"}, "ans": 309, "unit": {"vi": "chữ số", "en": "digits"}}], "steps": [{"vi": "Trang 1 đến 9: 9 trang, dùng 9 chữ số; trang 10 đến 99: 90 trang, dùng 180 chữ số.", "en": "Pages 1 to 9: 9 pages, 9 digits; pages 10 to 99: 90 pages, 180 digits."}, {"vi": "Trang 100 đến 139: 139 − 99 = 40 trang, dùng 40 × 3 = 120 chữ số.", "en": "Pages 100 to 139: 139 − 99 = 40 pages, 40 × 3 = 120 digits."}, {"vi": "Tổng: 9 + 180 + 120 = 309.", "en": "Total: 9 + 180 + 120 = 309."}], "tip": {"vi": "Chia trang theo số chữ số của số trang.", "en": "Group pages by how many digits their numbers have."}, "src": "Lần 26, Bài 10"}, {"id": "l26-b11", "lesson": "digits", "rank": 1, "q": {"vi": "Để đánh số trang của một quyển sách dày 399 trang, người ta phải dùng bao nhiêu chữ số?", "en": "To number the pages of a book with 399 pages, how many digits are needed?"}, "parts": [{"kind": "num", "lab": {"vi": "Số chữ số", "en": "Digits"}, "ans": 1089, "unit": {"vi": "chữ số", "en": "digits"}}], "steps": [{"vi": "Trang 1 đến 9: 9 chữ số; trang 10 đến 99: 90 × 2 = 180 chữ số.", "en": "Pages 1 to 9: 9 digits; pages 10 to 99: 90 × 2 = 180 digits."}, {"vi": "Trang 100 đến 399: 399 − 99 = 300 trang, dùng 300 × 3 = 900 chữ số.", "en": "Pages 100 to 399: 399 − 99 = 300 pages, 300 × 3 = 900 digits."}, {"vi": "Tổng: 9 + 180 + 900 = 1089.", "en": "Total: 9 + 180 + 900 = 1,089."}], "tip": {"vi": "Chia trang theo số chữ số của số trang.", "en": "Group pages by how many digits their numbers have."}, "src": "Lần 26, Bài 11"}, {"id": "cd5-b11", "lesson": "digits", "rank": 2, "q": {"vi": "Để đánh số trang của một quyển sách người ta phải dùng tất cả 234 chữ số. Hỏi quyển sách đó có bao nhiêu trang?", "en": "To number the pages of a book, 234 digits were used in all. How many pages does the book have?"}, "parts": [{"kind": "num", "lab": {"vi": "Số trang", "en": "Pages"}, "ans": 114, "unit": {"vi": "trang", "en": "pages"}}], "steps": [{"vi": "Trang 1 đến 99 dùng 9 + 180 = 189 chữ số.", "en": "Pages 1 to 99 use 9 + 180 = 189 digits."}, {"vi": "Số chữ số dùng cho các trang có 3 chữ số: 234 − 189 = 45 chữ số.", "en": "Digits used for 3-digit pages: 234 − 189 = 45."}, {"vi": "Số trang có 3 chữ số: 45 : 3 = 15 trang.", "en": "Number of 3-digit pages: 45 ÷ 3 = 15."}, {"vi": "Quyển sách có 99 + 15 = 114 trang.", "en": "The book has 99 + 15 = 114 pages."}], "tip": {"vi": "Trừ đi số chữ số dùng cho trang 1 đến 99 trước.", "en": "First subtract the digits used for pages 1 to 99."}, "src": "250 bài, CĐ5, Bài 11"}, {"id": "cd5-b14a", "lesson": "digits", "rank": 2, "q": {"vi": "Cho dãy các số tự nhiên liên tiếp: 1; 2; 3; 4; 5; …; 2013. Để viết các số của dãy phải dùng tất cả bao nhiêu chữ số?", "en": "Given the consecutive whole numbers 1, 2, 3, 4, 5, …, 2,013. How many digits are needed to write all of them?"}, "parts": [{"kind": "num", "lab": {"vi": "Số chữ số", "en": "Digits"}, "ans": 6945, "unit": {"vi": "chữ số", "en": "digits"}}], "steps": [{"vi": "Số có 1 chữ số: 9 số, dùng 9 chữ số; số có 2 chữ số: 90 số, dùng 180 chữ số.", "en": "1-digit numbers: 9 numbers, 9 digits; 2-digit numbers: 90 numbers, 180 digits."}, {"vi": "Số có 3 chữ số: 900 số, dùng 2700 chữ số.", "en": "3-digit numbers: 900 numbers, 2,700 digits."}, {"vi": "Số có 4 chữ số (1000 đến 2013): 2013 − 999 = 1014 số, dùng 1014 × 4 = 4056 chữ số.", "en": "4-digit numbers (1,000 to 2,013): 2,013 − 999 = 1,014 numbers, 1,014 × 4 = 4,056 digits."}, {"vi": "Tổng: 9 + 180 + 2700 + 4056 = 6945.", "en": "Total: 9 + 180 + 2,700 + 4,056 = 6,945."}], "tip": {"vi": "Chia theo số có 1, 2, 3, 4 chữ số.", "en": "Split into 1-, 2-, 3- and 4-digit numbers."}, "src": "250 bài, CĐ5, Bài 14a"}, {"id": "cd5-b21", "lesson": "digits", "rank": 2, "q": {"vi": "Cho dãy các số tự nhiên liên tiếp: 1; 2; 3; 4; 5; …; 2013; 2014. Hỏi dãy có tất cả bao nhiêu chữ số 4?", "en": "Take the consecutive whole numbers 1, 2, 3, 4, 5, …, 2,013, 2,014. How many digits 4 are there in total?"}, "parts": [{"kind": "num", "lab": {"vi": "Số chữ số 4", "en": "Number of 4s"}, "ans": 602, "unit": {"vi": "chữ số", "en": "digits"}}], "steps": [{"vi": "Hàng đơn vị: các số tận cùng 4 là 4, 14, …, 2014, có (2014 − 4) : 10 + 1 = 202 số.", "en": "Units place: numbers ending in 4 are 4, 14, …, 2,014, so (2,014 − 4) ÷ 10 + 1 = 202."}, {"vi": "Hàng chục: mỗi trăm có 10 số có chữ số hàng chục là 4 (40 đến 49); từ 0 đến 1999 có 20 trăm nên có 20 × 10 = 200 số; từ 2000 đến 2014 không có.", "en": "Tens place: each hundred has 10 numbers with tens digit 4 (40 to 49); 0 to 1,999 has 20 hundreds, so 20 × 10 = 200; none in 2,000 to 2,014."}, {"vi": "Hàng trăm: các số 400 đến 499 và 1400 đến 1499, có 100 + 100 = 200 số. Hàng nghìn không có chữ số 4.", "en": "Hundreds place: 400 to 499 and 1,400 to 1,499, so 100 + 100 = 200. The thousands place has no 4."}, {"vi": "Tổng cộng 202 + 200 + 200 = 602 chữ số 4.", "en": "Total: 202 + 200 + 200 = 602 digits 4."}], "tip": {"vi": "Đếm riêng chữ số 4 ở hàng đơn vị, hàng chục, hàng trăm.", "en": "Count the 4s separately in the units, tens and hundreds places."}, "src": "250 bài, CĐ5, Bài 21"}, {"id": "cd5-b9a", "lesson": "digits", "rank": 2, "q": {"vi": "Viết các số tự nhiên liên tiếp từ 1 đến 1000. Hỏi phải dùng tất cả bao nhiêu chữ số?", "en": "Write the consecutive whole numbers from 1 to 1,000. How many digits are used in all?"}, "parts": [{"kind": "num", "lab": {"vi": "Số chữ số", "en": "Digits"}, "ans": 2893, "unit": {"vi": "chữ số", "en": "digits"}}], "steps": [{"vi": "Số có 1 chữ số (1 đến 9): 9 số, dùng 9 chữ số.", "en": "1-digit numbers (1 to 9): 9 numbers, 9 digits."}, {"vi": "Số có 2 chữ số (10 đến 99): 90 số, dùng 90 × 2 = 180 chữ số.", "en": "2-digit numbers (10 to 99): 90 numbers, 90 × 2 = 180 digits."}, {"vi": "Số có 3 chữ số (100 đến 999): 900 số, dùng 900 × 3 = 2700 chữ số; số 1000 có 4 chữ số.", "en": "3-digit numbers (100 to 999): 900 numbers, 900 × 3 = 2,700 digits; 1,000 has 4 digits."}, {"vi": "Tổng: 9 + 180 + 2700 + 4 = 2893.", "en": "Total: 9 + 180 + 2,700 + 4 = 2,893."}], "tip": {"vi": "Chia theo số có 1, 2, 3, 4 chữ số.", "en": "Split into 1-, 2-, 3- and 4-digit numbers."}, "src": "250 bài, CĐ5, Bài 9a"}, {"id": "l26-b12", "lesson": "digits", "rank": 2, "q": {"vi": "Để lập danh sách học sinh đăng kí dự thi toàn trường, người viết danh sách đã phải dùng 306 chữ số để ghi số báo danh từ 1 đến hết. Hỏi toàn trường có bao nhiêu học sinh đăng kí dự thi?", "en": "To make the list of students registered for a school-wide exam, the writer used 306 digits to write the candidate numbers from 1 to the end. How many students registered?"}, "parts": [{"kind": "num", "lab": {"vi": "Số học sinh", "en": "Students"}, "ans": 138, "unit": {"vi": "học sinh", "en": "students"}}], "steps": [{"vi": "Số báo danh 1 đến 99 dùng 9 + 180 = 189 chữ số.", "en": "Numbers 1 to 99 use 9 + 180 = 189 digits."}, {"vi": "Còn lại 306 − 189 = 117 chữ số cho các số có 3 chữ số: 117 : 3 = 39 số.", "en": "The remaining 306 − 189 = 117 digits are for 3-digit numbers: 117 ÷ 3 = 39 numbers."}, {"vi": "Số học sinh: 99 + 39 = 138.", "en": "Number of students: 99 + 39 = 138."}], "tip": {"vi": "Trừ đi số chữ số của các số từ 1 đến 99.", "en": "Subtract the digits used for 1 to 99."}, "src": "Lần 26, Bài 12"}, {"id": "l26-b5b", "lesson": "digits", "rank": 2, "q": {"vi": "Cho dãy số: 2; 4; 6; 8; …; 2022. Viết dãy số trên phải dùng tất cả bao nhiêu chữ số?", "en": "Given the sequence: 2, 4, 6, 8, …, 2,022. How many digits are used to write the whole sequence?"}, "parts": [{"kind": "num", "lab": {"vi": "Số chữ số", "en": "Digits"}, "ans": 3492, "unit": {"vi": "chữ số", "en": "digits"}}], "steps": [{"vi": "Số chẵn có 1 chữ số (2; 4; 6; 8): 4 số, dùng 4 chữ số. Số chẵn có 2 chữ số (10 đến 98): 45 số, dùng 90 chữ số.", "en": "1-digit evens (2, 4, 6, 8): 4 numbers, 4 digits. 2-digit evens (10 to 98): 45 numbers, 90 digits."}, {"vi": "Số chẵn có 3 chữ số (100 đến 998): 450 số, dùng 1350 chữ số.", "en": "3-digit evens (100 to 998): 450 numbers, 1,350 digits."}, {"vi": "Số chẵn có 4 chữ số (1000 đến 2022): (2022 − 1000) : 2 + 1 = 512 số, dùng 512 × 4 = 2048 chữ số.", "en": "4-digit evens (1,000 to 2,022): (2,022 − 1,000) ÷ 2 + 1 = 512 numbers, 512 × 4 = 2,048 digits."}, {"vi": "Tổng: 4 + 90 + 1350 + 2048 = 3492.", "en": "Total: 4 + 90 + 1,350 + 2,048 = 3,492."}], "tip": {"vi": "Chia các số chẵn theo số chữ số.", "en": "Group the even numbers by their number of digits."}, "src": "Lần 26, Bài 5b"}, {"id": "l26-b6b", "lesson": "digits", "rank": 2, "q": {"vi": "Cho dãy số: 1; 3; 5; 7; 9; …; 1999. Viết dãy số trên phải dùng tất cả bao nhiêu chữ số?", "en": "Given the sequence: 1, 3, 5, 7, 9, …, 1,999. How many digits are used to write the whole sequence?"}, "parts": [{"kind": "num", "lab": {"vi": "Số chữ số", "en": "Digits"}, "ans": 3445, "unit": {"vi": "chữ số", "en": "digits"}}], "steps": [{"vi": "Số lẻ có 1 chữ số (1 đến 9): 5 số, dùng 5 chữ số. Số lẻ có 2 chữ số (11 đến 99): 45 số, dùng 90 chữ số.", "en": "1-digit odds (1 to 9): 5 numbers, 5 digits. 2-digit odds (11 to 99): 45 numbers, 90 digits."}, {"vi": "Số lẻ có 3 chữ số (101 đến 999): 450 số, dùng 1350 chữ số.", "en": "3-digit odds (101 to 999): 450 numbers, 1,350 digits."}, {"vi": "Số lẻ có 4 chữ số (1001 đến 1999): 500 số, dùng 500 × 4 = 2000 chữ số.", "en": "4-digit odds (1,001 to 1,999): 500 numbers, 500 × 4 = 2,000 digits."}, {"vi": "Tổng: 5 + 90 + 1350 + 2000 = 3445.", "en": "Total: 5 + 90 + 1,350 + 2,000 = 3,445."}], "tip": {"vi": "Chia các số lẻ theo số chữ số.", "en": "Group the odd numbers by their number of digits."}, "src": "Lần 26, Bài 6b"}, {"id": "cd2-b10c", "lesson": "digits", "rank": 2, "q": {"vi": "Viết liền các số có 2 chữ số từ 20 đến 11 theo thứ tự từ lớn đến bé để được số 20191817161514131211. Xóa đi 12 chữ số của số đó và giữ nguyên thứ tự các chữ số còn lại để được số chẵn lớn nhất. Hãy tìm số đó.", "en": "Write the 2-digit numbers from 20 down to 11 one after another to get the number 20191817161514131211. Delete 12 digits and keep the order of the remaining digits to get the largest even number. Find that number."}, "parts": [{"kind": "num", "lab": {"vi": "Số chẵn lớn nhất", "en": "Largest even number"}, "ans": 98765432, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số đã cho có 20 chữ số, xóa 12 chữ số thì còn lại 8 chữ số.", "en": "The number has 20 digits; deleting 12 leaves 8 digits."}, {"vi": "Chữ số đầu tiên chọn lớn nhất trong 13 chữ số đầu (20 − 7 = 13): đó là 9.", "en": "For the first digit, pick the largest of the first 13 digits (20 − 7 = 13): it is 9."}, {"vi": "Cứ thế, mỗi lần chọn chữ số lớn nhất có thể ở bên phải chữ số vừa chọn, ta được 9, 8, 7, 6, 5, 4, 3, 2.", "en": "Keep picking the largest digit possible to the right of the last pick: 9, 8, 7, 6, 5, 4, 3, 2."}, {"vi": "Số lớn nhất là 98 765 432, tận cùng bằng 2 nên đó cũng là số chẵn lớn nhất.", "en": "The largest number is 98,765,432; it ends in 2, so it is also the largest even number."}], "tip": {"vi": "Trước hết tìm số lớn nhất, rồi xem nó có chẵn không.", "en": "First find the largest number, then check whether it is even."}, "src": "250 bài, CĐ2, Bài 10c"}, {"id": "cd2-b10d", "lesson": "digits", "rank": 2, "q": {"vi": "Viết liền các số có 2 chữ số từ 20 đến 11 theo thứ tự từ lớn đến bé để được số 20191817161514131211. Xóa đi 12 chữ số của số đó và giữ nguyên thứ tự các chữ số còn lại để được số lẻ nhỏ nhất (chữ số đầu tiên khác 0). Hãy tìm số đó.", "en": "Write the 2-digit numbers from 20 down to 11 one after another to get the number 20191817161514131211. Delete 12 digits and keep the order of the remaining digits to get the smallest odd number (its first digit must not be 0). Find that number."}, "parts": [{"kind": "num", "lab": {"vi": "Số lẻ nhỏ nhất", "en": "Smallest odd number"}, "ans": 11111111, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số đã cho có 20 chữ số; xóa 12 chữ số thì còn lại 8 chữ số.", "en": "The number has 20 digits; deleting 12 leaves 8 digits."}, {"vi": "Chữ số đầu khác 0 nên nhỏ nhất là 1. Trong số đã cho có 10 chữ số 1.", "en": "The first digit is not 0, so the smallest it can be is 1. The number contains ten 1s."}, {"vi": "Giữ lại 8 chữ số 1, xóa 12 chữ số còn lại, được 11 111 111. Không thể có số 8 chữ số nào nhỏ hơn vì chữ số nhỏ nhất ở mọi hàng đã là 1.", "en": "Keep eight 1s and delete the other 12 digits to get 11,111,111. No 8-digit number can be smaller, since every place already has the smallest allowed digit 1."}, {"vi": "Số này tận cùng bằng 1 nên là số lẻ, vậy đó là số lẻ nhỏ nhất.", "en": "It ends in 1, so it is odd; it is the smallest odd number."}], "tip": {"vi": "Trong số đã cho có bao nhiêu chữ số 1?", "en": "How many 1s are there in the given number?"}, "src": "250 bài, CĐ2, Bài 10d"}, {"id": "cd5-b12", "lesson": "digits", "rank": 3, "q": {"vi": "Viết liên tiếp các số tự nhiên 1; 2; 3; 4; 5; … thành một số: 123456789101112… Viết đến khi được một số có 2012 chữ số. Chữ số hàng đơn vị của số đó bằng bao nhiêu?", "en": "Write the whole numbers 1, 2, 3, 4, 5, … one after another to make one long number: 123456789101112… Stop when the number has 2,012 digits. What is the units digit of that number?"}, "parts": [{"kind": "num", "lab": {"vi": "Chữ số hàng đơn vị", "en": "Units digit"}, "ans": 0, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Các số có 1 chữ số và 2 chữ số dùng 9 + 180 = 189 chữ số.", "en": "The 1-digit and 2-digit numbers use 9 + 180 = 189 digits."}, {"vi": "Còn lại 2012 − 189 = 1823 chữ số dành cho số có 3 chữ số.", "en": "The remaining 2,012 − 189 = 1,823 digits are for 3-digit numbers."}, {"vi": "1823 : 3 = 607 dư 2: viết được 607 số có 3 chữ số (từ 100 đến 706) và 2 chữ số đầu của số 707.", "en": "1,823 ÷ 3 = 607 remainder 2: we write 607 three-digit numbers (100 to 706) and the first 2 digits of 707."}, {"vi": "2 chữ số đầu của 707 là 7 và 0, nên chữ số cuối cùng là 0.", "en": "The first 2 digits of 707 are 7 and 0, so the last digit is 0."}], "tip": {"vi": "Chia số chữ số còn lại cho 3, chú ý số dư.", "en": "Divide the remaining digits by 3 and pay attention to the remainder."}, "src": "250 bài, CĐ5, Bài 12"}, {"id": "cd5-b13a", "lesson": "digits", "rank": 3, "q": {"vi": "Cho dãy số: 11; 14; 17; 20; … Viết liên tiếp các số của dãy thành một hàng chữ số: 11141720… Chữ số thứ 166 là chữ số nào?", "en": "Given the sequence: 11, 14, 17, 20, … Write the terms one after another as a row of digits: 11141720… Which digit is the 166th digit?"}, "parts": [{"kind": "num", "lab": {"vi": "Chữ số thứ 166", "en": "166th digit"}, "ans": 2, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số hạng có 2 chữ số: từ 11 đến 98, có (98 − 11) : 3 + 1 = 30 số, dùng 60 chữ số.", "en": "2-digit terms: 11 to 98, (98 − 11) ÷ 3 + 1 = 30 terms, 60 digits."}, {"vi": "Còn lại 166 − 60 = 106 chữ số dành cho số hạng có 3 chữ số (101; 104; 107; …).", "en": "The remaining 166 − 60 = 106 digits are for 3-digit terms (101, 104, 107, …)."}, {"vi": "106 : 3 = 35 dư 1: viết đủ 35 số, rồi chữ số đầu tiên của số hạng tiếp theo.", "en": "106 ÷ 3 = 35 remainder 1: 35 full terms, then the first digit of the next term."}, {"vi": "Số hạng thứ 36 trong nhóm 3 chữ số là 101 + 35 × 3 = 206, chữ số đầu là 2.", "en": "The 36th three-digit term is 101 + 35 × 3 = 206, and its first digit is 2."}], "tip": {"vi": "Đếm số chữ số của các số hạng có 2 chữ số trước.", "en": "First count the digits of the 2-digit terms."}, "src": "250 bài, CĐ5, Bài 13a"}, {"id": "cd5-b14b", "lesson": "digits", "rank": 3, "q": {"vi": "Cho dãy các số tự nhiên liên tiếp: 1; 2; 3; 4; 5; …; 2013. Khi viết dãy trên có tất cả bao nhiêu chữ số 5? Bao nhiêu chữ số 1? Bao nhiêu chữ số 0?", "en": "Given the consecutive whole numbers 1, 2, 3, 4, 5, …, 2,013. When writing them all, how many digits 5 are used? How many digits 1? How many digits 0?"}, "parts": [{"kind": "num", "lab": {"vi": "Số chữ số 5", "en": "Number of 5s"}, "ans": 601, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số chữ số 1", "en": "Number of 1s"}, "ans": 1606, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số chữ số 0", "en": "Number of 0s"}, "ans": 515, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Từ 1 đến 999 (coi mỗi số có 3 chữ số, thêm 0 ở đầu): mỗi hàng có 100 lần mỗi chữ số 1 đến 9 nên chữ số 5 xuất hiện 3 × 100 = 300 lần và chữ số 1 xuất hiện 300 lần.", "en": "From 1 to 999 (think of each as 3 digits, with leading zeros): in each place every digit appears 100 times, so digit 5 appears 3 × 100 = 300 times and digit 1 appears 300 times."}, {"vi": "Từ 1000 đến 1999: chữ số 1 ở hàng nghìn có 1000 lần, cộng 300 lần ở ba hàng còn lại; chữ số 5 có 300 lần.", "en": "From 1,000 to 1,999: digit 1 in the thousands place appears 1,000 times, plus 300 times in the other three places; digit 5 appears 300 times."}, {"vi": "Từ 2000 đến 2013 (14 số): chữ số 1 xuất hiện 6 lần (2001: 1; 2010: 1; 2011: 2; 2012: 1; 2013: 1); chữ số 5 xuất hiện 1 lần (số 2005).", "en": "From 2,000 to 2,013 (14 numbers): digit 1 appears 6 times (2,001: 1; 2,010: 1; 2,011: 2; 2,012: 1; 2,013: 1); digit 5 appears once (in 2,005)."}, {"vi": "Chữ số 5: 300 + 300 + 1 = 601. Chữ số 1: 300 + 1300 + 6 = 1606. Chữ số 0: từ 1 đến 999 có 99 + 90 = 189 lần; từ 1000 đến 1999 có 300 lần; từ 2000 đến 2013 có 26 lần; tổng 515.", "en": "Digit 5: 300 + 300 + 1 = 601. Digit 1: 300 + 1,300 + 6 = 1,606. Digit 0: 99 + 90 = 189 times from 1 to 999; 300 times from 1,000 to 1,999; 26 times from 2,000 to 2,013; total 515."}], "tip": {"vi": "Đếm số lần xuất hiện của từng chữ số theo từng hàng.", "en": "Count how often each digit appears, one place at a time."}, "src": "250 bài, CĐ5, Bài 14b"}, {"id": "cd5-b18", "lesson": "digits", "rank": 3, "q": {"vi": "Người ta viết liền nhau dãy các số tự nhiên chẵn liên tiếp: 24681012141618202224… Hỏi chữ số thứ 2000 của dãy trên là chữ số nào?", "en": "The consecutive even numbers are written one after another: 24681012141618202224… Which digit is the 2,000th digit?"}, "parts": [{"kind": "num", "lab": {"vi": "Chữ số thứ 2000", "en": "2,000th digit"}, "ans": 6, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số chẵn có 1 chữ số (2; 4; 6; 8): 4 số, dùng 4 chữ số. Số chẵn có 2 chữ số (10 đến 98): 45 số, dùng 90 chữ số.", "en": "1-digit evens (2, 4, 6, 8): 4 numbers, 4 digits. 2-digit evens (10 to 98): 45 numbers, 90 digits."}, {"vi": "Số chẵn có 3 chữ số (100 đến 998): 450 số, dùng 1350 chữ số. Tổng đến đây: 4 + 90 + 1350 = 1444 chữ số.", "en": "3-digit evens (100 to 998): 450 numbers, 1,350 digits. So far: 4 + 90 + 1,350 = 1,444 digits."}, {"vi": "Còn lại 2000 − 1444 = 556 chữ số dành cho số chẵn có 4 chữ số: 556 : 4 = 139 số, không dư.", "en": "The remaining 2,000 − 1,444 = 556 digits are for 4-digit evens: 556 ÷ 4 = 139 numbers, no remainder."}, {"vi": "Số thứ 139 là 1000 + 138 × 2 = 1276, chữ số thứ 2000 là chữ số cuối của 1276, tức là 6.", "en": "The 139th is 1,000 + 138 × 2 = 1,276, and the 2,000th digit is the last digit of 1,276, which is 6."}], "tip": {"vi": "Trừ dần số chữ số của các nhóm số chẵn 1, 2, 3 chữ số.", "en": "Subtract the digits of the 1-, 2- and 3-digit even groups in turn."}, "src": "250 bài, CĐ5, Bài 18"}, {"id": "cd5-b20", "lesson": "digits", "rank": 3, "q": {"vi": "Tính tổng các chữ số của dãy số liên tiếp 5; 6; 7; 8; …; 2004; 2005.", "en": "Find the sum of all the digits of the consecutive numbers 5, 6, 7, 8, …, 2,004, 2,005."}, "parts": [{"kind": "num", "lab": {"vi": "Tổng các chữ số", "en": "Sum of the digits"}, "ans": 28017, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Xét các số từ 0 đến 999 (viết đủ 3 chữ số): mỗi hàng có chữ số 0 đến 9 mỗi chữ số 100 lần, tổng các chữ số mỗi hàng là 45 × 100 = 4500; ba hàng là 13 500.", "en": "Consider 0 to 999 (written with 3 digits): in each place each digit 0–9 appears 100 times, so each place sums to 45 × 100 = 4,500; three places give 13,500."}, {"vi": "Các số 1000 đến 1999: hàng nghìn là 1000 chữ số 1 (tổng 1000) và ba hàng còn lại 13 500, được 14 500.", "en": "Numbers 1,000 to 1,999: the thousands place gives 1,000 ones (sum 1,000) and the other three places 13,500, total 14,500."}, {"vi": "Các số 2000 đến 2005: tổng chữ số là 6 × 2 + (0 + 1 + 2 + 3 + 4 + 5) = 27.", "en": "Numbers 2,000 to 2,005: digit sum is 6 × 2 + (0 + 1 + 2 + 3 + 4 + 5) = 27."}, {"vi": "Tổng từ 0 đến 2005 là 13 500 + 14 500 + 27 = 28 027. Bỏ các số 0 đến 4 (tổng chữ số 0 + 1 + 2 + 3 + 4 = 10): 28 017.", "en": "The total from 0 to 2,005 is 13,500 + 14,500 + 27 = 28,027. Remove 0 to 4 (digit sum 0 + 1 + 2 + 3 + 4 = 10): 28,017."}], "tip": {"vi": "Chia thành các nhóm 0–999, 1000–1999, 2000–2005.", "en": "Split into groups 0–999, 1,000–1,999, 2,000–2,005."}, "src": "250 bài, CĐ5, Bài 20"}, {"id": "cd5-b22b", "lesson": "digits", "rank": 3, "q": {"vi": "Viết các số tự nhiên liên tiếp liền nhau để tạo thành số có nhiều chữ số: 123456789101112131415… Bắt đầu từ chữ số thứ bao nhiêu thì lần đầu tiên xuất hiện 5 chữ số 2 liền nhau?", "en": "Write the whole numbers one after another to make a long number: 123456789101112131415… Starting at which digit position do five 2s in a row appear for the first time?"}, "parts": [{"kind": "num", "lab": {"vi": "Chữ số thứ", "en": "Digit position"}, "ans": 556, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Năm chữ số 2 liền nhau đầu tiên là 22222 nằm ở chỗ nối hai số 222 và 223 (…222 223…): ba chữ số 2 của số 222 và hai chữ số 2 đầu của số 223 (kiểm tra các số nhỏ hơn thì không có chỗ nào có 5 chữ số 2 liền nhau).", "en": "The first run of five 2s, 22222, comes where 222 and 223 meet (…222 223…): the three 2s of 222 and the first two 2s of 223. Checking smaller numbers, no earlier place has five 2s in a row."}, {"vi": "Các số từ 1 đến 9 dùng 9 chữ số; từ 10 đến 99 có 90 số, dùng 90 × 2 = 180 chữ số.", "en": "Numbers 1 to 9 use 9 digits; 10 to 99 are 90 numbers and use 90 × 2 = 180 digits."}, {"vi": "Các số từ 100 đến 221 có 122 số, dùng 122 × 3 = 366 chữ số.", "en": "Numbers 100 to 221 are 122 numbers and use 122 × 3 = 366 digits."}, {"vi": "Trước số 222 có 9 + 180 + 366 = 555 chữ số, nên số 222 bắt đầu từ chữ số thứ 556.", "en": "Before 222 there are 9 + 180 + 366 = 555 digits, so 222 starts at digit number 556."}], "tip": {"vi": "Tìm hai số liền nhau tạo ra 22222, rồi đếm số chữ số đứng trước chúng.", "en": "Find the two neighboring numbers that make 22222, then count the digits before them."}, "src": "250 bài, CĐ5, Bài 22b"}, {"id": "cd5-b9b", "lesson": "digits", "rank": 3, "q": {"vi": "Viết các số chẵn liên tiếp từ 0 đến 2014. Hỏi phải dùng tất cả bao nhiêu chữ số?", "en": "Write the consecutive even numbers from 0 to 2,014. How many digits are used in all?"}, "parts": [{"kind": "num", "lab": {"vi": "Số chữ số", "en": "Digits"}, "ans": 3477, "unit": {"vi": "chữ số", "en": "digits"}}], "steps": [{"vi": "Số 0 và các số chẵn có 1 chữ số (2; 4; 6; 8): 1 + 4 = 5 số, dùng 5 chữ số.", "en": "The number 0 and the 1-digit evens (2, 4, 6, 8): 1 + 4 = 5 numbers, 5 digits."}, {"vi": "Số chẵn có 2 chữ số (10 đến 98): (98 − 10) : 2 + 1 = 45 số, dùng 90 chữ số.", "en": "2-digit evens (10 to 98): (98 − 10) ÷ 2 + 1 = 45 numbers, 90 digits."}, {"vi": "Số chẵn có 3 chữ số (100 đến 998): (998 − 100) : 2 + 1 = 450 số, dùng 1350 chữ số.", "en": "3-digit evens (100 to 998): (998 − 100) ÷ 2 + 1 = 450 numbers, 1,350 digits."}, {"vi": "Số chẵn có 4 chữ số (1000 đến 2014): (2014 − 1000) : 2 + 1 = 508 số, dùng 508 × 4 = 2032 chữ số.", "en": "4-digit evens (1,000 to 2,014): (2,014 − 1,000) ÷ 2 + 1 = 508 numbers, 508 × 4 = 2,032 digits."}, {"vi": "Tổng: 5 + 90 + 1350 + 2032 = 3477.", "en": "Total: 5 + 90 + 1,350 + 2,032 = 3,477."}], "tip": {"vi": "Đếm số chẵn trong từng nhóm theo số chữ số.", "en": "Count the even numbers in each digit-length group."}, "src": "250 bài, CĐ5, Bài 9b"}, {"id": "l26-b13", "lesson": "digits", "rank": 3, "q": {"vi": "Để đánh số trang của một cuốn sách, trung bình mỗi trang phải dùng 2 chữ số. Hỏi cuốn sách đó có bao nhiêu trang?", "en": "To number the pages of a book, each page needs 2 digits on average. How many pages does the book have?"}, "parts": [{"kind": "num", "lab": {"vi": "Số trang", "en": "Pages"}, "ans": 108, "unit": {"vi": "trang", "en": "pages"}}], "steps": [{"vi": "Trang 1 đến 99 dùng 189 chữ số; nếu mỗi trang trung bình 2 chữ số thì 99 trang chỉ cần 99 × 2 = 198 chữ số, nghĩa là 189 chữ số ít hơn 198 chữ số: 9 chữ số.", "en": "Pages 1 to 99 use 189 digits; at 2 digits per page 99 pages would need 99 × 2 = 198 digits, so 189 digits is 9 fewer than 198."}, {"vi": "Sách phải có trang 3 chữ số. Mỗi trang 3 chữ số dùng nhiều hơn mức trung bình 3 − 2 = 1 chữ số.", "en": "The book must have 3-digit pages. Each 3-digit page uses 3 − 2 = 1 digit more than the average."}, {"vi": "Để bù 9 chữ số thiếu ở phần trước cần 9 : 1 = 9 trang có 3 chữ số.", "en": "To make up the 9-digit shortfall we need 9 ÷ 1 = 9 three-digit pages."}, {"vi": "Số trang: 99 + 9 = 108.", "en": "Number of pages: 99 + 9 = 108."}], "tip": {"vi": "Trang 1 đến 99 dùng ít hơn 2 chữ số mỗi trang; bù lại bằng trang 3 chữ số.", "en": "Pages 1 to 99 use fewer than 2 digits per page; the 3-digit pages make up the difference."}, "src": "Lần 26, Bài 13"}, {"id": "l26-b6d", "lesson": "digits", "rank": 3, "q": {"vi": "Viết liên tiếp các số của dãy 1; 3; 5; 7; 9; …; 1999 thành một hàng chữ số: 13579111315… Tìm chữ số thứ 3000 của hàng.", "en": "Write the terms of the sequence 1, 3, 5, 7, 9, …, 1,999 one after another as a row of digits: 13579111315… Find the 3,000th digit."}, "parts": [{"kind": "num", "lab": {"vi": "Chữ số thứ 3000", "en": "3,000th digit"}, "ans": 7, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số lẻ có 1 chữ số: 5 số, 5 chữ số; số lẻ có 2 chữ số: 45 số, 90 chữ số; số lẻ có 3 chữ số: 450 số, 1350 chữ số. Tổng: 5 + 90 + 1350 = 1445 chữ số.", "en": "1-digit odds: 5 numbers, 5 digits; 2-digit odds: 45 numbers, 90 digits; 3-digit odds: 450 numbers, 1,350 digits. Total: 5 + 90 + 1,350 = 1,445 digits."}, {"vi": "Còn lại 3000 − 1445 = 1555 chữ số cho số lẻ có 4 chữ số.", "en": "The remaining 3,000 − 1,445 = 1,555 digits are for 4-digit odds."}, {"vi": "1555 : 4 = 388 dư 3: viết đủ 388 số (từ 1001 đến 1775) rồi 3 chữ số đầu của số tiếp theo.", "en": "1,555 ÷ 4 = 388 remainder 3: 388 full numbers (1,001 to 1,775), then the first 3 digits of the next one."}, {"vi": "Số tiếp theo là 1001 + 388 × 2 = 1777, chữ số thứ ba của nó là 7.", "en": "The next number is 1,001 + 388 × 2 = 1,777, and its third digit is 7."}], "tip": {"vi": "Trừ đi số chữ số của các số lẻ có 1, 2, 3 chữ số.", "en": "Subtract the digits of the 1-, 2- and 3-digit odd numbers."}, "src": "Lần 26, Bài 6d"}, {"id": "cd2-b9", "lesson": "digits", "rank": 3, "q": {"vi": "Viết liền các số tự nhiên từ 1 đến 15 theo thứ tự từ bé đến lớn để được một số có nhiều chữ số: 123456789101112131415. Xóa đi 8 chữ số của số đó và giữ nguyên thứ tự các chữ số còn lại để được số lớn nhất (và, làm riêng, số nhỏ nhất có chữ số đầu khác 0). Hãy tìm hai số đó.", "en": "Write the whole numbers from 1 to 15 one after another, from smallest to largest, to get a long number: 123456789101112131415. Delete 8 digits and keep the order of the remaining digits to get the largest number (and, separately, the smallest number whose first digit is not 0). Find both numbers."}, "parts": [{"kind": "num", "lab": {"vi": "Số lớn nhất", "en": "Largest number"}, "ans": 9101112131415, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số nhỏ nhất", "en": "Smallest number"}, "ans": 1101112131415, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số đã cho có 9 + 6 × 2 = 21 chữ số; xóa 8 chữ số còn lại 13 chữ số.", "en": "The number has 9 + 6 × 2 = 21 digits; after deleting 8 digits, 13 digits remain."}, {"vi": "Lớn nhất: xóa 8 chữ số 1, 2, 3, 4, 5, 6, 7, 8 để chữ số đầu là 9. Còn lại 9 101 112 131 415.", "en": "Largest: delete the 8 digits 1, 2, 3, 4, 5, 6, 7, 8 so the first digit is 9. What remains is 9,101,112,131,415."}, {"vi": "Nhỏ nhất: giữ chữ số 1 đầu tiên rồi xóa 2, 3, 4, 5, 6, 7, 8, 9 để tiếp theo là 1, 0 của số 10. Còn lại 1 101 112 131 415.", "en": "Smallest: keep the first digit 1 and delete 2, 3, 4, 5, 6, 7, 8, 9 so that 1, 0 of the number 10 follow. What remains is 1,101,112,131,415."}], "tip": {"vi": "Đếm tổng số chữ số rồi xem còn lại bao nhiêu chữ số.", "en": "Count all the digits, then see how many remain."}, "src": "250 bài, CĐ2, Bài 9"}, {"id": "cd2-b10", "lesson": "digits", "rank": 3, "q": {"vi": "Viết liền các số có 2 chữ số từ 20 đến 11 theo thứ tự từ lớn đến bé để được một số có nhiều chữ số: 201918…1211. Xóa đi 12 chữ số của số đó và giữ nguyên thứ tự các chữ số còn lại để được số lớn nhất (và, làm riêng, số nhỏ nhất có chữ số đầu khác 0). Hãy tìm hai số đó.", "en": "Write the 2-digit numbers from 20 down to 11 one after another, from largest to smallest, to get a long number: 201918…1211. Delete 12 digits and keep the order of the remaining digits to get the largest number (and, separately, the smallest number whose first digit is not 0). Find both numbers."}, "parts": [{"kind": "num", "lab": {"vi": "Số lớn nhất", "en": "Largest number"}, "ans": 98765432, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số nhỏ nhất", "en": "Smallest number"}, "ans": 11111111, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số đã cho có 10 × 2 = 20 chữ số; xóa 12 chữ số còn lại 8 chữ số.", "en": "The number has 10 × 2 = 20 digits; after deleting 12 digits, 8 digits remain."}, {"vi": "Lớn nhất: giữ các chữ số 9, 8, 7, 6, 5, 4, 3, 2 (lần lượt nằm trong 19, 18, 17, …, 12). Được 98 765 432.", "en": "Largest: keep the digits 9, 8, 7, 6, 5, 4, 3, 2 (found in 19, 18, 17, …, 12 in that order). This gives 98,765,432."}, {"vi": "Nhỏ nhất: trong số có đúng 10 chữ số 1; giữ 8 chữ số 1 (không xếp 0 lên đầu và không có chữ số nào nhỏ hơn 1 để đứng đầu). Được 11 111 111.", "en": "Smallest: the number has exactly ten digits 1; keep eight 1s (0 cannot be first, and no digit is smaller than 1 to start). This gives 11,111,111."}], "tip": {"vi": "Số lớn nhất bắt đầu bằng chữ số 9.", "en": "The largest number starts with the digit 9."}, "src": "250 bài, CĐ2, Bài 10"}, {"id": "cd2-b8", "lesson": "digits", "rank": 3, "q": {"vi": "Viết số tự nhiên N gồm 6 số chẵn liên tiếp kể từ 12 (12; 14; 16; 18; 20; 22 viết liền nhau). Xóa bớt 6 chữ số của N để còn lại số lớn nhất, và (làm riêng) để còn lại số bé nhất (chữ số đầu khác 0). Hãy tìm hai số đó.", "en": "Write the whole number N made from 6 consecutive even numbers starting from 12 (12; 14; 16; 18; 20; 22 written one after another). Delete 6 digits of N to leave the largest possible number, and (separately) the smallest possible number (first digit not 0). Find both numbers."}, "parts": [{"kind": "num", "lab": {"vi": "Số lớn nhất", "en": "Largest number"}, "ans": 682022, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số bé nhất", "en": "Smallest number"}, "ans": 111022, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "N = 121 416 182 022 có 12 chữ số, sau khi xóa 6 chữ số còn lại 6 chữ số, giữ nguyên thứ tự.", "en": "N = 121,416,182,022 has 12 digits; after deleting 6 digits, 6 digits remain in the same order."}, {"vi": "Lớn nhất: chữ số đầu chọn lớn nhất trong 7 chữ số đầu 1214161 là 6; chữ số tiếp theo lớn nhất trong 1 và 8 là 8; bốn chữ số cuối 2022 giữ nguyên. Được 682 022.", "en": "Largest: the first digit is the biggest of the first 7 digits 1214161, which is 6; the next is the biggest of 1 and 8, which is 8; keep the last four digits 2022. This gives 682,022."}, {"vi": "Bé nhất: chữ số đầu (khác 0) bé nhất là 1; chọn tiếp các chữ số 1, 1, rồi chữ số 0 ở gần cuối và giữ 2, 2. Được 111 022.", "en": "Smallest: the first digit (not 0) is the smallest, 1; then pick 1, 1, then the 0 near the end and keep 2, 2. This gives 111,022."}], "tip": {"vi": "Để số lớn nhất, ưu tiên chữ số lớn ở hàng cao nhất mà vẫn đủ chữ số.", "en": "For the largest number, put the biggest digit in the highest place while keeping enough digits."}, "src": "250 bài, CĐ2, Bài 8"}, {"id": "cd2-b11b", "lesson": "digits", "rank": 3, "q": {"vi": "Số 200020012002…20142015 (viết liền các số từ 2000 đến 2015) có 64 chữ số. Xóa đi 20 chữ số của số đó và giữ nguyên thứ tự các chữ số còn lại để được số lớn nhất và, làm riêng, số nhỏ nhất (chữ số đầu khác 0). Hãy tìm tổng các chữ số của mỗi số đó.", "en": "The number 200020012002…20142015 (the numbers from 2,000 to 2,015 written one after another) has 64 digits. Delete 20 digits and keep the order of the remaining digits to get the largest number and, separately, the smallest number (its first digit must not be 0). Find the sum of the digits of each of these two numbers."}, "parts": [{"kind": "num", "lab": {"vi": "Tổng chữ số, số lớn nhất", "en": "Digit sum, largest number"}, "ans": 82, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Tổng chữ số, số nhỏ nhất", "en": "Digit sum, smallest number"}, "ans": 53, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Còn lại 64 − 20 = 44 chữ số.", "en": "64 − 20 = 44 digits remain."}, {"vi": "Số lớn nhất: chữ số đầu là chữ số lớn nhất trong 21 chữ số đầu, đó là 4 (của số 2004), xóa 19 chữ số đứng trước nó. Còn xóa 1 chữ số: xóa một chữ số 0 của số 2005 để chữ số 5 đứng lên trước. Ta được 42052006…2015.", "en": "Largest: the first digit is the largest of the first 21 digits, which is 4 (from 2004), so delete the 19 digits before it. One more digit to delete: delete a 0 of 2005 so the 5 moves up. We get 42052006…2015."}, {"vi": "Số nhỏ nhất: chữ số đầu khác 0 nhỏ nhất là 1 (của số 2001), xóa 7 chữ số trước nó. Sau đó giữ 14 chữ số 0 của các số 2002 đến 2008 và xóa 13 chữ số khác 0 xen giữa, giữ lại chữ số 8. Ta được 1 000 000 000 000 008 2009…2015 (1, mười bốn chữ số 0, rồi 8 2009 2010 … 2015).", "en": "Smallest: the smallest non-zero first digit is 1 (from 2001), so delete the 7 digits before it. Then keep the 14 zeros of 2002 to 2008 and delete 13 of the non-zero digits between them, keeping the 8. We get 1, fourteen 0s, then 8 2009 2010 … 2015."}, {"vi": "Tổng chữ số số lớn nhất: 82. Tổng chữ số số nhỏ nhất: 53.", "en": "Digit sum of the largest: 82. Digit sum of the smallest: 53."}], "tip": {"vi": "Mỗi lần chọn chữ số tốt nhất trong các chữ số còn được phép chọn.", "en": "Each time, pick the best digit among those still allowed."}, "src": "250 bài, CĐ2, Bài 11b"}], "mul": [{"id": "l26-b1a", "lesson": "mul", "rank": 1, "q": {"vi": "Đặt tính rồi tính: 3568 × 987", "en": "Write in columns and calculate: 3,568 × 987"}, "parts": [{"kind": "num", "lab": {"vi": "Tích", "en": "Product"}, "ans": 3521616, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Nhân 3568 lần lượt với từng chữ số của 987 (từ phải sang trái) rồi viết các tích riêng lùi dần sang trái.", "en": "Multiply 3,568 by each digit of 987 from right to left, shifting each partial product one place to the left."}, {"vi": "Tích riêng thứ nhất: 3568 × 7 = 24 976; thứ hai (hàng chục): 3568 × 8 = 28 544; thứ ba (hàng trăm): 3568 × 9 = 32 112.", "en": "First partial product: 3,568 × 7 = 24,976; second (tens): 3,568 × 8 = 28,544; third (hundreds): 3,568 × 9 = 32,112."}, {"vi": "Cộng các tích riêng: 24 976 + 285 440 + 3 211 200 = 3 521 616.", "en": "Add the partial products: 24,976 + 285,440 + 3,211,200 = 3,521,616."}], "tip": {"vi": "Nhân với từng chữ số của số nhân, nhớ lùi hàng.", "en": "Multiply by each digit of the second factor and shift each row."}, "src": "LẦN 26, Bài 1"}, {"id": "l26-b1b", "lesson": "mul", "rank": 2, "q": {"vi": "Đặt tính rồi tính: 7896 × 657", "en": "Write in columns and calculate: 7,896 × 657"}, "parts": [{"kind": "num", "lab": {"vi": "Tích", "en": "Product"}, "ans": 5187672, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Nhân 7896 lần lượt với từng chữ số của 657 (từ phải sang trái) rồi viết các tích riêng lùi dần sang trái.", "en": "Multiply 7,896 by each digit of 657 from right to left, shifting each partial product one place to the left."}, {"vi": "Tích riêng thứ nhất: 7896 × 7 = 55 272; thứ hai (hàng chục): 7896 × 5 = 39 480; thứ ba (hàng trăm): 7896 × 6 = 47 376.", "en": "First partial product: 7,896 × 7 = 55,272; second (tens): 7,896 × 5 = 39,480; third (hundreds): 7,896 × 6 = 47,376."}, {"vi": "Cộng các tích riêng: 55 272 + 394 800 + 4 737 600 = 5 187 672.", "en": "Add the partial products: 55,272 + 394,800 + 4,737,600 = 5,187,672."}], "tip": {"vi": "Nhân với từng chữ số của số nhân, nhớ lùi hàng.", "en": "Multiply by each digit of the second factor and shift each row."}, "src": "LẦN 26, Bài 1"}], "div": [{"id": "l26-b1c", "lesson": "div", "rank": 1, "q": {"vi": "Đặt tính rồi tính: 410 025 : 75", "en": "Write in columns and calculate: 410,025 ÷ 75"}, "parts": [{"kind": "num", "lab": {"vi": "Thương", "en": "Quotient"}, "ans": 5467, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Chia lần lượt từng nhóm chữ số của 410 025 cho 75, hạ chữ số tiếp theo sau mỗi lần.", "en": "Divide the digits of 410,025 by 75 group by group, bringing down the next digit each time."}, {"vi": "Các bước: 410 : 75 = 5 dư 35; 350 : 75 = 4 dư 50; 502 : 75 = 6 dư 52; 525 : 75 = 7 dư 0.", "en": "Steps: 410 ÷ 75 = 5 r 35; 350 ÷ 75 = 4 r 50; 502 ÷ 75 = 6 r 52; 525 ÷ 75 = 7 r 0."}, {"vi": "Thương là 5467 (chia hết). Thử lại: 5467 × 75 = 410 025.", "en": "The quotient is 5,467 (exact division). Check: 5,467 × 75 = 410,025."}], "tip": {"vi": "Mỗi lần chia, số dư phải bé hơn số chia.", "en": "Each time you divide, the remainder must be less than the divisor."}, "src": "LẦN 26, Bài 1"}, {"id": "l26-b1d", "lesson": "div", "rank": 1, "q": {"vi": "Đặt tính rồi tính: 596 733 : 87", "en": "Write in columns and calculate: 596,733 ÷ 87"}, "parts": [{"kind": "num", "lab": {"vi": "Thương", "en": "Quotient"}, "ans": 6859, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Chia lần lượt từng nhóm chữ số của 596 733 cho 87, hạ chữ số tiếp theo sau mỗi lần.", "en": "Divide the digits of 596,733 by 87 group by group, bringing down the next digit each time."}, {"vi": "Các bước: 596 : 87 = 6 dư 74; 747 : 87 = 8 dư 51; 513 : 87 = 5 dư 78; 783 : 87 = 9 dư 0.", "en": "Steps: 596 ÷ 87 = 6 r 74; 747 ÷ 87 = 8 r 51; 513 ÷ 87 = 5 r 78; 783 ÷ 87 = 9 r 0."}, {"vi": "Thương là 6859 (chia hết). Thử lại: 6859 × 87 = 596 733.", "en": "The quotient is 6,859 (exact division). Check: 6,859 × 87 = 596,733."}], "tip": {"vi": "Mỗi lần chia, số dư phải bé hơn số chia.", "en": "Each time you divide, the remainder must be less than the divisor."}, "src": "LẦN 26, Bài 1"}, {"id": "l26-b1e", "lesson": "div", "rank": 1, "q": {"vi": "Đặt tính rồi tính: 244 818 : 67", "en": "Write in columns and calculate: 244,818 ÷ 67"}, "parts": [{"kind": "num", "lab": {"vi": "Thương", "en": "Quotient"}, "ans": 3654, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Chia lần lượt từng nhóm chữ số của 244 818 cho 67, hạ chữ số tiếp theo sau mỗi lần.", "en": "Divide the digits of 244,818 by 67 group by group, bringing down the next digit each time."}, {"vi": "Các bước: 244 : 67 = 3 dư 43; 438 : 67 = 6 dư 36; 361 : 67 = 5 dư 26; 268 : 67 = 4 dư 0.", "en": "Steps: 244 ÷ 67 = 3 r 43; 438 ÷ 67 = 6 r 36; 361 ÷ 67 = 5 r 26; 268 ÷ 67 = 4 r 0."}, {"vi": "Thương là 3654 (chia hết). Thử lại: 3654 × 67 = 244 818.", "en": "The quotient is 3,654 (exact division). Check: 3,654 × 67 = 244,818."}], "tip": {"vi": "Mỗi lần chia, số dư phải bé hơn số chia.", "en": "Each time you divide, the remainder must be less than the divisor."}, "src": "LẦN 26, Bài 1"}, {"id": "l26-b1f", "lesson": "div", "rank": 2, "q": {"vi": "Đặt tính rồi tính: 195 225 : 57", "en": "Write in columns and calculate: 195,225 ÷ 57"}, "parts": [{"kind": "num", "lab": {"vi": "Thương", "en": "Quotient"}, "ans": 3425, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Chia lần lượt từng nhóm chữ số của 195 225 cho 57, hạ chữ số tiếp theo sau mỗi lần.", "en": "Divide the digits of 195,225 by 57 group by group, bringing down the next digit each time."}, {"vi": "Các bước: 195 : 57 = 3 dư 24; 242 : 57 = 4 dư 14; 142 : 57 = 2 dư 28; 285 : 57 = 5 dư 0.", "en": "Steps: 195 ÷ 57 = 3 r 24; 242 ÷ 57 = 4 r 14; 142 ÷ 57 = 2 r 28; 285 ÷ 57 = 5 r 0."}, {"vi": "Thương là 3425 (chia hết). Thử lại: 3425 × 57 = 195 225.", "en": "The quotient is 3,425 (exact division). Check: 3,425 × 57 = 195,225."}], "tip": {"vi": "Mỗi lần chia, số dư phải bé hơn số chia.", "en": "Each time you divide, the remainder must be less than the divisor."}, "src": "LẦN 26, Bài 1"}, {"id": "l26-b1g", "lesson": "div", "rank": 2, "q": {"vi": "Đặt tính rồi tính: 506 475 : 75", "en": "Write in columns and calculate: 506,475 ÷ 75"}, "parts": [{"kind": "num", "lab": {"vi": "Thương", "en": "Quotient"}, "ans": 6753, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Chia lần lượt từng nhóm chữ số của 506 475 cho 75, hạ chữ số tiếp theo sau mỗi lần.", "en": "Divide the digits of 506,475 by 75 group by group, bringing down the next digit each time."}, {"vi": "Các bước: 506 : 75 = 6 dư 56; 564 : 75 = 7 dư 39; 397 : 75 = 5 dư 22; 225 : 75 = 3 dư 0.", "en": "Steps: 506 ÷ 75 = 6 r 56; 564 ÷ 75 = 7 r 39; 397 ÷ 75 = 5 r 22; 225 ÷ 75 = 3 r 0."}, {"vi": "Thương là 6753 (chia hết). Thử lại: 6753 × 75 = 506 475.", "en": "The quotient is 6,753 (exact division). Check: 6,753 × 75 = 506,475."}], "tip": {"vi": "Mỗi lần chia, số dư phải bé hơn số chia.", "en": "Each time you divide, the remainder must be less than the divisor."}, "src": "LẦN 26, Bài 1"}, {"id": "l26-b1h", "lesson": "div", "rank": 2, "q": {"vi": "Đặt tính rồi tính: 373 230 : 58", "en": "Write in columns and calculate: 373,230 ÷ 58"}, "parts": [{"kind": "num", "lab": {"vi": "Thương", "en": "Quotient"}, "ans": 6435, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Chia lần lượt từng nhóm chữ số của 373 230 cho 58, hạ chữ số tiếp theo sau mỗi lần.", "en": "Divide the digits of 373,230 by 58 group by group, bringing down the next digit each time."}, {"vi": "Các bước: 373 : 58 = 6 dư 25; 252 : 58 = 4 dư 20; 203 : 58 = 3 dư 29; 290 : 58 = 5 dư 0.", "en": "Steps: 373 ÷ 58 = 6 r 25; 252 ÷ 58 = 4 r 20; 203 ÷ 58 = 3 r 29; 290 ÷ 58 = 5 r 0."}, {"vi": "Thương là 6435 (chia hết). Thử lại: 6435 × 58 = 373 230.", "en": "The quotient is 6,435 (exact division). Check: 6,435 × 58 = 373,230."}], "tip": {"vi": "Mỗi lần chia, số dư phải bé hơn số chia.", "en": "Each time you divide, the remainder must be less than the divisor."}, "src": "LẦN 26, Bài 1"}, {"id": "l26-b1i", "lesson": "div", "rank": 2, "q": {"vi": "Đặt tính rồi tính: 347 598 : 54", "en": "Write in columns and calculate: 347,598 ÷ 54"}, "parts": [{"kind": "num", "lab": {"vi": "Thương", "en": "Quotient"}, "ans": 6437, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Chia lần lượt từng nhóm chữ số của 347 598 cho 54, hạ chữ số tiếp theo sau mỗi lần.", "en": "Divide the digits of 347,598 by 54 group by group, bringing down the next digit each time."}, {"vi": "Các bước: 347 : 54 = 6 dư 23; 235 : 54 = 4 dư 19; 199 : 54 = 3 dư 37; 378 : 54 = 7 dư 0.", "en": "Steps: 347 ÷ 54 = 6 r 23; 235 ÷ 54 = 4 r 19; 199 ÷ 54 = 3 r 37; 378 ÷ 54 = 7 r 0."}, {"vi": "Thương là 6437 (chia hết). Thử lại: 6437 × 54 = 347 598.", "en": "The quotient is 6,437 (exact division). Check: 6,437 × 54 = 347,598."}], "tip": {"vi": "Mỗi lần chia, số dư phải bé hơn số chia.", "en": "Each time you divide, the remainder must be less than the divisor."}, "src": "LẦN 26, Bài 1"}, {"id": "l26-b1j", "lesson": "div", "rank": 2, "q": {"vi": "Đặt tính rồi tính: 391 671 : 58", "en": "Write in columns and calculate: 391,671 ÷ 58"}, "parts": [{"kind": "num", "lab": {"vi": "Thương", "en": "Quotient"}, "ans": 6752, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số dư", "en": "Remainder"}, "ans": 55, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Chia lần lượt từng nhóm chữ số của 391 671 cho 58, hạ chữ số tiếp theo sau mỗi lần.", "en": "Divide the digits of 391,671 by 58 group by group, bringing down the next digit each time."}, {"vi": "Các bước: 391 : 58 = 6 dư 43; 436 : 58 = 7 dư 30; 307 : 58 = 5 dư 17; 171 : 58 = 2 dư 55.", "en": "Steps: 391 ÷ 58 = 6 r 43; 436 ÷ 58 = 7 r 30; 307 ÷ 58 = 5 r 17; 171 ÷ 58 = 2 r 55."}, {"vi": "Thương là 6752, số dư là 55. Thử lại: 6752 × 58 + 55 = 391 671.", "en": "The quotient is 6,752, the remainder is 55. Check: 6,752 × 58 + 55 = 391,671."}], "tip": {"vi": "Mỗi lần chia, số dư phải bé hơn số chia.", "en": "Each time you divide, the remainder must be less than the divisor."}, "src": "LẦN 26, Bài 1"}, {"id": "l26-b2b", "lesson": "div", "rank": 2, "q": {"vi": "Tính giá trị biểu thức: 100 798 − 9894 : 34 × 23 − 23", "en": "Evaluate: 100,798 − 9,894 ÷ 34 × 23 − 23"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 94082, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Nhân, chia từ trái sang phải: 9894 : 34 = 291.", "en": "Multiply and divide from left to right: 9,894 ÷ 34 = 291."}, {"vi": "291 × 23 = 6693.", "en": "291 × 23 = 6,693."}, {"vi": "Cộng, trừ từ trái sang phải: 100 798 − 6693 = 94 105.", "en": "Subtract from left to right: 100,798 − 6,693 = 94,105."}, {"vi": "94 105 − 23 = 94 082.", "en": "94,105 − 23 = 94,082."}], "tip": {"vi": "Nhân, chia trước; cộng, trừ sau.", "en": "Multiply and divide first; then add and subtract."}, "src": "LẦN 26, Bài 2"}, {"id": "cd9-b13", "lesson": "div", "rank": 2, "q": {"vi": "Tìm số tự nhiên bé nhất sao cho khi chia số đó cho 3; 4; 5; 7 có số dư lần lượt là 1; 2; 3; 5.", "en": "Find the smallest natural number that leaves remainders 1, 2, 3 and 5 when divided by 3, 4, 5 and 7, respectively."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 418, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Ta thấy 3 − 1 = 4 − 2 = 5 − 3 = 7 − 5 = 2, nên thêm 2 vào số đó thì chia hết cho cả 3, 4, 5, 7.", "en": "Notice 3 − 1 = 4 − 2 = 5 − 3 = 7 − 5 = 2, so adding 2 to the number makes it divisible by 3, 4, 5 and 7."}, {"vi": "3, 4, 5, 7 đôi một không có ước chung khác 1, số bé nhất chia hết cho cả bốn là 3 × 4 × 5 × 7 = 420.", "en": "3, 4, 5 and 7 have no common factors other than 1 in pairs, so the smallest number divisible by all four is 3 × 4 × 5 × 7 = 420."}, {"vi": "Vậy số cần tìm là 420 − 2 = 418.", "en": "So the number is 420 − 2 = 418."}], "tip": {"vi": "Số chia trừ số dư luôn bằng bao nhiêu?", "en": "What is the divisor minus the remainder each time?"}, "src": "250 bài, CĐ9, Bài 13"}, {"id": "cd6-b15b", "lesson": "div", "rank": 3, "q": {"vi": "Một phép chia có số chia bằng 29, số dư là số dư lớn nhất có thể. Hỏi phải thêm vào số bị chia ít nhất bao nhiêu đơn vị để được phép chia hết và thương tăng thêm 3 đơn vị?", "en": "A division has a divisor of 29 and the largest possible remainder. What is the least amount that must be added to the dividend to make the division exact and the quotient 3 more?"}, "parts": [{"kind": "num", "lab": {"vi": "Phải thêm", "en": "Amount to add"}, "ans": 59, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số dư lớn nhất là 29 − 1 = 28, nên thêm 1 đơn vị thì được phép chia hết và thương tăng 1.", "en": "The largest remainder is 29 − 1 = 28, so adding 1 makes the division exact and the quotient 1 bigger."}, {"vi": "Cần thương tăng thêm 3 nên còn phải tăng thêm 2 nữa, tức thêm 2 lần số chia: 29 × 2 = 58.", "en": "The quotient must rise by 3, so it must rise by 2 more, which means adding 2 times the divisor: 29 × 2 = 58."}, {"vi": "Tổng cộng phải thêm: 1 + 58 = 59.", "en": "The total to add: 1 + 58 = 59."}], "tip": {"vi": "Số dư lớn nhất thì thiếu mấy đơn vị để chia hết?", "en": "With the largest remainder, how many more are needed to divide evenly?"}, "src": "250 bài, CĐ6, Bài 15b"}], "addsub": [{"id": "l26-b2a", "lesson": "addsub", "rank": 2, "q": {"vi": "Tính giá trị biểu thức: 10 000 − (93 120 : 24 − 24 × 57)", "en": "Evaluate: 10,000 − (93,120 ÷ 24 − 24 × 57)"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 7488, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Trong ngoặc, nhân chia trước: 93 120 : 24 = 3880 và 24 × 57 = 1368.", "en": "Inside the parentheses, multiply and divide first: 93,120 ÷ 24 = 3,880 and 24 × 57 = 1,368."}, {"vi": "Tính trong ngoặc: 3880 − 1368 = 2512.", "en": "Parentheses: 3,880 − 1,368 = 2,512."}, {"vi": "Kết quả: 10 000 − 2512 = 7488.", "en": "Result: 10,000 − 2,512 = 7,488."}], "tip": {"vi": "Làm phần trong ngoặc trước; trong ngoặc nhân, chia trước.", "en": "Do the parentheses first; inside, multiply and divide before subtracting."}, "src": "LẦN 26, Bài 2"}], "sumdiff": [{"id": "cd7-b1", "lesson": "sumdiff", "rank": 1, "q": {"vi": "An và Bình có 70 viên bi. Biết nếu Bình có thêm 16 viên bi thì hai bạn có số bi bằng nhau. Hỏi ban đầu mỗi bạn có bao nhiêu viên bi?", "en": "An and Binh have 70 marbles in all. If Binh gets 16 more marbles, the two boys will have the same number of marbles. How many marbles did each boy have at first?"}, "parts": [{"kind": "num", "lab": {"vi": "Số bi của An", "en": "An's marbles"}, "ans": 43, "unit": {"vi": "viên", "en": "marbles"}}, {"kind": "num", "lab": {"vi": "Số bi của Bình", "en": "Binh's marbles"}, "ans": 27, "unit": {"vi": "viên", "en": "marbles"}}], "steps": [{"vi": "An hơn Bình 16 viên bi, vì Bình thêm 16 viên thì bằng An.", "en": "An has 16 more marbles than Binh, because Binh needs 16 more to match An."}, {"vi": "Bình có: (70 − 16) : 2 = 27 (viên).", "en": "Binh has (70 − 16) ÷ 2 = 27 marbles."}, {"vi": "An có: 27 + 16 = 43 (viên).", "en": "An has 27 + 16 = 43 marbles."}], "tip": {"vi": "Hiệu của hai số là số bi cần thêm cho Bình.", "en": "The difference is the number of marbles Binh needs to catch up."}, "src": "250 bài, CĐ7, Bài 1"}, {"id": "cd7-b12", "lesson": "sumdiff", "rank": 1, "q": {"vi": "Tìm hai số lẻ liên tiếp có tổng bằng 4020.", "en": "Find two consecutive odd numbers whose sum is 4,020."}, "parts": [{"kind": "num", "lab": {"vi": "Số lẻ bé", "en": "Smaller odd number"}, "ans": 2009, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số lẻ lớn", "en": "Larger odd number"}, "ans": 2011, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hai số lẻ liên tiếp hơn kém nhau 2 đơn vị.", "en": "Two consecutive odd numbers differ by 2."}, {"vi": "Số bé: (4020 − 2) : 2 = 2009.", "en": "Smaller: (4,020 − 2) ÷ 2 = 2,009."}, {"vi": "Số lớn: 2009 + 2 = 2011.", "en": "Larger: 2,009 + 2 = 2,011."}], "tip": {"vi": "Hiệu của hai số lẻ liên tiếp là 2.", "en": "Consecutive odd numbers differ by 2."}, "src": "250 bài, CĐ7, Bài 12"}, {"id": "cd7-b2", "lesson": "sumdiff", "rank": 1, "q": {"vi": "Hai bao gạo cân nặng tổng cộng 147 kg. Biết rằng nếu lấy ra ở bao thứ nhất 5 kg và bao thứ hai 22 kg thì số gạo còn lại ở hai bao bằng nhau. Hỏi mỗi bao có bao nhiêu ki-lô-gam gạo?", "en": "Two bags of rice weigh 147 kg in all. If 5 kg is taken out of the first bag and 22 kg is taken out of the second bag, the two bags have the same amount of rice left. How many kilograms of rice are in each bag?"}, "parts": [{"kind": "num", "lab": {"vi": "Bao thứ nhất", "en": "First bag"}, "ans": 65, "unit": {"vi": "kg", "en": "kg"}}, {"kind": "num", "lab": {"vi": "Bao thứ hai", "en": "Second bag"}, "ans": 82, "unit": {"vi": "kg", "en": "kg"}}], "steps": [{"vi": "Hai bao bằng nhau sau khi lấy ra nên bao thứ hai nặng hơn bao thứ nhất: 22 − 5 = 17 (kg).", "en": "The bags are equal after removing, so the second bag is heavier by 22 − 5 = 17 kg."}, {"vi": "Bao thứ nhất nặng: (147 − 17) : 2 = 65 (kg).", "en": "The first bag weighs (147 − 17) ÷ 2 = 65 kg."}, {"vi": "Bao thứ hai nặng: 65 + 17 = 82 (kg).", "en": "The second bag weighs 65 + 17 = 82 kg."}], "tip": {"vi": "Bao nào bị lấy ra nhiều hơn thì ban đầu nặng hơn bao nhiêu?", "en": "The bag that lost more was heavier by how much?"}, "src": "250 bài, CĐ7, Bài 2"}, {"id": "cd7-b4", "lesson": "sumdiff", "rank": 1, "q": {"vi": "Hai tổ trồng được 30 cây. Sau đó tổ 1 trồng thêm 5 cây nữa, tổ hai trồng thêm 3 cây nữa nên số cây tổ 1 nhiều hơn số cây tổ 2 trồng được là 8 cây. Hỏi lúc đầu mỗi tổ trồng được bao nhiêu cây?", "en": "Two groups planted 30 trees in all. Then Group 1 planted 5 more trees and Group 2 planted 3 more trees, so Group 1 has planted 8 more trees than Group 2. How many trees did each group plant at first?"}, "parts": [{"kind": "num", "lab": {"vi": "Tổ 1 lúc đầu", "en": "Group 1 at first"}, "ans": 18, "unit": {"vi": "cây", "en": "trees"}}, {"kind": "num", "lab": {"vi": "Tổ 2 lúc đầu", "en": "Group 2 at first"}, "ans": 12, "unit": {"vi": "cây", "en": "trees"}}], "steps": [{"vi": "Sau khi trồng thêm, tổ 1 hơn tổ 2 là 8 cây, mà tổ 1 trồng thêm nhiều hơn tổ 2 là 5 − 3 = 2 (cây).", "en": "After planting more, Group 1 leads by 8, and it planted 5 − 3 = 2 more in the second round."}, {"vi": "Lúc đầu tổ 1 hơn tổ 2: 8 − 2 = 6 (cây).", "en": "At first Group 1 led by 8 − 2 = 6 trees."}, {"vi": "Tổ 1: (30 + 6) : 2 = 18 (cây).", "en": "Group 1: (30 + 6) ÷ 2 = 18 trees."}, {"vi": "Tổ 2: 30 − 18 = 12 (cây).", "en": "Group 2: 30 − 18 = 12 trees."}], "tip": {"vi": "Tìm hiệu lúc đầu trước.", "en": "Find the difference at the start first."}, "src": "250 bài, CĐ7, Bài 4"}, {"id": "cd7-b7", "lesson": "sumdiff", "rank": 1, "q": {"vi": "Hai thùng có tổng cộng 82 lít dầu. Nếu chuyển 7 lít dầu từ thùng thứ nhất sang thùng thứ hai thì hai thùng có số dầu bằng nhau. Hỏi mỗi thùng có bao nhiêu lít dầu?", "en": "Two barrels hold 82 liters of oil in all. If 7 liters of oil are moved from the first barrel to the second barrel, the two barrels hold the same amount. How many liters of oil does each barrel hold?"}, "parts": [{"kind": "num", "lab": {"vi": "Thùng thứ nhất", "en": "First barrel"}, "ans": 48, "unit": {"vi": "lít", "en": "liters"}}, {"kind": "num", "lab": {"vi": "Thùng thứ hai", "en": "Second barrel"}, "ans": 34, "unit": {"vi": "lít", "en": "liters"}}], "steps": [{"vi": "Sau khi chuyển, mỗi thùng có 82 : 2 = 41 (lít).", "en": "After moving, each barrel has 82 ÷ 2 = 41 liters."}, {"vi": "Thùng thứ nhất ban đầu: 41 + 7 = 48 (lít).", "en": "The first barrel had 41 + 7 = 48 liters."}, {"vi": "Thùng thứ hai ban đầu: 41 − 7 = 34 (lít).", "en": "The second barrel had 41 − 7 = 34 liters."}], "tip": {"vi": "Chuyển dầu không làm đổi tổng số dầu.", "en": "Moving oil does not change the total."}, "src": "250 bài, CĐ7, Bài 7"}, {"id": "cd7-b11", "lesson": "sumdiff", "rank": 2, "q": {"vi": "Tổng số sách của hai ngăn là 2995 quyển sách. Nếu chuyển 125 quyển từ ngăn thứ nhất sang ngăn thứ hai rồi lại chuyển 48 quyển từ ngăn thứ hai sang ngăn thứ nhất thì ngăn thứ nhất vẫn hơn ngăn thứ hai 341 quyển. Hỏi mỗi ngăn có bao nhiêu quyển sách?", "en": "Two shelves hold 2,995 books in all. If 125 books are moved from the first shelf to the second, and then 48 books are moved from the second shelf back to the first, the first shelf still has 341 more books than the second. How many books are on each shelf?"}, "parts": [{"kind": "num", "lab": {"vi": "Ngăn thứ nhất", "en": "First shelf"}, "ans": 1745, "unit": {"vi": "quyển", "en": "books"}}, {"kind": "num", "lab": {"vi": "Ngăn thứ hai", "en": "Second shelf"}, "ans": 1250, "unit": {"vi": "quyển", "en": "books"}}], "steps": [{"vi": "Cuối cùng ngăn thứ nhất bớt 125 − 48 = 77 (quyển), ngăn thứ hai thêm 77 quyển.", "en": "In the end the first shelf lost 125 − 48 = 77 books and the second gained 77."}, {"vi": "Lúc đầu ngăn thứ nhất hơn ngăn thứ hai: 341 + 77 + 77 = 495 (quyển).", "en": "At first the first shelf led by 341 + 77 + 77 = 495 books."}, {"vi": "Ngăn thứ nhất: (2995 + 495) : 2 = 1745 (quyển).", "en": "First shelf: (2,995 + 495) ÷ 2 = 1,745 books."}, {"vi": "Ngăn thứ hai: 2995 − 1745 = 1250 (quyển).", "en": "Second shelf: 2,995 − 1,745 = 1,250 books."}], "tip": {"vi": "Gộp hai lần chuyển thành một lần.", "en": "Combine the two moves into one."}, "src": "250 bài, CĐ7, Bài 11"}, {"id": "cd7-b13", "lesson": "sumdiff", "rank": 2, "q": {"vi": "Tìm hai số chẵn có tổng bằng 1000, biết giữa chúng có đúng 2 số lẻ.", "en": "Find two even numbers whose sum is 1,000, if there are exactly 2 odd numbers between them."}, "parts": [{"kind": "num", "lab": {"vi": "Số chẵn bé", "en": "Smaller even number"}, "ans": 498, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số chẵn lớn", "en": "Larger even number"}, "ans": 502, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Giữa hai số chẵn có đúng 2 số lẻ thì chúng hơn kém nhau 4 đơn vị (ví dụ 10 và 14 có 11, 13).", "en": "Two odd numbers between two even numbers means they differ by 4 (like 10 and 14 with 11 and 13 between)."}, {"vi": "Số bé: (1000 − 4) : 2 = 498.", "en": "Smaller: (1,000 − 4) ÷ 2 = 498."}, {"vi": "Số lớn: 498 + 4 = 502.", "en": "Larger: 498 + 4 = 502."}], "tip": {"vi": "Hãy thử với hai số chẵn nhỏ để tìm hiệu.", "en": "Try small even numbers to find the difference."}, "src": "250 bài, CĐ7, Bài 13"}, {"id": "cd7-b14", "lesson": "sumdiff", "rank": 2, "q": {"vi": "Tổng hai số chẵn bằng 480. Tìm hai số đó, biết giữa chúng có 6 số lẻ liên tiếp.", "en": "The sum of two even numbers is 480. Find the numbers, if there are 6 consecutive odd numbers between them."}, "parts": [{"kind": "num", "lab": {"vi": "Số chẵn bé", "en": "Smaller even number"}, "ans": 234, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số chẵn lớn", "en": "Larger even number"}, "ans": 246, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Giữa hai số chẵn có 6 số lẻ thì có thêm 5 số chẵn xen kẽ, hai số hơn kém nhau 6 × 2 = 12.", "en": "With 6 odd numbers between them, the two even numbers differ by 6 × 2 = 12."}, {"vi": "Số bé: (480 − 12) : 2 = 234.", "en": "Smaller: (480 − 12) ÷ 2 = 234."}, {"vi": "Số lớn: 234 + 12 = 246.", "en": "Larger: 234 + 12 = 246."}], "tip": {"vi": "Mỗi số lẻ ứng với một bước nhảy 2 đơn vị.", "en": "Each odd number between adds a step of 2."}, "src": "250 bài, CĐ7, Bài 14"}, {"id": "cd7-b15", "lesson": "sumdiff", "rank": 2, "q": {"vi": "Tìm hai số lẻ có tổng bằng 2010, biết giữa chúng có đúng 10 số chẵn.", "en": "Find two odd numbers whose sum is 2,010, if there are exactly 10 even numbers between them."}, "parts": [{"kind": "num", "lab": {"vi": "Số lẻ bé", "en": "Smaller odd number"}, "ans": 995, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số lẻ lớn", "en": "Larger odd number"}, "ans": 1015, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Giữa hai số lẻ có 10 số chẵn thì chúng hơn kém nhau 10 × 2 = 20.", "en": "With 10 even numbers between, the two odd numbers differ by 10 × 2 = 20."}, {"vi": "Số bé: (2010 − 20) : 2 = 995.", "en": "Smaller: (2,010 − 20) ÷ 2 = 995."}, {"vi": "Số lớn: 995 + 20 = 1015.", "en": "Larger: 995 + 20 = 1,015."}], "tip": {"vi": "Mỗi số chẵn ở giữa ứng với một bước nhảy 2.", "en": "Each even number between adds a step of 2."}, "src": "250 bài, CĐ7, Bài 15"}, {"id": "cd7-b19", "lesson": "sumdiff", "rank": 2, "q": {"vi": "Một số có hai chữ số mà tổng của hai chữ số bằng 11. Nếu đổi chỗ hai chữ số cho nhau thì số đó tăng lên 27 đơn vị. Tìm số có hai chữ số đó.", "en": "A two-digit number has digits that add up to 11. If the two digits swap places, the number increases by 27. Find the two-digit number."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 47, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số đảo hơn số ban đầu 9 lần hiệu hai chữ số, nên hiệu hai chữ số là 27 : 9 = 3.", "en": "Swapping changes the number by 9 times the digit difference, so the digits differ by 27 ÷ 9 = 3."}, {"vi": "Chữ số hàng chục: (11 − 3) : 2 = 4.", "en": "Tens digit: (11 − 3) ÷ 2 = 4."}, {"vi": "Chữ số hàng đơn vị: 4 + 3 = 7, vậy số đó là 47.", "en": "Ones digit: 4 + 3 = 7, so the number is 47."}], "tip": {"vi": "Viết số dưới dạng 10 × a + b.", "en": "Write the number as 10 × a + b."}, "src": "250 bài, CĐ7, Bài 19"}, {"id": "cd7-b3", "lesson": "sumdiff", "rank": 2, "q": {"vi": "Một trại chăn nuôi có 200 con vịt, ngan và ngỗng. Số vịt bằng tổng số ngan và ngỗng, số ngan nhiều hơn số ngỗng là 40 con. Hỏi trại đó có bao nhiêu con ngan, vịt, ngỗng?", "en": "A farm has 200 ducks, Muscovy ducks, and geese in all. The number of ducks equals the total number of Muscovy ducks and geese. There are 40 more Muscovy ducks than geese. How many ducks, Muscovy ducks, and geese are there?"}, "parts": [{"kind": "num", "lab": {"vi": "Số vịt", "en": "Ducks"}, "ans": 100, "unit": {"vi": "con", "en": "animals"}}, {"kind": "num", "lab": {"vi": "Số ngan", "en": "Muscovy ducks"}, "ans": 70, "unit": {"vi": "con", "en": "animals"}}, {"kind": "num", "lab": {"vi": "Số ngỗng", "en": "Geese"}, "ans": 30, "unit": {"vi": "con", "en": "animals"}}], "steps": [{"vi": "Số vịt bằng nửa tổng cả đàn: 200 : 2 = 100 (con).", "en": "Ducks are half of all the birds: 200 ÷ 2 = 100."}, {"vi": "Ngan và ngỗng có tổng là 100 con, ngan hơn ngỗng 40 con.", "en": "Muscovy ducks and geese total 100, with 40 more Muscovy ducks."}, {"vi": "Ngan: (100 + 40) : 2 = 70 (con).", "en": "Muscovy ducks: (100 + 40) ÷ 2 = 70."}, {"vi": "Ngỗng: 100 − 70 = 30 (con).", "en": "Geese: 100 − 70 = 30."}], "tip": {"vi": "Số vịt bằng một nửa cả trại.", "en": "The ducks are half of the whole farm."}, "src": "250 bài, CĐ7, Bài 3"}, {"id": "cd7-b5", "lesson": "sumdiff", "rank": 2, "q": {"vi": "Cách đây 5 năm tổng số tuổi hai mẹ con là 34 tuổi. Biết rằng mẹ sinh con năm 26 tuổi. Tính tuổi mỗi người hiện nay.", "en": "Five years ago, the total age of a mother and her child was 34 years. The mother was 26 when the child was born. Find each person's age now."}, "parts": [{"kind": "num", "lab": {"vi": "Tuổi mẹ hiện nay", "en": "Mother's age now"}, "ans": 35, "unit": {"vi": "tuổi", "en": "years"}}, {"kind": "num", "lab": {"vi": "Tuổi con hiện nay", "en": "Child's age now"}, "ans": 9, "unit": {"vi": "tuổi", "en": "years"}}], "steps": [{"vi": "Mẹ luôn hơn con 26 tuổi.", "en": "The mother is always 26 years older than the child."}, {"vi": "Cách đây 5 năm, tuổi con là: (34 − 26) : 2 = 4 (tuổi).", "en": "Five years ago the child was (34 − 26) ÷ 2 = 4."}, {"vi": "Tuổi con hiện nay: 4 + 5 = 9 (tuổi).", "en": "The child's age now is 4 + 5 = 9."}, {"vi": "Tuổi mẹ hiện nay: 9 + 26 = 35 (tuổi).", "en": "The mother's age now is 9 + 26 = 35."}], "tip": {"vi": "Hiệu số tuổi không bao giờ thay đổi.", "en": "The age difference never changes."}, "src": "250 bài, CĐ7, Bài 5"}, {"id": "cd7-b8", "lesson": "sumdiff", "rank": 2, "q": {"vi": "An và Bình có 120 viên bi. Nếu Bình cho An 25 viên thì Bình còn hơn An 10 viên. Hỏi lúc đầu mỗi bạn có bao nhiêu viên bi?", "en": "An and Binh have 120 marbles in all. If Binh gives An 25 marbles, Binh will still have 10 more marbles than An. How many marbles did each boy have at first?"}, "parts": [{"kind": "num", "lab": {"vi": "Số bi của An", "en": "An's marbles"}, "ans": 30, "unit": {"vi": "viên", "en": "marbles"}}, {"kind": "num", "lab": {"vi": "Số bi của Bình", "en": "Binh's marbles"}, "ans": 90, "unit": {"vi": "viên", "en": "marbles"}}], "steps": [{"vi": "Sau khi cho, Bình hơn An 10 viên, nên lúc đầu Bình hơn An: 10 + 25 + 25 = 60 (viên).", "en": "After giving, Binh leads by 10, so at first Binh led by 10 + 25 + 25 = 60 marbles."}, {"vi": "Số bi của An: (120 − 60) : 2 = 30 (viên).", "en": "An has (120 − 60) ÷ 2 = 30 marbles."}, {"vi": "Số bi của Bình: 30 + 60 = 90 (viên).", "en": "Binh has 30 + 60 = 90 marbles."}], "tip": {"vi": "Cho đi 25 viên thì Bình giảm 25 còn An tăng 25.", "en": "Binh loses 25 and An gains 25."}, "src": "250 bài, CĐ7, Bài 8"}, {"id": "cd7-b9a", "lesson": "sumdiff", "rank": 2, "q": {"vi": "Huy và Hoàng có tất cả 25 viên bi. Nếu Huy cho Hoàng 5 viên, rồi Hoàng cho lại Huy 3 viên thì số bi của Huy nhiều hơn của Hoàng là 1 viên. Hỏi mỗi bạn lúc đầu có bao nhiêu viên bi?", "en": "Huy and Hoang have 25 marbles in all. If Huy gives Hoang 5 marbles, and then Hoang gives Huy 3 marbles, Huy will have 1 more marble than Hoang. How many marbles did each boy have at first?"}, "parts": [{"kind": "num", "lab": {"vi": "Số bi của Huy", "en": "Huy's marbles"}, "ans": 15, "unit": {"vi": "viên", "en": "marbles"}}, {"kind": "num", "lab": {"vi": "Số bi của Hoàng", "en": "Hoang's marbles"}, "ans": 10, "unit": {"vi": "viên", "en": "marbles"}}], "steps": [{"vi": "Cuối cùng Huy cho đi 5 − 3 = 2 viên, Hoàng nhận thêm 2 viên.", "en": "In the end Huy gave away 5 − 3 = 2 marbles and Hoang gained 2."}, {"vi": "Lúc đầu Huy hơn Hoàng: 1 + 2 + 2 = 5 (viên).", "en": "At first Huy led by 1 + 2 + 2 = 5 marbles."}, {"vi": "Huy: (25 + 5) : 2 = 15 (viên).", "en": "Huy: (25 + 5) ÷ 2 = 15 marbles."}, {"vi": "Hoàng: 25 − 15 = 10 (viên).", "en": "Hoang: 25 − 15 = 10 marbles."}], "tip": {"vi": "Gộp hai lần chuyển thành một lần.", "en": "Combine the two transfers into one."}, "src": "250 bài, CĐ7, Bài 9 (a)"}, {"id": "cd7-b9b", "lesson": "sumdiff", "rank": 2, "q": {"vi": "Huy và Hoàng có tất cả 25 viên bi, Huy nhiều hơn Hoàng 5 viên bi. Huy phải cho Hoàng mấy viên bi để Hoàng có nhiều hơn Huy 1 viên?", "en": "Huy and Hoang have 25 marbles in all, and Huy has 5 more than Hoang. How many marbles must Huy give Hoang so that Hoang has 1 more marble than Huy?"}, "parts": [{"kind": "num", "lab": {"vi": "Số bi Huy cho", "en": "Marbles Huy gives"}, "ans": 3, "unit": {"vi": "viên", "en": "marbles"}}], "steps": [{"vi": "Lúc đầu Huy có 15 viên, Hoàng có 10 viên.", "en": "At first Huy has 15 marbles and Hoang has 10."}, {"vi": "Sau khi cho, Hoàng hơn Huy 1 viên nên Huy có (25 − 1) : 2 = 12 (viên).", "en": "After giving, Hoang leads by 1, so Huy has (25 − 1) ÷ 2 = 12."}, {"vi": "Huy phải cho: 15 − 12 = 3 (viên).", "en": "Huy must give 15 − 12 = 3 marbles."}], "tip": {"vi": "Tìm số bi của Huy sau khi cho.", "en": "Find Huy's marbles after giving."}, "src": "250 bài, CĐ7, Bài 9 (b)"}, {"id": "cd7-b10", "lesson": "sumdiff", "rank": 3, "q": {"vi": "Hai kho chứa tất cả 45 tấn thóc. Sau khi lấy ra ở kho thứ nhất 5 tấn và ở kho thứ hai 4 tấn rồi chuyển từ kho thứ nhất sang kho thứ hai 10 tấn thì kho thứ nhất còn lại số thóc ít hơn kho thứ hai là 6 tấn. Hỏi lúc đầu mỗi kho có bao nhiêu tấn thóc?", "en": "Two storehouses hold 45 tons of rice in all. After 5 tons are taken out of the first storehouse and 4 tons are taken out of the second, 10 tons are moved from the first to the second. Then the first has 6 tons less than the second. How many tons of rice did each storehouse have at first?"}, "parts": [{"kind": "num", "lab": {"vi": "Kho thứ nhất", "en": "First storehouse"}, "ans": 30, "unit": {"vi": "tấn", "en": "tons"}}, {"kind": "num", "lab": {"vi": "Kho thứ hai", "en": "Second storehouse"}, "ans": 15, "unit": {"vi": "tấn", "en": "tons"}}], "steps": [{"vi": "Kho thứ nhất giảm 5 + 10 = 15 (tấn); kho thứ hai tăng 10 − 4 = 6 (tấn).", "en": "The first drops by 5 + 10 = 15; the second changes by +10 − 4 = +6."}, {"vi": "Lúc đầu kho thứ nhất hơn kho thứ hai: 15 + 6 − 6 = 15 (tấn).", "en": "So at first the first led by 15 + 6 − 6 = 15 tons."}, {"vi": "Kho thứ nhất: (45 + 15) : 2 = 30 (tấn).", "en": "First: (45 + 15) ÷ 2 = 30 tons."}, {"vi": "Kho thứ hai: 45 − 30 = 15 (tấn).", "en": "Second: 45 − 30 = 15 tons."}], "tip": {"vi": "Tính xem mỗi kho thay đổi bao nhiêu tấn.", "en": "Work out how much each storehouse changed."}, "src": "250 bài, CĐ7, Bài 10"}, {"id": "cd7-b17", "lesson": "sumdiff", "rank": 3, "q": {"vi": "Tìm hai số tự nhiên biết tổng của chúng bằng 2003 và giữa chúng có tất cả 15 số chẵn.", "en": "Find two natural numbers whose sum is 2,003, if there are 15 even numbers between them."}, "parts": [{"kind": "num", "lab": {"vi": "Số bé", "en": "Smaller number"}, "ans": 986, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số lớn", "en": "Larger number"}, "ans": 1017, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tổng 2003 là số lẻ nên một số chẵn, một số lẻ, và hiệu của chúng là số lẻ.", "en": "The sum is odd, so one number is even and the other odd, and their difference is odd."}, {"vi": "Nếu số bé chẵn, số lớn lẻ thì 15 số chẵn nằm giữa nên hiệu là 15 × 2 + 1 = 31.", "en": "If the smaller is even and the larger odd, 15 evens between means the difference is 15 × 2 + 1 = 31."}, {"vi": "Số bé: (2003 − 31) : 2 = 986 (chẵn, hợp lí); số lớn: 986 + 31 = 1017.", "en": "Smaller: (2,003 − 31) ÷ 2 = 986 (even, which fits); larger: 986 + 31 = 1,017."}, {"vi": "Trường hợp số bé lẻ cho cùng hiệu 31 nhưng số bé 986 là chẵn nên bị loại.", "en": "If the smaller were odd, the difference would still be 31 but 986 is even, so that case fails."}], "tip": {"vi": "Xét tính chẵn lẻ của hai số.", "en": "Think about which number is even and which is odd."}, "src": "250 bài, CĐ7, Bài 17"}, {"id": "cd7-b18", "lesson": "sumdiff", "rank": 3, "q": {"vi": "Trung bình cộng của hai số tự nhiên bằng 2375. Tìm số bé biết, nếu viết thêm chữ số 3 vào bên trái số bé ta được số lớn.", "en": "The average of two natural numbers is 2,375. Find the smaller number, given that writing the digit 3 to the left of it gives the larger number."}, "parts": [{"kind": "num", "lab": {"vi": "Số bé", "en": "Smaller number"}, "ans": 875, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tổng hai số: 2375 × 2 = 4750.", "en": "The sum is 2,375 × 2 = 4,750."}, {"vi": "Nếu số bé có 3 chữ số thì số lớn = 3000 + số bé, hiệu hai số là 3000.", "en": "If the smaller number has 3 digits, the larger is 3,000 + the smaller, so they differ by 3,000."}, {"vi": "Số bé: (4750 − 3000) : 2 = 875 (có 3 chữ số, hợp lí).", "en": "Smaller: (4,750 − 3,000) ÷ 2 = 875 (3 digits, which fits)."}, {"vi": "Số bé có 2 chữ số hoặc 4 chữ số đều không thoả mãn.", "en": "A 2-digit or 4-digit smaller number does not work."}], "tip": {"vi": "Hiệu hai số chính là 3 ở hàng nào đó.", "en": "The difference is a 3 followed by zeros."}, "src": "250 bài, CĐ7, Bài 18"}, {"id": "cd7-b20", "lesson": "sumdiff", "rank": 3, "q": {"vi": "Cho một số tự nhiên có hai chữ số. Hiệu của hai chữ số là 5. Tổng của số đó với số có được khi đổi vị trí hai chữ số cho nhau là 143. Tìm số lớn nhất như vậy.", "en": "A natural number has two digits. The difference of the two digits is 5. The sum of the number and the number made by swapping its two digits is 143. Find the largest such number."}, "parts": [{"kind": "num", "lab": {"vi": "Số lớn nhất", "en": "Largest number"}, "ans": 94, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số đó cộng số đảo bằng 11 lần tổng hai chữ số nên tổng hai chữ số là 143 : 11 = 13.", "en": "The number plus its swap equals 11 times the digit sum, so the digits add up to 143 ÷ 11 = 13."}, {"vi": "Chữ số lớn: (13 + 5) : 2 = 9; chữ số bé: 13 − 9 = 4.", "en": "Bigger digit: (13 + 5) ÷ 2 = 9; smaller digit: 13 − 9 = 4."}, {"vi": "Hai số thoả mãn là 94 và 49; số lớn nhất là 94.", "en": "The numbers are 94 and 49; the largest is 94."}], "tip": {"vi": "Tổng một số và số đảo của nó chia hết cho 11.", "en": "A number plus its swap is a multiple of 11."}, "src": "250 bài, CĐ7, Bài 20"}], "simplify": [{"id": "cd10-b1", "lesson": "simplify", "rank": 1, "q": {"vi": "Viết các phân số sau dưới dạng phân số tối giản: {49/28}; {22/55}; {85/51}; {65/90}; {18/24}; {26/39}; {80/64}.", "en": "Write each fraction in simplest form: {49/28}; {22/55}; {85/51}; {65/90}; {18/24}; {26/39}; {80/64}."}, "parts": [{"kind": "frac", "lab": {"vi": "49/28", "en": "49/28"}, "ans": [7, 4]}, {"kind": "frac", "lab": {"vi": "22/55", "en": "22/55"}, "ans": [2, 5]}, {"kind": "frac", "lab": {"vi": "85/51", "en": "85/51"}, "ans": [5, 3]}, {"kind": "frac", "lab": {"vi": "65/90", "en": "65/90"}, "ans": [13, 18]}, {"kind": "frac", "lab": {"vi": "18/24", "en": "18/24"}, "ans": [3, 4]}, {"kind": "frac", "lab": {"vi": "26/39", "en": "26/39"}, "ans": [2, 3]}, {"kind": "frac", "lab": {"vi": "80/64", "en": "80/64"}, "ans": [5, 4]}], "steps": [{"vi": "Tìm ước chung lớn nhất của tử và mẫu mỗi phân số.", "en": "Find the greatest common factor of the numerator and denominator of each fraction."}, {"vi": "Chia cả tử và mẫu cho ước chung đó, ví dụ 49 : 7 = 7 và 28 : 7 = 4 nên {49/28} = {7/4}.", "en": "Divide both by it. For example 49 ÷ 7 = 7 and 28 ÷ 7 = 4, so {49/28} = {7/4}."}, {"vi": "Làm tương tự: {22/55} = {2/5}; {85/51} = {5/3}; {65/90} = {13/18}; {18/24} = {3/4}; {26/39} = {2/3}; {80/64} = {5/4}.", "en": "Do the same: {22/55} = {2/5}; {85/51} = {5/3}; {65/90} = {13/18}; {18/24} = {3/4}; {26/39} = {2/3}; {80/64} = {5/4}."}], "tip": {"vi": "Chia tử và mẫu cho cùng một số lớn nhất có thể.", "en": "Divide the top and bottom by the biggest number that fits both."}, "src": "250 bài, CĐ10, Bài 1"}, {"id": "cd10-b2", "lesson": "simplify", "rank": 2, "q": {"vi": "Viết các phân số sau dưới dạng phân số tối giản: {549/1281}; {3672/4284}; {7976/9970}; {252525/808080}; {165165165/462462462}.", "en": "Write each fraction in simplest form: {549/1281}; {3672/4284}; {7976/9970}; {252525/808080}; {165165165/462462462}."}, "parts": [{"kind": "frac", "lab": {"vi": "549/1 281", "en": "549/1,281"}, "ans": [3, 7]}, {"kind": "frac", "lab": {"vi": "3 672/4 284", "en": "3,672/4,284"}, "ans": [6, 7]}, {"kind": "frac", "lab": {"vi": "7 976/9 970", "en": "7,976/9,970"}, "ans": [4, 5]}, {"kind": "frac", "lab": {"vi": "252 525/808 080", "en": "252,525/808,080"}, "ans": [5, 16]}, {"kind": "frac", "lab": {"vi": "165 165 165/462 462 462", "en": "165,165,165/462,462,462"}, "ans": [5, 14]}], "steps": [{"vi": "Với {549/1281}, chia tử và mẫu cho 183 (549 : 183 = 3; 1281 : 183 = 7) được {3/7}.", "en": "For {549/1281}, divide both by 183 (549 ÷ 183 = 3; 1281 ÷ 183 = 7) to get {3/7}."}, {"vi": "{3672/4284}: chia cho 612 được {6/7}; {7976/9970}: chia cho 1994 được {4/5}.", "en": "{3672/4284}: divide by 612 to get {6/7}; {7976/9970}: divide by 1994 to get {4/5}."}, {"vi": "{252525/808080} = {25/80} (chia cho 10101) = {5/16}.", "en": "{252525/808080} = {25/80} (divide by 10101) = {5/16}."}, {"vi": "{165165165/462462462} = {165/462} (chia cho 1001001) = {5/14}.", "en": "{165165165/462462462} = {165/462} (divide by 1001001) = {5/14}."}], "tip": {"vi": "Nhìn xem tử và mẫu có phải là số lặp lại một nhóm chữ số không.", "en": "Look for a group of digits that repeats in both numbers."}, "src": "250 bài, CĐ10, Bài 2"}], "fracprop": [{"id": "cd10-b3a", "lesson": "fracprop", "rank": 1, "q": {"vi": "Tìm x, biết: {3/7} = {x/21}.", "en": "Find x: {3/7} = {x/21}."}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 9, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Mẫu số 7 nhân với 3 được 21.", "en": "The denominator 7 times 3 is 21."}, {"vi": "Nhân cả tử số 3 với 3 được x = 9.", "en": "Multiply the numerator 3 by 3 too, so x = 9."}], "tip": {"vi": "Xem mẫu số được nhân với mấy.", "en": "Find what the denominator was multiplied by."}, "src": "250 bài, CĐ10, Bài 3a"}, {"id": "cd10-b3b", "lesson": "fracprop", "rank": 1, "q": {"vi": "Tìm x, biết: {x/8} = {18/72}.", "en": "Find x: {x/8} = {18/72}."}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 2, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Mẫu số 72 chia cho 9 được 8.", "en": "The denominator 72 divided by 9 gives 8."}, {"vi": "Chia tử số 18 cho 9 được x = 2.", "en": "Divide the numerator 18 by 9 to get x = 2."}], "tip": {"vi": "Phân số bên phải được rút gọn thành mẫu số 8.", "en": "Reduce the right fraction so its denominator is 8."}, "src": "250 bài, CĐ10, Bài 3b"}, {"id": "cd10-b4a", "lesson": "fracprop", "rank": 1, "q": {"vi": "Tìm các số tự nhiên x và y, biết: {2/x} = {y/6} = {12/18}.", "en": "Find the whole numbers x and y: {2/x} = {y/6} = {12/18}."}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 3, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "y", "en": "y"}, "ans": 4, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Rút gọn {12/18} = {2/3}.", "en": "Simplify {12/18} = {2/3}."}, {"vi": "{2/x} = {2/3} nên x = 3.", "en": "{2/x} = {2/3}, so x = 3."}, {"vi": "{y/6} = {2/3} = {4/6} nên y = 4.", "en": "{y/6} = {2/3} = {4/6}, so y = 4."}], "tip": {"vi": "Rút gọn phân số đã biết đủ tử và mẫu.", "en": "Simplify the fraction that is fully given."}, "src": "250 bài, CĐ10, Bài 4a"}, {"id": "cd10-b6a", "lesson": "fracprop", "rank": 1, "q": {"vi": "Tìm 3 phân số bằng phân số {6/12} và có tử số lần lượt là 3; 12; 24. Điền mẫu số của từng phân số.", "en": "Find 3 fractions equal to {6/12} whose numerators are 3, 12 and 24. Fill in each denominator."}, "parts": [{"kind": "num", "lab": {"vi": "Mẫu số của {3/…}", "en": "Denominator of {3/…}"}, "ans": 6, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Mẫu số của {12/…}", "en": "Denominator of {12/…}"}, "ans": 24, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Mẫu số của {24/…}", "en": "Denominator of {24/…}"}, "ans": 48, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "{6/12} = {3/6} (chia tử và mẫu cho 2).", "en": "{6/12} = {3/6} (divide top and bottom by 2)."}, {"vi": "{6/12} = {12/24} (nhân tử và mẫu với 2).", "en": "{6/12} = {12/24} (multiply top and bottom by 2)."}, {"vi": "{6/12} = {24/48} (nhân tử và mẫu với 4).", "en": "{6/12} = {24/48} (multiply top and bottom by 4)."}], "tip": {"vi": "Xem tử số mới gấp hay kém tử số cũ mấy lần.", "en": "See how many times bigger or smaller the new numerator is."}, "src": "250 bài, CĐ10, Bài 6a"}, {"id": "cd10-b3c", "lesson": "fracprop", "rank": 2, "q": {"vi": "Tìm x, biết: {4/(x × 3 − 1)} = {15/30}.", "en": "Find x: {4/(x × 3 − 1)} = {15/30}."}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 3, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Rút gọn {15/30} = {1/2}, nên {4/(x × 3 − 1)} = {4/8}.", "en": "Simplify {15/30} = {1/2}, so {4/(x × 3 − 1)} = {4/8}."}, {"vi": "Vậy x × 3 − 1 = 8, suy ra x × 3 = 9.", "en": "So x × 3 − 1 = 8, which gives x × 3 = 9."}, {"vi": "x = 9 : 3 = 3.", "en": "x = 9 ÷ 3 = 3."}], "tip": {"vi": "Đưa vế phải về tử số 4.", "en": "Make the right side have 4 on top."}, "src": "250 bài, CĐ10, Bài 3c"}, {"id": "cd10-b3d", "lesson": "fracprop", "rank": 2, "q": {"vi": "Tìm x, biết: {(x + 5)/8} = {9/12}.", "en": "Find x: {(x + 5)/8} = {9/12}."}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 1, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Rút gọn {9/12} = {3/4} = {6/8}.", "en": "Simplify {9/12} = {3/4} = {6/8}."}, {"vi": "Vậy x + 5 = 6.", "en": "So x + 5 = 6."}, {"vi": "x = 6 − 5 = 1.", "en": "x = 6 − 5 = 1."}], "tip": {"vi": "Đưa vế phải về mẫu số 8.", "en": "Make the right side have 8 on the bottom."}, "src": "250 bài, CĐ10, Bài 3d"}, {"id": "cd10-b3e", "lesson": "fracprop", "rank": 2, "q": {"vi": "Tìm x, biết: {60/(x : 3)} = 12.", "en": "Find x: {60/(x ÷ 3)} = 12."}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 15, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Phân số là thương: 60 : (x : 3) = 12.", "en": "A fraction is a quotient: 60 ÷ (x ÷ 3) = 12."}, {"vi": "x : 3 = 60 : 12 = 5.", "en": "x ÷ 3 = 60 ÷ 12 = 5."}, {"vi": "x = 5 × 3 = 15.", "en": "x = 5 × 3 = 15."}], "tip": {"vi": "Phân số {a/b} chính là a : b.", "en": "The fraction {a/b} means a ÷ b."}, "src": "250 bài, CĐ10, Bài 3e"}, {"id": "cd10-b4b", "lesson": "fracprop", "rank": 2, "q": {"vi": "Tìm các số tự nhiên x và y, biết: {6/x} = {y/20} = {21/28}.", "en": "Find the whole numbers x and y: {6/x} = {y/20} = {21/28}."}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 8, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "y", "en": "y"}, "ans": 15, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Rút gọn {21/28} = {3/4}.", "en": "Simplify {21/28} = {3/4}."}, {"vi": "{6/x} = {3/4} = {6/8} nên x = 8.", "en": "{6/x} = {3/4} = {6/8}, so x = 8."}, {"vi": "{y/20} = {3/4} = {15/20} nên y = 15.", "en": "{y/20} = {3/4} = {15/20}, so y = 15."}], "tip": {"vi": "Rút gọn phân số đã biết đủ tử và mẫu.", "en": "Simplify the fraction that is fully given."}, "src": "250 bài, CĐ10, Bài 4b"}, {"id": "cd10-b5", "lesson": "fracprop", "rank": 2, "q": {"vi": "Tìm các số a, b, c, d biết rằng: {4/6} = {6/a} = {b/15} = {18/c} = {d/30}.", "en": "Find a, b, c, d if {4/6} = {6/a} = {b/15} = {18/c} = {d/30}."}, "parts": [{"kind": "num", "lab": {"vi": "a", "en": "a"}, "ans": 9, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "b", "en": "b"}, "ans": 10, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "c", "en": "c"}, "ans": 27, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "d", "en": "d"}, "ans": 20, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Rút gọn {4/6} = {2/3}.", "en": "Simplify {4/6} = {2/3}."}, {"vi": "{6/a} = {2/3} = {6/9} nên a = 9; {18/c} = {6/9} = {18/27} nên c = 27.", "en": "{6/a} = {2/3} = {6/9}, so a = 9; {18/c} = {6/9} = {18/27}, so c = 27."}, {"vi": "{b/15} = {2/3} = {10/15} nên b = 10; {d/30} = {2/3} = {20/30} nên d = 20.", "en": "{b/15} = {2/3} = {10/15}, so b = 10; {d/30} = {2/3} = {20/30}, so d = 20."}], "tip": {"vi": "Mọi phân số đều bằng {2/3}.", "en": "Every fraction equals {2/3}."}, "src": "250 bài, CĐ10, Bài 5"}, {"id": "cd10-b6b", "lesson": "fracprop", "rank": 2, "q": {"vi": "Tìm các phân số bằng phân số {5/8} và có mẫu số lớn hơn 15 nhưng nhỏ hơn 50. Hỏi có bao nhiêu phân số như vậy và tổng các tử số của chúng bằng bao nhiêu?", "en": "Find all fractions equal to {5/8} whose denominator is greater than 15 and less than 50. How many such fractions are there, and what is the sum of their numerators?"}, "parts": [{"kind": "num", "lab": {"vi": "Số phân số", "en": "Number of fractions"}, "ans": 5, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Tổng các tử số", "en": "Sum of numerators"}, "ans": 100, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Phân số bằng {5/8} có dạng {(5 × k)/(8 × k)}, mẫu số 8 × k phải từ 16 đến 49 nên k = 2; 3; 4; 5; 6.", "en": "Fractions equal to {5/8} look like {(5 × k)/(8 × k)}. The denominator 8 × k must be between 16 and 49, so k = 2, 3, 4, 5, 6."}, {"vi": "Các phân số: {10/16}; {15/24}; {20/32}; {25/40}; {30/48}, tức là 5 phân số.", "en": "The fractions: {10/16}; {15/24}; {20/32}; {25/40}; {30/48}. That is 5 fractions."}, {"vi": "Tổng tử số: 10 + 15 + 20 + 25 + 30 = 100.", "en": "Sum of numerators: 10 + 15 + 20 + 25 + 30 = 100."}], "tip": {"vi": "Nhân tử và mẫu với cùng một số tự nhiên k.", "en": "Multiply top and bottom by the same whole number k."}, "src": "250 bài, CĐ10, Bài 6b"}, {"id": "cd10-b7a", "lesson": "fracprop", "rank": 2, "q": {"vi": "Tìm tất cả các phân số bằng {13/17} sao cho tử số và mẫu số của các phân số đó đều là số tự nhiên có 2 chữ số. Kể cả chính {13/17}, hỏi có bao nhiêu phân số như vậy?", "en": "Find all fractions equal to {13/17} whose numerator and denominator are both 2-digit whole numbers. Counting {13/17} itself, how many such fractions are there?"}, "parts": [{"kind": "num", "lab": {"vi": "Số phân số", "en": "Number of fractions"}, "ans": 5, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Phân số bằng {13/17} có dạng {(13 × k)/(17 × k)}.", "en": "Fractions equal to {13/17} look like {(13 × k)/(17 × k)}."}, {"vi": "Mẫu số 17 × k phải nhỏ hơn 100 nên k ≤ 5 (17 × 6 = 102 đã có 3 chữ số).", "en": "The denominator 17 × k must be less than 100, so k ≤ 5 (17 × 6 = 102 has 3 digits)."}, {"vi": "Với k = 1; 2; 3; 4; 5 ta được {13/17}; {26/34}; {39/51}; {52/68}; {65/85}, tức là 5 phân số.", "en": "With k = 1, 2, 3, 4, 5 we get {13/17}; {26/34}; {39/51}; {52/68}; {65/85}. That is 5 fractions."}], "tip": {"vi": "Nhân cả tử và mẫu với k, rồi xem k lớn nhất là mấy.", "en": "Multiply top and bottom by k, then find the biggest k."}, "src": "250 bài, CĐ10, Bài 7a"}, {"id": "cd10-b8", "lesson": "fracprop", "rank": 2, "q": {"vi": "Cho phân số {8/12}. Tìm một số sao cho khi lấy mẫu số của phân số đã cho trừ đi số đó và giữ nguyên tử số thì được phân số mới có giá trị bằng {4/3}.", "en": "Take the fraction {8/12}. Find a number such that when you subtract it from the denominator and keep the numerator, the new fraction equals {4/3}."}, "parts": [{"kind": "num", "lab": {"vi": "Số cần tìm", "en": "The number"}, "ans": 6, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Giữ nguyên tử số 8, viết {4/3} = {8/6}.", "en": "Keep the numerator 8 and write {4/3} = {8/6}."}, {"vi": "Vậy mẫu số mới là 6.", "en": "So the new denominator is 6."}, {"vi": "Số cần trừ là 12 − 6 = 6.", "en": "The number to subtract is 12 − 6 = 6."}], "tip": {"vi": "Đưa {4/3} về phân số có tử số 8.", "en": "Rewrite {4/3} with numerator 8."}, "src": "250 bài, CĐ10, Bài 8"}, {"id": "l26-b4b", "lesson": "fracprop", "rank": 2, "q": {"vi": "Tìm x: {6/8} = {15/x}", "en": "Find x: {6/8} = {15/x}"}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 20, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Rút gọn {6/8} = {3/4}.", "en": "Simplify {6/8} = {3/4}."}, {"vi": "Ta có {15/x} = {3/4}. Tử số 15 gấp 3 là 5 lần.", "en": "We have {15/x} = {3/4}. The numerator 15 is 5 times 3."}, {"vi": "Vậy x gấp 4 là 5 lần: x = 4 × 5 = 20.", "en": "So x is 5 times 4: x = 4 × 5 = 20."}], "tip": {"vi": "Rút gọn phân số bên trái trước.", "en": "Simplify the fraction on the left first."}, "src": "LẦN 26, Bài 4"}, {"id": "cd10-b7b", "lesson": "fracprop", "rank": 3, "q": {"vi": "Tìm tất cả các phân số bằng {68/119} sao cho tử số là số có 2 chữ số chia hết cho 3 và 4. Hỏi có bao nhiêu phân số như vậy và tổng các tử số của chúng bằng bao nhiêu?", "en": "Find all fractions equal to {68/119} whose numerator is a 2-digit number divisible by both 3 and 4. How many such fractions are there, and what is the sum of their numerators?"}, "parts": [{"kind": "num", "lab": {"vi": "Số phân số", "en": "Number of fractions"}, "ans": 8, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Tổng các tử số", "en": "Sum of numerators"}, "ans": 432, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Rút gọn {68/119} = {4/7} (chia cho 17), nên các phân số có dạng {(4 × k)/(7 × k)}.", "en": "Simplify {68/119} = {4/7} (divide by 17), so the fractions look like {(4 × k)/(7 × k)}."}, {"vi": "Tử số chia hết cho 3 và 4 nên chia hết cho 12, các số có 2 chữ số: 12; 24; 36; 48; 60; 72; 84; 96 (8 số).", "en": "The numerator is divisible by 3 and 4, so by 12. The 2-digit choices: 12, 24, 36, 48, 60, 72, 84, 96 (8 numbers)."}, {"vi": "Có 8 phân số: {12/21}; {24/42}; {36/63}; {48/84}; {60/105}; {72/126}; {84/147}; {96/168}.", "en": "There are 8 fractions: {12/21}; {24/42}; {36/63}; {48/84}; {60/105}; {72/126}; {84/147}; {96/168}."}, {"vi": "Tổng tử số: 12 + 24 + 36 + 48 + 60 + 72 + 84 + 96 = 432.", "en": "Sum of numerators: 12 + 24 + 36 + 48 + 60 + 72 + 84 + 96 = 432."}], "tip": {"vi": "Tử số chia hết cho cả 3 và 4 thì chia hết cho số nào?", "en": "A number divisible by both 3 and 4 is divisible by what?"}, "src": "250 bài, CĐ10, Bài 7b"}, {"id": "cd10-b9", "lesson": "fracprop", "rank": 3, "q": {"vi": "Từ các chữ số 2; 0; 3; 4; 6 ta viết được các số có ba chữ số khác nhau. Cứ hai số trong các số vừa viết được ta lập một phân số có tử số và mẫu số là hai số đó. Hỏi có bao nhiêu phân số như vậy có giá trị là {1/2}?", "en": "Using the digits 2, 0, 3, 4, 6, we can write 3-digit numbers with all different digits. Take any two of these numbers to make a fraction (one is the numerator, the other the denominator). How many such fractions equal {1/2}?"}, "parts": [{"kind": "num", "lab": {"vi": "Số phân số", "en": "Number of fractions"}, "ans": 4, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Phân số có giá trị {1/2} thì mẫu số gấp đôi tử số.", "en": "A fraction equal to {1/2} has a denominator that is double its numerator."}, {"vi": "Tử số phải nhỏ hơn 500 nên chỉ có thể là số bắt đầu bằng 2, 3 hoặc 4; thử từng số và nhân đôi, xem kết quả có viết được từ các chữ số đã cho, khác nhau không.", "en": "The numerator must be below 500, so it starts with 2, 3 or 4. Double each candidate and check that the result uses only the given digits, all different."}, {"vi": "Các phân số thoả mãn: {203/406}; {230/460}; {320/640}; {302/604}. Có 4 phân số.", "en": "The fractions that work: {203/406}; {230/460}; {320/640}; {302/604}. There are 4 of them."}], "tip": {"vi": "Mẫu số gấp mấy lần tử số?", "en": "How many times bigger is the denominator than the numerator?"}, "src": "250 bài, CĐ10, Bài 9"}], "fraccmp": [{"id": "cd10-b16a", "lesson": "fraccmp", "rank": 1, "q": {"vi": "So sánh hai phân số {997/999} và {1993/1995} bằng cách hợp lý.", "en": "Compare the fractions {997/999} and {1993/1995} using a smart method (no common denominator)."}, "parts": [{"kind": "choice", "lab": {"vi": "{997/999} so với {1993/1995}", "en": "{997/999} vs {1993/1995}"}, "opts": {"vi": ["Bé hơn (<)", "Bằng (=)", "Lớn hơn (>)"], "en": ["Less than (<)", "Equal to (=)", "Greater than (>)"]}, "ans": 0}], "steps": [{"vi": "Phần bù với 1: 1 − {997/999} = {2/999}; 1 − {1993/1995} = {2/1995}.", "en": "Missing part to reach 1: 1 − {997/999} = {2/999}; 1 − {1993/1995} = {2/1995}."}, {"vi": "Hai phần bù cùng tử số 2, mẫu 999 < 1 995 nên {2/999} > {2/1995}.", "en": "Both have numerator 2 and 999 < 1,995, so {2/999} > {2/1995}."}, {"vi": "Phần thiếu càng lớn thì phân số càng bé, nên {997/999} < {1993/1995}.", "en": "The bigger the missing part, the smaller the fraction, so {997/999} < {1993/1995}."}], "tip": {"vi": "Thử so sánh với 1 hoặc với {1/2}, hoặc xem phần còn thiếu so với 1.", "en": "Try comparing with 1 or {1/2}, or look at what each is missing from 1."}, "src": "250 bài, CĐ10, Bài 16a"}, {"id": "cd10-b16b", "lesson": "fraccmp", "rank": 1, "q": {"vi": "So sánh hai phân số {208/209} và {209/210} bằng cách hợp lý.", "en": "Compare the fractions {208/209} and {209/210} using a smart method (no common denominator)."}, "parts": [{"kind": "choice", "lab": {"vi": "{208/209} so với {209/210}", "en": "{208/209} vs {209/210}"}, "opts": {"vi": ["Bé hơn (<)", "Bằng (=)", "Lớn hơn (>)"], "en": ["Less than (<)", "Equal to (=)", "Greater than (>)"]}, "ans": 0}], "steps": [{"vi": "Phần bù với 1: 1 − {208/209} = {1/209}; 1 − {209/210} = {1/210}.", "en": "Missing part to 1: 1 − {208/209} = {1/209}; 1 − {209/210} = {1/210}."}, {"vi": "Cùng tử số 1, mẫu 209 < 210 nên {1/209} > {1/210}.", "en": "Same numerator 1 and 209 < 210, so {1/209} > {1/210}."}, {"vi": "Phần thiếu lớn hơn nên {208/209} < {209/210}.", "en": "The bigger missing part means {208/209} < {209/210}."}], "tip": {"vi": "Thử so sánh với 1 hoặc với {1/2}, hoặc xem phần còn thiếu so với 1.", "en": "Try comparing with 1 or {1/2}, or look at what each is missing from 1."}, "src": "250 bài, CĐ10, Bài 16b"}, {"id": "cd10-b16c", "lesson": "fraccmp", "rank": 1, "q": {"vi": "So sánh hai phân số {13/27} và {27/41} bằng cách hợp lý.", "en": "Compare the fractions {13/27} and {27/41} using a smart method (no common denominator)."}, "parts": [{"kind": "choice", "lab": {"vi": "{13/27} so với {27/41}", "en": "{13/27} vs {27/41}"}, "opts": {"vi": ["Bé hơn (<)", "Bằng (=)", "Lớn hơn (>)"], "en": ["Less than (<)", "Equal to (=)", "Greater than (>)"]}, "ans": 0}], "steps": [{"vi": "So sánh với {1/2}: 13 × 2 = 26 < 27 nên {13/27} < {1/2}.", "en": "Compare with {1/2}: 13 × 2 = 26 < 27, so {13/27} < {1/2}."}, {"vi": "27 × 2 = 54 > 41 nên {27/41} > {1/2}.", "en": "27 × 2 = 54 > 41, so {27/41} > {1/2}."}, {"vi": "Vậy {13/27} < {1/2} < {27/41}.", "en": "So {13/27} < {1/2} < {27/41}."}], "tip": {"vi": "Thử so sánh với 1 hoặc với {1/2}, hoặc xem phần còn thiếu so với 1.", "en": "Try comparing with 1 or {1/2}, or look at what each is missing from 1."}, "src": "250 bài, CĐ10, Bài 16c"}, {"id": "cd10-b17a", "lesson": "fraccmp", "rank": 1, "q": {"vi": "So sánh hai phân số {27/13} và {41/27} bằng cách hợp lý.", "en": "Compare the fractions {27/13} and {41/27} using a smart method (no common denominator)."}, "parts": [{"kind": "choice", "lab": {"vi": "{27/13} so với {41/27}", "en": "{27/13} vs {41/27}"}, "opts": {"vi": ["Bé hơn (<)", "Bằng (=)", "Lớn hơn (>)"], "en": ["Less than (<)", "Equal to (=)", "Greater than (>)"]}, "ans": 2}], "steps": [{"vi": "So sánh với 2: 13 × 2 = 26 < 27 nên {27/13} > 2.", "en": "Compare with 2: 13 × 2 = 26 < 27, so {27/13} > 2."}, {"vi": "27 × 2 = 54 > 41 nên {41/27} < 2.", "en": "27 × 2 = 54 > 41, so {41/27} < 2."}, {"vi": "Vậy {27/13} > 2 > {41/27}.", "en": "So {27/13} > 2 > {41/27}."}], "tip": {"vi": "So sánh cả hai với số 2.", "en": "Compare both with 2."}, "src": "250 bài, CĐ10, Bài 17a"}, {"id": "cd10-b17b", "lesson": "fraccmp", "rank": 1, "q": {"vi": "So sánh hai phân số {13/7} và {23/17} bằng cách hợp lý.", "en": "Compare the fractions {13/7} and {23/17} using a smart method (no common denominator)."}, "parts": [{"kind": "choice", "lab": {"vi": "{13/7} so với {23/17}", "en": "{13/7} vs {23/17}"}, "opts": {"vi": ["Bé hơn (<)", "Bằng (=)", "Lớn hơn (>)"], "en": ["Less than (<)", "Equal to (=)", "Greater than (>)"]}, "ans": 2}], "steps": [{"vi": "Tách phần nguyên: {13/7} = 1 + {6/7}; {23/17} = 1 + {6/17}.", "en": "Split off the whole: {13/7} = 1 + {6/7}; {23/17} = 1 + {6/17}."}, {"vi": "Cùng tử số 6, mẫu 7 < 17 nên {6/7} > {6/17}.", "en": "Same numerator 6 and 7 < 17, so {6/7} > {6/17}."}, {"vi": "Vậy {13/7} > {23/17}.", "en": "So {13/7} > {23/17}."}], "tip": {"vi": "Cả hai đều lớn hơn 1; hãy xem mỗi phân số hơn 1 bao nhiêu.", "en": "Both are greater than 1; see how much each exceeds 1."}, "src": "250 bài, CĐ10, Bài 17b"}, {"id": "cd10-b17c", "lesson": "fraccmp", "rank": 1, "q": {"vi": "So sánh hai phân số {15/11} và {25/21} bằng cách hợp lý.", "en": "Compare the fractions {15/11} and {25/21} using a smart method (no common denominator)."}, "parts": [{"kind": "choice", "lab": {"vi": "{15/11} so với {25/21}", "en": "{15/11} vs {25/21}"}, "opts": {"vi": ["Bé hơn (<)", "Bằng (=)", "Lớn hơn (>)"], "en": ["Less than (<)", "Equal to (=)", "Greater than (>)"]}, "ans": 2}], "steps": [{"vi": "Tách phần nguyên: {15/11} = 1 + {4/11}; {25/21} = 1 + {4/21}.", "en": "Split off the whole: {15/11} = 1 + {4/11}; {25/21} = 1 + {4/21}."}, {"vi": "Cùng tử số 4, mẫu 11 < 21 nên {4/11} > {4/21}.", "en": "Same numerator 4 and 11 < 21, so {4/11} > {4/21}."}, {"vi": "Vậy {15/11} > {25/21}.", "en": "So {15/11} > {25/21}."}], "tip": {"vi": "Cả hai đều lớn hơn 1; hãy xem mỗi phân số hơn 1 bao nhiêu.", "en": "Both are greater than 1; see how much each exceeds 1."}, "src": "250 bài, CĐ10, Bài 17c"}, {"id": "cd10-b18a", "lesson": "fraccmp", "rank": 1, "q": {"vi": "So sánh hai phân số {27/13} và {35/17} bằng cách hợp lý.", "en": "Compare the fractions {27/13} and {35/17} using a smart method (no common denominator)."}, "parts": [{"kind": "choice", "lab": {"vi": "{27/13} so với {35/17}", "en": "{27/13} vs {35/17}"}, "opts": {"vi": ["Bé hơn (<)", "Bằng (=)", "Lớn hơn (>)"], "en": ["Less than (<)", "Equal to (=)", "Greater than (>)"]}, "ans": 2}], "steps": [{"vi": "Tách phần nguyên: {27/13} = 2 + {1/13}; {35/17} = 2 + {1/17}.", "en": "Split off the whole: {27/13} = 2 + {1/13}; {35/17} = 2 + {1/17}."}, {"vi": "Cùng tử số 1, mẫu 13 < 17 nên {1/13} > {1/17}.", "en": "Same numerator 1 and 13 < 17, so {1/13} > {1/17}."}, {"vi": "Vậy {27/13} > {35/17}.", "en": "So {27/13} > {35/17}."}], "tip": {"vi": "Tách mỗi phân số thành số tự nhiên cộng phân số bé hơn 1.", "en": "Write each as a whole number plus a fraction less than 1."}, "src": "250 bài, CĐ10, Bài 18a"}, {"id": "cd10-b18b", "lesson": "fraccmp", "rank": 1, "q": {"vi": "So sánh hai phân số {23/7} và {47/15} bằng cách hợp lý.", "en": "Compare the fractions {23/7} and {47/15} using a smart method (no common denominator)."}, "parts": [{"kind": "choice", "lab": {"vi": "{23/7} so với {47/15}", "en": "{23/7} vs {47/15}"}, "opts": {"vi": ["Bé hơn (<)", "Bằng (=)", "Lớn hơn (>)"], "en": ["Less than (<)", "Equal to (=)", "Greater than (>)"]}, "ans": 2}], "steps": [{"vi": "Tách phần nguyên: {23/7} = 3 + {2/7}; {47/15} = 3 + {2/15}.", "en": "Split off the whole: {23/7} = 3 + {2/7}; {47/15} = 3 + {2/15}."}, {"vi": "Cùng tử số 2, mẫu 7 < 15 nên {2/7} > {2/15}.", "en": "Same numerator 2 and 7 < 15, so {2/7} > {2/15}."}, {"vi": "Vậy {23/7} > {47/15}.", "en": "So {23/7} > {47/15}."}], "tip": {"vi": "Tách mỗi phân số thành số tự nhiên cộng phân số bé hơn 1.", "en": "Write each as a whole number plus a fraction less than 1."}, "src": "250 bài, CĐ10, Bài 18b"}, {"id": "cd10-b18d", "lesson": "fraccmp", "rank": 1, "q": {"vi": "So sánh hai phân số {42/211} và {63/314} bằng cách hợp lý.", "en": "Compare the fractions {42/211} and {63/314} using a smart method (no common denominator)."}, "parts": [{"kind": "choice", "lab": {"vi": "{42/211} so với {63/314}", "en": "{42/211} vs {63/314}"}, "opts": {"vi": ["Bé hơn (<)", "Bằng (=)", "Lớn hơn (>)"], "en": ["Less than (<)", "Equal to (=)", "Greater than (>)"]}, "ans": 0}], "steps": [{"vi": "42 × 5 = 210 < 211 nên {42/211} < {1/5}.", "en": "42 × 5 = 210 < 211, so {42/211} < {1/5}."}, {"vi": "63 × 5 = 315 > 314 nên {63/314} > {1/5}.", "en": "63 × 5 = 315 > 314, so {63/314} > {1/5}."}, {"vi": "Vậy {42/211} < {1/5} < {63/314}.", "en": "So {42/211} < {1/5} < {63/314}."}], "tip": {"vi": "Thử so sánh cả hai với {1/5}.", "en": "Try comparing both with {1/5}."}, "src": "250 bài, CĐ10, Bài 18d"}, {"id": "cd10-b10a", "lesson": "fraccmp", "rank": 2, "q": {"vi": "Tìm số tự nhiên x khác 0, biết {2/x} > {1/2}. Hỏi x có thể nhận bao nhiêu giá trị và giá trị lớn nhất là bao nhiêu?", "en": "Find the whole numbers x (not 0) such that {2/x} > {1/2}. How many values can x take, and what is the largest?"}, "parts": [{"kind": "num", "lab": {"vi": "Số giá trị của x", "en": "Number of values"}, "ans": 3, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Giá trị lớn nhất", "en": "Largest value"}, "ans": 3, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Viết {1/2} = {2/4}, hai phân số có cùng tử số 2.", "en": "Write {1/2} = {2/4}; both fractions have numerator 2."}, {"vi": "Hai phân số cùng tử số, phân số nào có mẫu số bé hơn thì lớn hơn, nên x < 4.", "en": "With equal numerators, the smaller denominator gives the bigger fraction, so x < 4."}, {"vi": "x = 1; 2; 3, có 3 giá trị, lớn nhất là 3.", "en": "x = 1, 2, 3. That is 3 values and the largest is 3."}], "tip": {"vi": "Đưa {1/2} về tử số 2.", "en": "Rewrite {1/2} with numerator 2."}, "src": "250 bài, CĐ10, Bài 10a"}, {"id": "cd10-b10b", "lesson": "fraccmp", "rank": 2, "q": {"vi": "Tìm số tự nhiên x, biết 1 < {11/x} < 2. Hỏi x có thể nhận bao nhiêu giá trị và tổng các giá trị đó bằng bao nhiêu?", "en": "Find the whole numbers x such that 1 < {11/x} < 2. How many values can x take, and what is their sum?"}, "parts": [{"kind": "num", "lab": {"vi": "Số giá trị của x", "en": "Number of values"}, "ans": 5, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Tổng các giá trị", "en": "Sum of values"}, "ans": 40, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "{11/x} > 1 nên tử số lớn hơn mẫu số: x < 11.", "en": "{11/x} > 1 means the numerator is bigger than the denominator: x < 11."}, {"vi": "{11/x} < 2 nghĩa là 11 < 2 × x, tức x lớn hơn 5 (vì 2 × 5 = 10 < 11).", "en": "{11/x} < 2 means 11 < 2 × x, so x is more than 5 (because 2 × 5 = 10 < 11)."}, {"vi": "x = 6; 7; 8; 9; 10, có 5 giá trị, tổng là 40.", "en": "x = 6, 7, 8, 9, 10. That is 5 values with sum 40."}], "tip": {"vi": "Thử từng giá trị x gần 11 và gần 5.", "en": "Try values of x near 11 and near 5."}, "src": "250 bài, CĐ10, Bài 10b"}, {"id": "cd10-b11a", "lesson": "fraccmp", "rank": 2, "q": {"vi": "Tìm 7 phân số nằm giữa hai phân số {7/9} và {8/9}. Quy đồng để các phân số có mẫu số là 72, hỏi tổng các tử số của 7 phân số đó bằng bao nhiêu?", "en": "Find 7 fractions between {7/9} and {8/9}. Rename them so the denominator is 72. What is the sum of the numerators of the 7 fractions?"}, "parts": [{"kind": "num", "lab": {"vi": "Tổng các tử số", "en": "Sum of numerators"}, "ans": 420, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Nhân tử và mẫu với 8: {7/9} = {56/72}; {8/9} = {64/72}.", "en": "Multiply top and bottom by 8: {7/9} = {56/72}; {8/9} = {64/72}."}, {"vi": "Các phân số ở giữa có tử số từ 57 đến 63: {57/72}; {58/72}; …; {63/72}, đúng 7 phân số.", "en": "The fractions in between have numerators 57 to 63: {57/72}; {58/72}; …; {63/72}. That is exactly 7 fractions."}, {"vi": "Tổng các tử số: 57 + 58 + … + 63 = 60 × 7 = 420.", "en": "Sum of numerators: 57 + 58 + … + 63 = 60 × 7 = 420."}], "tip": {"vi": "Quy đồng mẫu số 72 rồi xem các tử số ở giữa.", "en": "Use denominator 72, then look at the numerators in between."}, "src": "250 bài, CĐ10, Bài 11a"}, {"id": "cd10-b11b", "lesson": "fraccmp", "rank": 2, "q": {"vi": "Tìm 8 phân số nằm giữa 1 và {5/4}. Quy đồng để các phân số có mẫu số là 36, hỏi tổng các tử số của 8 phân số đó bằng bao nhiêu?", "en": "Find 8 fractions between 1 and {5/4}. Rename them so the denominator is 36. What is the sum of the numerators of the 8 fractions?"}, "parts": [{"kind": "num", "lab": {"vi": "Tổng các tử số", "en": "Sum of numerators"}, "ans": 324, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Viết 1 = {36/36} và {5/4} = {45/36} (nhân tử và mẫu với 9).", "en": "Write 1 = {36/36} and {5/4} = {45/36} (multiply top and bottom by 9)."}, {"vi": "Các phân số ở giữa có tử số từ 37 đến 44: {37/36}; …; {44/36}, đúng 8 phân số.", "en": "The fractions in between have numerators 37 to 44: {37/36}; …; {44/36}. That is exactly 8 fractions."}, {"vi": "Tổng các tử số: 37 + 38 + … + 44 = (37 + 44) × 8 : 2 = 324.", "en": "Sum of numerators: 37 + 38 + … + 44 = (37 + 44) × 8 ÷ 2 = 324."}], "tip": {"vi": "Quy đồng mẫu số 36 rồi xem các tử số ở giữa.", "en": "Use denominator 36, then look at the numerators in between."}, "src": "250 bài, CĐ10, Bài 11b"}, {"id": "cd10-b13", "lesson": "fraccmp", "rank": 2, "q": {"vi": "Tìm số tự nhiên x, biết rằng nếu thêm x vào cả tử và mẫu số của phân số {39/64} ta được phân số mới có giá trị là {3/4}.", "en": "Find the whole number x, if adding x to both the numerator and the denominator of {39/64} gives a new fraction equal to {3/4}."}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 36, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Hiệu của mẫu số và tử số không đổi: 64 − 39 = 25.", "en": "The difference between denominator and numerator stays the same: 64 − 39 = 25."}, {"vi": "Phân số mới {3/4}: mẫu số hơn tử số 1 phần nên 1 phần là 25, tử số mới là 25 × 3 = 75.", "en": "In {3/4} the denominator is 1 part more than the numerator, so 1 part is 25 and the new numerator is 25 × 3 = 75."}, {"vi": "x = 75 − 39 = 36.", "en": "x = 75 − 39 = 36."}], "tip": {"vi": "Hiệu giữa mẫu số và tử số không thay đổi.", "en": "The gap between denominator and numerator does not change."}, "src": "250 bài, CĐ10, Bài 13"}, {"id": "cd10-b15a", "lesson": "fraccmp", "rank": 2, "q": {"vi": "Tìm số tự nhiên x để phân số {156/(327 − x)} có giá trị lớn nhất. Giá trị lớn nhất đó là bao nhiêu?", "en": "Find the whole number x that makes the fraction {156/(327 − x)} as large as possible. What is that largest value?"}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 326, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Giá trị lớn nhất", "en": "Largest value"}, "ans": 156, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tử số 156 không đổi nên phân số lớn nhất khi mẫu số 327 − x bé nhất.", "en": "The numerator 156 stays fixed, so the fraction is largest when the denominator 327 − x is smallest."}, {"vi": "Mẫu số là số tự nhiên khác 0 nên bé nhất là 1, khi x = 326.", "en": "The denominator must be a whole number above 0, so the smallest is 1, when x = 326."}, {"vi": "Giá trị lớn nhất là {156/1} = 156.", "en": "The largest value is {156/1} = 156."}], "tip": {"vi": "Cùng tử số, mẫu số thế nào thì phân số lớn?", "en": "With the same numerator, which denominator gives a bigger fraction?"}, "src": "250 bài, CĐ10, Bài 15a"}, {"id": "cd10-b15b", "lesson": "fraccmp", "rank": 2, "q": {"vi": "Tìm số tự nhiên x (x có thể bằng 0) để phân số {156/(327 − x)} có giá trị bé nhất. Viết phân số bé nhất đó dưới dạng tối giản.", "en": "Find the whole number x (x may be 0) that makes the fraction {156/(327 − x)} as small as possible. Write that smallest fraction in simplest form."}, "parts": [{"kind": "frac", "lab": {"vi": "Phân số bé nhất", "en": "Smallest fraction"}, "ans": [52, 109]}], "steps": [{"vi": "Tử số không đổi nên phân số bé nhất khi mẫu số 327 − x lớn nhất.", "en": "The numerator is fixed, so the fraction is smallest when the denominator 327 − x is largest."}, {"vi": "Mẫu số lớn nhất khi x = 0, mẫu số là 327.", "en": "The denominator is largest when x = 0, giving 327."}, {"vi": "Phân số là {156/327}; chia tử và mẫu cho 3 được {52/109}.", "en": "The fraction is {156/327}; dividing top and bottom by 3 gives {52/109}."}], "tip": {"vi": "Xét x nhỏ nhất có thể.", "en": "Try the smallest possible x."}, "src": "250 bài, CĐ10, Bài 15b"}, {"id": "cd10-b18c", "lesson": "fraccmp", "rank": 2, "q": {"vi": "So sánh hai phân số {11/45} và {21/85} bằng cách hợp lý.", "en": "Compare the fractions {11/45} and {21/85} using a smart method (no common denominator)."}, "parts": [{"kind": "choice", "lab": {"vi": "{11/45} so với {21/85}", "en": "{11/45} vs {21/85}"}, "opts": {"vi": ["Bé hơn (<)", "Bằng (=)", "Lớn hơn (>)"], "en": ["Less than (<)", "Equal to (=)", "Greater than (>)"]}, "ans": 0}], "steps": [{"vi": "11 × 4 = 44 < 45 nên {11/45} < {1/4}; 21 × 4 = 84 < 85 nên {21/85} < {1/4}.", "en": "11 × 4 = 44 < 45, so {11/45} < {1/4}; 21 × 4 = 84 < 85, so {21/85} < {1/4}."}, {"vi": "Phần còn thiếu để bằng {1/4}: {1/4} − {11/45} = {1/180}; {1/4} − {21/85} = {1/340}.", "en": "Gap to {1/4}: {1/4} − {11/45} = {1/180}; {1/4} − {21/85} = {1/340}."}, {"vi": "{1/180} > {1/340}: {11/45} cách {1/4} xa hơn nên {11/45} < {21/85}.", "en": "{1/180} > {1/340}: {11/45} is farther below {1/4}, so {11/45} < {21/85}."}], "tip": {"vi": "Dùng phân số {1/4} làm mốc trung gian.", "en": "Use {1/4} as a benchmark."}, "src": "250 bài, CĐ10, Bài 18c"}, {"id": "cd10-b10c", "lesson": "fraccmp", "rank": 3, "q": {"vi": "Tìm số tự nhiên x, biết {8/202} < {(x × 6)/303} < {9/101}. Hỏi x có thể nhận bao nhiêu giá trị và tổng các giá trị đó bằng bao nhiêu?", "en": "Find the whole numbers x such that {8/202} < {(x × 6)/303} < {9/101}. How many values can x take, and what is their sum?"}, "parts": [{"kind": "num", "lab": {"vi": "Số giá trị của x", "en": "Number of values"}, "ans": 2, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Tổng các giá trị", "en": "Sum of values"}, "ans": 7, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Rút gọn: {8/202} = {4/101}; {(x × 6)/303} = {(x × 2)/101}.", "en": "Simplify: {8/202} = {4/101}; {(x × 6)/303} = {(x × 2)/101}."}, {"vi": "Cùng mẫu số 101 nên 4 < x × 2 < 9.", "en": "With the same denominator 101, we need 4 < x × 2 < 9."}, {"vi": "x × 2 = 6 hoặc 8 nên x = 3 hoặc x = 4: có 2 giá trị, tổng là 7.", "en": "So x × 2 is 6 or 8, giving x = 3 or 4. That is 2 values with sum 7."}], "tip": {"vi": "Rút gọn các phân số về mẫu số 101.", "en": "Reduce the fractions to denominator 101."}, "src": "250 bài, CĐ10, Bài 10c"}], "fracmul": [{"id": "cd10-b23a", "lesson": "fracmul", "rank": 1, "q": {"vi": "Tính giá trị biểu thức: 2 × {3/16} × {4/15} × 5", "en": "Find the value: 2 × {3/16} × {4/15} × 5"}, "parts": [{"kind": "frac", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": [1, 2]}], "steps": [{"vi": "Viết thành một phân số: (2 × 3 × 4 × 5) / (16 × 15) = {120/240}.", "en": "Write as one fraction: (2 × 3 × 4 × 5) / (16 × 15) = {120/240}."}, {"vi": "Rút gọn cho 120: {120/240} = {1/2}.", "en": "Divide top and bottom by 120: {120/240} = {1/2}."}], "tip": {"vi": "Nhân các tử số với nhau, các mẫu số với nhau rồi rút gọn.", "en": "Multiply the numerators, multiply the denominators, then simplify."}, "src": "250 bài, CĐ10, Bài 23a"}, {"id": "cd10-b23b", "lesson": "fracmul", "rank": 1, "q": {"vi": "Tính giá trị biểu thức: {6/7} × {14/9} × {3/18}", "en": "Find the value: {6/7} × {14/9} × {3/18}"}, "parts": [{"kind": "frac", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": [2, 9]}], "steps": [{"vi": "Viết thành một phân số: (6 × 14 × 3) / (7 × 9 × 18).", "en": "Write as one fraction: (6 × 14 × 3) / (7 × 9 × 18)."}, {"vi": "Rút gọn: 14 : 7 = 2; 6 × 3 = 18 nên cùng 18 ở mẫu, còn lại {2/9}.", "en": "Simplify: 14 ÷ 7 = 2; 6 × 3 = 18 cancels the 18 below, leaving {2/9}."}], "tip": {"vi": "Rút gọn chéo trước khi nhân.", "en": "Cancel common factors before multiplying."}, "src": "250 bài, CĐ10, Bài 23b"}, {"id": "cd10-b19a", "lesson": "fracmul", "rank": 2, "q": {"vi": "Tính giá trị của biểu thức: (6 : {3/5} − {7/6} × {6/7}) : ({21/5} × {10/11} + {57/11})", "en": "Evaluate: (6 ÷ {3/5} − {7/6} × {6/7}) ÷ ({21/5} × {10/11} + {57/11})"}, "parts": [{"kind": "num", "lab": {"vi": "Giá trị", "en": "Value"}, "ans": 1, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Ngoặc thứ nhất: 6 : {3/5} = 6 × {5/3} = 10; {7/6} × {6/7} = 1; vậy 10 − 1 = 9.", "en": "First parentheses: 6 ÷ {3/5} = 6 × {5/3} = 10; {7/6} × {6/7} = 1; so 10 − 1 = 9."}, {"vi": "Ngoặc thứ hai: {21/5} × {10/11} = {42/11}; {42/11} + {57/11} = {99/11} = 9.", "en": "Second parentheses: {21/5} × {10/11} = {42/11}; {42/11} + {57/11} = {99/11} = 9."}, {"vi": "Vậy biểu thức bằng 9 : 9 = 1.", "en": "So the expression equals 9 ÷ 9 = 1."}], "tip": {"vi": "Tính từng ngoặc trước, rồi chia hai kết quả cho nhau.", "en": "Work out each pair of parentheses first, then divide."}, "src": "250 bài, CĐ10, Bài 19a"}, {"id": "cd10-b20a", "lesson": "fracmul", "rank": 2, "q": {"vi": "Tìm x biết: ({1/2} + {1/3} + {1/4}) × x = 1 + {2/3} + {1/2}", "en": "Find x: ({1/2} + {1/3} + {1/4}) × x = 1 + {2/3} + {1/2}"}, "parts": [{"kind": "num", "lab": {"vi": "x =", "en": "x ="}, "ans": 2, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tổng trong ngoặc: {1/2} + {1/3} + {1/4} = {6/12} + {4/12} + {3/12} = {13/12}.", "en": "Sum in parentheses: {1/2} + {1/3} + {1/4} = {6/12} + {4/12} + {3/12} = {13/12}."}, {"vi": "Vế phải: 1 + {2/3} + {1/2} = {6/6} + {4/6} + {3/6} = {13/6}.", "en": "Right side: 1 + {2/3} + {1/2} = {6/6} + {4/6} + {3/6} = {13/6}."}, {"vi": "x là thừa số chưa biết: x = {13/6} : {13/12} = {13/6} × {12/13} = 2.", "en": "x is the unknown factor: x = {13/6} ÷ {13/12} = {13/6} × {12/13} = 2."}], "tip": {"vi": "Tính tổng ở ngoặc và vế phải trước, rồi lấy tích chia cho thừa số đã biết.", "en": "Work out the parentheses and the right side first, then divide the product by the known factor."}, "src": "250 bài, CĐ10, Bài 20a"}, {"id": "cd10-b20b", "lesson": "fracmul", "rank": 2, "q": {"vi": "Tìm x biết: ({1/2} + {1/3} − {1/4}) : x = {1/6} + {1/9} − {1/12}", "en": "Find x: ({1/2} + {1/3} − {1/4}) ÷ x = {1/6} + {1/9} − {1/12}"}, "parts": [{"kind": "num", "lab": {"vi": "x =", "en": "x ="}, "ans": 3, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Vế trái trong ngoặc: {1/2} + {1/3} − {1/4} = {6/12} + {4/12} − {3/12} = {7/12}.", "en": "Left parentheses: {1/2} + {1/3} − {1/4} = {6/12} + {4/12} − {3/12} = {7/12}."}, {"vi": "Vế phải: {1/6} + {1/9} − {1/12} = {6/36} + {4/36} − {3/36} = {7/36}.", "en": "Right side: {1/6} + {1/9} − {1/12} = {6/36} + {4/36} − {3/36} = {7/36}."}, {"vi": "x là số chia: x = {7/12} : {7/36} = {7/12} × {36/7} = 3.", "en": "x is the divisor: x = {7/12} ÷ {7/36} = {7/12} × {36/7} = 3."}], "tip": {"vi": "Số chia = số bị chia : thương.", "en": "Divisor = dividend ÷ quotient."}, "src": "250 bài, CĐ10, Bài 20b"}, {"id": "cd10-b20d", "lesson": "fracmul", "rank": 2, "q": {"vi": "Tìm x biết: {3/5} + {2/7} : x = 1", "en": "Find x: {3/5} + {2/7} ÷ x = 1"}, "parts": [{"kind": "frac", "lab": {"vi": "x =", "en": "x ="}, "ans": [5, 7]}], "steps": [{"vi": "Số hạng chưa biết: {2/7} : x = 1 − {3/5} = {2/5}.", "en": "The unknown term: {2/7} ÷ x = 1 − {3/5} = {2/5}."}, {"vi": "x là số chia: x = {2/7} : {2/5} = {2/7} × {5/2}.", "en": "x is the divisor: x = {2/7} ÷ {2/5} = {2/7} × {5/2}."}, {"vi": "Rút gọn: x = {5/7}.", "en": "Simplify: x = {5/7}."}], "tip": {"vi": "Tìm trước giá trị của phép chia {2/7} : x.", "en": "First find the value of {2/7} ÷ x."}, "src": "250 bài, CĐ10, Bài 20d"}, {"id": "cd10-b20e", "lesson": "fracmul", "rank": 2, "q": {"vi": "Tìm x biết: {6/5} − x : {1/2} = {1/2}", "en": "Find x: {6/5} − x ÷ {1/2} = {1/2}"}, "parts": [{"kind": "frac", "lab": {"vi": "x =", "en": "x ="}, "ans": [7, 20]}], "steps": [{"vi": "Số trừ: x : {1/2} = {6/5} − {1/2} = {12/10} − {5/10} = {7/10}.", "en": "The subtrahend: x ÷ {1/2} = {6/5} − {1/2} = {12/10} − {5/10} = {7/10}."}, {"vi": "x là số bị chia: x = {7/10} × {1/2}.", "en": "x is the dividend: x = {7/10} × {1/2}."}, {"vi": "x = {7/20}.", "en": "x = {7/20}."}], "tip": {"vi": "Tìm số trừ trước, rồi tìm số bị chia.", "en": "Find the subtrahend first, then the dividend."}, "src": "250 bài, CĐ10, Bài 20e"}, {"id": "cd10-b22d", "lesson": "fracmul", "rank": 2, "q": {"vi": "Tính: {7/8} : ({14/3} + {7/2}) + {4/28}", "en": "Calculate: {7/8} ÷ ({14/3} + {7/2}) + {4/28}"}, "parts": [{"kind": "frac", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": [1, 4]}], "steps": [{"vi": "Trong ngoặc: {14/3} + {7/2} = {28/6} + {21/6} = {49/6}.", "en": "In parentheses: {14/3} + {7/2} = {28/6} + {21/6} = {49/6}."}, {"vi": "{7/8} : {49/6} = {7/8} × {6/49} = {42/392} = {3/28}.", "en": "{7/8} ÷ {49/6} = {7/8} × {6/49} = {42/392} = {3/28}."}, {"vi": "{3/28} + {4/28} = {7/28} = {1/4}.", "en": "{3/28} + {4/28} = {7/28} = {1/4}."}], "tip": {"vi": "Làm ngoặc trước, rồi chia, cuối cùng mới cộng.", "en": "Parentheses first, then divide, and add last."}, "src": "250 bài, CĐ10, Bài 22d"}, {"id": "l26-b2e3", "lesson": "fracmul", "rank": 2, "q": {"vi": "Tính: {6/7} + {1/2} : {7/2}", "en": "Calculate: {6/7} + {1/2} ÷ {7/2}"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 1, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Chia trước: {1/2} : {7/2} = {1/2} × {2/7} = {1/7}.", "en": "Divide first: {1/2} ÷ {7/2} = {1/2} × {2/7} = {1/7}."}, {"vi": "Cộng: {6/7} + {1/7} = {7/7} = 1.", "en": "Add: {6/7} + {1/7} = {7/7} = 1."}], "tip": {"vi": "Nhân, chia trước; cộng, trừ sau.", "en": "Multiply and divide first; then add and subtract."}, "src": "LẦN 26, Bài 2e"}, {"id": "l26-b2e5", "lesson": "fracmul", "rank": 2, "q": {"vi": "Tính: {3/4} : {6/8} : {2/3}", "en": "Calculate: {3/4} ÷ {6/8} ÷ {2/3}"}, "parts": [{"kind": "frac", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": [3, 2]}], "steps": [{"vi": "Chia từ trái sang phải: {3/4} : {6/8} = {3/4} × {8/6} = {24/24} = 1.", "en": "Divide from left to right: {3/4} ÷ {6/8} = {3/4} × {8/6} = {24/24} = 1."}, {"vi": "1 : {2/3} = 1 × {3/2} = {3/2}.", "en": "1 ÷ {2/3} = 1 × {3/2} = {3/2}."}], "tip": {"vi": "Nhân, chia trước; cộng, trừ sau.", "en": "Multiply and divide first; then add and subtract."}, "src": "LẦN 26, Bài 2e"}, {"id": "l26-b2e11", "lesson": "fracmul", "rank": 2, "q": {"vi": "Tính: {5/6} + {2/3} : {2/3}", "en": "Calculate: {5/6} + {2/3} ÷ {2/3}"}, "parts": [{"kind": "frac", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": [11, 6]}], "steps": [{"vi": "Chia trước: {2/3} : {2/3} = 1.", "en": "Divide first: {2/3} ÷ {2/3} = 1."}, {"vi": "Cộng: {5/6} + 1 = {5/6} + {6/6} = {11/6}.", "en": "Add: {5/6} + 1 = {5/6} + {6/6} = {11/6}."}], "tip": {"vi": "Nhân, chia trước; cộng, trừ sau.", "en": "Multiply and divide first; then add and subtract."}, "src": "LẦN 26, Bài 2e"}, {"id": "cd10-b20c", "lesson": "fracmul", "rank": 3, "q": {"vi": "Tìm x biết: ({4/7} + {2/3}) : (x + {1/2}) = {8/7} + {4/3}", "en": "Find x: ({4/7} + {2/3}) ÷ (x + {1/2}) = {8/7} + {4/3}"}, "parts": [{"kind": "num", "lab": {"vi": "x =", "en": "x ="}, "ans": 0, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Số bị chia: {4/7} + {2/3} = {12/21} + {14/21} = {26/21}.", "en": "Dividend: {4/7} + {2/3} = {12/21} + {14/21} = {26/21}."}, {"vi": "Thương: {8/7} + {4/3} = {24/21} + {28/21} = {52/21}.", "en": "Quotient: {8/7} + {4/3} = {24/21} + {28/21} = {52/21}."}, {"vi": "Số chia: x + {1/2} = {26/21} : {52/21} = {1/2}.", "en": "Divisor: x + {1/2} = {26/21} ÷ {52/21} = {1/2}."}, {"vi": "Vậy x = {1/2} − {1/2} = 0.", "en": "So x = {1/2} − {1/2} = 0."}], "tip": {"vi": "Số chia bằng số bị chia chia cho thương.", "en": "The divisor equals the dividend divided by the quotient."}, "src": "250 bài, CĐ10, Bài 20c"}, {"id": "cd10-b23c", "lesson": "fracmul", "rank": 3, "q": {"vi": "Tính giá trị biểu thức: {13/14} × {17/4} × {56/15} × {70/39} × {21/34} × {25/49}", "en": "Find the value: {13/14} × {17/4} × {56/15} × {70/39} × {21/34} × {25/49}"}, "parts": [{"kind": "frac", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": [25, 3]}], "steps": [{"vi": "Rút gọn từng cặp: 13 / 39 = {1/3}; 17 / 34 = {1/2}; 56 / (14 × 4) = 1.", "en": "Cancel pairs: 13 / 39 = {1/3}; 17 / 34 = {1/2}; 56 / (14 × 4) = 1."}, {"vi": "Còn lại: (70 × 21 × 25) / (3 × 2 × 15 × 49); 21 / 3 = 7 và 70 × 7 / 49 = 10.", "en": "What is left: (70 × 21 × 25) / (3 × 2 × 15 × 49); 21 / 3 = 7 and 70 × 7 / 49 = 10."}, {"vi": "Cuối cùng: (10 × 25) / (2 × 15) = {250/30} = {25/3}.", "en": "Finally: (10 × 25) / (2 × 15) = {250/30} = {25/3}."}], "tip": {"vi": "Phân tích mỗi số thành tích rồi rút gọn.", "en": "Factor each number and cancel."}, "src": "250 bài, CĐ10, Bài 23c"}, {"id": "cd10-b23d", "lesson": "fracmul", "rank": 3, "q": {"vi": "Tính giá trị biểu thức: (1 × 3 × 5 + 2 × 6 × 10 + 3 × 9 × 15) / (3 × 5 × 12 + 6 × 10 × 24 + 9 × 15 × 36)", "en": "Find the value: (1 × 3 × 5 + 2 × 6 × 10 + 3 × 9 × 15) / (3 × 5 × 12 + 6 × 10 × 24 + 9 × 15 × 36)"}, "parts": [{"kind": "frac", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": [1, 12]}], "steps": [{"vi": "Tử số: 1 × 3 × 5 + 2 × 6 × 10 + 3 × 9 × 15 = 15 + 120 + 405 = 540.", "en": "Top: 1 × 3 × 5 + 2 × 6 × 10 + 3 × 9 × 15 = 15 + 120 + 405 = 540."}, {"vi": "Mẫu số: 3 × 5 × 12 + 6 × 10 × 24 + 9 × 15 × 36 = 180 + 1 440 + 4 860 = 6 480.", "en": "Bottom: 3 × 5 × 12 + 6 × 10 × 24 + 9 × 15 × 36 = 180 + 1,440 + 4,860 = 6,480."}, {"vi": "{540/6480} = {1/12}.", "en": "{540/6480} = {1/12}."}], "tip": {"vi": "Mỗi hạng tử ở mẫu gấp hạng tử tương ứng ở tử cùng một số lần.", "en": "Each term on the bottom is the same multiple of the matching term on top."}, "src": "250 bài, CĐ10, Bài 23d"}, {"id": "cd10-b24a", "lesson": "fracmul", "rank": 3, "q": {"vi": "Tính giá trị biểu thức: (1 + {1/91}) × (1 + {1/92}) × (1 + {1/93}) × … × (1 + {1/647})", "en": "Find the value: (1 + {1/91}) × (1 + {1/92}) × (1 + {1/93}) × … × (1 + {1/647})"}, "parts": [{"kind": "frac", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": [648, 91]}], "steps": [{"vi": "Mỗi thừa số: 1 + {1/91} = {92/91}; 1 + {1/92} = {93/92}; …; 1 + {1/647} = {648/647}.", "en": "Each factor: 1 + {1/91} = {92/91}; 1 + {1/92} = {93/92}; …; 1 + {1/647} = {648/647}."}, {"vi": "Tích = {92/91} × {93/92} × … × {648/647}; tử của phân số này triệt tiêu mẫu của phân số kế tiếp.", "en": "Product = {92/91} × {93/92} × … × {648/647}; each numerator cancels the next denominator."}, {"vi": "Còn lại {648/91}.", "en": "What is left is {648/91}."}], "tip": {"vi": "Đổi mỗi ngoặc thành một phân số rồi rút gọn dây chuyền.", "en": "Turn each bracket into one fraction and cancel in a chain."}, "src": "250 bài, CĐ10, Bài 24a"}, {"id": "cd10-b24b", "lesson": "fracmul", "rank": 3, "q": {"vi": "Tính giá trị biểu thức: (1 − {1/97}) × (1 − {1/98}) × (1 − {1/99}) × … × (1 − {1/1000})", "en": "Find the value: (1 − {1/97}) × (1 − {1/98}) × (1 − {1/99}) × … × (1 − {1/1000})"}, "parts": [{"kind": "frac", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": [12, 125]}], "steps": [{"vi": "Mỗi thừa số: 1 − {1/97} = {96/97}; 1 − {1/98} = {97/98}; …; 1 − {1/1000} = {999/1000}.", "en": "Each factor: 1 − {1/97} = {96/97}; 1 − {1/98} = {97/98}; …; 1 − {1/1000} = {999/1000}."}, {"vi": "Tích = {96/97} × {97/98} × … × {999/1000}; các số ở giữa triệt tiêu nhau.", "en": "Product = {96/97} × {97/98} × … × {999/1000}; the middle numbers cancel."}, {"vi": "Còn lại {96/1000} = {12/125}.", "en": "What is left is {96/1000} = {12/125}."}], "tip": {"vi": "Đổi mỗi ngoặc thành một phân số rồi rút gọn dây chuyền.", "en": "Turn each bracket into one fraction and cancel in a chain."}, "src": "250 bài, CĐ10, Bài 24b"}, {"id": "cd10-b24c", "lesson": "fracmul", "rank": 3, "q": {"vi": "Tính giá trị biểu thức: (1 + {1/3}) × (1 + {1/8}) × (1 + {1/15}) × … × (1 + {1/9999})", "en": "Find the value: (1 + {1/3}) × (1 + {1/8}) × (1 + {1/15}) × … × (1 + {1/9999})"}, "parts": [{"kind": "frac", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": [200, 101]}], "steps": [{"vi": "Các mẫu số 3 = 1 × 3, 8 = 2 × 4, 15 = 3 × 5, …, 9 999 = 99 × 101; mỗi thừa số là (2 × 2) / (1 × 3), (3 × 3) / (2 × 4), (4 × 4) / (3 × 5), …, (100 × 100) / (99 × 101).", "en": "The denominators are 3 = 1 × 3, 8 = 2 × 4, 15 = 3 × 5, …, 9,999 = 99 × 101; each factor is (2 × 2) / (1 × 3), (3 × 3) / (2 × 4), (4 × 4) / (3 × 5), …, (100 × 100) / (99 × 101)."}, {"vi": "Tích = (2 × 3 × … × 100) × (2 × 3 × … × 100) / ((1 × 2 × … × 99) × (3 × 4 × … × 101)).", "en": "Product = (2 × 3 × … × 100) × (2 × 3 × … × 100) / ((1 × 2 × … × 99) × (3 × 4 × … × 101))."}, {"vi": "Rút gọn: (2 × 3 × … × 100) / (1 × 2 × … × 99) = 100 và (2 × 3 × … × 100) / (3 × … × 101) = {2/101}.", "en": "Cancel: (2 × 3 × … × 100) / (1 × 2 × … × 99) = 100 and (2 × 3 × … × 100) / (3 × … × 101) = {2/101}."}, {"vi": "Kết quả: 100 × {2/101} = {200/101}.", "en": "Result: 100 × {2/101} = {200/101}."}], "tip": {"vi": "Viết 3 = 1 × 3, 8 = 2 × 4, 15 = 3 × 5 … và nhận ra quy luật.", "en": "Write 3 = 1 × 3, 8 = 2 × 4, 15 = 3 × 5 … and spot the pattern."}, "src": "250 bài, CĐ10, Bài 24c"}, {"id": "cd10-b24d", "lesson": "fracmul", "rank": 3, "q": {"vi": "Tính giá trị biểu thức: (1 + {7/9}) × (1 + {7/20}) × (1 + {7/33}) × … × (1 + {7/10800})", "en": "Find the value: (1 + {7/9}) × (1 + {7/20}) × (1 + {7/33}) × … × (1 + {7/10800})"}, "parts": [{"kind": "frac", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": [202, 27]}], "steps": [{"vi": "Các mẫu số: 9 = 1 × 9, 20 = 2 × 10, 33 = 3 × 11, …, 10 800 = 100 × 108.", "en": "The denominators: 9 = 1 × 9, 20 = 2 × 10, 33 = 3 × 11, …, 10,800 = 100 × 108."}, {"vi": "Mỗi thừa số: 1 + {7/9} = {16/9} = (2 × 8) / (1 × 9); 1 + {7/20} = {27/20} = (3 × 9) / (2 × 10); …; 1 + {7/10800} = (101 × 107) / (100 × 108).", "en": "Each factor: 1 + {7/9} = {16/9} = (2 × 8) / (1 × 9); 1 + {7/20} = {27/20} = (3 × 9) / (2 × 10); …; 1 + {7/10800} = (101 × 107) / (100 × 108)."}, {"vi": "Các thừa số 2, 3, …, 101 ở tử triệt tiêu với 1, 2, …, 100 ở mẫu, còn {101/1}.", "en": "The numerators 2, 3, …, 101 cancel with 1, 2, …, 100 on the bottom, leaving {101/1}."}, {"vi": "Các thừa số 8, 9, …, 107 ở tử triệt tiêu với 9, 10, …, 108 ở mẫu, còn {8/108}.", "en": "The numerators 8, 9, …, 107 cancel with 9, 10, …, 108 on the bottom, leaving {8/108}."}, {"vi": "Kết quả: 101 × {8/108} = {202/27}.", "en": "Result: 101 × {8/108} = {202/27}."}], "tip": {"vi": "Hãy thử 1 + {7/9} = {16/9}, 1 + {7/20} = {27/20} và tách thành tích hai số.", "en": "Try 1 + {7/9} = {16/9}, 1 + {7/20} = {27/20} and split into products."}, "src": "250 bài, CĐ10, Bài 24d"}, {"id": "l26-b4d", "lesson": "fracmul", "rank": 3, "q": {"vi": "Tìm y: {42/25} : {y/5} = {6/5}", "en": "Find y: {42/25} ÷ {y/5} = {6/5}"}, "parts": [{"kind": "num", "lab": {"vi": "y", "en": "y"}, "ans": 7, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "{y/5} là số chia nên {y/5} = {42/25} : {6/5} (số bị chia chia cho thương).", "en": "{y/5} is the divisor, so {y/5} = {42/25} ÷ {6/5} (dividend divided by quotient)."}, {"vi": "{42/25} : {6/5} = {42/25} × {5/6} = {210/150} = {7/5}.", "en": "{42/25} ÷ {6/5} = {42/25} × {5/6} = {210/150} = {7/5}."}, {"vi": "{y/5} = {7/5} nên y = 7.", "en": "{y/5} = {7/5}, so y = 7."}], "tip": {"vi": "Số chia = số bị chia : thương.", "en": "Divisor = dividend ÷ quotient."}, "src": "LẦN 26, Bài 4"}, {"id": "l26-b2e10-tu-quick", "lesson": "fracmul", "rank": 2, "q": {"vi": "Tính: {6/7} × {3/2} − {6/7} × {1/2}", "en": "Calculate: {6/7} × {3/2} − {6/7} × {1/2}"}, "parts": [{"kind": "frac", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": [6, 7]}], "steps": [{"vi": "Thừa số chung {6/7}: {6/7} × ({3/2} − {1/2}).", "en": "Common factor {6/7}: {6/7} × ({3/2} − {1/2})."}, {"vi": "{3/2} − {1/2} = {2/2} = 1.", "en": "{3/2} − {1/2} = {2/2} = 1."}, {"vi": "{6/7} × 1 = {6/7}.", "en": "{6/7} × 1 = {6/7}."}], "tip": {"vi": "Hãy tìm thừa số chung ở hai tích.", "en": "Look for the common factor in both products."}, "src": "LẦN 26, Bài 2e"}, {"id": "l26-b2e8-tu-quick", "lesson": "fracmul", "rank": 2, "q": {"vi": "Tính: {3/4} × {1/5} + {3/4} × {4/5}", "en": "Calculate: {3/4} × {1/5} + {3/4} × {4/5}"}, "parts": [{"kind": "frac", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": [3, 4]}], "steps": [{"vi": "Thừa số chung {3/4}: {3/4} × ({1/5} + {4/5}).", "en": "Common factor {3/4}: {3/4} × ({1/5} + {4/5})."}, {"vi": "{1/5} + {4/5} = 1.", "en": "{1/5} + {4/5} = 1."}, {"vi": "{3/4} × 1 = {3/4}.", "en": "{3/4} × 1 = {3/4}."}], "tip": {"vi": "Hãy tìm thừa số chung ở hai tích.", "en": "Look for the common factor in both products."}, "src": "LẦN 26, Bài 2e"}], "fraddsub": [{"id": "cd10-b22b", "lesson": "fraddsub", "rank": 1, "q": {"vi": "Tính hợp lý: {3/5} + {4/7} + {2/5} + {1/7} + {2/7}", "en": "Calculate smartly: {3/5} + {4/7} + {2/5} + {1/7} + {2/7}"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 2, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Ghép cùng mẫu: ({3/5} + {2/5}) + ({4/7} + {1/7} + {2/7}).", "en": "Group by denominator: ({3/5} + {2/5}) + ({4/7} + {1/7} + {2/7})."}, {"vi": "{3/5} + {2/5} = 1; {4/7} + {1/7} + {2/7} = {7/7} = 1.", "en": "{3/5} + {2/5} = 1; {4/7} + {1/7} + {2/7} = {7/7} = 1."}, {"vi": "Vậy tổng là 1 + 1 = 2.", "en": "So the total is 1 + 1 = 2."}], "tip": {"vi": "Ghép các phân số cùng mẫu số lại với nhau.", "en": "Group fractions with the same denominator."}, "src": "250 bài, CĐ10, Bài 22b"}, {"id": "cd10-b22a", "lesson": "fraddsub", "rank": 2, "q": {"vi": "Tính hợp lý: {17/12} + {9/7} − ({8/7} − {7/12})", "en": "Calculate smartly: {17/12} + {9/7} − ({8/7} − {7/12})"}, "parts": [{"kind": "frac", "lab": {"vi": "Giá trị", "en": "Value"}, "ans": [15, 7]}], "steps": [{"vi": "Bỏ ngoặc (trừ một hiệu): {17/12} + {9/7} − {8/7} + {7/12}.", "en": "Remove the parentheses: {17/12} + {9/7} − {8/7} + {7/12}."}, {"vi": "Nhóm cùng mẫu: ({17/12} + {7/12}) + ({9/7} − {8/7}) = 2 + {1/7}.", "en": "Group same denominators: ({17/12} + {7/12}) + ({9/7} − {8/7}) = 2 + {1/7}."}, {"vi": "2 + {1/7} = {15/7}.", "en": "2 + {1/7} = {15/7}."}], "tip": {"vi": "Bỏ ngoặc rồi ghép các phân số cùng mẫu số.", "en": "Remove the parentheses and group fractions with the same denominator."}, "src": "250 bài, CĐ10, Bài 22a"}, {"id": "cd10-b22e", "lesson": "fraddsub", "rank": 2, "q": {"vi": "Tính hợp lý: {175/100} + {18/21} + {13/32} + {5/4} + {1/7} − {45/32}", "en": "Calculate smartly: {175/100} + {18/21} + {13/32} + {5/4} + {1/7} − {45/32}"}, "parts": [{"kind": "num", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": 3, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Rút gọn: {175/100} = {7/4}; {18/21} = {6/7}.", "en": "Simplify: {175/100} = {7/4}; {18/21} = {6/7}."}, {"vi": "Ghép: ({7/4} + {5/4}) + ({6/7} + {1/7}) − ({45/32} − {13/32}) = 3 + 1 − {32/32}.", "en": "Group: ({7/4} + {5/4}) + ({6/7} + {1/7}) − ({45/32} − {13/32}) = 3 + 1 − {32/32}."}, {"vi": "Vậy kết quả là 3 + 1 − 1 = 3.", "en": "So the result is 3 + 1 − 1 = 3."}], "tip": {"vi": "Rút gọn trước rồi ghép các phân số cùng mẫu.", "en": "Simplify first, then group fractions with the same denominator."}, "src": "250 bài, CĐ10, Bài 22e"}, {"id": "cd10-b26a", "lesson": "fraddsub", "rank": 2, "q": {"vi": "Tìm y biết: (y + {1/2}) + (y + {1/4}) + (y + {1/8}) + (y + {1/16}) = 1", "en": "Find y: (y + {1/2}) + (y + {1/4}) + (y + {1/8}) + (y + {1/16}) = 1"}, "parts": [{"kind": "frac", "lab": {"vi": "y =", "en": "y ="}, "ans": [1, 64]}], "steps": [{"vi": "Bỏ ngoặc: 4 × y + ({1/2} + {1/4} + {1/8} + {1/16}) = 1.", "en": "Remove parentheses: 4 × y + ({1/2} + {1/4} + {1/8} + {1/16}) = 1."}, {"vi": "{1/2} + {1/4} + {1/8} + {1/16} = {8/16} + {4/16} + {2/16} + {1/16} = {15/16}.", "en": "{1/2} + {1/4} + {1/8} + {1/16} = {8/16} + {4/16} + {2/16} + {1/16} = {15/16}."}, {"vi": "4 × y = 1 − {15/16} = {1/16}, nên y = {1/16} : 4 = {1/64}.", "en": "4 × y = 1 − {15/16} = {1/16}, so y = {1/16} ÷ 4 = {1/64}."}], "tip": {"vi": "Có 4 số y; gộp chúng lại và cộng các phân số riêng.", "en": "There are four y's; combine them and add the fractions separately."}, "src": "250 bài, CĐ10, Bài 26a"}, {"id": "cd10-b28a", "lesson": "fraddsub", "rank": 2, "q": {"vi": "Tính giá trị A = {1/2} + {1/4} + {1/8} + … + {1/1024} + {1/2048}", "en": "Find the value A = {1/2} + {1/4} + {1/8} + … + {1/1024} + {1/2048}"}, "parts": [{"kind": "frac", "lab": {"vi": "Giá trị", "en": "Value"}, "ans": [2047, 2048]}], "steps": [{"vi": "Mỗi số hạng bằng số hạng trước chia 2. Nhân A với 2: 2 × A = 1 + {1/2} + {1/4} + … + {1/1024}.", "en": "Each term is half the previous one. Multiply A by 2: 2 × A = 1 + {1/2} + {1/4} + … + {1/1024}."}, {"vi": "Lấy 2 × A trừ A: A = 1 − {1/2048} = {2047/2048}.", "en": "Subtract A: A = 1 − {1/2048} = {2047/2048}."}, {"vi": "Vì A = {2047/2048} bé hơn 1 nên đề gốc 'A < 1' đúng.", "en": "Since A = {2047/2048} is less than 1, the original claim A < 1 is true."}], "tip": {"vi": "Nhân A với 2 rồi trừ đi A.", "en": "Multiply A by 2, then subtract A."}, "src": "250 bài, CĐ10, Bài 28a"}, {"id": "l26-b2e1", "lesson": "fraddsub", "rank": 2, "q": {"vi": "Tính: {7/9} + {3/8} : {6/5}", "en": "Calculate: {7/9} + {3/8} ÷ {6/5}"}, "parts": [{"kind": "frac", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": [157, 144]}], "steps": [{"vi": "Chia trước: {3/8} : {6/5} = {3/8} × {5/6} = {15/48} = {5/16}.", "en": "Divide first: {3/8} ÷ {6/5} = {3/8} × {5/6} = {15/48} = {5/16}."}, {"vi": "Quy đồng mẫu 144: {7/9} = {112/144}, {5/16} = {45/144}.", "en": "Common denominator 144: {7/9} = {112/144}, {5/16} = {45/144}."}, {"vi": "Cộng: {112/144} + {45/144} = {157/144}.", "en": "Add: {112/144} + {45/144} = {157/144}."}], "tip": {"vi": "Nhân, chia trước; cộng, trừ sau.", "en": "Multiply and divide first; then add and subtract."}, "src": "LẦN 26, Bài 2e"}, {"id": "l26-b2e2", "lesson": "fraddsub", "rank": 2, "q": {"vi": "Tính: {5/6} + {2/3} − {1/8}", "en": "Calculate: {5/6} + {2/3} − {1/8}"}, "parts": [{"kind": "frac", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": [11, 8]}], "steps": [{"vi": "Quy đồng mẫu 24: {5/6} = {20/24}, {2/3} = {16/24}, {1/8} = {3/24}.", "en": "Common denominator 24: {5/6} = {20/24}, {2/3} = {16/24}, {1/8} = {3/24}."}, {"vi": "Tính từ trái sang phải: {20/24} + {16/24} = {36/24}.", "en": "Left to right: {20/24} + {16/24} = {36/24}."}, {"vi": "{36/24} − {3/24} = {33/24} = {11/8}.", "en": "{36/24} − {3/24} = {33/24} = {11/8}."}], "tip": {"vi": "Nhân, chia trước; cộng, trừ sau.", "en": "Multiply and divide first; then add and subtract."}, "src": "LẦN 26, Bài 2e"}, {"id": "l26-b2e4", "lesson": "fraddsub", "rank": 2, "q": {"vi": "Tính: {4/5} + {3/10} − {1/20}", "en": "Calculate: {4/5} + {3/10} − {1/20}"}, "parts": [{"kind": "frac", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": [21, 20]}], "steps": [{"vi": "Quy đồng mẫu 20: {4/5} = {16/20}, {3/10} = {6/20}.", "en": "Common denominator 20: {4/5} = {16/20}, {3/10} = {6/20}."}, {"vi": "{16/20} + {6/20} = {22/20}.", "en": "{16/20} + {6/20} = {22/20}."}, {"vi": "{22/20} − {1/20} = {21/20}.", "en": "{22/20} − {1/20} = {21/20}."}], "tip": {"vi": "Nhân, chia trước; cộng, trừ sau.", "en": "Multiply and divide first; then add and subtract."}, "src": "LẦN 26, Bài 2e"}, {"id": "l26-b2e6", "lesson": "fraddsub", "rank": 2, "q": {"vi": "Tính: {8/7} + {3/14} − {1/7}", "en": "Calculate: {8/7} + {3/14} − {1/7}"}, "parts": [{"kind": "frac", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": [17, 14]}], "steps": [{"vi": "Các phân số có mẫu 14: {8/7} = {16/14}, {1/7} = {2/14}.", "en": "Use denominator 14: {8/7} = {16/14}, {1/7} = {2/14}."}, {"vi": "{16/14} + {3/14} = {19/14}.", "en": "{16/14} + {3/14} = {19/14}."}, {"vi": "{19/14} − {2/14} = {17/14}.", "en": "{19/14} − {2/14} = {17/14}."}], "tip": {"vi": "Nhân, chia trước; cộng, trừ sau.", "en": "Multiply and divide first; then add and subtract."}, "src": "LẦN 26, Bài 2e"}, {"id": "l26-b2e9", "lesson": "fraddsub", "rank": 2, "q": {"vi": "Tính: {8/9} + {2/3} − {1/4}", "en": "Calculate: {8/9} + {2/3} − {1/4}"}, "parts": [{"kind": "frac", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": [47, 36]}], "steps": [{"vi": "Quy đồng mẫu 36: {8/9} = {32/36}, {2/3} = {24/36}, {1/4} = {9/36}.", "en": "Common denominator 36: {8/9} = {32/36}, {2/3} = {24/36}, {1/4} = {9/36}."}, {"vi": "{32/36} + {24/36} = {56/36}.", "en": "{32/36} + {24/36} = {56/36}."}, {"vi": "{56/36} − {9/36} = {47/36}.", "en": "{56/36} − {9/36} = {47/36}."}], "tip": {"vi": "Nhân, chia trước; cộng, trừ sau.", "en": "Multiply and divide first; then add and subtract."}, "src": "LẦN 26, Bài 2e"}, {"id": "cd10-b25a", "lesson": "fraddsub", "rank": 3, "q": {"vi": "Tính giá trị: A = 1 + {1/5} + {1/25} + {1/125} + {1/625} + … + {1/78125}", "en": "Find the value: A = 1 + {1/5} + {1/25} + {1/125} + {1/625} + … + {1/78125}"}, "parts": [{"kind": "frac", "lab": {"vi": "Giá trị", "en": "Value"}, "ans": [97656, 78125]}], "steps": [{"vi": "Mỗi số hạng bằng số hạng trước chia 5 (78 125 = 5 × 5 × 5 × 5 × 5 × 5 × 5). Nhân A với 5: 5 × A = 5 + 1 + {1/5} + … + {1/15625}.", "en": "Each term is the previous one divided by 5 (78,125 = 5 × 5 × 5 × 5 × 5 × 5 × 5). Multiply A by 5: 5 × A = 5 + 1 + {1/5} + … + {1/15625}."}, {"vi": "Lấy 5 × A trừ A: 4 × A = 5 − {1/78125} = {390624/78125}.", "en": "Subtract A: 4 × A = 5 − {1/78125} = {390624/78125}."}, {"vi": "A = {390624/78125} : 4 = {97656/78125}.", "en": "A = {390624/78125} ÷ 4 = {97656/78125}."}], "tip": {"vi": "Nhân cả A với 5 rồi trừ đi A để các số hạng giống nhau mất đi.", "en": "Multiply A by 5, then subtract A so the matching terms cancel."}, "src": "250 bài, CĐ10, Bài 25a"}, {"id": "cd10-b25c", "lesson": "fraddsub", "rank": 3, "q": {"vi": "Tính giá trị: C = {5/3} + {5/6} + {5/12} + {5/24} + … + {5/192} + {5/384}", "en": "Find the value: C = {5/3} + {5/6} + {5/12} + {5/24} + … + {5/192} + {5/384}"}, "parts": [{"kind": "frac", "lab": {"vi": "Giá trị", "en": "Value"}, "ans": [425, 128]}], "steps": [{"vi": "Mẫu số gấp đôi dần: 3, 6, 12, 24, …, 192, 384. Nhân C với 2: 2 × C = {10/3} + {5/3} + {5/6} + … + {5/192}.", "en": "The denominators double each time: 3, 6, 12, 24, …, 192, 384. Multiply C by 2: 2 × C = {10/3} + {5/3} + {5/6} + … + {5/192}."}, {"vi": "Lấy 2 × C trừ C: C = {10/3} − {5/384}.", "en": "Subtract C: C = {10/3} − {5/384}."}, {"vi": "{10/3} = {1280/384} nên C = {1275/384} = {425/128}.", "en": "{10/3} = {1280/384}, so C = {1275/384} = {425/128}."}], "tip": {"vi": "Nhân C với 2 rồi trừ đi C.", "en": "Multiply C by 2, then subtract C."}, "src": "250 bài, CĐ10, Bài 25c"}, {"id": "cd10-b25d", "lesson": "fraddsub", "rank": 3, "q": {"vi": "Tính giá trị: D = 4 / (1 × 3) + 4 / (3 × 5) + 4 / (5 × 7) + … + 4 / (49 × 51)", "en": "Find the value: D = 4 / (1 × 3) + 4 / (3 × 5) + 4 / (5 × 7) + … + 4 / (49 × 51)"}, "parts": [{"kind": "frac", "lab": {"vi": "Giá trị", "en": "Value"}, "ans": [100, 51]}], "steps": [{"vi": "Hiệu hai thừa số ở mẫu là 2 nên 2 / (a × (a + 2)) = {1/a} − {1/(a+2)}; do đó 4 / (1 × 3) = 2 × ({1/1} − {1/3}).", "en": "The two factors differ by 2, so 2 / (a × (a + 2)) = 1/a − 1/(a + 2); hence 4 / (1 × 3) = 2 × (1 − {1/3})."}, {"vi": "D = 2 × ({1/1} − {1/3} + {1/3} − {1/5} + … + {1/49} − {1/51}).", "en": "D = 2 × (1 − {1/3} + {1/3} − {1/5} + … + {1/49} − {1/51})."}, {"vi": "Các phân số ở giữa triệt tiêu: D = 2 × (1 − {1/51}) = 2 × {50/51} = {100/51}.", "en": "The middle fractions cancel: D = 2 × (1 − {1/51}) = 2 × {50/51} = {100/51}."}], "tip": {"vi": "Chú ý: hiệu hai thừa số ở mẫu số là hằng số; hãy tách mỗi số hạng thành hiệu hai phân số.", "en": "Notice the two factors in each denominator differ by a constant; split each term into a difference of two fractions."}, "src": "250 bài, CĐ10, Bài 25d"}, {"id": "cd10-b25e", "lesson": "fraddsub", "rank": 3, "q": {"vi": "Tính giá trị: E = 1 / (2 × 5) + 1 / (5 × 8) + 1 / (8 × 11) + 1 / (11 × 14) + … + 1 / (98 × 101)", "en": "Find the value: E = 1 / (2 × 5) + 1 / (5 × 8) + 1 / (8 × 11) + 1 / (11 × 14) + … + 1 / (98 × 101)"}, "parts": [{"kind": "frac", "lab": {"vi": "Giá trị", "en": "Value"}, "ans": [33, 202]}], "steps": [{"vi": "Hiệu hai thừa số ở mẫu là 3 nên 3 / (a × (a + 3)) = {1/a} − {1/(a+3)}; do đó mỗi số hạng 1 / (a × (a + 3)) = {1/3} × ({1/a} − {1/(a+3)}).", "en": "The two factors differ by 3, so 3 / (a × (a + 3)) = 1/a − 1/(a + 3); each term 1 / (a × (a + 3)) = {1/3} × (1/a − 1/(a + 3))."}, {"vi": "E = {1/3} × ({1/2} − {1/5} + {1/5} − {1/8} + … + {1/98} − {1/101}).", "en": "E = {1/3} × ({1/2} − {1/5} + {1/5} − {1/8} + … + {1/98} − {1/101})."}, {"vi": "Triệt tiêu: E = {1/3} × ({1/2} − {1/101}) = {1/3} × {99/202} = {33/202}.", "en": "Cancel: E = {1/3} × ({1/2} − {1/101}) = {1/3} × {99/202} = {33/202}."}], "tip": {"vi": "Chú ý: hiệu hai thừa số ở mẫu số là hằng số; hãy tách mỗi số hạng thành hiệu hai phân số.", "en": "Notice the two factors in each denominator differ by a constant; split each term into a difference of two fractions."}, "src": "250 bài, CĐ10, Bài 25e"}, {"id": "cd10-b25f", "lesson": "fraddsub", "rank": 3, "q": {"vi": "Tính giá trị: F = 2 / (1 × 5) + 2 / (5 × 9) + 2 / (9 × 13) + … + 2 / (81 × 85)", "en": "Find the value: F = 2 / (1 × 5) + 2 / (5 × 9) + 2 / (9 × 13) + … + 2 / (81 × 85)"}, "parts": [{"kind": "frac", "lab": {"vi": "Giá trị", "en": "Value"}, "ans": [42, 85]}], "steps": [{"vi": "Hiệu hai thừa số ở mẫu là 4 nên 4 / (a × (a + 4)) = {1/a} − {1/(a+4)}; mỗi số hạng 2 / (a × (a + 4)) = {1/2} × ({1/a} − {1/(a+4)}).", "en": "The two factors differ by 4, so 4 / (a × (a + 4)) = 1/a − 1/(a + 4); each term 2 / (a × (a + 4)) = {1/2} × (1/a − 1/(a + 4))."}, {"vi": "F = {1/2} × (1 − {1/5} + {1/5} − {1/9} + … + {1/81} − {1/85}).", "en": "F = {1/2} × (1 − {1/5} + {1/5} − {1/9} + … + {1/81} − {1/85})."}, {"vi": "F = {1/2} × (1 − {1/85}) = {1/2} × {84/85} = {42/85}.", "en": "F = {1/2} × (1 − {1/85}) = {1/2} × {84/85} = {42/85}."}], "tip": {"vi": "Chú ý: hiệu hai thừa số ở mẫu số là hằng số; hãy tách mỗi số hạng thành hiệu hai phân số.", "en": "Notice the two factors in each denominator differ by a constant; split each term into a difference of two fractions."}, "src": "250 bài, CĐ10, Bài 25f"}, {"id": "cd10-b25g", "lesson": "fraddsub", "rank": 3, "q": {"vi": "Tính giá trị: G = 3 / (4 × 9) + 3 / (9 × 14) + 3 / (14 × 19) + … + 3 / (34 × 39)", "en": "Find the value: G = 3 / (4 × 9) + 3 / (9 × 14) + 3 / (14 × 19) + … + 3 / (34 × 39)"}, "parts": [{"kind": "frac", "lab": {"vi": "Giá trị", "en": "Value"}, "ans": [7, 52]}], "steps": [{"vi": "Hiệu hai thừa số ở mẫu là 5 nên 5 / (a × (a + 5)) = {1/a} − {1/(a+5)}; mỗi số hạng 3 / (a × (a + 5)) = {3/5} × ({1/a} − {1/(a+5)}).", "en": "The two factors differ by 5, so 5 / (a × (a + 5)) = 1/a − 1/(a + 5); each term 3 / (a × (a + 5)) = {3/5} × (1/a − 1/(a + 5))."}, {"vi": "G = {3/5} × ({1/4} − {1/9} + {1/9} − {1/14} + … + {1/34} − {1/39}).", "en": "G = {3/5} × ({1/4} − {1/9} + {1/9} − {1/14} + … + {1/34} − {1/39})."}, {"vi": "Triệt tiêu: G = {3/5} × ({1/4} − {1/39}) = {3/5} × {35/156} = {7/52}.", "en": "Cancel: G = {3/5} × ({1/4} − {1/39}) = {3/5} × {35/156} = {7/52}."}], "tip": {"vi": "Chú ý: hiệu hai thừa số ở mẫu số là hằng số; hãy tách mỗi số hạng thành hiệu hai phân số.", "en": "Notice the two factors in each denominator differ by a constant; split each term into a difference of two fractions."}, "src": "250 bài, CĐ10, Bài 25g"}, {"id": "cd10-b26b", "lesson": "fraddsub", "rank": 3, "q": {"vi": "Tìm y biết: (y + {1/2}) + (y + {1/4}) + (y + {1/8}) + … + (y + {1/1024}) = 1", "en": "Find y: (y + {1/2}) + (y + {1/4}) + (y + {1/8}) + … + (y + {1/1024}) = 1"}, "parts": [{"kind": "frac", "lab": {"vi": "y =", "en": "y ="}, "ans": [1, 10240]}], "steps": [{"vi": "Có 10 ngoặc (mẫu 2, 4, 8, …, 1024 = 2 × 2 × … × 2, mười thừa số 2), nên 10 × y + ({1/2} + {1/4} + … + {1/1024}) = 1.", "en": "There are 10 brackets (denominators 2, 4, 8, …, 1024, ten factors of 2), so 10 × y + ({1/2} + {1/4} + … + {1/1024}) = 1."}, {"vi": "Tổng: {1/2} + {1/4} + … + {1/1024} = 1 − {1/1024} = {1023/1024}.", "en": "Sum: {1/2} + {1/4} + … + {1/1024} = 1 − {1/1024} = {1023/1024}."}, {"vi": "10 × y = 1 − {1023/1024} = {1/1024}, nên y = {1/1024} : 10 = {1/10240}.", "en": "10 × y = 1 − {1023/1024} = {1/1024}, so y = {1/1024} ÷ 10 = {1/10240}."}], "tip": {"vi": "Đếm số ngoặc để biết có bao nhiêu số y.", "en": "Count the brackets to see how many y's there are."}, "src": "250 bài, CĐ10, Bài 26b"}, {"id": "cd10-b27", "lesson": "fraddsub", "rank": 3, "q": {"vi": "Tìm x biết: ({1/2} + {1/4} + {1/8} + {1/16}) : x = 3 / (1 × 2) + 3 / (2 × 3) + 3 / (3 × 4) + … + 3 / (15 × 16)", "en": "Find x: ({1/2} + {1/4} + {1/8} + {1/16}) ÷ x = 3 / (1 × 2) + 3 / (2 × 3) + 3 / (3 × 4) + … + 3 / (15 × 16)"}, "parts": [{"kind": "frac", "lab": {"vi": "x =", "en": "x ="}, "ans": [1, 3]}], "steps": [{"vi": "Vế trái trong ngoặc: {1/2} + {1/4} + {1/8} + {1/16} = {15/16}.", "en": "Left parentheses: {1/2} + {1/4} + {1/8} + {1/16} = {15/16}."}, {"vi": "Vế phải: 1 / (n × (n + 1)) = {1/n} − {1/(n+1)} nên tổng = 3 × (1 − {1/16}) = 3 × {15/16} = {45/16}.", "en": "Right side: 1 / (n × (n + 1)) = 1/n − 1/(n + 1), so the sum = 3 × (1 − {1/16}) = 3 × {15/16} = {45/16}."}, {"vi": "x là số chia: x = {15/16} : {45/16} = {15/45} = {1/3}.", "en": "x is the divisor: x = {15/16} ÷ {45/16} = {15/45} = {1/3}."}], "tip": {"vi": "Tính riêng hai vế rồi tìm số chia.", "en": "Work out each side, then find the divisor."}, "src": "250 bài, CĐ10, Bài 27"}, {"id": "cd10-b28b", "lesson": "fraddsub", "rank": 3, "q": {"vi": "Tính giá trị B = {1/3} + {1/9} + {1/27} + … + {1/2187} + {1/6561}", "en": "Find the value B = {1/3} + {1/9} + {1/27} + … + {1/2187} + {1/6561}"}, "parts": [{"kind": "frac", "lab": {"vi": "Giá trị", "en": "Value"}, "ans": [3280, 6561]}], "steps": [{"vi": "Mỗi số hạng bằng số hạng trước chia 3. Nhân B với 3: 3 × B = 1 + {1/3} + {1/9} + … + {1/2187}.", "en": "Each term is the previous one divided by 3. Multiply B by 3: 3 × B = 1 + {1/3} + {1/9} + … + {1/2187}."}, {"vi": "Lấy 3 × B trừ B: 2 × B = 1 − {1/6561} = {6560/6561}.", "en": "Subtract B: 2 × B = 1 − {1/6561} = {6560/6561}."}, {"vi": "B = {6560/6561} : 2 = {3280/6561}; bé hơn {1/2} nên đề gốc 'B < {1/2}' đúng.", "en": "B = {6560/6561} ÷ 2 = {3280/6561}; it is less than {1/2}, so the original claim B < {1/2} is true."}], "tip": {"vi": "Nhân B với 3 rồi trừ đi B.", "en": "Multiply B by 3, then subtract B."}, "src": "250 bài, CĐ10, Bài 28b"}, {"id": "cd10-b29a", "lesson": "fraddsub", "rank": 3, "q": {"vi": "Tính giá trị: A = {1/4} + {1/12} + {1/24} + {1/40} + … + {1/4900}", "en": "Find the value: A = {1/4} + {1/12} + {1/24} + {1/40} + … + {1/4900}"}, "parts": [{"kind": "frac", "lab": {"vi": "Giá trị", "en": "Value"}, "ans": [49, 100]}], "steps": [{"vi": "Các mẫu số: 4 = 2 × 1 × 2; 12 = 2 × 2 × 3; 24 = 2 × 3 × 4; 40 = 2 × 4 × 5; …; 4 900 = 2 × 49 × 50.", "en": "The denominators: 4 = 2 × 1 × 2; 12 = 2 × 2 × 3; 24 = 2 × 3 × 4; 40 = 2 × 4 × 5; …; 4,900 = 2 × 49 × 50."}, {"vi": "Mỗi số hạng = {1/2} × 1 / (n × (n + 1)) = {1/2} × ({1/n} − {1/(n+1)}).", "en": "Each term = {1/2} × 1 / (n × (n + 1)) = {1/2} × (1/n − 1/(n + 1))."}, {"vi": "A = {1/2} × (1 − {1/50}) = {1/2} × {49/50} = {49/100}.", "en": "A = {1/2} × (1 − {1/50}) = {1/2} × {49/50} = {49/100}."}], "tip": {"vi": "Phân tích mỗi mẫu số thành 2 × n × (n + 1).", "en": "Write each denominator as 2 × n × (n + 1)."}, "src": "250 bài, CĐ10, Bài 29a"}, {"id": "cd10-b29b", "lesson": "fraddsub", "rank": 3, "q": {"vi": "Tính giá trị: B = {1/2} + {1/14} + {1/35} + {1/65} + … + {1/4850}", "en": "Find the value: B = {1/2} + {1/14} + {1/35} + {1/65} + … + {1/4850}"}, "parts": [{"kind": "frac", "lab": {"vi": "Giá trị", "en": "Value"}, "ans": [33, 50]}], "steps": [{"vi": "Nhân đôi các mẫu số: 4 = 1 × 4; 28 = 4 × 7; 70 = 7 × 10; 130 = 10 × 13; …; 9 700 = 97 × 100. Mỗi số hạng = 2 / (a × (a + 3)).", "en": "Double the denominators: 4 = 1 × 4; 28 = 4 × 7; 70 = 7 × 10; 130 = 10 × 13; …; 9,700 = 97 × 100. Each term = 2 / (a × (a + 3))."}, {"vi": "Hiệu hai thừa số là 3 nên 2 / (a × (a + 3)) = {2/3} × ({1/a} − {1/(a+3)}).", "en": "The factors differ by 3, so 2 / (a × (a + 3)) = {2/3} × (1/a − 1/(a + 3))."}, {"vi": "B = {2/3} × (1 − {1/100}) = {2/3} × {99/100} = {33/50}.", "en": "B = {2/3} × (1 − {1/100}) = {2/3} × {99/100} = {33/50}."}], "tip": {"vi": "Nhân đôi mỗi mẫu số để thấy hai thừa số cách nhau 3.", "en": "Double each denominator to see two factors that differ by 3."}, "src": "250 bài, CĐ10, Bài 29b"}, {"id": "cd10-b29d", "lesson": "fraddsub", "rank": 3, "q": {"vi": "Tính giá trị: D = {1/6} + {1/66} + {1/176} + {1/336} + … + {1/1886}", "en": "Find the value: D = {1/6} + {1/66} + {1/176} + {1/336} + … + {1/1886}"}, "parts": [{"kind": "frac", "lab": {"vi": "Giá trị", "en": "Value"}, "ans": [9, 46]}], "steps": [{"vi": "Các mẫu số: 6 = 1 × 6; 66 = 6 × 11; 176 = 11 × 16; 336 = 16 × 21; …; 1 886 = 41 × 46.", "en": "The denominators: 6 = 1 × 6; 66 = 6 × 11; 176 = 11 × 16; 336 = 16 × 21; …; 1,886 = 41 × 46."}, {"vi": "Hiệu hai thừa số là 5 nên 1 / (a × (a + 5)) = {1/5} × ({1/a} − {1/(a+5)}).", "en": "The factors differ by 5, so 1 / (a × (a + 5)) = {1/5} × (1/a − 1/(a + 5))."}, {"vi": "D = {1/5} × (1 − {1/46}) = {1/5} × {45/46} = {9/46}.", "en": "D = {1/5} × (1 − {1/46}) = {1/5} × {45/46} = {9/46}."}], "tip": {"vi": "Phân tích mỗi mẫu số thành tích hai số hơn kém nhau 5.", "en": "Write each denominator as a product of two numbers that differ by 5."}, "src": "250 bài, CĐ10, Bài 29d"}, {"id": "cd10-b29e", "lesson": "fraddsub", "rank": 3, "q": {"vi": "Tính giá trị: E = {3/2} + {5/4} + {9/8} + {17/16} + … + {1025/1024}", "en": "Find the value: E = {3/2} + {5/4} + {9/8} + {17/16} + … + {1025/1024}"}, "parts": [{"kind": "frac", "lab": {"vi": "Giá trị", "en": "Value"}, "ans": [11263, 1024]}], "steps": [{"vi": "Tách mỗi số hạng: {3/2} = 1 + {1/2}; {5/4} = 1 + {1/4}; {9/8} = 1 + {1/8}; …; {1025/1024} = 1 + {1/1024}. Có 10 số hạng (2, 4, 8, …, 1024).", "en": "Split each term: {3/2} = 1 + {1/2}; {5/4} = 1 + {1/4}; {9/8} = 1 + {1/8}; …; {1025/1024} = 1 + {1/1024}. There are 10 terms (2, 4, 8, …, 1024)."}, {"vi": "Tổng các số 1 là 10; tổng {1/2} + {1/4} + … + {1/1024} = 1 − {1/1024} = {1023/1024}.", "en": "The ones add up to 10; {1/2} + {1/4} + … + {1/1024} = 1 − {1/1024} = {1023/1024}."}, {"vi": "E = 10 + {1023/1024} = {11263/1024}.", "en": "E = 10 + {1023/1024} = {11263/1024}."}], "tip": {"vi": "Tách mỗi phân số thành 1 cộng một phân số.", "en": "Split each fraction into 1 plus a fraction."}, "src": "250 bài, CĐ10, Bài 29e"}, {"id": "cd10-b29f", "lesson": "fraddsub", "rank": 3, "q": {"vi": "Tính giá trị: F = 1 − {1/3} + {1/9} − {1/27} + {1/81} − … + {1/6561} − {1/19683}", "en": "Find the value: F = 1 − {1/3} + {1/9} − {1/27} + {1/81} − … + {1/6561} − {1/19683}"}, "parts": [{"kind": "frac", "lab": {"vi": "Giá trị", "en": "Value"}, "ans": [14762, 19683]}], "steps": [{"vi": "Có các mẫu 1, 3, 9, …, 19 683 = 3 × 3 × … × 3 (9 thừa số 3); dấu cộng trừ xen kẽ. Nhân F với 3: 3 × F = 3 − 1 + {1/3} − {1/9} + … − {1/6561}.", "en": "The denominators are 1, 3, 9, …, 19,683 (nine 3s multiplied); the signs alternate. Multiply F by 3: 3 × F = 3 − 1 + {1/3} − {1/9} + … − {1/6561}."}, {"vi": "Cộng 3 × F với F: các số hạng đối nhau triệt tiêu, 4 × F = 3 − {1/19683} = {59048/19683}.", "en": "Add F to 3 × F: the opposite terms cancel, so 4 × F = 3 − {1/19683} = {59048/19683}."}, {"vi": "F = {59048/19683} : 4 = {14762/19683}.", "en": "F = {59048/19683} ÷ 4 = {14762/19683}."}], "tip": {"vi": "Nhân F với 3 rồi cộng với F (vì dấu xen kẽ).", "en": "Multiply F by 3 and then add F (the signs alternate)."}, "src": "250 bài, CĐ10, Bài 29f"}, {"id": "cd10-b30a", "lesson": "fraddsub", "rank": 3, "q": {"vi": "Tìm y biết: y × ({1/4} + {1/28} + {1/70} + … + {1/550}) = 1", "en": "Find y: y × ({1/4} + {1/28} + {1/70} + … + {1/550}) = 1"}, "parts": [{"kind": "frac", "lab": {"vi": "y =", "en": "y ="}, "ans": [25, 8]}], "steps": [{"vi": "Các mẫu số: 4 = 1 × 4; 28 = 4 × 7; 70 = 7 × 10; …; 550 = 22 × 25. Hiệu hai thừa số là 3.", "en": "The denominators: 4 = 1 × 4; 28 = 4 × 7; 70 = 7 × 10; …; 550 = 22 × 25. The factors differ by 3."}, {"vi": "Tổng trong ngoặc = {1/3} × (1 − {1/25}) = {1/3} × {24/25} = {8/25}.", "en": "Sum in parentheses = {1/3} × (1 − {1/25}) = {1/3} × {24/25} = {8/25}."}, {"vi": "y là thừa số chưa biết: y = 1 : {8/25} = {25/8}.", "en": "y is the unknown factor: y = 1 ÷ {8/25} = {25/8}."}], "tip": {"vi": "Tính tổng trong ngoặc bằng cách tách hiệu hai phân số.", "en": "Find the sum in parentheses by splitting into differences."}, "src": "250 bài, CĐ10, Bài 30a"}, {"id": "cd10-b30b", "lesson": "fraddsub", "rank": 3, "q": {"vi": "Tìm y biết: ({1/2} + {1/4} + {1/8} + {1/16}) × y = {1/2} + {1/6} + {1/12} + {1/20} + … + {1/132}", "en": "Find y: ({1/2} + {1/4} + {1/8} + {1/16}) × y = {1/2} + {1/6} + {1/12} + {1/20} + … + {1/132}"}, "parts": [{"kind": "frac", "lab": {"vi": "y =", "en": "y ="}, "ans": [44, 45]}], "steps": [{"vi": "Vế trái trong ngoặc: {1/2} + {1/4} + {1/8} + {1/16} = {15/16}.", "en": "Left parentheses: {1/2} + {1/4} + {1/8} + {1/16} = {15/16}."}, {"vi": "Vế phải: 2 = 1 × 2; 6 = 2 × 3; …; 132 = 11 × 12 nên tổng = 1 − {1/12} = {11/12}.", "en": "Right side: 2 = 1 × 2; 6 = 2 × 3; …; 132 = 11 × 12, so the sum = 1 − {1/12} = {11/12}."}, {"vi": "y = {11/12} : {15/16} = {11/12} × {16/15} = {44/45}.", "en": "y = {11/12} ÷ {15/16} = {11/12} × {16/15} = {44/45}."}], "tip": {"vi": "Tính riêng hai vế rồi tìm thừa số chưa biết.", "en": "Work out each side, then find the unknown factor."}, "src": "250 bài, CĐ10, Bài 30b"}, {"id": "cd10-b31a", "lesson": "fraddsub", "rank": 3, "q": {"vi": "Tìm y biết: {1/4} + {1/28} + {1/70} + {1/130} + … + 1 / (y × (y + 3)) = {34/103}", "en": "Find y: {1/4} + {1/28} + {1/70} + {1/130} + … + 1 / (y × (y + 3)) = {34/103}"}, "parts": [{"kind": "num", "lab": {"vi": "y =", "en": "y ="}, "ans": 100, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Các mẫu số: 4 = 1 × 4; 28 = 4 × 7; 70 = 7 × 10; 130 = 10 × 13; … Hiệu hai thừa số là 3.", "en": "The denominators: 4 = 1 × 4; 28 = 4 × 7; 70 = 7 × 10; 130 = 10 × 13; … The factors differ by 3."}, {"vi": "Tổng vế trái = {1/3} × (1 − {1/(y+3)}).", "en": "Left side = {1/3} × (1 − {1/(y+3)})."}, {"vi": "{1/3} × (1 − {1/(y+3)}) = {34/103} nên 1 − {1/(y+3)} = {102/103}, suy ra {1/(y+3)} = {1/103}.", "en": "{1/3} × (1 − {1/(y+3)}) = {34/103}, so 1 − {1/(y+3)} = {102/103}, which gives {1/(y+3)} = {1/103}."}, {"vi": "y + 3 = 103 nên y = 100.", "en": "y + 3 = 103, so y = 100."}], "tip": {"vi": "Viết tổng vế trái dưới dạng một hiệu rồi tìm y + 3.", "en": "Write the left side as one difference, then find y + 3."}, "src": "250 bài, CĐ10, Bài 31a"}, {"id": "cd10-b31b", "lesson": "fraddsub", "rank": 3, "q": {"vi": "Tìm y biết: {1/3} + {1/6} + {1/10} + {1/15} + … + 1 / (y × (y + 1) : 2) = {2009/2011}", "en": "Find y: {1/3} + {1/6} + {1/10} + {1/15} + … + 1 / (y × (y + 1) ÷ 2) = {2009/2011}"}, "parts": [{"kind": "num", "lab": {"vi": "y =", "en": "y ="}, "ans": 2010, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Các mẫu số: 3 = 2 × 3 : 2; 6 = 3 × 4 : 2; 10 = 4 × 5 : 2; 15 = 5 × 6 : 2; … nên mỗi số hạng = 2 / (n × (n + 1)), n bắt đầu từ 2.", "en": "The denominators: 3 = 2 × 3 ÷ 2; 6 = 3 × 4 ÷ 2; 10 = 4 × 5 ÷ 2; 15 = 5 × 6 ÷ 2; … so each term = 2 / (n × (n + 1)), starting at n = 2."}, {"vi": "2 / (n × (n + 1)) = 2 × ({1/n} − {1/(n+1)}) nên tổng vế trái = 2 × ({1/2} − {1/(y+1)}) = 1 − {2/(y+1)}.", "en": "2 / (n × (n + 1)) = 2 × (1/n − 1/(n + 1)), so the left side = 2 × ({1/2} − {1/(y+1)}) = 1 − {2/(y+1)}."}, {"vi": "1 − {2/(y+1)} = {2009/2011} nên {2/(y+1)} = {2/2011}.", "en": "1 − {2/(y+1)} = {2009/2011}, so {2/(y+1)} = {2/2011}."}, {"vi": "y + 1 = 2011 nên y = 2010.", "en": "y + 1 = 2011, so y = 2010."}], "tip": {"vi": "Mỗi số hạng có dạng 2 / (n × (n + 1)).", "en": "Each term looks like 2 / (n × (n + 1))."}, "src": "250 bài, CĐ10, Bài 31b"}, {"id": "l26-b4a", "lesson": "fraddsub", "rank": 3, "q": {"vi": "Tìm x: {1/6} − {1/10} = {36/x}", "en": "Find x: {1/6} − {1/10} = {36/x}"}, "parts": [{"kind": "num", "lab": {"vi": "x", "en": "x"}, "ans": 540, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Tính vế trái: {1/6} − {1/10} = {5/30} − {3/30} = {2/30} = {1/15}.", "en": "Left side: {1/6} − {1/10} = {5/30} − {3/30} = {2/30} = {1/15}."}, {"vi": "Vậy {36/x} = {1/15}.", "en": "So {36/x} = {1/15}."}, {"vi": "Tử số 36 gấp 1 là 36 lần nên x gấp 15 là 36 lần: x = 15 × 36 = 540.", "en": "The numerator 36 is 36 times 1, so x is 36 times 15: x = 15 × 36 = 540."}], "tip": {"vi": "Hai phân số bằng nhau: nhân (hoặc chia) tử và mẫu với cùng một số.", "en": "Equal fractions: multiply (or divide) the top and bottom by the same number."}, "src": "LẦN 26, Bài 4"}, {"id": "l26-b2e7", "lesson": "fraddsub", "rank": 3, "q": {"vi": "Tính: {4/3} + {3/45} : {3/5}", "en": "Calculate: {4/3} + {3/45} ÷ {3/5}"}, "parts": [{"kind": "frac", "lab": {"vi": "Kết quả", "en": "Result"}, "ans": [13, 9]}], "steps": [{"vi": "Chia trước: {3/45} : {3/5} = {3/45} × {5/3} = {15/135} = {1/9}.", "en": "Divide first: {3/45} ÷ {3/5} = {3/45} × {5/3} = {15/135} = {1/9}."}, {"vi": "Quy đồng mẫu 9: {4/3} = {12/9}.", "en": "Common denominator 9: {4/3} = {12/9}."}, {"vi": "Cộng: {12/9} + {1/9} = {13/9}.", "en": "Add: {12/9} + {1/9} = {13/9}."}], "tip": {"vi": "Nhân, chia trước; cộng, trừ sau.", "en": "Multiply and divide first; then add and subtract."}, "src": "LẦN 26, Bài 2e"}], "chick": [{"id": "cd6-b11", "lesson": "chick", "rank": 2, "q": {"vi": "Tìm hai số có tổng bằng 140, biết nếu gấp số thứ nhất lên 3 lần và gấp số thứ hai lên 5 lần rồi cộng lại ta được tổng mới bằng 516.", "en": "Find two numbers whose sum is 140, knowing that if the first number is multiplied by 3 and the second number is multiplied by 5 and the results are added, the new sum is 516."}, "parts": [{"kind": "num", "lab": {"vi": "Số thứ nhất", "en": "First number"}, "ans": 92, "unit": {"vi": "", "en": ""}}, {"kind": "num", "lab": {"vi": "Số thứ hai", "en": "Second number"}, "ans": 48, "unit": {"vi": "", "en": ""}}], "steps": [{"vi": "Nếu gấp cả hai số lên 3 lần thì tổng là 140 × 3 = 420.", "en": "If both numbers were multiplied by 3, the sum would be 140 × 3 = 420."}, {"vi": "Tổng mới hơn 420 là 516 − 420 = 96, do số thứ hai được gấp thêm 2 lần nữa.", "en": "The new sum is 516 − 420 = 96 more, because the second number was multiplied by 2 more."}, {"vi": "Số thứ hai: 96 : 2 = 48.", "en": "Second number: 96 ÷ 2 = 48."}, {"vi": "Số thứ nhất: 140 − 48 = 92.", "en": "First number: 140 − 48 = 92."}], "tip": {"vi": "Hãy so sánh với trường hợp cả hai số cùng gấp 3 lần.", "en": "Compare with the case where both numbers are multiplied by 3."}, "src": "250 bài, CĐ6, Bài 11"}]};
